    input wire [63:0] UnsignedImmediate,
    input wire Issigned,
    output reg [63:0] ExtendedImm
);

always @(*) begin
    if (Issigned)
        ExtendedImm = SignedImmediate;
    else
        ExtendedImm = UnsignedImmediate;
end

endmodule

module loop #(
    parameter DATA_W = 8,
    parameter MODE = "block"
) (
    input wire clk,
    input wire rst,
    input wire [DATA_W-1:0] lim,
    input wire trig,
    output reg [DATA_W-1:0] cnt,
    output reg last
);

    reg [DATA_W-1:0] next_cnt;
    reg next_last;

    always @(*) begin
        next_cnt = cnt;
        next_last = last;

        if (trig) begin
            if (cnt == lim) begin
                next_cnt = {DATA_W{1'b0}};
            end else begin
                next_cnt = cnt + 1'b1;
            end
        end

        if (MODE == "block") begin
            next_last = (cnt == lim - 1'b1) && trig;
        end else begin
            next_last = (cnt == lim);
        end
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            cnt <= {DATA_W{1'b0}};
            if (MODE == "block") begin
                last <= 1'b0;
            end
        end else begin
            cnt <= next_cnt;
            last <= next_last;
        end
    end

endmodule

module pwm_generator (
    input wire Clk50M,
    input wire Rst_n,
    input wire cnt_en,
    input wire [31:0] counter_arr,
    input wire [31:0] counter_ccr,
    output reg o_pwm
);

    reg [31:0] counter;

    always @(posedge Clk50M or negedge Rst_n) begin
        if (!Rst_n) begin
            counter <= 32'd0;
            o_pwm <= 1'b0;
        end else begin
            if (cnt_en) begin
                if (counter == 32'd0) begin
                    counter <= counter_arr;
                end else begin
                    counter <= counter - 1'b1;
                end
            end else begin
                counter <= counter_arr;
            end

            o_pwm <= (counter < counter_ccr) ? 1'b1 : 1'b0;
        end
    end

endmodule

