module memory_read_proxy(
input wire [9:0] x_in,
input wire [9:0] y_in,
input wire [0:0] memory_value,
output reg [9:0] x_out,
output reg [9:0] y_out,
output reg [0:0] proxy_value
);
parameter [31:0] STARTING_X=0;
parameter [31:0] STARTING_Y=0;
parameter [31:0] X_LENGTH=350;
parameter [31:0] Y_LENGTH=350;
reg [0:0] memory_data = 1'b0;
  always @(x_in, y_in) begin : P1
    reg [31:0] x_in_int = 0;
    reg [31:0] y_in_int = 0;
    x_in_int = x_in;
    y_in_int = y_in;
    memory_data <= memory_value;
    if((x_in_int >= STARTING_X && x_in_int <= (STARTING_X + X_LENGTH) && y_in_int >= STARTING_Y && y_in_int <= (STARTING_Y + Y_LENGTH))) begin
      x_out <= x_in_int - STARTING_X;
      y_out <= y_in_int - STARTING_Y;
      proxy_value <= memory_data;
    end
    else begin
      x_out <= {10{1'b0}};
      y_out <= {10{1'b0}};
      proxy_value <= {1{1'b0}};
    end
  end
endmodule

