module als_driver(
input wire rst,
input wire clk,
output wire cs,
output wire scl,
input wire sda,
output wire [7:0] data_out
);
reg cs_sig = 1'b1; wire sclk = 1'b1;
reg [31:0] w_counter = 15;
reg [15:0] data_buffer = 16'b0000000000000000;
  assign scl = sclk;
  assign cs = cs_sig;
  assign data_out = data_buffer[11:4];
  // Divides clock down to 2MHz
  clk_divider CLK_DIV(
      .rst(rst),
    .clk_in(clk),
    .clk_out(sclk),
    .const(24));
  always @(posedge sclk, posedge rst) begin
    if((rst == 1'b1)) begin
      cs_sig <= 1'b1;
      data_buffer <= 16'b0000000000000000;
      w_counter <= 15;
    end else begin
      if(w_counter == 15) begin
        cs_sig <= 1'b0;
        w_counter <= w_counter - 1;
      end
      else if(w_counter > 0) begin
        data_buffer[w_counter] <= sda;
        w_counter <= w_counter - 1;
      end
      else begin
        data_buffer[w_counter] <= sda;
        cs_sig <= 1'b1;
        w_counter <= 15;
      end
    end
  end
endmodule

