module ClkDiv50MHzTo4Hz (
    input wire iClk,
    input wire iRst,
    output wire oCE
);

    // Parameters
    localparam COUNTER_MAX = 24'd12_500_000;

    // Registers
    reg [23:0] rvCnt_q;
    reg rCE_q;

    // Wires
    wire [23:0] wvCnt_d;
    wire wCE_d;

    // Sequential logic
    always @(posedge iClk or posedge iRst) begin
        if (iRst) begin
            rvCnt_q <= 24'd0;
            rCE_q <= 1'b0;
        end else begin
            rvCnt_q <= wvCnt_d;
            rCE_q <= wCE_d;
        end
    end

    // Combinational logic
    assign wvCnt_d = (rvCnt_q == COUNTER_MAX) ? 24'd0 : rvCnt_q + 1'b1;
    assign wCE_d = (rvCnt_q == COUNTER_MAX);

    // Output assignment
    assign oCE = rCE_q;

endmodule

module proc_interrupt(
input wire clock,
input wire clock_en,
input wire reset,
input wire irq_n,
input wire nmi_n,
input wire i_flag,
output reg clear_b,
input wire vect_bit,
output wire interrupt,
output wire [3:0] vect_addr
);
reg irq_c = 1'b0;
reg nmi_c = 1'b0;
reg nmi_d = 1'b0;
reg nmi_act = 1'b0;
reg [1:0] vect_h = 2'b00;
parameter [1:0]
  idle = 0,
  do_irq = 1,
  do_nmi = 2;
reg [1:0] state;
  assign vect_addr = {1'b1,vect_h,vect_bit};
  assign interrupt = irq_c | nmi_act;
  always @(posedge clock) begin
    irq_c <=  ~(irq_n | i_flag);
    nmi_c <=  ~nmi_n;
    clear_b <= 1'b0;
    if(clock_en == 1'b1) begin
      nmi_d <= nmi_c;
      if(nmi_d == 1'b0 && nmi_c == 1'b1) begin
        // edge
        nmi_act <= 1'b1;
      end
      case(state)
      idle : begin
        vect_h <= 2'b11;
        // FE/FF
        if(nmi_act == 1'b1) begin
          vect_h <= 2'b01;
          // FA/FB
          state <= do_nmi;
        end
        else if(irq_c == 1'b1) begin
          state <= do_irq;
          clear_b <= 1'b1;
        end
      end
      do_irq : begin
        if(vect_bit == 1'b0 || irq_c == 1'b0) begin
          state <= idle;
        end
      end
      do_nmi : begin
        if(vect_bit == 1'b0) begin
          nmi_act <= 1'b0;
          state <= idle;
        end
      end
      default : begin
        state <= idle;
      end
      endcase
    end
    if(reset == 1'b1) begin
      vect_h <= 2'b10;
      // FC/FD 1100
      state <= do_nmi;
      nmi_act <= 1'b0;
    end
  end
endmodule

