module i8255(
input wire CLK,
input wire RESET,
input wire [1:0] A,
input wire [7:0] DI,
output wire [7:0] DO,
input wire WR,
input wire [7:0] PAI,
output wire [7:0] PAO,
input wire [7:0] PBI,
output wire [7:0] PBO,
input wire [7:0] PCI,
output wire [7:0] PCO
);
reg [7:0] PORTA;
reg [7:0] PORTB;
reg [7:0] PORTC;
reg [7:0] CONTROL;
  assign DO = A == 2'b00 && CONTROL[4] == 1'b1 ? PAI : A == 2'b00 && CONTROL[4] == 1'b0 ? PORTA : A == 2'b01 && CONTROL[1] == 1'b1 ? PBI : A == 2'b01 && CONTROL[1] == 1'b0 ? PORTB : A == 2'b10 && CONTROL[0] == 1'b1 && CONTROL[3] == 1'b1 ? PCI : A == 2'b10 && CONTROL[0] == 1'b0 && CONTROL[3] == 1'b0 ? PORTC : A == 2'b10 && CONTROL[0] == 1'b1 && CONTROL[3] == 1'b0 ? {PCI[7:4],PORTC[3:0]} : A == 2'b10 && CONTROL[0] == 1'b0 && CONTROL[3] == 1'b1 ? {PORTC[7:4],PCI[3:0]} : CONTROL;
  assign PAO = PORTA;
  assign PBO = PORTB;
  assign PCO = PORTC;
  always @(posedge CLK) begin
    if(RESET == 1'b1) begin
      CONTROL <= 8'b10011011;
      PORTA <= 8'b00000000;
      PORTB <= 8'b00000000;
      PORTC <= 8'b00000000;
    end
    else begin
      if(WR == 1'b1) begin
        case(A)
        2'b00 : begin
          PORTA <= DI;
        end
        2'b01 : begin
          PORTB <= DI;
        end
        2'b10 : begin
          PORTC <= DI;
        end
        default : begin
          CONTROL <= DI;
          if(DI[7] == 1'b0) begin
            // Bit set/reset
            case(DI[3:1])
            3'b000 : begin
              PORTC[0] <= DI[0];
            end
            3'b001 : begin
              PORTC[1] <= DI[0];
            end
            3'b010 : begin
              PORTC[2] <= DI[0];
            end
            3'b011 : begin
              PORTC[3] <= DI[0];
            end
            3'b100 : begin
              PORTC[4] <= DI[0];
            end
            3'b101 : begin
              PORTC[5] <= DI[0];
            end
            3'b110 : begin
              PORTC[6] <= DI[0];
            end
            default : begin
              PORTC[7] <= DI[0];
            end
            endcase
          end
        end
        endcase
      end
    end
  end
endmodule

module dma_controller (
    input wire hclk,
    input wire hreset_n,
    input wire hready_i,
    input wire dma_start,
    input wire done,
    input wire hready_pulldown,
    output reg start,
    output reg sel_control,
    output reg buf_control,
    output reg write_control,
    output reg length_control,
    output reg trans_control
);

    // State encoding
    localparam S0 = 2'b00;
    localparam S1 = 2'b01;
    localparam S2 = 2'b10;
    localparam S3 = 2'b11;

    reg [1:0] current_state, next_state;

    // State register
    always @(posedge hclk or negedge hreset_n) begin
        if (!hreset_n)
            current_state <= S0;
        else
            current_state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            S0: next_state = (hready_i && dma_start && hready_pulldown) ? S1 : S0;
            S1: next_state = S2;
            S2: begin
                if (done)
                    next_state = S0;
                else if (hready_i)
                    next_state = S3;
                else
                    next_state = S2;
            end
            S3: next_state = S2;
            default: next_state = S0;
        endcase
    end

    // Output logic
    always @(posedge hclk or negedge hreset_n) begin
        if (!hreset_n) begin
            start <= 1'b0;
            sel_control <= 1'b0;
            buf_control <= 1'b0;
            write_control <= 1'b0;
            length_control <= 1'b0;
            trans_control <= 1'b0;
        end
        else begin
            case (next_state)
                S0: begin
                    start <= 1'b0;
                    sel_control <= 1'b0;
                    buf_control <= 1'b0;
                    write_control <= 1'b0;
                    length_control <= 1'b0;
                    trans_control <= 1'b0;
                end
                S1: begin
                    start <= 1'b1;
                    sel_control <= 1'b1;
                    write_control <= 1'b1;
                    buf_control <= 1'b0;
                    length_control <= 1'b0;
                    trans_control <= 1'b0;
                end
                S2: begin
                    start <= 1'b0;
                    sel_control <= 1'b1;
                    write_control <= 1'b1;
                    buf_control <= 1'b1;
                    length_control <= 1'b1;
                    trans_control <= 1'b0;
                end
                S3: begin
                    start <= 1'b0;
                    sel_control <= 1'b1;
                    write_control <= 1'b1;
                    buf_control <= 1'b0;
                    length_control <= 1'b0;
                    trans_control <= 1'b1;
                end
            endcase
        end
    end

endmodule

