  assign input_status = {foo[9:4],baz[3:0] & foo[3:0] | ( ~baz[3:0] & bam[3:0])};
  // drive based on foo
  assign out_i = (enable & (aux ^ outy)) | (debug & dv &  ~enable) | ( ~debug &  ~enable & value);
  // not drive
  always @(negedge reset, negedge sysclk) begin
    if((reset != 1'b0)) begin
      foo <= {14{1'b0}};
    end else begin
      foo[3 * (2 - 1)] <= 4 * (1 + 2);
      bam[13:0] <= foo;
    end
  end
endmodule

module fsm_controller (
    input wire clk_d,
    input wire one_pulse,
    input wire rst,
    input wire push,
    output reg en,
    output reg rst_2
);

    // State encoding
    localparam IDLE = 2'b00;
    localparam ENABLED = 2'b01;
    localparam RESET = 2'b10;

    // Internal signals
    reg [1:0] state, next_state;
    reg rst_2_en;
    reg [8:0] push_time;

    // State register
    always @(posedge clk_d or posedge rst) begin
        if (rst)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Push button timer
    always @(posedge clk_d or posedge rst) begin
        if (rst) begin
            push_time <= 9'b0;
            rst_2_en <= 1'b0;
        end else if (push) begin
            if (push_time == 9'b110_000_000) begin
                rst_2_en <= 1'b1;
                push_time <= push_time;
            end else begin
                push_time <= push_time + 1'b1;
                rst_2_en <= 1'b0;
            end
        end else begin
            push_time <= 9'b0;
            rst_2_en <= 1'b0;
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            IDLE: begin
                if (rst_2_en)
                    next_state = RESET;
                else if (one_pulse)
                    next_state = ENABLED;
                else
                    next_state = IDLE;
            end
            ENABLED: begin
                if (rst_2_en)
                    next_state = RESET;
                else if (one_pulse)
                    next_state = IDLE;
                else
                    next_state = ENABLED;
            end
            RESET: begin
                if (one_pulse)
                    next_state = ENABLED;
                else
                    next_state = RESET;
            end
            default: next_state = IDLE;
        endcase
    end

    // Output logic
    always @(*) begin
        case (state)
            IDLE: begin
                en = 1'b0;
                rst_2 = 1'b0;
            end
            ENABLED: begin
                en = 1'b1;
                rst_2 = 1'b0;
            end
            RESET: begin
                en = 1'b0;
                rst_2 = 1'b1;
            end
            default: begin
                en = 1'b0;
                rst_2 = 1'b0;
            end
        endcase
    end

endmodule

