module exe_write_latch (
    input wire clk_i,
    input wire rsn_i,
    input wire kill_i,

    // Execution unit inputs
    input wire [31:0] exe_result_i,
    input wire [31:0] exe_instruction_i,
    input wire [4:0] exe_rd_i,
    input wire exe_rd_valid_i,
    input wire [3:0] exe_exception_i,
    input wire exe_illegal_instruction_i,

    // Multiplier inputs
    input wire mult5_int_write_enable_i,
    input wire [31:0] mult5_result_i,
    input wire [4:0] mult5_rd_i,

    // Cache inputs
    input wire cache_cache_enable_i,
    input wire [31:0] cache_result_i,
    input wire [4:0] cache_rd_i,

    // Outputs
    output reg [31:0] write_result_o,
    output reg [31:0] write_instruction_o,
    output reg [4:0] write_rd_o,
    output reg write_rd_valid_o,
    output reg [4:0] write_exception_o,
    output reg write_int_write_enable_o
);

    wire is_branch = (exe_instruction_i[6:0] == 7'b1100011);
    wire is_load = (exe_instruction_i[6:0] == 7'b0000011);
    wire is_store = (exe_instruction_i[6:0] == 7'b0100011);
    wire exe_write_enable = exe_rd_valid_i && !is_branch && !is_store;

    always @(posedge clk_i or negedge rsn_i) begin
        if (!rsn_i || kill_i) begin
            write_result_o <= 32'b0;
            write_instruction_o <= 32'b0;
            write_rd_o <= 5'b0;
            write_rd_valid_o <= 1'b0;
            write_exception_o <= 5'b0;
            write_int_write_enable_o <= 1'b0;
        end else begin
            if (mult5_int_write_enable_i) begin
                write_result_o <= mult5_result_i;
                write_rd_o <= mult5_rd_i;
                write_rd_valid_o <= 1'b1;
                write_int_write_enable_o <= 1'b1;
            end else if (cache_cache_enable_i) begin
                write_result_o <= cache_result_i;
                write_rd_o <= cache_rd_i;
                write_rd_valid_o <= 1'b1;
                write_int_write_enable_o <= 1'b1;
            end else if (exe_write_enable) begin
                write_result_o <= exe_result_i;
                write_rd_o <= exe_rd_i;
                write_rd_valid_o <= exe_rd_valid_i;
                write_int_write_enable_o <= 1'b1;
            end else begin
                write_int_write_enable_o <= 1'b0;
            end

            write_instruction_o <= exe_instruction_i;
            write_exception_o <= {exe_illegal_instruction_i, exe_exception_i};
        end
    end

endmodule

