module pdata (
    input wire clk,
    input wire nRst,
    input wire rx,
    input wire [2:0] opcode,
    output reg tx
);

    // Parameters for opcodes
    localparam OUT_DATA1   = 3'h0;
    localparam OUT_DATA2   = 3'h1;
    localparam OUT_RES     = 3'h2;
    localparam OUT_RES_ADD = 3'h3;
    localparam LOAD_RES    = 3'h4;
    localparam MUL         = 3'h5;
    localparam MUL_ADD     = 3'h6;
    localparam NO_OP       = 3'h7;

    // Internal registers
    reg [31:0] data_1;
    reg [31:0] data_2;
    reg [127:0] acc;

    always @(posedge clk or negedge nRst) begin
        if (!nRst) begin
            data_1 <= 32'b0;
            data_2 <= 32'b0;
            acc <= 128'b0;
            tx <= 1'b0;
        end else begin
            case (opcode)
                OUT_DATA1: begin
                    data_1 <= {data_1[30:0], rx};
                    tx <= data_1[31];
                end
                OUT_DATA2: begin
                    data_2 <= {data_2[30:0], rx};
                    tx <= data_2[31];
                end
                OUT_RES, OUT_RES_ADD: begin
                    acc <= {acc[126:0], 1'b0};
                    tx <= acc[127];
                end
                MUL: begin
                    acc <= data_1 * data_2;
                end
                MUL_ADD: begin
                    acc <= acc + (data_1 * data_2);
                end
                default: begin
                    // No operation
                end
            endcase
        end
    end

endmodule

