module spi_controller (
    input wire clk,
    input wire rst_n,
    input wire trigger,
    input wire [7:0] tx_cmd,
    input wire [7:0] tx_data,
    input wire spi_miso,
    output reg spi_clk,
    output reg spi_mosi,
    output reg spi_cs,
    output reg busy,
    output reg [7:0] rx_data
);

    reg [31:0] div_clk;
    reg [7:0] state;
    reg [64:0] data_reg;
    reg [64:0] clk_reg;
    reg [7:0] rx_shift;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            div_clk <= 32'd0;
            state <= 8'd0;
            data_reg <= 65'd0;
            clk_reg <= 65'd0;
            spi_clk <= 1'b0;
            spi_mosi <= 1'b0;
            spi_cs <= 1'b1;
            busy <= 1'b0;
            rx_data <= 8'd0;
            rx_shift <= 8'd0;
        end else begin
            div_clk <= div_clk + 1;

            if (state == 0) begin
                if (trigger) begin
                    state <= 8'd1;
                    busy <= 1'b1;
                    spi_cs <= 1'b0;
                    data_reg <= {1'b0, {8{tx_data[7:0], tx_cmd[7:0]}}};
                    clk_reg <= {1'b0, {16{4'b0110}}};
                end
            end else if (state < 65) begin
                if (div_clk == 0) begin
                    state <= state + 1;
                    spi_clk <= clk_reg[64];
                    spi_mosi <= data_reg[64];
                    data_reg <= {data_reg[63:0], 1'b0};
                    clk_reg <= {clk_reg[63:0], 1'b0};

                    if (spi_clk) begin
                        rx_shift <= {rx_shift[6:0], spi_miso};
                        if (state[1:0] == 2'b00) begin
                            rx_data <= {rx_shift[6:0], spi_miso};
                        end
                    end
                end
            end else begin
                state <= 8'd0;
                busy <= 1'b0;
                spi_cs <= 1'b1;
            end
        end
    end

endmodule

module IfftControl(
input wire reset,
input wire clk,
input wire IfftEnable,
output reg start,
output wire [6:0] cp_len,
output reg cp_len_we,
output reg unload,
output wire fwd_inv,
output reg fwd_inv_we,
input wire rfd
);
parameter [31:0] CARRIERS=128;
//
//declaracion de estados
parameter [1:0]
  reposo = 0,
  inicio = 1,
  activo = 2;
  //señales 
reg [1:0] estado_actual; reg [1:0] estado_nuevo;  //	signal datoIn : STD_LOGIC_VECTOR (15 downto 0);
//	signal outReal, outImag : STD_LOGIC_VECTOR (7 downto 0);
//	signal dire_actual, dire_nuevo: STD_LOGIC_VECTOR(6 downto 0);
//	signal addra, p_addra : INTEGER RANGE 0 to CARRIERS; -- deberia ser carriers -1 pero sino no detectamos que es mayor por que desborda
  assign cp_len = 7'b0001100;
  //configuracion prefijo ciclico
  assign fwd_inv = 1'b0;
  // inversa ifft
  //proceso sincrono
  always @(posedge reset, posedge clk) begin
    if((reset == 1'b1)) begin
      estado_actual <= reposo;
    end else begin
      estado_actual <= estado_nuevo;
    end
  end
  always @(estado_actual, ifftEnable, rfd) begin
    estado_nuevo <= estado_actual;
    start <= 1'b0;
    cp_len_we <= 1'b0;
    unload <= 1'b1;
    fwd_inv_we <= 1'b0;
    case(estado_actual)
    reposo : begin
      if(ifftEnable == 1'b1) begin
        estado_nuevo <= inicio;
      end
      else begin
        estado_nuevo <= reposo;
      end
    end
    inicio : begin
      //Conexiones con el core de FFT
      start <= 1'b1;
      cp_len_we <= 1'b1;
      fwd_inv_we <= 1'b1;
      //saltamos a otro estado 
      estado_nuevo <= activo;
    end
    activo : begin
      start <= 1'b0;
      //saltamos a otro estado 
      if(rfd == 1'b1) begin
        estado_nuevo <= activo;
      end
      else begin
        estado_nuevo <= reposo;
      end
    end
    endcase
  end
endmodule

