module tensor_2d #(
    parameter ROW_BITS = 2,
    parameter COL_BITS = 4
)(
    input wire clk,
    input wire rst_n,
    input wire write,
    input wire [15:0] param_in,
    input wire [ROW_BITS-1:0] sel_r,
    input wire [COL_BITS-1:0] sel_c,
    output reg [15:0] param_out
);

    localparam ROWS = 1 << ROW_BITS;
    localparam COLS = 1 << COL_BITS;

    reg [15:0] matrix [0:ROWS-1][0:COLS-1];
    integer i, j;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < ROWS; i = i + 1) begin
                for (j = 0; j < COLS; j = j + 1) begin
                    matrix[i][j] <= 16'b0;
                end
            end
        end else if (write) begin
            matrix[sel_r][sel_c] <= param_in;
        end
    end

    always @(posedge clk) begin
        param_out <= matrix[sel_r][sel_c];
    end

endmodule

