module Submatrix (
    input wire clk,
    input wire resetN,
    input wire loaded,
    input wire encrypted,
    input wire processed,
    input wire [15:0] submatrixGeneratorOutput,
    input wire [15:0] encryptorOutput,
    output reg readyToBeLoaded,
    output reg readyToBeEncrypted,
    output reg readyToBeProcessed,
    output reg [15:0] encryptorInput,
    output reg [15:0] imageGeneratorInput
);

    // State encoding
    localparam READY_TO_LOAD = 2'b00;
    localparam READY_TO_ENCRYPT = 2'b01;
    localparam READY_TO_PROCESS = 2'b10;

    reg [1:0] current_state, next_state;

    // State transition logic
    always @(posedge clk or negedge resetN) begin
        if (!resetN)
            current_state <= READY_TO_LOAD;
        else
            current_state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            READY_TO_LOAD:
                if (loaded)
                    next_state = READY_TO_ENCRYPT;
                else
                    next_state = READY_TO_LOAD;
            READY_TO_ENCRYPT:
                if (encrypted)
                    next_state = READY_TO_PROCESS;
                else
                    next_state = READY_TO_ENCRYPT;
            READY_TO_PROCESS:
                if (processed)
                    next_state = READY_TO_LOAD;
                else
                    next_state = READY_TO_PROCESS;
            default:
                next_state = READY_TO_LOAD;
        endcase
    end

    // Output logic
    always @(posedge clk or negedge resetN) begin
        if (!resetN) begin
            readyToBeLoaded <= 1'b1;
            readyToBeEncrypted <= 1'b0;
            readyToBeProcessed <= 1'b0;
            encryptorInput <= 16'b0;
            imageGeneratorInput <= 16'b0;
        end else begin
            case (current_state)
                READY_TO_LOAD: begin
                    readyToBeLoaded <= 1'b1;
                    readyToBeEncrypted <= 1'b0;
                    readyToBeProcessed <= 1'b0;
                    if (loaded) begin
                        encryptorInput <= submatrixGeneratorOutput;
                    end
                end
                READY_TO_ENCRYPT: begin
                    readyToBeLoaded <= 1'b0;
                    readyToBeEncrypted <= 1'b1;
                    readyToBeProcessed <= 1'b0;
                    if (encrypted) begin
                        imageGeneratorInput <= encryptorOutput;
                    end
                end
                READY_TO_PROCESS: begin
                    readyToBeLoaded <= 1'b0;
                    readyToBeEncrypted <= 1'b0;
                    readyToBeProcessed <= 1'b1;
                end
            endcase
        end
    end

endmodule

