      data_received_in <= 1'b0;
    end
    else begin
      data_received_in <= 1'b1;
    end
  end
  always @(posedge recv_clock) begin
    if((recv_strobe == 1'b1)) begin
      if((write_address_counter == 0 && read_address_counter == 0) || write_address_counter != (read_address_counter - 1)) begin
        ram[write_address_counter] <= recv_data;
        write_address_counter <= write_address_counter + 1;
      end
    end
  end
  always @(posedge clk) begin
    if((ram_enable == 1'b1)) begin
      if(read_address_counter != write_address_counter) begin
        ram_output <= {ram[read_address_counter],ram[read_address_counter + 1]};
        read_address_counter <= read_address_counter + 2;
      end
    end
  end
endmodule

