module ControlUnit(
    input [5:0] opCode,
    input zero,
    output reg PCWre,
    output reg ALUSrcA,
    output reg ALUSrcB,
    output reg DBDataSrc,
    output reg RegWre,
    output reg InsMemRW,
    output reg mRD,
    output reg mWR,
    output reg RegDst,
    output reg ExtSel,
    output reg [1:0] PCSrc,
    output reg [2:0] ALUOp
);

    initial begin
        InsMemRW = 1'b1;
        PCWre = 1'b1;
        PCSrc = 2'b00;
        mRD = 1'b0;
        mWR = 1'b0;
    end

    always @(*) begin
        case(opCode)
            6'b000000: begin // R-type instructions
                PCWre = 1'b1;
                ALUSrcA = 1'b0;
                ALUSrcB = 1'b0;
                DBDataSrc = 1'b0;
                RegWre = 1'b1;
                mRD = 1'b0;
                mWR = 1'b0;
                RegDst = 1'b1;
                ExtSel = 1'b0;
                PCSrc = 2'b00;
                ALUOp = 3'b010;
            end
            6'b100111: begin // LW
                PCWre = 1'b1;
                ALUSrcA = 1'b0;
                ALUSrcB = 1'b1;
                DBDataSrc = 1'b1;
                RegWre = 1'b1;
                mRD = 1'b1;
                mWR = 1'b0;
                RegDst = 1'b0;
                ExtSel = 1'b1;
                PCSrc = 2'b00;
                ALUOp = 3'b000;
            end
            6'b100110: begin // SW
                PCWre = 1'b1;
                ALUSrcA = 1'b0;
                ALUSrcB = 1'b1;
                DBDataSrc = 1'b0;
                RegWre = 1'b0;
                mRD = 1'b0;
                mWR = 1'b1;
                RegDst = 1'b0;
                ExtSel = 1'b1;
                PCSrc = 2'b00;
                ALUOp = 3'b000;
            end
            6'b110000: begin // BEQ
                PCWre = 1'b1;
                ALUSrcA = 1'b0;
                ALUSrcB = 1'b0;
                DBDataSrc = 1'b0;
                RegWre = 1'b0;
                mRD = 1'b0;
                mWR = 1'b0;
                RegDst = 1'b0;
                ExtSel = 1'b1;
                PCSrc = zero ? 2'b01 : 2'b00;
                ALUOp = 3'b001;
            end
            6'b110001: begin // BNE
                PCWre = 1'b1;
                ALUSrcA = 1'b0;
                ALUSrcB = 1'b0;
                DBDataSrc = 1'b0;
                RegWre = 1'b0;
                mRD = 1'b0;
                mWR = 1'b0;
                RegDst = 1'b0;
                ExtSel = 1'b1;
                PCSrc = zero ? 2'b00 : 2'b01;
                ALUOp = 3'b001;
            end
            6'b111000: begin // J
                PCWre = 1'b1;
                ALUSrcA = 1'b0;
                ALUSrcB = 1'b0;
                DBDataSrc = 1'b0;
                RegWre = 1'b0;
                mRD = 1'b0;
                mWR = 1'b0;
                RegDst = 1'b0;
                ExtSel = 1'b0;
                PCSrc = 2'b10;
                ALUOp = 3'b000;
            end
            6'b111111: begin // HALT
                PCWre = 1'b0;
                ALUSrcA = 1'b0;
                ALUSrcB = 1'b0;
                DBDataSrc = 1'b0;
                RegWre = 1'b0;
                mRD = 1'b0;
                mWR = 1'b0;
                RegDst = 1'b0;
                ExtSel = 1'b0;
                PCSrc = 2'b00;
                ALUOp = 3'b000;
            end
            default: begin // Default case
                PCWre = 1'b1;
                ALUSrcA = 1'b0;
                ALUSrcB = 1'b0;
                DBDataSrc = 1'b0;
                RegWre = 1'b0;
                mRD = 1'b0;
                mWR = 1'b0;
                RegDst = 1'b0;
                ExtSel = 1'b0;
                PCSrc = 2'b00;
                ALUOp = 3'b000;
            end
        endcase
    end
endmodule

