module ptngen_axi4s #(
    parameter AXI4S_DATA_WIDTH = 32,
    parameter X_NUM = 640,
    parameter Y_NUM = 480
) (
    input wire aresetn,
    input wire aclk,
    input wire m_axi4s_tready,
    output wire m_axi4s_tuser,
    output wire m_axi4s_tlast,
    output wire [AXI4S_DATA_WIDTH-1:0] m_axi4s_tdata,
    output wire m_axi4s_tvalid
);

    localparam X_WIDTH = $clog2(X_NUM);
    localparam Y_WIDTH = $clog2(Y_NUM);

    reg [X_WIDTH-1:0] x_count;
    reg [Y_WIDTH-1:0] y_count;
    wire cke;

    assign cke = m_axi4s_tready || !m_axi4s_tvalid;
    assign m_axi4s_tvalid = 1'b1;
    assign m_axi4s_tuser = (x_count == 0) && (y_count == 0);
    assign m_axi4s_tlast = (x_count == X_NUM - 1);
    assign m_axi4s_tdata = {y_count, {(AXI4S_DATA_WIDTH/2-Y_WIDTH){1'b0}}, x_count, {(AXI4S_DATA_WIDTH/2-X_WIDTH){1'b0}}};

    always @(posedge aclk or negedge aresetn) begin
        if (!aresetn) begin
            x_count <= 0;
            y_count <= 0;
        end else if (cke) begin
            if (x_count == X_NUM - 1) begin
                x_count <= 0;
                if (y_count == Y_NUM - 1) begin
                    y_count <= 0;
                end else begin
                    y_count <= y_count + 1;
                end
            end else begin
                x_count <= x_count + 1;
            end
        end
    end

endmodule

