module HazardDetection (
    input [4:0] R1, R2, WBWriteReg, MEWriteReg, EXWriteReg,
    input [3:0] IDType,
    input EXMemRead, MEMemRead,
    input IDCompare, IDPCSrc,
    input EXRegWrite, MERegWrite, WBRegWrite,
    output reg IFIDWrite, PCWrite,
    output reg [1:0] RD1Haz, RD2Haz,
    output reg flush
);

    // Forwarding and flush control
    always @(*) begin
        // Default values
        RD1Haz = 2'b00;
        RD2Haz = 2'b00;
        flush = 1'b0;

        // Forwarding logic for R1
        if (R1 != 5'b0) begin
            if (R1 == WBWriteReg && WBRegWrite)
                RD1Haz = 2'b01;
            else if (R1 == MEWriteReg && MERegWrite)
                RD1Haz = 2'b10;
        end

        // Forwarding logic for R2
        if (R2 != 5'b0) begin
            if (R2 == WBWriteReg && WBRegWrite)
                RD2Haz = 2'b01;
            else if (R2 == MEWriteReg && MERegWrite)
                RD2Haz = 2'b10;
        end

        // Control hazard detection
        if ((IDType == 4'b1010 || IDType == 4'b1000) && IDPCSrc && IDCompare)
            flush = 1'b1;
    end

    // Stall control
    always @(*) begin
        // Default values
        IFIDWrite = 1'b1;
        PCWrite = 1'b1;

        // Load-use hazard detection
        if (EXMemRead && 
            ((IDType == 4'b0111 || IDType == 4'b0011 || IDType == 4'b1000) &&
             (EXWriteReg == R1 || EXWriteReg == R2))) begin
            IFIDWrite = 1'b0;
            PCWrite = 1'b0;
        end

        // Additional stall conditions
        if (MEMemRead && 
            ((IDType == 4'b0111 || IDType == 4'b0011 || IDType == 4'b1000) &&
             (MEWriteReg == R1 || MEWriteReg == R2))) begin
            IFIDWrite = 1'b0;
            PCWrite = 1'b0;
        end
    end

endmodule

