module circuito_superamostragem(
input wire clock,
input wire reset,
input wire tick,
input wire load,
output wire habilita_circuito
);
parameter [31:0] M=16;
// para transmissao de 110 bauds com gerador de tick 16 * 110 Hz
reg [31:0] contagem; wire [31:0] prox_contagem;
reg prox_enable;
  always @(posedge clock, posedge reset) begin
    if((reset == 1'b1)) begin
      contagem <= 0;
    end else begin
      if(tick == 1'b1) begin
        if(load == 1'b1) begin
          contagem <= M / 2;
        end
        else begin
          contagem <= prox_contagem;
        end
      end
      if(prox_enable == 1'b0) begin
        if(((contagem == (M - 1)) && (tick == 1'b1))) begin
          prox_enable <= 1'b1;
        end
      end
      else begin
        prox_enable <= 1'b0;
      end
    end
  end
  // logica de proximo estado
  assign prox_contagem = contagem == (M - 1) ? 0 : contagem + 1;
  // logica de saida
  assign habilita_circuito = prox_enable;
endmodule

