module SEG_decoder_4_8(
    input [7:0] dig,
    input rst,
    input [3:0] num,
    output reg [7:0] seg
);

    always @(dig or rst) begin
        if (!rst) begin
            seg = 8'b1111_1111; // All segments off
        end else begin
            case (num)
                4'd0: seg[6:0] = 7'b1000000;
                4'd1: seg[6:0] = 7'b1111001;
                4'd2: seg[6:0] = 7'b0100100;
                4'd3: seg[6:0] = 7'b0110000;
                4'd4: seg[6:0] = 7'b0011001;
                4'd5: seg[6:0] = 7'b0010010;
                4'd6: seg[6:0] = 7'b0000010;
                4'd7: seg[6:0] = 7'b1111000;
                4'd8: seg[6:0] = 7'b0000000;
                4'd9: seg[6:0] = 7'b0010000;
                default: seg[6:0] = 7'b1111111; // All segments off
            endcase

            // Control decimal point
            seg[7] = (dig == 8'b1111_1101) ? 1'b0 : 1'b1;
        end
    end

endmodule

