module fifo_16x8 (
    input wire clk,
    input wire rst_n,
    input wire wr,
    input wire rd,
    input wire [7:0] din,
    output reg [7:0] dout,
    output reg full,
    output reg empty
);

    reg [7:0] mem [0:15];
    reg [3:0] wp, rp;
    reg [4:0] count;

    // Write pointer logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            wp <= 4'b0000;
        else if (wr && !full)
            wp <= wp + 1'b1;
    end

    // Read pointer logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            rp <= 4'b0000;
        else if (rd && !empty)
            rp <= rp + 1'b1;
    end

    // Data write logic
    always @(posedge clk) begin
        if (wr && !full)
            mem[wp] <= din;
    end

    // Data read logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            dout <= 8'b0;
        else if (rd && !empty)
            dout <= mem[rp];
    end

    // FIFO count logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            count <= 5'b0;
        else if (wr && !rd && !full)
            count <= count + 1'b1;
        else if (rd && !wr && !empty)
            count <= count - 1'b1;
    end

    // Full flag logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            full <= 1'b0;
        else
            full <= (count == 5'd15);
    end

    // Empty flag logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            empty <= 1'b1;
        else
            empty <= (count == 5'd0);
    end

endmodule

