module clk2Hz(
input wire CLK_IN,
input wire RST,
output wire CLK_OUT
);
reg clkdv = 1'b0;
reg [31:0] counter = 0;
  always @(posedge RST, posedge CLK_IN) begin
    if((RST == 1'b1)) begin
      clkdv <= 1'b0;
      counter <= 0;
    end else begin
      if((counter == 50000000)) begin
        if((clkdv == 1'b0)) begin
          clkdv <= 1'b1;
        end
        else begin
          clkdv <= 1'b0;
        end
        counter <= 0;
      end
      else begin
        counter <= counter + 1;
      end
    end
  end
  assign CLK_OUT = clkdv;
endmodule

