module FSMctrl(
input wire CLK,
input wire RST,
input wire ENTER,
input wire [1:0] Operacao,
output reg [1:0] Selecao,
output reg Enable_1,
output reg Enable_2
);
//ARCHITECTURE
parameter [2:0]
  S0 = 0,
  S1 = 1,
  S2 = 2,
  S3 = 3,
  S4 = 4,
  S5 = 5,
  S6 = 6,
  S7 = 7;
reg [2:0] EA; reg [2:0] PE;
wire clock;
wire reset;
  assign clock = CLK;
  always @(posedge clock, posedge reset) begin
    if(reset == 1'b0) begin
      EA <= S0;
    end else begin
      EA <= PE;
    end
  end
  always @(EA, ENTER, Operacao) begin
    case(EA)
    S0 : begin
      if(Enter == 1'b1) begin
        PE <= S0;
      end
      else begin
        PE <= S1;
      end
      Enable_1 <= 1'b0;
      Enable_2 <= 1'b0;
    end
    S1 : begin
      if(Enter == 1'b0) begin
        PE <= S1;
      end
      else begin
        PE <= S2;
      end
      Enable_1 <= 1'b1;
      Enable_2 <= 1'b0;
    end
    S2 : begin
      Enable_1 <= 1'b0;
      Enable_2 <= 1'b0;
      if(Operacao == 2'b00) begin
        PE <= S3;
      end
      else if(Operacao == 2'b01) begin
        PE <= S4;
      end
      else if(Operacao == 2'b10) begin
        PE <= S5;
      end
      else if(Operacao == 2'b11) begin
        PE <= S6;
      end
    end
    S3 : begin
      Selecao <= 2'b00;
      if(Enter == 1'b1) begin
        PE <= S3;
      end
      else begin
        PE <= S7;
      end
    end
    S4 : begin
      Selecao <= 2'b01;
      if(Enter == 1'b1) begin
        PE <= S4;
      end
      else begin
        PE <= S7;
      end
    end
    S5 : begin
      Enable_1 <= 1'b1;
      Enable_2 <= 1'b1;
      Selecao <= 2'b10;
      PE <= S0;
    end
    S6 : begin
      Enable_1 <= 1'b1;
      Enable_2 <= 1'b1;
      Selecao <= 2'b11;
      PE <= S0;
    end
    S7 : begin
      Enable_1 <= 1'b0;
      Enable_2 <= 1'b1;
      PE <= S0;
    end
    endcase
  end
endmodule

module DataMemory (
    input [31:0] DPC,
    input clk,
    input reset,
    input [31:0] dmAd,
    input MemWr_M,
    input [31:0] DIn_M,
    output [31:0] DO_M
);

    reg [31:0] datamemory [0:1023];
    integer i;

    // Initialization
    initial begin
        for (i = 0; i < 1024; i = i + 1) begin
            datamemory[i] = 32'b0;
        end
    end

    // Reset behavior
    always @(posedge reset) begin
        for (i = 0; i < 1024; i = i + 1) begin
            datamemory[i] <= 32'b0;
        end
    end

    // Write operation
    always @(posedge clk) begin
        if (MemWr_M) begin
            datamemory[dmAd[11:2]] <= DIn_M;
            $display("Time: %t, DPC: %h, Write Address: %h, Data: %h", $time, DPC, dmAd, DIn_M);
        end
    end

    // Read operation (asynchronous)
    assign DO_M = datamemory[dmAd[11:2]];

endmodule

module CD_COUNTER(
input wire CLK,
input wire RESET,
input wire xoff,
input wire COUNT_ENA,
input wire [2:0] MAX_COUNT,
output wire [11:0] count_out,
output wire truncate_data
);
// high only when data is sent (not counting header and trailers)
// (15 downto 0);
//---
reg [11:0] count_sig = 1'b0;
wire max_mark; wire max_ena;
  //
  assign max_ena = (MAX_COUNT == 3'b000) ? 1'b0 : 1'b1;
  // when max count is 0x0, no chunk length limit is set  
  assign max_mark = ((count_sig[11:9] == MAX_COUNT) && (max_ena == 1'b1)) ? 1'b1 : 1'b0;
  // stays high until reset
  //
  always @(posedge RESET, posedge CLK) begin
    if(RESET == 1'b1) begin
      count_sig <= {12{1'b0}};
    end else begin
      if((COUNT_ENA == 1'b1 && max_mark == 1'b0)) begin
        count_sig <= count_sig + 1;
        // keeps the final value until reset
      end
    end
  end
  //
  assign truncate_data = max_mark | xoff;
  assign count_out = count_sig;
    //
endmodule

