module rotate_mix_nibbles(
input wire [63:0] data_in,
output wire [63:0] data_out
);
wire [63:0] rotated;
wire [63:0] mix_mul_in; wire [63:0] mix_mul_out;
  assign rotated = {data_in[47:0],data_in[63:48]};
  // MixNibbles algorithm inspired from
  // https://link.springer.com/chapter/10.1007/978-3-642-25578-6_11
  assign mix_mul_in[63:56] = rotated[63:56] ^ rotated[55:48];
  assign mix_mul_in[55:48] = rotated[55:48] ^ rotated[47:40];
  assign mix_mul_in[47:40] = rotated[47:40] ^ rotated[39:32];
  assign mix_mul_in[39:32] = rotated[39:32] ^ rotated[63:56];
  assign mix_mul_in[31:24] = rotated[31:24] ^ rotated[23:16];
  assign mix_mul_in[23:16] = rotated[23:16] ^ rotated[15:8];
  assign mix_mul_in[15:8] = rotated[15:8] ^ rotated[7:0];
  assign mix_mul_in[7:0] = rotated[7:0] ^ rotated[31:24];
  genvar i;
  generate for (i=0; i <= 7; i = i + 1) begin: MUL
      mul_poly MX(
          .data_in(mix_mul_in[63 - (8 * i):63 - (8 * i) - 7]),
      .data_out(mix_mul_out[63 - (8 * i):63 - (8 * i) - 7]));
  end
  endgenerate
  assign data_out[63:56] = mix_mul_out[63:56] ^ mix_mul_in[55:48] ^ rotated[39:32];
  assign data_out[55:48] = mix_mul_out[55:48] ^ mix_mul_in[47:40] ^ rotated[63:56];
  assign data_out[47:40] = mix_mul_out[47:40] ^ mix_mul_in[63:56] ^ rotated[39:32];
  assign data_out[39:32] = mix_mul_out[39:32] ^ mix_mul_in[63:56] ^ rotated[47:40];
  assign data_out[31:24] = mix_mul_out[31:24] ^ mix_mul_in[23:16] ^ rotated[7:0];
  assign data_out[23:16] = mix_mul_out[23:16] ^ mix_mul_in[15:8] ^ rotated[31:24];
  assign data_out[15:8] = mix_mul_out[15:8] ^ mix_mul_in[31:24] ^ rotated[7:0];
  assign data_out[7:0] = mix_mul_out[7:0] ^ mix_mul_in[31:24] ^ rotated[15:8];
endmodule

module MUX8to1(
input wire [2:0] SEL,
input wire [7:0] DATA,
output reg OUTPUT
);
wire [2:0] SEL1;
  assign SEL1 = SEL - 2;
  always @(*) begin
    case(SEL1)
      3'b000 : OUTPUT <= DATA[7];
      3'b001 : OUTPUT <= DATA[6];
      3'b010 : OUTPUT <= DATA[5];
      3'b011 : OUTPUT <= DATA[4];
      3'b100 : OUTPUT <= DATA[3];
      3'b101 : OUTPUT <= DATA[2];
      3'b110 : OUTPUT <= DATA[1];
      3'b111 : OUTPUT <= DATA[0];
      default : OUTPUT <= 1'b0;
    endcase
  end
endmodule

