    input wire i_we,
    input wire [WIDTH-1:0] i_d,
    output reg [WIDTH-1:0] o_q
);

    always @(posedge i_clk or negedge i_arstn) begin
        if (!i_arstn) begin
            o_q <= {WIDTH{1'b0}};
        end else if (!i_srstn) begin
            o_q <= {WIDTH{1'b0}};
        end else if (i_we) begin
            o_q <= i_d;
        end
    end

endmodule

