module noekeon_loop(
input wire clk,
input wire rst,
input wire enc,
input wire [31:0] a_0_in,
input wire [31:0] a_1_in,
input wire [31:0] a_2_in,
input wire [31:0] a_3_in,
input wire [31:0] k_0_in,
input wire [31:0] k_1_in,
input wire [31:0] k_2_in,
input wire [31:0] k_3_in,
output wire [31:0] a_0_out,
output wire [31:0] a_1_out,
output wire [31:0] a_2_out,
output wire [31:0] a_3_out
);
// (enc, 0) / (dec, 1)
wire [7:0] rc_s;
wire [31:0] rc_ext_s;
wire [7:0] rc_2_s;
wire [31:0] rc_2_ext_s;
reg [31:0] a_0_in_s;
reg [31:0] a_1_in_s;
reg [31:0] a_2_in_s;
reg [31:0] a_3_in_s;
reg [31:0] out_t_a_0_in_s;
reg [31:0] out_t_a_1_in_s;
reg [31:0] out_t_a_2_in_s;
reg [31:0] out_t_a_3_in_s;
wire [31:0] a_0_out_s;
wire [31:0] a_1_out_s;
wire [31:0] a_2_out_s;
wire [31:0] a_3_out_s;
wire [31:0] stage_0_a_0_out_s;
wire [31:0] stage_0_a_1_out_s;
wire [31:0] stage_0_a_2_out_s;
wire [31:0] stage_0_a_3_out_s;
wire [31:0] k_0_d_s;
wire [31:0] k_1_d_s;
wire [31:0] k_2_d_s;
wire [31:0] k_3_d_s;
wire [31:0] k_0_mux_s;
wire [31:0] k_1_mux_s;
wire [31:0] k_2_mux_s;
wire [31:0] k_3_mux_s;
wire [71:0] init_val_shr_0;
wire [71:0] init_val_shr_1;
  assign init_val_shr_0 = 72'h8036d84d2fbcc635d4;
  assign init_val_shr_1 = 72'h1b6cab9a5e63976ad4;
  rc_shr RC_SHR_0(
      clk,
    rst,
    init_val_shr_0,
    rc_s);
  rc_shr RC_SHR_1(
      clk,
    rst,
    init_val_shr_1,
    rc_2_s);
  assign rc_ext_s = {24'h000000,rc_s};
  assign rc_2_ext_s = {24'h000000,rc_2_s};
  round_f ROUND_F_0(
      enc,
    rc_ext_s,
    a_0_in_s,
    a_1_in_s,
    a_2_in_s,
    a_3_in_s,
    k_0_mux_s,
    k_1_mux_s,
    k_2_mux_s,
    k_3_mux_s,
    stage_0_a_0_out_s,
    stage_0_a_1_out_s,
    stage_0_a_2_out_s,
    stage_0_a_3_out_s);
  round_f ROUND_F_1(
      enc,
    rc_2_ext_s,
    stage_0_a_0_out_s,
    stage_0_a_1_out_s,
    stage_0_a_2_out_s,
    stage_0_a_3_out_s,
    k_0_mux_s,
    k_1_mux_s,
    k_2_mux_s,
    k_3_mux_s,
    a_0_out_s,
    a_1_out_s,
    a_2_out_s,
    a_3_out_s);
  always @(posedge clk, posedge rst, posedge enc) begin
    if(rst == 1'b1) begin
      a_0_in_s <= a_0_in;
      a_1_in_s <= a_1_in;
      a_2_in_s <= a_2_in;
      a_3_in_s <= a_3_in;
    end
    else begin
      a_0_in_s <= a_0_out_s;
      a_1_in_s <= a_1_out_s;
      a_2_in_s <= a_2_out_s;
      a_3_in_s <= a_3_out_s;
    end
  end
  // Key decryption as k' = theta(0, k)
  // This is the key required for decryption
  // in NOEKEON
  theta THETA_DECRYPT_0(
      k_0_in,
    k_1_in,
    k_2_in,
    k_3_in,
    {broken{0}},
    {broken{0}},
    {broken{0}},
    {broken{0}},
    k_0_d_s,
    k_1_d_s,
    k_2_d_s,
    k_3_d_s);
  // These multiplexers select the key that is used
  // in each mode i.e. during decryption the key generated
  // as k' = theta(0, k) (THETA_DECRYPT_0) is utilized.
  assign k_0_mux_s = enc == 1'b0 ? k_0_in : k_0_d_s;
  assign k_1_mux_s = enc == 1'b0 ? k_1_in : k_1_d_s;
  assign k_2_mux_s = enc == 1'b0 ? k_2_in : k_2_d_s;
  assign k_3_mux_s = enc == 1'b0 ? k_3_in : k_3_d_s;
  always @(posedge clk, posedge rst, posedge a_0_out_s, posedge a_1_out_s, posedge a_2_out_s, posedge a_3_out_s) begin
    out_t_a_0_in_s <= a_0_out_s;
    out_t_a_1_in_s <= a_1_out_s;
    out_t_a_2_in_s <= a_2_out_s;
    out_t_a_3_in_s <= a_3_out_s;
  end
  // This component performs the last operation
  // with theta.
  output_trans OUT_TRANS_0(
      clk,
    enc,
    rc_ext_s,
    out_t_a_0_in_s,
    out_t_a_1_in_s,
    out_t_a_2_in_s,
    out_t_a_3_in_s,
    k_0_mux_s,
    k_1_mux_s,
    k_2_mux_s,
    k_3_mux_s,
    a_0_out,
    a_1_out,
    a_2_out,
    a_3_out);
endmodule

module register_file (
    input wire clock,
    input wire reset,
    input wire wEn,
    input wire [31:0] write_data,
    input wire [4:0] read_sel1,
    input wire [4:0] read_sel2,
    input wire [4:0] write_sel,
    output wire [31:0] read_data1,
    output wire [31:0] read_data2
);

    reg [31:0] registers [31:0];
    integer i;

    // Asynchronous reset
    always @(posedge clock or posedge reset) begin
        if (reset) begin
            for (i = 1; i < 32; i = i + 1) begin
                registers[i] <= 32'b0;
            end
        end else if (wEn && write_sel != 5'b00000) begin
            registers[write_sel] <= write_data;
        end
    end

    // Read operations
    assign read_data1 = (read_sel1 == 5'b00000) ? 32'b0 : registers[read_sel1];
    assign read_data2 = (read_sel2 == 5'b00000) ? 32'b0 : registers[read_sel2];

    // Ensure register 0 is always 0
    always @(*) begin
        registers[0] = 32'b0;
    end

endmodule

module BMG_TB(
input wire CLK_IN,
input wire CLKB_IN,
input wire RESET_IN,
output reg [8:0] STATUS
);
//ERROR STATUS OUT OF FPGA
wire CLKA = 1'b0;
wire RSTA = 1'b0;
wire [0:0] WEA = 1'b0;
wire [9:0] ADDRA = 1'b0;
wire [255:0] DINA = 1'b0;
wire [255:0] DOUTA;
wire CLKB = 1'b0;
wire RSTB = 1'b0;
wire [0:0] WEB = 1'b0;
wire [14:0] ADDRB = 1'b0;
wire [7:0] DINB = 1'b0;
wire [7:0] DOUTB;
wire CHECKER_EN = 1'b0;
wire [1:0] CHECK_DATA_TDP = 1'b0;
reg [22:0] STIMULUS_FLOW = 1'b0;
wire clk_in_i;
reg RESET_SYNC_R1;
reg RESET_SYNC_R2;
reg RESET_SYNC_R3;
wire clkb_in_i;
reg RESETB_SYNC_R1;
reg RESETB_SYNC_R2;
reg RESETB_SYNC_R3;
wire ITER_R0 = 1'b0;
wire ITER_R1 = 1'b0;
wire ITER_R2 = 1'b0;
wire [7:0] ISSUE_FLAG = 1'b0;
reg [7:0] ISSUE_FLAG_STATUS = 1'b0;
  bufg clk_buf(
      .i(CLK_IN),
    .o(clk_in_i));
  assign CLKA = clk_in_i;
  bufg clkb_buf(
      .i(CLKB_IN),
    .o(clkb_in_i));
  assign CLKB = clkb_in_i;
  assign RSTA = RESET_IN;
  always @(posedge clk_in_i) begin
    RESET_SYNC_R1 <= RESET_IN;
    RESET_SYNC_R2 <= RESET_SYNC_R1;
    RESET_SYNC_R3 <= RESET_SYNC_R2;
  end
  assign RSTB = RESET_IN;
  always @(posedge clkb_in_i) begin
    RESETB_SYNC_R1 <= RESET_IN;
    RESETB_SYNC_R2 <= RESETB_SYNC_R1;
    RESETB_SYNC_R3 <= RESETB_SYNC_R2;
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      ISSUE_FLAG_STATUS <= {8{1'b0}};
    end
    else begin
      ISSUE_FLAG_STATUS <= ISSUE_FLAG_STATUS | ISSUE_FLAG;
    end
  end
  assign STATUS[7:0] = ISSUE_FLAG_STATUS;
  CHECKER #(
      .WRITE_WIDTH(256),
    .READ_WIDTH(256))
  BMG_DATA_CHECKER_INST_A(
      .CLK(CLKA),
    .RST(RSTA),
    .EN(CHECK_DATA_TDP[0]),
    .DATA_IN(DOUTA),
    .STATUS(ISSUE_FLAG[0]));
  CHECKER #(
      .WRITE_WIDTH(8),
    .READ_WIDTH(8))
  BMG_DATA_CHECKER_INST_B(
      .CLK(CLKB),
    .RST(RSTB),
    .EN(CHECK_DATA_TDP[1]),
    .DATA_IN(DOUTB),
    .STATUS(ISSUE_FLAG[1]));
  BMG_STIM_GEN BMG_STIM_GEN_INST(
      .CLKA(CLKA),
    .CLKB(CLKB),
    .TB_RST(RSTA),
    .ADDRA(ADDRA),
    .DINA(DINA),
    .WEA(WEA),
    .WEB(WEB),
    .ADDRB(ADDRB),
    .DINB(DINB),
    .CHECK_DATA(CHECK_DATA_TDP));
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STATUS[8] <= 1'b0;
      iter_r2 <= 1'b0;
      iter_r1 <= 1'b0;
      iter_r0 <= 1'b0;
    end
    else begin
      STATUS[8] <= iter_r2;
      iter_r2 <= iter_r1;
      iter_r1 <= iter_r0;
      iter_r0 <= STIMULUS_FLOW[8];
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STIMULUS_FLOW <= {23{1'b0}};
    end
    else if((WEA[0] == 1'b1)) begin
      STIMULUS_FLOW <= STIMULUS_FLOW + 1;
    end
  end
  RAM_WRITE_top BMG_PORT(
      //Port A
    .WEA(WEA),
    .ADDRA(ADDRA),
    .DINA(DINA),
    .DOUTA(DOUTA),
    .CLKA(CLKA),
    //Port B
    .WEB(WEB),
    .ADDRB(ADDRB),
    .DINB(DINB),
    .DOUTB(DOUTB),
    .CLKB(CLKB));
endmodule

