module UC_receptor(
input wire CLOCK,
input wire RESET,
input wire LIGA,
input wire CD,
output reg DTR,
output reg enable_recepcao,
output reg [1:0] dep_estado
);
parameter [1:0]
  INICIAL = 0,
  LIGADO = 1,
  RECEBENDO = 2;
reg [1:0] estado;
  always @(posedge LIGA, posedge RESET, posedge CLOCK, posedge estado) begin
    if(RESET == 1'b1) begin
      estado <= INICIAL;
    end else begin
      case(estado)
      INICIAL : begin
        if(LIGA == 1'b1) begin
          estado <= LIGADO;
        end
      end
      LIGADO : begin
        if(LIGA == 1'b1 && CD == 1'b1) begin
          estado <= RECEBENDO;
        end
        else if(LIGA == 1'b0) begin
          estado <= INICIAL;
        end
      end
      RECEBENDO : begin
        if(LIGA == 1'b0) begin
          estado <= INICIAL;
        end
        else if(CD == 1'b0) begin
          estado <= LIGADO;
        end
      end
      endcase
    end
  end
  always @(estado) begin
    case(estado)
    INICIAL : begin
      dep_estado <= 2'b00;
      DTR <= 1'b0;
      enable_recepcao <= 1'b0;
    end
    LIGADO : begin
      dep_estado <= 2'b01;
      DTR <= 1'b1;
      enable_recepcao <= 1'b0;
    end
    RECEBENDO : begin
      dep_estado <= 2'b10;
      DTR <= 1'b1;
      enable_recepcao <= 1'b1;
    end
    endcase
  end
endmodule

