module uart_tx #(
    parameter clk_speed = 100_000_000,  // 100MHz
    parameter baud_rate = 115_200,
    parameter clks_per_bit = clk_speed / baud_rate
) (
    input wire clk,
    input wire bufferEmpty,
    input wire [7:0] tx_byte,
    output reg tx_out,
    output reg read_buffer,
    output reg [2:0] state
);

    // States
    localparam IDLE = 3'd0,
               TX_START_BIT = 3'd1,
               TX_DATA_BITS = 3'd2,
               TX_STOP_BIT = 3'd3,
               CLEANUP = 3'd4;

    reg [$clog2(clks_per_bit)-1:0] clock_count;
    reg [2:0] bit_index;
    reg [7:0] tx_data;

    always @(posedge clk) begin
        case (state)
            IDLE: begin
                tx_out <= 1'b1;
                read_buffer <= 1'b0;
                clock_count <= 0;
                bit_index <= 0;

                if (!bufferEmpty) begin
                    state <= TX_START_BIT;
                    tx_data <= tx_byte;
                    read_buffer <= 1'b1;
                end else begin
                    state <= IDLE;
                end
            end

            TX_START_BIT: begin
                tx_out <= 1'b0;
                read_buffer <= 1'b0;

                if (clock_count < clks_per_bit - 1) begin
                    clock_count <= clock_count + 1;
                    state <= TX_START_BIT;
                end else begin
                    clock_count <= 0;
                    state <= TX_DATA_BITS;
                end
            end

            TX_DATA_BITS: begin
                tx_out <= tx_data[bit_index];

                if (clock_count < clks_per_bit - 1) begin
                    clock_count <= clock_count + 1;
                    state <= TX_DATA_BITS;
                end else begin
                    clock_count <= 0;

                    if (bit_index < 7) begin
                        bit_index <= bit_index + 1;
                        state <= TX_DATA_BITS;
                    end else begin
                        bit_index <= 0;
                        state <= TX_STOP_BIT;
                    end
                end
            end

            TX_STOP_BIT: begin
                tx_out <= 1'b1;

                if (clock_count < clks_per_bit - 1) begin
                    clock_count <= clock_count + 1;
                    state <= TX_STOP_BIT;
                end else begin
                    clock_count <= 0;
                    state <= CLEANUP;
                end
            end

            CLEANUP: begin
                state <= IDLE;
            end

            default: begin
                state <= IDLE;
            end
        endcase
    end

endmodule

