module control(
input wire [5:0] Opcode,
output wire flush,
input wire flushP,
input wire Zero,
input wire LessThanZero,
output wire RegDst,
output wire ALUSrc,
output wire MemtoReg,
output wire RegWrite,
output wire MemRead,
output wire MemWrite,
output wire Branch,
output wire BranchLessThanZero,
output wire [1:0] ALUop,
input wire clock,
input wire reset
);
wire R_format; wire Lw; wire Sw; wire Beq; wire Blt; wire Addi;
  // Code to generate control signals using opcode bits
  assign R_format = Opcode == 6'b000000 ? 1'b1 : 1'b0;
  assign Lw = Opcode == 6'b100011 ? 1'b1 : 1'b0;
  assign Sw = Opcode == 6'b101011 ? 1'b1 : 1'b0;
  assign Beq = Opcode == 6'b000100 ? 1'b1 : 1'b0;
  assign Blt = Opcode == 6'b000110 ? 1'b1 : 1'b0;
  assign Addi = Opcode == 6'b001000 ? 1'b1 : 1'b0;
  assign RegDst = R_format;
  //OR Addi;
  assign ALUSrc = Lw | Sw | Addi;
  assign MemtoReg = flushP == 1'b0 ? Lw : 1'b0;
  assign RegWrite = flushP == 1'b0 ? R_format | Lw | Addi : 1'b0;
  assign MemRead = flushP == 1'b0 ? Lw : 1'b0;
  assign MemWrite = flushP == 1'b0 ? Sw : 1'b0;
  assign Branch = flushP == 1'b0 ? Beq : 1'b0;
  assign BranchLessThanZero = flushP == 1'b0 ? Blt : 1'b0;
  assign ALUOp[1] = R_format;
  assign ALUOp[0] = Beq | Blt;
  //Backup: ALUOp( 0 ) 	<=  Beq ; 
  assign flush = (flushP == 1'b0) && ((((Beq == 1'b1) && (Zero == 1'b1)) || ((BLt == 1'b1) && (LessThanZero == 1'b1)))) ? 1'b1 : 1'b0;
endmodule

module somaSub(
input wire [2:0] A,
input wire [2:0] B,
input wire sel,
output wire [2:0] S,
output wire E
);
reg [2:0] aux;
reg c;
reg c2;
reg ccomp;
reg over;
reg igua;
reg [2:0] comp1;
reg [2:0] comp2;
  always @(a, b, sel, c, c2, comp1, comp2, ccomp, aux, igua) begin
    // Soma
    if((sel == 1'b0)) begin
      aux[0] <= a[0] ^ b[0];
      c <= a[0] & b[0];
      aux[1] <= a[1] ^ b[1] ^ c;
      aux[2] <= (a[1] & b[1]) | (a[1] & c) | (b[1] & c);
      igua <=  ~(a[0] ^ b[0]);
      over <= c & igua;
      //subtrai
    end
    else begin
      // Aplica complemento de 1 no B
      comp1 <= b ^ 3'b111;
      // Aplica complemento de 2 no B
      comp2[0] <= comp1[0] ^ 1'b1;
      ccomp <= comp1[0] & 1'b1;
      comp2[1] <= comp1[1] ^ ccomp;
      comp2[2] <= (comp1[1] & 1'b1) | (comp1[1] & ccomp) | (1'b1 & ccomp);
      // Faz a soma
      aux[0] <= a[0] ^ comp2[0];
      c2 <= (a[0] & comp2[0]) | (a[0] & ccomp) | (comp2[0] & ccomp);
      aux[1] <= a[1] ^ comp2[1] ^ c2;
      aux[2] <= (a[1] & comp2[1]) | (a[1] & c2);
      igua <=  ~(a[0] ^ comp2[0]);
      over <= c2 & igua;
    end
  end
  assign e = over;
  assign s = aux;
endmodule

module periferico_io(
input wire reset,
input wire clk,
input wire read_en,
input wire write_en,
input wire [31:0] address,
input wire [31:0] dato_bus_i,
output wire [31:0] dato_bus_o,
inout wire [7:0] dato_inout
);
//señales de habilitación para la lectura y escritura en los periféricos
//dirección del periférico mapeada en el espacio de direcciones
//dato de entrada al periférico desde el bus
//dato de salida del periférico hacia el bus
//conexión del periférico hacia el exterior
reg [31:0] config_perif;
reg [7:0] reg_salida; reg [7:0] reg_entrada;
  // configuración del periferico
  always @(negedge clk, negedge reset) begin
    if(reset == 1'b1) begin
      config_perif <= {32{1'b0}};
    end else begin
      if(write_en == 1'b1) begin
        //La dirección terminada en 0 es el puerto de config
        if(address[3:0] == 4'h0) begin
          config_perif <= dato_bus_i;
        end
      end
    end
  end
  // config_perif = 00000002 lectura
  // config_perif = 00000004 escritura
  // config_perif = 0000000X no inicializado
  //Si el periferico se usa de entrada
  always @(negedge clk, negedge reset) begin
    if(reset == 1'b1) begin
      reg_entrada <= {8{1'b0}};
    end else begin
      if(read_en == 1'b1) begin
        if(address[3:0] == 4'h4) begin
          if(config_perif[3:0] == 4'h2) begin
            // si config como lectura
            //se almacena el dato dentro del periferico
            reg_entrada <= dato_inout;
          end
        end
      end
    end
  end
  assign dato_bus_o = {24'h000000,reg_entrada};
  //se saca el dato hacia el bus
  //Si el periferico se usa de salida
  always @(negedge clk, negedge reset) begin
    if(reset == 1'b1) begin
      reg_salida <= {8{1'b0}};
    end else begin
      if(write_en == 1'b1) begin
        if(address[3:0] == 4'h4) begin
          if(config_perif[3:0] == 4'h4) begin
            // config como escritura
            //se almacena el dato dentro del periferico. Solo 8 bits
            reg_salida <= dato_bus_i[7:0];
          end
        end
      end
    end
  end
  //se saca el dato cuando es de salida, sino se deja a alta impedancia
  assign dato_inout = config_perif[3:0] == 4'h4 ? reg_salida : {8{1'bZ}};
endmodule

module ps4 (
    input [3:0] req,
    input en,
    output reg [3:0] gnt
);

always @* begin
    if (!en) begin
        gnt = 4'b0000;
    end else begin
        casez (req)
            4'b1???: gnt = 4'b1000;
            4'b01??: gnt = 4'b0100;
            4'b001?: gnt = 4'b0010;
            4'b0001: gnt = 4'b0001;
            default: gnt = 4'b0000;
        endcase
    end
end

endmodule

module add_601(
output wire [26:0] result,
input wire [26:0] in_a,
input wire [26:0] in_b
);
wire [28:0] carry_inA;
wire [28:0] carry_inB;
wire [28:0] carry_res;
  // To handle the CI input, the operation is '1' + CI
  // If CI is not present, the operation is '1' + '0'
  assign carry_inA = {1'b0,in_a,1'b1};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) + (carry_inB);
  // Set the outputs
  assign result = carry_res[27:1];
endmodule

module Four_Digit_Seven_Segment_Driver(
    input clk,
    input [12:0] num,
    output reg [3:0] Anode,
    output reg [6:0] LED_out
);

    reg [19:0] refresh_counter;
    wire [1:0] LED_activating_counter;
    reg [3:0] LED_BCD;
    reg [3:0] Thousand, Hundreds, Tens, Ones;

    always @(posedge clk)
        refresh_counter <= refresh_counter + 1;

    assign LED_activating_counter = refresh_counter[19:18];

    always @(posedge clk)
    begin
        // Binary to BCD conversion using Double Dabble algorithm
        reg [12:0] shift;
        reg [3:0] thousands, hundreds, tens, ones;
        integer i;

        shift = num;
        thousands = 4'd0;
        hundreds = 4'd0;
        tens = 4'd0;
        ones = 4'd0;

        for (i = 0; i < 13; i = i + 1)
        begin
            if (thousands >= 5)
                thousands = thousands + 3;
            if (hundreds >= 5)
                hundreds = hundreds + 3;
            if (tens >= 5)
                tens = tens + 3;
            if (ones >= 5)
                ones = ones + 3;

            thousands = thousands << 1;
            thousands[0] = hundreds[3];
            hundreds = hundreds << 1;
            hundreds[0] = tens[3];
            tens = tens << 1;
            tens[0] = ones[3];
            ones = ones << 1;
            ones[0] = shift[12];
            shift = shift << 1;
        end

        Thousand = thousands;
        Hundreds = hundreds;
        Tens = tens;
        Ones = ones;
    end

    always @(*)
    begin
        case(LED_activating_counter)
            2'b00: begin
                Anode = 4'b1110;
                LED_BCD = Ones;
            end
            2'b01: begin
                Anode = 4'b1101;
                LED_BCD = Tens;
            end
            2'b10: begin
                Anode = 4'b1011;
                LED_BCD = Hundreds;
            end
            2'b11: begin
                Anode = 4'b0111;
                LED_BCD = Thousand;
            end
        endcase
    end

    always @(*)
    begin
        case(LED_BCD)
            4'b0000: LED_out = 7'b0000001; // "0"
            4'b0001: LED_out = 7'b1001111; // "1"
            4'b0010: LED_out = 7'b0010010; // "2"
            4'b0011: LED_out = 7'b0000110; // "3"
            4'b0100: LED_out = 7'b1001100; // "4"
            4'b0101: LED_out = 7'b0100100; // "5"
            4'b0110: LED_out = 7'b0100000; // "6"
            4'b0111: LED_out = 7'b0001111; // "7"
            4'b1000: LED_out = 7'b0000000; // "8"
            4'b1001: LED_out = 7'b0000100; // "9"
            default: LED_out = 7'b1111111; // "off"
        endcase
    end

endmodule

