module sincronizador(
    input wire clk, reset,
    output wire hsync, vsync, video_activado, instante_pulso,
    output wire [9:0] pixel_x, pixel_y
);

    // Timing constants
    localparam HD = 640;  // Horizontal display
    localparam HF = 48;   // Horizontal front porch
    localparam HB = 16;   // Horizontal back porch
    localparam HR = 96;   // Horizontal retrace
    localparam VD = 480;  // Vertical display
    localparam VF = 10;   // Vertical front porch
    localparam VB = 30;   // Vertical back porch
    localparam VR = 2;    // Vertical retrace

    // Derived constants
    localparam HMAX = HD + HF + HB + HR - 1;
    localparam VMAX = VD + VF + VB + VR - 1;

    // Internal signals
    reg modo2_reg, modo2_next;
    reg [9:0] h_contador_reg, h_contador_next;
    reg [9:0] v_contador_reg, v_contador_next;
    reg v_sync_reg, h_sync_reg;
    reg v_sync_next, h_sync_next;
    wire h_fin, v_fin, pixel_tick;

    // Register logic
    always @(posedge clk, posedge reset)
        if (reset)
            begin
                modo2_reg <= 0;
                h_contador_reg <= 0;
                v_contador_reg <= 0;
                v_sync_reg <= 1'b0;
                h_sync_reg <= 1'b0;
            end
        else
            begin
                modo2_reg <= modo2_next;
                h_contador_reg <= h_contador_next;
                v_contador_reg <= v_contador_next;
                v_sync_reg <= v_sync_next;
                h_sync_reg <= h_sync_next;
            end

    // Next-state logic
    assign pixel_tick = modo2_reg;

    always @*
    begin
        modo2_next = ~modo2_reg;
        h_contador_next = pixel_tick ? 
                          (h_fin ? 0 : h_contador_reg + 1) :
                          h_contador_reg;
        v_contador_next = pixel_tick && h_fin ? 
                          (v_fin ? 0 : v_contador_reg + 1) :
                          v_contador_reg;
        h_sync_next = (h_contador_reg >= (HD + HF) &&
                       h_contador_reg <= (HD + HF + HR - 1));
        v_sync_next = (v_contador_reg >= (VD + VF) &&
                       v_contador_reg <= (VD + VF + VR - 1));
    end

    // Status signals
    assign h_fin = (h_contador_reg == HMAX);
    assign v_fin = (v_contador_reg == VMAX);

    // Output logic
    assign hsync = h_sync_reg;
    assign vsync = v_sync_reg;
    assign video_activado = (h_contador_reg < HD) && (v_contador_reg < VD);
    assign instante_pulso = pixel_tick;
    assign pixel_x = h_contador_reg;
    assign pixel_y = v_contador_reg;

endmodule

module async_transmitter (
    input wire Clk,
    input wire Start,
    input wire [5:0] Din,
    output reg D
);

    reg [3:0] counter;
    reg odd;
    reg [5:0] data_reg;

    always @(posedge Clk) begin
        if (!Start) begin
            counter <= 4'b0000;
            odd <= 1'b0;
            D <= 1'b1;
        end else begin
            case (counter)
                4'b0000: begin // Start bit
                    D <= 1'b0;
                    data_reg <= Din;
                    odd <= 1'b0;
                    counter <= counter + 1;
                end
                4'b0001, 4'b0010, 4'b0011, 4'b0100, 4'b0101, 4'b0110: begin // Data bits
                    D <= data_reg[0];
                    odd <= odd ^ data_reg[0];
                    data_reg <= data_reg >> 1;
                    counter <= counter + 1;
                end
                4'b0111: begin // Parity bit
                    D <= ~odd;
                    counter <= counter + 1;
                end
                4'b1000: begin // Stop bit
                    D <= 1'b1;
                    counter <= 4'b0000;
                end
                default: counter <= 4'b0000;
            endcase
        end
    end

endmodule

module rs232_receiver(
input wire clock,
input wire reset,
output reg [7:0] data,
input wire rx,
output reg dataReceived
);
// clock frequency, in hz
parameter [31:0] SYSTEM_SPEED;
BAUDRATE;
// received RS232 data
// RS232 RX pin
// this is set for one clock pulse to 1, when the data was received
parameter MAX_COUNTER = SYSTEM_SPEED / BAUDRATE;
reg [31:0] baudrateCounter = 0;
parameter [1:0]
  WAIT_FOR_RX_START = 0,
  WAIT_HALF_BIT = 1,
  RECEIVE_BITS = 2,
  WAIT_FOR_STOP_BIT = 3;
reg [1:0] state = WAIT_FOR_RX_START;
reg [31:0] bitCounter = 0;
reg [7:0] shiftRegister = 1'b0;
reg rxLatch;
  always @(posedge clock, posedge reset) begin
    dataReceived <= 1'b0;
    rxLatch <= rx;
    if(reset == 1'b1) begin
      state <= WAIT_FOR_RX_START;
      data <= {8{1'b0}};
    end
    else begin
      case(state)
      WAIT_FOR_RX_START : begin
        if(rxLatch == 1'b0) begin
          // start bit received, wait for a half bit time
          // to sample bits in the middle of the signal
          state <= WAIT_HALF_BIT;
          baudrateCounter <= MAX_COUNTER / 2 - 1;
        end
      end
      WAIT_HALF_BIT : begin
        if(baudrateCounter == 0) begin
          // now we are in the middle of the start bit,
          // wait a full bit for the middle of the first bit
          state <= RECEIVE_BITS;
          bitCounter <= 7;
          baudrateCounter <= MAX_COUNTER - 1;
        end
        else begin
          baudrateCounter <= baudrateCounter - 1;
        end
      end
      RECEIVE_BITS : begin
        // sample a bit
        if(baudrateCounter == 0) begin
          shiftRegister <= {rxLatch,shiftRegister[7:1]};
          if(bitCounter == 0) begin
            state <= WAIT_FOR_STOP_BIT;
          end
          else begin
            bitCounter <= bitCounter - 1;
          end
          baudrateCounter <= MAX_COUNTER - 1;
        end
        else begin
          baudrateCounter <= baudrateCounter - 1;
        end
      end
      WAIT_FOR_STOP_BIT : begin
        // wait for the middle of the stop bit
        if(baudrateCounter == 0) begin
          state <= WAIT_FOR_RX_START;
          if(rxLatch == 1'b1) begin
            data <= shiftRegister;
            dataReceived <= 1'b1;
            // else: missing stop bit, ignore
          end
        end
        else begin
          baudrateCounter <= baudrateCounter - 1;
        end
      end
      endcase
    end
  end
endmodule

module sawtooth(
output wire [7:0] data,
input wire [15:0] freq,
input wire clk
);
reg [21:0] sum = 1'b0;
reg [7:0] adata;
  assign data = adata;
  always @(posedge clk) begin
    sum <= ({1'b0,sum[20:0]}) + (freq);
    if(sum[21] == 1'b1) begin
      adata <= (adata) + 1;
    end
  end
endmodule

module CLOCK_DIVIDER(
    input clk_IN,
    output reg clk
);

    reg [7:0] counter = 8'd0;

    always @(posedge clk_IN) begin
        if (counter == 8'd9) begin
            counter <= 8'd0;
            clk <= ~clk;
        end else begin
            counter <= counter + 1'b1;
        end
    end

endmodule

module clk_generator(
    input clk,
    output reg s_tick
);

    parameter clk_devide_count = 320;

    reg [8:0] counter = 9'd0;

    always @(posedge clk) begin
        if (counter == clk_devide_count) begin
            counter <= 9'd0;
            s_tick <= 1'b1;
        end else begin
            counter <= counter + 1'b1;
            s_tick <= 1'b0;
        end
    end

endmodule

module stat_writer(
input wire Clk,
input wire Rst,
output reg [0:0] MemWe,
output wire [8:0] MemAddr,
output reg [35:0] MemDin,
input wire [35:0] MemDout,
input wire [8:0] Value,
input wire Kick
);
parameter [1:0]
  ZERO_OUT = 0,
  IDLE = 1,
  READ_OLD = 2,
  WRITE_NEW = 3;
reg [1:0] state; reg [1:0] NEXT_state;
reg [8:0] addr; reg [8:0] NEXT_addr;
  assign MemAddr = addr;
  always @(state, addr, MemDout, Value, Kick) begin
    NEXT_state <= state;
    NEXT_addr <= addr;
    MemDin <= MemDout + 1;
    MemWe <= 1'b0;
    case(state)
    ZERO_OUT : begin
      NEXT_addr <= addr + 1;
      MemWe <= 1'b1;
      MemDin <= {36{1'b0}};
      if(addr == {1'b1,8'hFF}) begin
        NEXT_state <= IDLE;
      end
    end
    IDLE : begin
      if(Kick == 1'b1) begin
        NEXT_state <= READ_OLD;
        NEXT_addr <= Value;
      end
    end
    READ_OLD : begin
      NEXT_state <= WRITE_NEW;
    end
    WRITE_NEW : begin
      NEXT_state <= IDLE;
      MemWe <= 1'b1;
    end
    endcase
  end
  always @(posedge Clk) begin
    state <= NEXT_state;
    addr <= NEXT_addr;
    if(Rst == 1'b1) begin
      state <= ZERO_OUT;
      addr <= {9{1'b0}};
    end
  end
endmodule

