module led_shifter_2 (
    input wire clk,
    input wire async_nreset,
    input wire button0_re,
    input wire button1_re,
    input wire show_parity_deb,
    output wire [7:0] out,
    output reg [7:0] hex
);

    reg [7:0] number_reg, number_next;

    always @(posedge clk or negedge async_nreset) begin
        if (!async_nreset)
            number_reg <= 8'b0;
        else
            number_reg <= number_next;
    end

    always @(*) begin
        number_next = number_reg;
        if (button0_re)
            number_next = {number_reg[6:0], 1'b0};
        else if (button1_re)
            number_next = {number_reg[6:0], 1'b1};
    end

    assign out = number_reg;

    always @(*) begin
        if (show_parity_deb)
            hex = ^number_reg ? 8'b0000_0011 : 8'b0011_1111;
        else
            hex = 8'b0000_0000;
    end

endmodule

module fir_filter (
    input wire clk,
    input wire rst_n,

    input wire [7:0] input_data,
    input wire input_valid,
    output reg input_ready,

    input wire [7:0] weight_data,
    input wire [2:0] weight_idx,
    input wire weight_valid,
    output reg weight_ready,

    output reg [15:0] output_data,
    output reg output_valid,
    input wire output_ready
);

    reg [7:0] inputs [6:0];
    reg [7:0] weights [6:0];
    reg input_valid_d;

    integer i;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < 7; i = i + 1) begin
                inputs[i] <= 8'b0;
                weights[i] <= 8'b0;
            end
            input_ready <= 1'b0;
            weight_ready <= 1'b0;
            output_valid <= 1'b0;
            input_valid_d <= 1'b0;
        end else begin
            input_ready <= 1'b1;
            weight_ready <= 1'b1;

            if (weight_valid && weight_ready) begin
                weights[weight_idx] <= weight_data;
            end

            if (input_valid && input_ready) begin
                for (i = 6; i > 0; i = i - 1) begin
                    inputs[i] <= inputs[i-1];
                end
                inputs[0] <= input_data;
            end

            input_valid_d <= input_valid;
            output_valid <= input_valid_d;
        end
    end

    always @(posedge clk) begin
        if (output_valid && output_ready) begin
            output_data <= 16'b0;
            for (i = 0; i < 7; i = i + 1) begin
                output_data <= output_data + inputs[i] * weights[i];
            end
        end
    end

endmodule

module decoder_2to4 (
