    assign d[1] = en & ~a[1] &  a[0];
    assign d[2] = en &  a[1] & ~a[0];
    assign d[3] = en &  a[1] &  a[0];

endmodule

module ID_EX_reg (
    input wire clk,
    input wire rst,
    input wire ID_EX_stall,
    input wire ID_EX_flush,

    // Control signals
    input wire rd_src_in,
    input wire alu_in2_sel_in,
    input wire pc_src_in,
    input wire [1:0] wb_sel_in,
    input wire reg_w_in,
    input wire mem_r_in,
    input wire mem_w_in,
    input wire disable_stall_in,

    // Data signals
    input wire [31:0] pc_in,
    input wire [31:0] rr1_data_in,
    input wire [31:0] rr2_data_in,
    input wire [31:0] imm_in,

    // Address signals
    input wire [4:0] rr1_addr_in,
    input wire [4:0] rr2_addr_in,
    input wire [4:0] wr_addr_in,

    // Instruction-specific signals
    input wire [4:0] alu_ctrl_in,
    input wire [6:0] opcode_in,
    input wire [2:0] funct3_in,

    // Output signals
    output reg rd_src_out,
    output reg alu_in2_sel_out,
    output reg pc_src_out,
    output reg [1:0] wb_sel_out,
    output reg reg_w_out,
    output reg mem_r_out,
    output reg mem_w_out,
    output reg disable_stall_out,
    output reg [31:0] pc_out,
    output reg [31:0] rr1_data_out,
    output reg [31:0] rr2_data_out,
    output reg [31:0] imm_out,
    output reg [4:0] rr1_addr_out,
    output reg [4:0] rr2_addr_out,
    output reg [4:0] wr_addr_out,
    output reg [4:0] alu_ctrl_out,
    output reg [6:0] opcode_out,
    output reg [2:0] funct3_out
);

    reg flush_second_time;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            rd_src_out <= 1'b0;
            alu_in2_sel_out <= 1'b0;
            pc_src_out <= 1'b0;
            wb_sel_out <= 2'b00;
            reg_w_out <= 1'b0;
            mem_r_out <= 1'b0;
            mem_w_out <= 1'b0;
            disable_stall_out <= 1'b0;
            pc_out <= 32'b0;
            rr1_data_out <= 32'b0;
            rr2_data_out <= 32'b0;
            imm_out <= 32'b0;
            rr1_addr_out <= 5'b0;
            rr2_addr_out <= 5'b0;
            wr_addr_out <= 5'b0;
            alu_ctrl_out <= 5'b0;
            opcode_out <= 7'b0;
            funct3_out <= 3'b0;
            flush_second_time <= 1'b0;
        end else if (ID_EX_flush || flush_second_time) begin
            rd_src_out <= 1'b0;
            alu_in2_sel_out <= 1'b0;
            pc_src_out <= 1'b0;
            wb_sel_out <= 2'b00;
            reg_w_out <= 1'b0;
            mem_r_out <= 1'b0;
            mem_w_out <= 1'b0;
            disable_stall_out <= 1'b0;
            pc_out <= 32'b0;
            rr1_data_out <= 32'b0;
            rr2_data_out <= 32'b0;
            imm_out <= 32'b0;
            rr1_addr_out <= 5'b0;
            rr2_addr_out <= 5'b0;
            wr_addr_out <= 5'b0;
            alu_ctrl_out <= 5'b0;
            opcode_out <= 7'b0;
            funct3_out <= 3'b0;
            flush_second_time <= ID_EX_flush;
        end else if (!ID_EX_stall) begin
            rd_src_out <= rd_src_in;
            alu_in2_sel_out <= alu_in2_sel_in;
            pc_src_out <= pc_src_in;
            wb_sel_out <= wb_sel_in;
            reg_w_out <= reg_w_in;
            mem_r_out <= mem_r_in;
            mem_w_out <= mem_w_in;
            disable_stall_out <= disable_stall_in;
            pc_out <= pc_in;
            rr1_data_out <= rr1_data_in;
            rr2_data_out <= rr2_data_in;
            imm_out <= imm_in;
            rr1_addr_out <= rr1_addr_in;
            rr2_addr_out <= rr2_addr_in;
            wr_addr_out <= wr_addr_in;
            alu_ctrl_out <= alu_ctrl_in;
            opcode_out <= opcode_in;
            funct3_out <= funct3_in;
            flush_second_time <= 1'b0;
        end
    end

endmodule

