module sumSub(
input wire [2:0] entrada1,
input wire [2:0] entrada2,
input wire sel,
output reg [2:0] saida,
output reg cout,
output wire E
);
reg cin0;
reg cin1;
reg cin2;
reg [2:0] complemento1;
reg [2:0] complemento2;
  always @(entrada1, entrada2, sel) begin
    if((sel == 1'b0)) begin
      //saida <= entrada1 + entrada2;
      if((entrada1[2] == 1'b1)) begin
        //inverte a
        complemento1 <= entrada1 ^ 3'b111;
        complemento2[0] <= entrada1[0] ^ 1'b1;
        cin0 <= entrada1[0] & 1'b1;
        complemento2[1] <= entrada1[1] ^ 1'b1 ^ cin0;
        cin1 <= (entrada1[1] & cin0) | (entrada1[1] & 1'b1) | (1'b1 & cin0);
        complemento2[2] <= entrada1[2] ^ 1'b1 ^ cin1;
        cin2 <= (entrada1[1] & cin1) | (entrada1[1] & 1'b1) | (1'b1 & cin1);
      end
      else if((entrada2[2] == 1'b1)) begin
        //inverte b
        complemento1 <= entrada2 ^ 3'b111;
        complemento2[0] <= entrada2[0] ^ 1'b1;
        cin0 <= entrada2[0] & 1'b1;
        complemento2[1] <= entrada2[1] ^ 1'b1 ^ cin0;
        cin1 <= (entrada2[1] & cin0) | (entrada2[1] & 1'b1) | (1'b1 & cin0);
        complemento2[2] <= entrada2[2] ^ 1'b1 ^ cin1;
        cin2 <= (entrada2[1] & cin1) | (entrada2[1] & 1'b1) | (1'b1 & cin1);
      end
      saida[0] <= entrada1[0] ^ entrada2[0];
      cin0 <= entrada1[0] & entrada2[0];
      saida[1] <= entrada1[1] ^ entrada2[1] ^ cin0;
      cout <= (entrada1[1] & cin0) | (entrada1[1] & entrada2[1]) | (entrada2[1] & cin0);
      saida[2] <= 1'b0;
    end
    else begin
      //saida <= entrada1 - entrada2;
      if((entrada1[2] == 1'b1)) begin
        //inverte a
        complemento1 <= entrada1 ^ 3'b111;
        complemento2[0] <= entrada1[0] ^ 1'b1;
        cin0 <= entrada1[0] & 1'b1;
        complemento2[1] <= entrada1[1] ^ 1'b1 ^ cin0;
        cin1 <= (entrada1[1] & cin0) | (entrada1[1] & 1'b1) | (1'b1 & cin0);
        complemento2[2] <= entrada1[2] ^ 1'b1 ^ cin1;
        cin2 <= (entrada1[1] & cin1) | (entrada1[1] & 1'b1) | (1'b1 & cin1);
      end
      else if((entrada2[2] == 1'b1)) begin
        //inverte b
        complemento1 <= entrada2 ^ 3'b111;
        complemento2[0] <= entrada2[0] ^ 1'b1;
        cin0 <= entrada2[0] & 1'b1;
        complemento2[1] <= entrada2[1] ^ 1'b1 ^ cin0;
        cin1 <= (entrada2[1] & cin0) | (entrada2[1] & 1'b1) | (1'b1 & cin0);
        complemento2[2] <= entrada2[2] ^ 1'b1 ^ cin1;
        cin2 <= (entrada2[1] & cin1) | (entrada2[1] & 1'b1) | (1'b1 & cin1);
      end
      // Aplica o complemento no B
      //---------------------------------------------------------------------------
      complemento1 <= entrada2 ^ 3'b111;
      complemento2[0] <= entrada2[0] ^ 1'b1;
      cin0 <= entrada2[0] & 1'b1;
      complemento2[1] <= entrada2[1] ^ 1'b1 ^ cin0;
      cin1 <= (entrada2[1] & cin0) | (entrada2[1] & 1'b1) | (1'b1 & cin0);
      complemento2[2] <= entrada2[2] ^ 1'b1 ^ cin1;
      cin2 <= (entrada2[1] & cin1) | (entrada2[1] & 1'b1) | (1'b1 & cin1);
      //---------------------------------------------------------------------------
      saida[0] <= entrada1[0] ^ entrada2[0];
      cin0 <= entrada1[0] & entrada2[0];
      saida[1] <= entrada1[1] ^ entrada2[1] ^ cin0;
      cout <= (entrada1[1] & cin0) | (entrada1[1] & entrada2[1]) | (entrada2[1] & cin0);
      saida[2] <= 1'b0;
    end
  end
endmodule

