  idle = 0,
  startbit = 1,
  senddata = 2,
  stopbit = 3;
reg [1:0] current_st; reg [1:0] next_st;
reg [7:0] copy_data;
reg enable_copy; reg pw_sreset; reg dc_sreset; reg dc_enable;
reg [8:0] pulse_width;
parameter PEOC = 9'b010101101;
reg [2:0] data_count;
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b0) begin
      current_st <= idle;
    end else begin
      current_st <= next_st;
    end
  end
  always @(current_st, start, pulse_width, data_count) begin
    enable_copy <= 1'b0;
    pw_sreset <= 1'b0;
    dc_sreset <= 1'b0;
    dc_enable <= 1'b0;
    EOT <= 1'b0;
    TX <= 1'b1;
    case(current_st)
    idle : begin
      enable_copy <= 1'b1;
      EOT <= 1'b1;
      if((start == 1'b1)) begin
        pw_sreset <= 1'b1;
        next_st <= startbit;
      end
      else begin
        next_st <= idle;
      end
    end
    startbit : begin
      TX <= 1'b0;
      if((pulse_width == PEOC)) begin
        pw_sreset <= 1'b1;
        dc_sreset <= 1'b1;
        next_st <= senddata;
      end
      else begin
        next_st <= startbit;
      end
    end
    senddata : begin
      TX <= copy_data[data_count];
      if((pulse_width == PEOC)) begin
        dc_enable <= 1'b1;
        pw_sreset <= 1'b1;
      end
      if((data_count == 3'b111) && (pulse_width == PEOC)) begin
        pw_sreset <= 1'b1;
        next_st <= stopbit;
      end
      else begin
        next_st <= senddata;
      end
    end
    stopbit : begin
      TX <= 1'b1;
      if((pulse_width == PEOC)) begin
        next_st <= idle;
      end
      else begin
        next_st <= stopbit;
      end
    end
    endcase
  end
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b0) begin
      copy_data <= {8{1'b0}};
    end else begin
      if(enable_copy == 1'b1) begin
        copy_data <= data;
      end
    end
  end
  always @(posedge clk, posedge reset, posedge pw_sreset) begin
    if(reset == 1'b0) begin
      pulse_width <= {9{1'b0}};
    end else begin
      if(pw_sreset == 1'b1) begin
        pulse_width <= {9{1'b0}};
      end
      else begin
        pulse_width <= pulse_width + 1'b1;
      end
    end
  end
  always @(posedge clk, posedge reset, posedge dc_sreset) begin
    if(reset == 1'b0) begin
      data_count <= {3{1'b0}};
    end else begin
      if(dc_sreset == 1'b1) begin
        data_count <= {3{1'b0}};
      end
      else if(dc_enable == 1'b1) begin
        data_count <= data_count + 1'b1;
      end
    end
  end
endmodule

