module DisplayOut(
input wire PIXEL_CLK,
output wire COMP_SYNCH,
output reg OUT_BLANK_Z,
output reg HSYNC,
output reg VSYNC,
output wire [7:0] R,
output wire [7:0] G,
output wire [7:0] B,
output reg [19:0] MEMORY_ADDRESS,
input wire [0:0] MEMORY_OUT
);
parameter [31:0] w_pixels;
parameter [31:0] w_fp;
parameter [31:0] w_synch;
parameter [31:0] w_bp;
parameter w_syncval;
parameter [31:0] h_pixels;
parameter [31:0] h_fp;
parameter [31:0] h_synch;
parameter [31:0] h_bp;
parameter h_syncval;
parameter w_total = w_pixels + w_fp + w_synch + w_bp;
parameter h_total = h_pixels + h_fp + h_synch + h_bp;
  assign COMP_SYNCH = 1'b0;
  // Disable "sync on green"
  assign R = {8{MEMORY_OUT[0]}};
  assign G = {8{MEMORY_OUT[0]}};
  assign B = {8{MEMORY_OUT[0]}};
  always @(posedge PIXEL_CLK) begin : P1
    reg [31:0] clk_x = 0;
    reg [31:0] clk_y = 0;
    reg [19:0] clk_xy = 20'b00000000000000000000;
  // 1048576 = 2 ^ 20 as we have 20 bits.
    // VGA Signals
    if(clk_x < (w_pixels + w_fp) || clk_x >= (w_pixels + w_fp + w_synch)) begin
      HSYNC <=  ~w_syncval;
      // not on synch location
    end
    else begin
      HSYNC <= w_syncval;
      // on synch location
    end
    if(clk_y < (h_pixels + h_fp) || clk_y >= (h_pixels + h_fp + h_synch)) begin
      VSYNC <=  ~h_syncval;
      // not on synch location
    end
    else begin
      VSYNC <= h_syncval;
      // on synch location
    end
    if(clk_x >= w_pixels || clk_y >= h_pixels) begin
      OUT_BLANK_Z <= 1'b0;
    end
    else begin
      OUT_BLANK_Z <= 1'b1;
    end
    // Increment coordinate counters
    if(clk_x < (w_total - 1)) begin
      clk_x = clk_x + 1;
    end
    else begin
      clk_x = 0;
      if(clk_y < (h_total - 1)) begin
        clk_y = clk_y + 1;
      end
      else begin
        clk_y = 0;
      end
    end
    // Let it be one clock ahead
    if(clk_x == (w_pixels - 1)) begin
      if(clk_y < (h_pixels - 1)) begin
        clk_xy[19:10] = clk_xy[19:10] + 1;
        clk_xy[9:0] = 10'b0000000000;
      end
      else if(clk_y == (h_total - 1)) begin
        clk_xy = 20'b00000000000000000000;
      end
    end
    else if(clk_x < (w_pixels - 1)) begin
      // add up
      clk_xy = clk_xy + 1'b1;
    end
    MEMORY_ADDRESS <= clk_xy;
  end
endmodule

module cdc_src #(
    parameter type T = logic [31:0]
) (
    input  logic clk_i,
    input  logic rst_ni,
    input  T     data_i,
    input  logic valid_i,
    input  logic async_ack_i,
    output logic async_req_o,
    output T     async_data_o,
    output logic ready_o
);

    // FSM states
    localparam logic [1:0] WAIT_GRANT = 2'b00;
    localparam logic [1:0] WAIT_ACK   = 2'b01;

    // State variables
    logic [1:0] state_q, state_d;

    // Synchronizer flip-flops
    logic async_ack_tx0, async_ack_tx1, async_ack_tx2;

    // Internal signals
    logic req_q, req_d;
    T     data_q, data_d;

    // 3-stage synchronizer for async_ack_i
    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (~rst_ni) begin
            async_ack_tx0 <= 1'b0;
            async_ack_tx1 <= 1'b0;
            async_ack_tx2 <= 1'b0;
        end else begin
            async_ack_tx0 <= async_ack_i;
            async_ack_tx1 <= async_ack_tx0;
            async_ack_tx2 <= async_ack_tx1;
        end
    end

    // FSM and output logic
    always_comb begin
        state_d = state_q;
        req_d = req_q;
        data_d = data_q;
        ready_o = 1'b0;

        case (state_q)
            WAIT_GRANT: begin
                ready_o = 1'b1;
                if (valid_i && ready_o) begin
                    state_d = WAIT_ACK;
                    req_d = ~req_q;
                    data_d = data_i;
                end
            end

            WAIT_ACK: begin
                if (async_ack_tx2 != async_ack_tx1) begin
                    state_d = WAIT_GRANT;
                end
            end

            default: state_d = WAIT_GRANT;
        endcase
    end

    // Sequential logic
    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (~rst_ni) begin
            state_q <= WAIT_GRANT;
            req_q <= 1'b0;
            data_q <= '0;
        end else begin
            state_q <= state_d;
            req_q <= req_d;
            data_q <= data_d;
        end
    end

    // Output assignments
    assign async_req_o = req_q;
    assign async_data_o = data_q;

endmodule

