        y[11] <= 1'b1;
      end
      else begin
        NextState <= a6;
      end
    end
    a6 : begin
      NextState <= a1;
      y[12] <= 1'b1;
    end
    default : begin
      NextState <= a1;
      // ïðèñâîåíèå çíà÷åíèé âûõîäàì äëÿ ñîñòîÿíèÿ ïî óìîë÷àíèþ
      //Óñòàíîâêà àâòîìàòà â íà÷àëüíîå ñîñòîÿíèå
    end
    endcase
  end
  always @(posedge Clk, posedge reset) begin
    if(Reset == 1'b0) begin
      State <= a1;
      // íà÷àëüíîå ñîñòîÿíèå
    end else begin
      State <= NextState;
    end
  end
