module cdc_handshake #(
    parameter CDC_REG_AMOUNT = 2,
    parameter PASS_IMMEDIATELY = 0
) (
    input  wire rst_m_i,
    input  wire rst_s_i,
    input  wire clk_m_i,
    input  wire clk_s_i,
    input  wire m_req_i,
    output wire m_ack_o,
    input  wire s_ack_i,
    output wire s_req_o
);

    reg m_req, s_ack;
    reg m_wait;
    reg s_req;

    reg [CDC_REG_AMOUNT-1:0] m_ack_sync_reg;
    reg [CDC_REG_AMOUNT-1:0] s_req_sync_reg;

    wire m_ack_sync = m_ack_sync_reg[CDC_REG_AMOUNT-1];
    wire s_req_sync = s_req_sync_reg[CDC_REG_AMOUNT-1];

    // Master domain logic
    always @(posedge clk_m_i or posedge rst_m_i) begin
        if (rst_m_i) begin
            m_req <= 1'b0;
            m_wait <= 1'b0;
        end else begin
            if (m_req_i && !m_wait) begin
                m_req <= !m_req;
                m_wait <= 1'b1;
            end else if (m_ack_sync != s_ack) begin
                m_wait <= 1'b0;
            end
        end
    end

    assign m_ack_o = !m_wait;

    // Slave domain logic
    always @(posedge clk_s_i or posedge rst_s_i) begin
        if (rst_s_i) begin
            s_ack <= 1'b0;
            s_req <= 1'b0;
        end else begin
            if (s_req_sync != m_req) begin
                s_req <= 1'b1;
            end else if (s_ack_i) begin
                s_ack <= !s_ack;
                s_req <= 1'b0;
            end
        end
    end

    assign s_req_o = s_req;

    // CDC synchronizers
    always @(posedge clk_m_i or posedge rst_m_i) begin
        if (rst_m_i) begin
            m_ack_sync_reg <= {CDC_REG_AMOUNT{1'b0}};
        end else begin
            m_ack_sync_reg <= {m_ack_sync_reg[CDC_REG_AMOUNT-2:0], s_ack};
        end
    end

    always @(posedge clk_s_i or posedge rst_s_i) begin
        if (rst_s_i) begin
            s_req_sync_reg <= {CDC_REG_AMOUNT{1'b0}};
        end else begin
            s_req_sync_reg <= {s_req_sync_reg[CDC_REG_AMOUNT-2:0], m_req};
        end
    end

    // Immediate pass-through logic
    generate
        if (PASS_IMMEDIATELY) begin
            assign m_ack_o = s_ack_i;
            assign s_req_o = m_req_i;
        end
    endgenerate

endmodule

module detection(
    input go,
    input [7:0] x_lane0, x_lane1, x_lane2, x_lane3, x_lane4,
    input [6:0] y_lane0, y_lane1, y_lane2, y_lane3, y_lane4,
    input [7:0] x_dot,
    input [6:0] y_dot,
    input CLK,
    output reg resetn
);

    reg [2:0] x_lane;

    // Lane detection
    always @(*) begin
        if (y_dot > 7'd80 && y_dot < 7'd100) x_lane = 3'd0;
        else if (y_dot > 7'd60 && y_dot <= 7'd80) x_lane = 3'd1;
        else if (y_dot > 7'd40 && y_dot <= 7'd60) x_lane = 3'd2;
        else if (y_dot > 7'd20 && y_dot <= 7'd40) x_lane = 3'd3;
        else if (y_dot > 7'd0 && y_dot <= 7'd20) x_lane = 3'd4;
        else x_lane = 3'd5;
    end

    // Collision detection and reset logic
    always @(posedge CLK) begin
        if (go && !resetn) begin
            resetn <= 1'b1;
        end else begin
            case (x_lane)
                3'd0: if (x_dot >= x_lane0 - 2 && x_dot <= x_lane0 + 2) resetn <= 1'b0;
                3'd1: if (x_dot >= x_lane1 - 2 && x_dot <= x_lane1 + 2) resetn <= 1'b0;
                3'd2: if (x_dot >= x_lane2 - 2 && x_dot <= x_lane2 + 2) resetn <= 1'b0;
                3'd3: if (x_dot >= x_lane3 - 2 && x_dot <= x_lane3 + 2) resetn <= 1'b0;
                3'd4: if (x_dot >= x_lane4 - 2 && x_dot <= x_lane4 + 2) resetn <= 1'b0;
                default: resetn <= resetn;
            endcase
        end
    end

    // Initial value for resetn
    initial begin
        resetn = 1'b1;
    end

endmodule

