module ALU1Bit(
    input a, b, ci,
    input [1:0] c,
    output y, z
);
    wire sum, cout, and_out, not_out, xor_out;

    FullAdder fa(.a(a), .b(b), .ci(ci), .s(sum), .co(cout));

    assign and_out = a & b;
    assign not_out = ~a;
    assign xor_out = a ^ b;

    Mux4to1 mux_y(.i1(sum), .i2(and_out), .i3(not_out), .i4(1'b0), .c(c), .o(y));
    Mux4to1 mux_z(.i1(cout), .i2(1'b0), .i3(1'b0), .i4(xor_out), .c(c), .o(z));
endmodule

module FullAdder(
    input a, b, ci,
    output s, co
);
    assign s = a ^ b ^ ci;
    assign co = (a & b) | (b & ci) | (a & ci);
endmodule

