    wire y, z;

    ALU1Bit alu(.a(a), .b(b), .ci(ci), .c(c), .y(y), .z(z));

    initial begin
        $monitor("Time=%0t a=%b b=%b ci=%b c=%b y=%b z=%b", $time, a, b, ci, c, y, z);

        // Test case 1: Addition
        a = 0; b = 1; ci = 0; c = 2'b00;
        #10 a = 1; b = 1; ci = 1;

        // Test case 2: AND
        #10 a = 1; b = 0; c = 2'b01;
        #10 a = 1; b = 1;

        // Test case 3: NOT
        #10 a = 0; c = 2'b10;
        #10 a = 1;

        // Test case 4: XOR
        #10 a = 0; b = 1; c = 2'b11;
        #10 a = 1; b = 1;

        #10 $finish;
    end
endmodule

module shiftRegE (
