            outRs2 <= 32'b0;
            outRd <= 5'b0;
            outWBsel <= 2'b0;
            outRegWEn <= 1'b0;
            outMemRW <= 1'b0;
        end
        else begin
            outALU <= alu;
            outPC <= pc;
            outRs2 <= rs2;
            outRd <= rd;
            outWBsel <= WBsel;
            outRegWEn <= RegWEn;
            outMemRW <= memRW;
        end
    end

endmodule

module booth_sel (
    input [2:0] B_operation,
    input [127:0] multiplicand,
    output reg op_code,
    output reg [127:0] B_multiplicand,
    output [127:0] next_multiplicand
);

    reg [31:0] B_multiplicand0, B_multiplicand1, B_multiplicand2, B_multiplicand3;

    always @(*) begin
        case (B_operation)
            3'b000: begin // ZERO
                {B_multiplicand3, B_multiplicand2, B_multiplicand1, B_multiplicand0} = 128'b0;
                op_code = 1'b0;
            end
            3'b001: begin // ADD1
                {B_multiplicand3, B_multiplicand2, B_multiplicand1, B_multiplicand0} = multiplicand;
                op_code = 1'b0;
            end
            3'b010: begin // SUB1
                {B_multiplicand3, B_multiplicand2, B_multiplicand1, B_multiplicand0} = ~multiplicand;
                op_code = 1'b1;
            end
            3'b011: begin // ADD2
                {B_multiplicand3, B_multiplicand2, B_multiplicand1, B_multiplicand0} = multiplicand << 1;
                op_code = 1'b0;
            end
            3'b100: begin // SUB2
                {B_multiplicand3, B_multiplicand2, B_multiplicand1, B_multiplicand0} = ~(multiplicand << 1);
                op_code = 1'b1;
            end
            default: begin
                {B_multiplicand3, B_multiplicand2, B_multiplicand1, B_multiplicand0} = 128'b0;
                op_code = 1'b0;
            end
        endcase

        B_multiplicand = {B_multiplicand3, B_multiplicand2, B_multiplicand1, B_multiplicand0};
    end

    assign next_multiplicand = multiplicand << 2;

endmodule

module ledc8x8(
input wire SMCLK,
input wire RESET,
output reg [0:7] ROW,
output reg [0:7] LED
);
wire ce;  // clock enable
reg [7:0] ce_cnt = 1'b0;  // kontrolny citac
reg [7:0] row_cnt;  // citac riadku
reg [7:0] inicialy;
  //delenie signalu 256
  always @(posedge RESET, posedge SMCLK) begin
    if(RESET == 1'b1) begin
      ce_cnt <= 8'b00000000;
    end else begin
      ce_cnt <= ce_cnt + 1;
    end
  end
  assign ce = ce_cnt == 8'b10000000 ? 1'b1 : 1'b0;
  //dekoder riadkov
  always @(row_cnt) begin
    case(row_cnt)
    8'b00000001 : begin
      inicialy <= 8'b10011111;
    end
    8'b00000010 : begin
      inicialy <= 8'b01101111;
    end
    8'b00000100 : begin
      inicialy <= 8'b01101001;
    end
    8'b00001000 : begin
      inicialy <= 8'b11100110;
    end
    8'b00010000 : begin
      inicialy <= 8'b11100110;
    end
    8'b00100000 : begin
      inicialy <= 8'b11101110;
    end
    8'b01000000 : begin
      inicialy <= 8'b11111110;
    end
    8'b10000000 : begin
      inicialy <= 8'b11111110;
    end
    default : begin
      inicialy <= 8'b11111111;
    end
    endcase
  end
  //rotacia riadkov
  always @(posedge RESET, posedge ce) begin
    if(RESET == 1'b1) begin
      row_cnt <= 8'b00000001;
    end else begin
      case(row_cnt)
      8'b00000001 : begin
        row_cnt <= 8'b00000010;
      end
      8'b00000010 : begin
        row_cnt <= 8'b00000100;
      end
      8'b00000100 : begin
        row_cnt <= 8'b00001000;
      end
      8'b00001000 : begin
        row_cnt <= 8'b00010000;
      end
      8'b00010000 : begin
        row_cnt <= 8'b00100000;
      end
      8'b00100000 : begin
        row_cnt <= 8'b01000000;
      end
      8'b01000000 : begin
        row_cnt <= 8'b10000000;
      end
      8'b10000000 : begin
        row_cnt <= 8'b00000001;
      end
      default : begin
      end
      endcase
    end
  end
  //svietenie
  always @(inicialy) begin
    ROW <= row_cnt;
    LED <= inicialy;
  end
endmodule

