module Altera_UP_SD_CRC16_Generator(
input wire i_clock,
input wire i_enable,
input wire i_reset_n,
input wire i_sync_reset,
input wire i_shift,
input wire i_datain,
output wire o_dataout,
output wire [15:0] o_crcout
);
// Local wires
// REGISTERED
reg [15:0] shift_register;
  always @(posedge i_clock, posedge i_reset_n) begin
    if((i_reset_n == 1'b0)) begin
      shift_register <= {16{1'b0}};
    end else begin
      if((i_sync_reset == 1'b1)) begin
        shift_register <= {16{1'b0}};
      end
      else if((i_enable == 1'b1)) begin
        if((i_shift == 1'b0)) begin
          shift_register[0] <= i_datain ^ shift_register[15];
          shift_register[4:1] <= shift_register[3:0];
          shift_register[5] <= shift_register[4] ^ i_datain ^ shift_register[15];
          shift_register[11:6] <= shift_register[10:5];
          shift_register[12] <= shift_register[11] ^ i_datain ^ shift_register[15];
          shift_register[15:13] <= shift_register[14:12];
        end
        else begin
          // shift CRC out (no more calculation now)
          shift_register[15:1] <= shift_register[14:0];
          shift_register[0] <= 1'b0;
        end
      end
    end
  end
  assign o_dataout = shift_register[15];
  assign o_crcout = shift_register;
endmodule

module fourbitscarrylookaheadadder(
    input [3:0] a, b,
    input cin,
    output [3:0] sum,
    output cout, P, G
);

    wire [3:0] p, g;
    wire c1, c2, c3;

    pfa o1(.a(a[0]), .b(b[0]), .cin(cin), .p(p[0]), .g(g[0]), .sum(sum[0]));
    pfa o2(.a(a[1]), .b(b[1]), .cin(c1), .p(p[1]), .g(g[1]), .sum(sum[1]));
    pfa o3(.a(a[2]), .b(b[2]), .cin(c2), .p(p[2]), .g(g[2]), .sum(sum[2]));
    pfa o4(.a(a[3]), .b(b[3]), .cin(c3), .p(p[3]), .g(g[3]), .sum(sum[3]));

    carrygenerator o5(.p(p), .g(g), .cin(cin), .c1(c1), .c2(c2), .c3(c3), .P(P), .G(G));

    assign cout = G | (P & cin);

endmodule

module pfa(
    input a, b, cin,
    output p, g, sum
);

    assign p = a ^ b;
    assign g = a & b;
    assign sum = p ^ cin;

endmodule

module carrygenerator(
    input [3:0] p, g,
    input cin,
    output c1, c2, c3, P, G
);

    assign c1 = g[0] | (p[0] & cin);
    assign c2 = g[1] | (p[1] & g[0]) | (p[1] & p[0] & cin);
    assign c3 = g[2] | (p[2] & g[1]) | (p[2] & p[1] & g[0]) | (p[2] & p[1] & p[0] & cin);

    assign P = &p;
    assign G = g[3] | (p[3] & g[2]) | (p[3] & p[2] & g[1]) | (p[3] & p[2] & p[1] & g[0]);

endmodule

