module xdelay #(
    parameter BWID = 8,
    parameter N_Clk = 32,
    parameter N_ND = 0,
    parameter IsReset = 1
) (
    input wire clk,
    input wire rst,
    input wire [BWID-1:0] iv_data,
    input wire i_nd,
    output wire [BWID-1:0] ov_data,
    output wire o_dv
);

    reg [BWID-1:0] r0 [N_ND:0];
    reg [BWID-1:0] r1 [N_Clk-1:0];
    reg nd_ds [N_Clk-1:0];

    genvar i, j;

    // Non-clocked delay
    generate
        if (N_ND > 0) begin : gen_nd
            always @(*) begin
                r0[0] = iv_data;
                for (j = 1; j <= N_ND; j = j + 1) begin
                    r0[j] = i_nd ? r0[j-1] : r0[j];
                end
            end
        end
    endgenerate

    // Clocked delay
    generate
        for (i = 0; i < N_Clk; i = i + 1) begin : gen_clk
            always @(posedge clk) begin
                if (IsReset && rst) begin
                    r1[i] <= {BWID{1'b0}};
                    nd_ds[i] <= 1'b0;
                end else begin
                    if (i == 0) begin
                        r1[i] <= (N_ND > 0) ? r0[N_ND] : iv_data;
                        nd_ds[i] <= i_nd;
                    end else begin
                        r1[i] <= r1[i-1];
                        nd_ds[i] <= nd_ds[i-1];
                    end
                end
            end
        end
    endgenerate

    assign ov_data = r1[N_Clk-1];
    assign o_dv = nd_ds[N_Clk-1];

endmodule

