module I82C55(
input wire [1:0] I_ADDR,
input wire [7:0] I_DATA,
output reg [7:0] O_DATA,
input wire CS_H,
input wire WR_L,
output reg [7:0] O_PA,
input wire [7:0] I_PB,
input wire [3:0] I_PC,
output reg [3:0] O_PC,
input wire RESET,
input wire ENA,
input wire CLK
);
// A1-A0
// D7-D0
// (CPU) clk enable
// registers
reg [7:0] r_porta;
reg [7:0] r_portb;
reg [3:0] l_portc;
reg [3:0] h_portc;
reg [7:0] ctrl_reg;
  always @(posedge RESET, posedge CLK) begin
    if((RESET == 1'b0)) begin
      r_porta <= 8'h00;
      r_portb <= 8'h00;
      l_portc <= 4'h0;
      h_portc <= 4'h0;
      ctrl_reg <= 8'h00;
    end else begin
      O_PA <= r_porta;
      r_portb <= I_PB;
      h_portc <= I_PC;
      O_PC <= l_portc;
      if((CS_H == 1'b1)) begin
        if((WR_L == 1'b0)) begin
          case(I_ADDR)
          2'b00 : begin
            r_porta <= I_DATA;
            //when "01" => r_portb   <= I_DATA;
          end
          2'b10 : begin
            l_portc <= I_DATA[3:0];
          end
          2'b11 : begin
            if((I_DATA[7] == 1'b0)) begin
              // set/clr
              l_portc[2] <= I_DATA[0];
            end
            else begin
              ctrl_reg <= I_DATA;
            end
          end
          default : begin
          end
          endcase
        end
        else begin
          // read ports
          case(I_ADDR)
          2'b00 : begin
            O_DATA <= r_porta;
          end
          2'b01 : begin
            O_DATA <= r_portb;
          end
          2'b10 : begin
            O_DATA <= {h_portc,l_portc};
          end
          2'b11 : begin
            O_DATA <= ctrl_reg;
          end
          default : begin
          end
          endcase
        end
      end
    end
  end
endmodule

module lpm_latch (
    input [lpm_width-1:0] data,
    input gate,
    input aclr,
    input aset,
    input aconst,
    output reg [lpm_width-1:0] q
);

parameter lpm_width = 1;
parameter lpm_avalue = "UNUSED";
parameter lpm_pvalue = "UNUSED";
parameter lpm_type = "lpm_latch";
parameter lpm_hint = "UNUSED";

reg [lpm_width-1:0] avalue;
reg [lpm_width-1:0] pvalue;
reg i_aclr, i_aset;

// Convert string parameters to register values
task string_to_reg;
    input [8*256:1] s;
    output [lpm_width-1:0] o;
    integer i;
    begin
        o = 0;
        for (i = 1; i <= 256; i = i + 1) begin
            if (s[i*8-:8] == 0) i = 257;
            else if (s[i*8-:8] == "1") o[i-1] = 1'b1;
        end
    end
endtask

initial begin
    // Parameter validation
    if (lpm_width <= 0) begin
        $display("Error: lpm_width must be greater than 0");
        $finish;
    end

    // Initialize avalue and pvalue
    if (lpm_avalue !== "UNUSED") string_to_reg(lpm_avalue, avalue);
    if (lpm_pvalue !== "UNUSED") string_to_reg(lpm_pvalue, pvalue);

    // Initialize output
    if (lpm_pvalue !== "UNUSED") q = pvalue;
    else q = {lpm_width{1'b0}};

    i_aclr = 1'b0;
    i_aset = 1'b0;
end

always @(data or gate or aclr or aset or avalue) begin
    i_aclr = aclr;
    i_aset = aset;

    if (i_aclr) begin
        q <= {lpm_width{1'b0}};
    end
    else if (i_aset) begin
        q <= avalue;
    end
    else if (gate) begin
        q <= data;
    end
end

endmodule

module Output_Driver_test (
    input wire clki,
    input wire Output_Driver_clk_enb,
    input wire Output_Driver_enb,
    output reg clk_o,
    output reg Output_Driver_IN
);

    parameter M = 166667;

    reg [25:0] cnt;
    reg [7:0] cnt_data;

    // Clock division
    always @(posedge clki) begin
        if (Output_Driver_clk_enb) begin
            cnt <= 26'd0;
            clk_o <= 1'b0;
        end else begin
            if (cnt == (M/2 - 1)) begin
                cnt <= 26'd0;
                clk_o <= ~clk_o;
            end else begin
                cnt <= cnt + 1'b1;
            end
        end
    end

    // Data output generation
    always @(negedge clk_o) begin
        if (Output_Driver_enb) begin
            cnt_data <= 8'd0;
            Output_Driver_IN <= 1'b0;
        end else begin
            if (cnt_data == 8'd128) begin
                cnt_data <= 8'd0;
                Output_Driver_IN <= 1'b1;
            end else begin
                cnt_data <= cnt_data + 1'b1;
                Output_Driver_IN <= 1'b0;
            end
        end
    end

endmodule

