module sevenseg(
input wire [3:0] dataIn,
output reg [6:0] segmentsOut
);
  // The following SELECT statement converts a 4 bit number, called dataIn to a pattern of 7 bits, or wires, 
  //   to connect to a 7-segment display called segmentsOut
  //
  always @(*) begin
    case(dataIn)
  // 7-segment bits are A to G but the LSB is A
      4'b0000 : segmentsOut[6:0] <= 7'b1000000;
  // 0
      4'b0001 : segmentsOut[6:0] <= 7'b1111001;
  // 1
      4'b0010 : segmentsOut[6:0] <= 7'b0100100;
  // 2
      4'b0011 : segmentsOut[6:0] <= 7'b0110000;
  // 3
      4'b0100 : segmentsOut[6:0] <= 7'b0011001;
  // 4
      4'b0101 : segmentsOut[6:0] <= 7'b0010010;
  // 5
      4'b0110 : segmentsOut[6:0] <= 7'b0000010;
  // 6
      4'b0111 : segmentsOut[6:0] <= 7'b1111000;
  // 7
      4'b1000 : segmentsOut[6:0] <= 7'b0000000;
  // 8
      4'b1001 : segmentsOut[6:0] <= 7'b0010000;
  // 9
      4'b1010 : segmentsOut[6:0] <= 7'b0001000;
  // A
      4'b1011 : segmentsOut[6:0] <= 7'b0000011;
  // b
      4'b1100 : segmentsOut[6:0] <= 7'b0100111;
  // c
      4'b1101 : segmentsOut[6:0] <= 7'b0100001;
  // d
      4'b1110 : segmentsOut[6:0] <= 7'b0000110;
