module n_modulo_counter #(
    parameter n = 2,
    parameter counter_bits = 1
)(
    input wire clk,
    input wire r,
    input wire en,
    output wire co,
    output reg [counter_bits-1:0] q
);

    // Combinational logic for carry out
    assign co = en && (q == n - 1);

    // Sequential logic for counter
    always @(posedge clk or posedge r) begin
        if (r) begin
            q <= 0;
        end else if (en) begin
            if (q == n - 1) begin
                q <= 0;
            end else begin
                q <= q + 1;
            end
        end
    end

endmodule

