module prescaler_FSM(
input wire clk,
input wire toggle,
input wire reset,
output reg [1:0] clk_state
);
parameter [1:0]
  clk1 = 0,
  clk2 = 1,
  clk3 = 2,
  clk4 = 3;
reg [1:0] next_state;
  always @(posedge clk, posedge reset, posedge next_state, posedge toggle) begin
    if(reset == 1'b1) begin
      next_state <= clk1;
    end else begin
      case(next_state)
      clk1 : begin
        if(toggle == 1'b1) begin
          next_state <= clk2;
        end
        else begin
          next_state <= clk1;
          clk_state <= 2'b00;
        end
        //------------------------------------		
      end
      clk2 : begin
        if(toggle == 1'b1) begin
          next_state <= clk3;
        end
        else begin
          next_state <= clk2;
          clk_state <= 2'b01;
        end
        //------------------------------------			
      end
      clk3 : begin
        if(toggle == 1'b1) begin
          next_state <= clk4;
        end
        else begin
          next_state <= clk3;
          clk_state <= 2'b10;
        end
        //----------------------------------			
      end
      clk4 : begin
        if(toggle == 1'b1) begin
          next_state <= clk1;
        end
        else begin
          next_state <= clk4;
          clk_state <= 2'b11;
        end
      end
      endcase
    end
  end
endmodule

module modulo_m_counter #(
    parameter N = 32
)(
    input wire [N-1:0] M,
    input wire clk,
    input wire reset,
    output reg max_tick,
    output wire [N-1:0] q
);

reg [N-1:0] r_reg, r_next;

always @(posedge clk or posedge reset)
begin
    if (reset)
        r_reg <= {N{1'b0}};
    else
        r_reg <= r_next;
end

always @*
begin
    if (M == {N{1'b0}} || r_reg == M - 1'b1)
        r_next = {N{1'b0}};
    else
        r_next = r_reg + 1'b1;
end

always @(posedge clk or posedge reset)
begin
    if (reset)
        max_tick <= 1'b0;
    else
        max_tick <= (M == {N{1'b0}}) || (r_reg == M - 1'b1);
end

assign q = r_reg;

endmodule

