module barrel_shifter_32bit (
    input [31:0] in,
    input [4:0] s,
    input dir,
    output [31:0] out
);

    wire [31:0] a, b, c, d, e;
    wire [31:0] a1, b1, c1, d1, e1;

    // Left shift stages
    assign a = s[0] ? {in[30:0], 1'b0} : in;
    assign b = s[1] ? {a[29:0], 2'b0} : a;
    assign c = s[2] ? {b[27:0], 4'b0} : b;
    assign d = s[3] ? {c[23:0], 8'b0} : c;
    assign e = s[4] ? {d[15:0], 16'b0} : d;

    // Right shift stages
    assign a1 = s[0] ? {1'b0, in[31:1]} : in;
    assign b1 = s[1] ? {2'b0, a1[31:2]} : a1;
    assign c1 = s[2] ? {4'b0, b1[31:4]} : b1;
    assign d1 = s[3] ? {8'b0, c1[31:8]} : c1;
    assign e1 = s[4] ? {16'b0, d1[31:16]} : d1;

    // Output selection based on direction
    assign out = dir ? e1 : e;

endmodule

module register16(
input wire [3:0] d,
output reg [15:0] q,
input wire clk,
input wire reset,
input wire load
);
// Intermediate Signals --
reg [1:0] i_nibbleCount;
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      i_nibbleCount <= 2'b11;
      q <= {16{1'b0}};
    end else begin
      if(load == 1'b1) begin
        // Load Nibble 3 --
        if(i_nibbleCount == 2'b11) begin
          q[15] <= d[3];
          q[14] <= d[2];
          q[13] <= d[1];
          q[12] <= d[0];
          // Load Nibble 2 --
        end
        else if(i_nibbleCount == 2'b10) begin
          q[11] <= d[3];
          q[10] <= d[2];
          q[9] <= d[1];
          q[8] <= d[0];
          // Load Nibble 1 --
        end
        else if(i_nibbleCount == 2'b01) begin
          q[7] <= d[3];
          q[6] <= d[2];
          q[5] <= d[1];
          q[4] <= d[0];
          // Load Nibble 0 --
        end
        else if(i_nibbleCount == 2'b00) begin
          q[3] <= d[3];
          q[2] <= d[2];
          q[1] <= d[1];
          q[0] <= d[0];
        end
        if(i_nibbleCount == 2'b00) begin
          i_nibbleCount <= 2'b11;
        end
        else begin
          i_nibbleCount <= i_nibbleCount - 1'b1;
        end
      end
    end
  end
endmodule

