        if (Reset)
            LED <= 0;
        else if (w)
            LED <= 1;
        else if (~Pushn)
            LED <= 0;
    end

    BCDcount counter(
        .Clock(c9),
        .Clear(Reset),
        .E(E),
        .BCD1(BCD1),
        .BCD0(BCD0)
    );

    seg7 seg_1(
