module BCDcount(
    input Clock, Clear, E,
    output reg [3:0] BCD1, BCD0
);
    always @(posedge Clock or posedge Clear) begin
        if (Clear) begin
            BCD1 <= 4'b0000;
            BCD0 <= 4'b0000;
        end
        else if (E) begin
            if (BCD0 == 4'b1001) begin
                BCD0 <= 4'b0000;
                if (BCD1 == 4'b1001)
                    BCD1 <= 4'b0000;
                else
                    BCD1 <= BCD1 + 1;
            end
            else
                BCD0 <= BCD0 + 1;
        end
    end
endmodule

