output wire [7:0] segs_out,
output reg [3:0] anodes_out
);
// This can be overridden to change the refresh rate. The anode pattern will change at a
// frequency given by F(clk_in) / (2**COUNTER_WIDTH). So for a 50MHz clk_in and
// COUNTER_WIDTH=18, the anode pattern changes at ~191Hz, which means each digit gets
// refreshed at ~48Hz.
parameter [31:0] COUNTER_WIDTH=16;
reg [COUNTER_WIDTH - 1:0] count = 1'b0;
wire [COUNTER_WIDTH - 1:0] count_next;
wire [1:0] anodeSelect;
reg [3:0] nibble;
reg [6:0] segs;
reg dot;
  // Infer counter register
  always @(posedge clk_in) begin
    count <= count_next;
  end
  // Increment counter and derive anode select from top two bits
  assign count_next = count + 1;
  assign anodeSelect = count[COUNTER_WIDTH - 1:COUNTER_WIDTH - 2];
  // Drive anodes
  always @(*) begin
    case(anodeSelect)
      2'b00 : anodes_out <= 4'b0111;
      2'b01 : anodes_out <= 4'b1011;
      2'b10 : anodes_out <= 4'b1101;
      default : anodes_out <= 4'b1110;
    endcase
  end
  // Select the appropriate bit from dots_in
  always @(*) begin
    case(anodeSelect)
      2'b00 : dot <=  ~(dots_in[3]);
      2'b01 : dot <=  ~(dots_in[2]);
      2'b10 : dot <=  ~(dots_in[1]);
      default : dot <=  ~(dots_in[0]);
    endcase
  end
  // Choose a nibble to display
  always @(*) begin
    case(anodeSelect)
      2'b00 : nibble <= data_in[15:12];
      2'b01 : nibble <= data_in[11:8];
      2'b10 : nibble <= data_in[7:4];
      default : nibble <= data_in[3:0];
    endcase
  end
  // Decode chosen nibble
  always @(*) begin
    case(nibble)
      4'b0000 : segs <= 7'b1000000;
      4'b0001 : segs <= 7'b1111001;
      4'b0010 : segs <= 7'b0100100;
      4'b0011 : segs <= 7'b0110000;
      4'b0100 : segs <= 7'b0011001;
      4'b0101 : segs <= 7'b0010010;
      4'b0110 : segs <= 7'b0000010;
      4'b0111 : segs <= 7'b1111000;
      4'b1000 : segs <= 7'b0000000;
      4'b1001 : segs <= 7'b0010000;
      4'b1010 : segs <= 7'b0001000;
      4'b1011 : segs <= 7'b0000011;
      4'b1100 : segs <= 7'b1000110;
      4'b1101 : segs <= 7'b0100001;
      4'b1110 : segs <= 7'b0000110;
      default : segs <= 7'b0001110;
    endcase
  end
  // Drive segs_out
  assign segs_out = {dot,segs};
endmodule

module exp_compare (
    input [15:0] exponents,
    output reg [8:0] valoarea1,
    output reg [7:0] exp_out
);

    reg [7:0] exp_a, exp_b;
    reg signed [8:0] adjusted_exp_a, adjusted_exp_b;

    always @(*) begin
        // Extract exponents
        exp_a = exponents[15:8];
        exp_b = exponents[7:0];

        // Adjust exponents
        adjusted_exp_a = exp_a - 9'd127;
        adjusted_exp_b = exp_b - 9'd127;

        // Compare adjusted exponents
        if (adjusted_exp_a > adjusted_exp_b) begin
            valoarea1[8] = 1'b1;
            valoarea1[7:0] = adjusted_exp_a - adjusted_exp_b;
            exp_out = exp_a;
        end else begin
            valoarea1[8] = 1'b0;
            valoarea1[7:0] = adjusted_exp_b - adjusted_exp_a;
            exp_out = exp_b;
        end
    end

endmodule

