module next_pc(
input wire I_srcA_isPort,
input wire I_dst_isPort,
input wire I_pr_isDataOutValid,
input wire I_pw_isDataOutValid,
input wire [15:0] I_regB_data,
input wire [15:0] I_imm,
input wire I_containsIMM,
input wire I_isJump,
input wire [2:0] I_jmpCondition,
input wire I_isZero,
input wire I_isLessThan,
input wire [5:0] I_PC,
output reg [5:0] O_NewPC
);
reg isReadPortReady; reg isWritePortReady;
reg [5:0] jmpDelta;
reg takeJump;
  always @(I_srcA_isPort, I_pr_isDataOutValid) begin
    isReadPortReady <= ( ~I_srcA_isPort) | (I_srcA_isPort & I_pr_isDataOutValid);
  end
  always @(I_dst_isPort, I_pw_isDataOutValid) begin
    isWritePortReady <= ( ~I_dst_isPort) | (I_dst_isPort & I_pw_isDataOutValid);
  end
  always @(I_regB_data, I_imm, I_containsIMM) begin
    if((I_containsIMM == 1'b1)) begin
      jmpDelta <= I_imm[5:0];
    end
    else begin
      jmpDelta <= I_regB_data[5:0];
    end
  end
  always @(I_jmpCondition, I_isZero, I_isLessThan) begin
    case(I_jmpCondition)
    3'b000 : begin
      takeJump <= 1'b1;
      // Unconditional jump
    end
    3'b001 : begin
      takeJump <=  ~((I_isZero & 1'b1) | (I_isLessThan & 1'b1));
      // JGZ
    end
    3'b010 : begin
      takeJump <= (I_isZero & 1'b0) | (I_isLessThan & 1'b1);
      // JLZ
    end
    3'b011 : begin
      takeJump <= (I_isZero & 1'b1) | (I_isLessThan & 1'b0);
      // JEZ
    end
    3'b100 : begin
      takeJump <=  ~(I_isZero & 1'b1) | (I_isLessThan & 1'b0);
      // JNZ
    end
    default : begin
      takeJump <= 1'b0;
      // Unknown jump condition
    end
    endcase
  end
  always @(I_PC, takeJump, jmpDelta, isWritePortReady, isReadPortReady) begin
    // If this is a port instruction, wait until the port is ready.
    if((isReadPortReady == 1'b0 || isWritePortReady == 1'b0)) begin
      O_NewPC <= I_PC;
    end
    else begin
      // Otherwise, if it's not a jump or the jump condition is false, move on to the next instruction.
      if((I_isJump == 1'b0 || takeJump == 1'b0)) begin
        O_NewPC <= I_PC + 1;
      end
      else begin
        // Finally, this is a jump instruction and the condition is true. Jump!
        O_NewPC <= I_PC + jmpDelta;
        // This is a signed add.
      end
    end
  end
endmodule

module mux4 (
    input wire Jump,
    input wire [25:0] inst,
    input wire [31:0] PC,
    input wire [31:0] mux5out,
    output wire [31:0] result
);

    wire [31:0] temp;
    wire [31:0] JumpAddress;

    // Increment PC by 1
    assign temp = PC + 32'd1;

    // Construct jump address
    assign JumpAddress = {temp[31:28], inst[25:0], 2'b00};

    // Select between jump address and mux5out based on Jump signal
    assign result = Jump ? JumpAddress : mux5out;

endmodule

module flow_ctrl (
    input wire reset,
    input wire dc_stall,
    input wire is_branch,
    input wire is_jump,
    input wire hzd_stall,
    input wire ic_stall,
    output reg pc_we, if_we, id_we, ex_we, mem_we, wb_we,
    output reg pc_flush, if_flush, id_flush, ex_flush, mem_flush, wb_flush
);

always @(*) begin
    if (reset) begin
        {pc_we, if_we, id_we, ex_we, mem_we, wb_we} = 6'b111111;
        {pc_flush, if_flush, id_flush, ex_flush, mem_flush, wb_flush} = 6'b111111;
    end
    else if (dc_stall) begin
        {pc_we, if_we, id_we, ex_we, mem_we, wb_we} = 6'b000011;
        {pc_flush, if_flush, id_flush, ex_flush, mem_flush, wb_flush} = 6'b000010;
    end
    else if (is_branch) begin
        {pc_we, if_we, id_we, ex_we, mem_we, wb_we} = 6'b111111;
        {pc_flush, if_flush, id_flush, ex_flush, mem_flush, wb_flush} = 6'b011100;
    end
    else if (is_jump) begin
        {pc_we, if_we, id_we, ex_we, mem_we, wb_we} = 6'b111111;
        {pc_flush, if_flush, id_flush, ex_flush, mem_flush, wb_flush} = 6'b011000;
    end
    else if (hzd_stall) begin
        {pc_we, if_we, id_we, ex_we, mem_we, wb_we} = 6'b001111;
        {pc_flush, if_flush, id_flush, ex_flush, mem_flush, wb_flush} = 6'b001000;
    end
    else if (ic_stall) begin
        {pc_we, if_we, id_we, ex_we, mem_we, wb_we} = 6'b011111;
        {pc_flush, if_flush, id_flush, ex_flush, mem_flush, wb_flush} = 6'b010000;
    end
    else begin
        {pc_we, if_we, id_we, ex_we, mem_we, wb_we} = 6'b111111;
        {pc_flush, if_flush, id_flush, ex_flush, mem_flush, wb_flush} = 6'b100000;
    end
end

endmodule

