module intel_8254_simplified (
    input wire clk,
    input wire rst,
    input wire CS,
    input wire GATE0,
    output reg OUT0,
    output reg [7:0] data
);

reg GATE0S;
reg flag;
reg FLAG;
reg [3:0] counter;
reg [3:0] capture;
reg [3:0] Toggles;

always @(posedge clk or negedge rst) begin
    if (!rst) begin
        GATE0S <= 1'b1;
        FLAG <= 1'b0;
        OUT0 <= 1'b0;
        counter <= 4'd1;
        Toggles <= 4'd0;
    end else if (CS) begin
        GATE0S <= GATE0;
        FLAG <= flag;

        if (GATE0 != GATE0S) begin
            capture <= counter + 1'b1;
            flag <= 1'b1;
            Toggles <= (Toggles == 4'd10 && FLAG) ? 4'd1 : Toggles + 1'b1;
        end

        if (flag) begin
            if (GATE0 != GATE0S) begin
                OUT0 <= FLAG && (Toggles % 10 != 0);
                counter <= 4'd1;
            end else begin
                OUT0 <= 1'b0;
                counter <= counter + 1'b1;
            end
        end
    end
end

always @(*) begin
    if (CS && flag)
        data = {4'b0000, capture};
    else
        data = 8'bz;
end

endmodule

