module dp_lnnornd(
input wire sysclk,
input wire reset,
input wire enable,
input wire signln,
input wire [11:1] exponentln,
input wire [53:1] mantissaln,
input wire nanin,
input wire infinityin,
input wire zeroin,
output wire signout,
output wire [11:1] exponentout,
output wire [52:1] mantissaout,
output wire nanout,
output wire overflowout,
output wire zeroout
);
//------------------------------------------------
parameter expwidth = 11;
parameter manwidth = 52;
reg nanff;
reg infinityff;
reg zeroff;
reg signff;
reg [manwidth:1] mantissaff;
reg [expwidth:1] exponentff;
wire setmanzero; wire setexpzero; wire setmanmax; wire setexpmax;
  always @(posedge sysclk, posedge reset) begin
    if((reset == 1'b1)) begin
      nanff <= 1'b0;
      signff <= 1'b0;
      for (k=1; k <= manwidth; k = k + 1) begin
        mantissaff[k] <= 1'b0;
      end
      for (k=1; k <= expwidth; k = k + 1) begin
        exponentff[k] <= 1'b0;
      end
    end else begin
      if((enable == 1'b1)) begin
        signff <= signln;
        nanff <= nanin;
        infinityff <= infinityin;
        zeroff <= zeroin;
        // nan takes precedence (set max)  
        for (k=1; k <= manwidth; k = k + 1) begin
          mantissaff[k] <= (mantissaln[k + 1] &  ~(setmanzero)) | setmanmax;
        end
        for (k=1; k <= expwidth; k = k + 1) begin
          exponentff[k] <= (exponentln[k] &  ~(setexpzero)) | setexpmax;
        end
      end
    end
  end
  //**********************************
  //*** CHECK GENERATED CONDITIONS ***   
  //**********************************
  // all set to '1' when true
  // set mantissa to 0 when zero or infinity condition
  assign setmanzero =  ~(zeroin) | infinityin;
  // setmantissa to "11..11" when nan
  assign setmanmax = nanin;
  // set exponent to 0 when zero condition 
  assign setexpzero =  ~(zeroin);
  // set exponent to "11..11" when nan or infinity
  assign setexpmax = nanin | infinityin;
  //***************
  //*** OUTPUTS ***
  //***************
  assign signout = signff;
  assign mantissaout = mantissaff;
  assign exponentout = exponentff;
  //---------------------------------------------
  assign nanout = nanff;
  assign overflowout = infinityff;
  assign zeroout = zeroff;
endmodule

module Controller (
    input wire clk,
    input wire reset,
    input wire record_1,
    input wire record_2,
    input wire play_1,
    input wire play_2,
    input wire flag,
    output reg en_des,
    output reg en_ser,
    output reg wea,
    output reg id,
    output reg re,
    output reg dn,
    output reg en,
    output reg en2
);

    // State encoding
    localparam [2:0] 
        IDLE = 3'b000,
        RECORD_CLIP_1 = 3'b001,
        DONE_RECORD = 3'b010,
        OUTPUT_CLIP_1 = 3'b011,
        RECORD_CLIP_2 = 3'b100,
        OUTPUT_CLIP_2 = 3'b101;

    reg [2:0] state, next_state;
    reg [2:0] repeat1, repeat2;

    // Sequential logic for state updates
    always @(posedge clk or posedge reset) begin
        if (reset)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Combinational logic for next state and output
    always @(*) begin
        // Default assignments
        next_state = state;
        en_des = 0;
        en_ser = 0;
        wea = 0;
        id = 0;
        re = 0;
        dn = 0;
        en = 0;
        en2 = 0;

        case (state)
            IDLE: begin
                if (record_1)
                    next_state = RECORD_CLIP_1;
                else if (record_2)
                    next_state = RECORD_CLIP_2;
            end

            RECORD_CLIP_1: begin
                en_des = 1;
                wea = 1;
                if (flag)
                    next_state = DONE_RECORD;
            end

            DONE_RECORD: begin
                dn = 1;
                if (play_1 && repeat1 < 7)
                    next_state = OUTPUT_CLIP_1;
                else if (play_2 && repeat2 < 7)
                    next_state = OUTPUT_CLIP_2;
                else if (repeat1 >= 7 && repeat2 >= 7)
                    next_state = IDLE;
            end

            OUTPUT_CLIP_1: begin
                en_ser = 1;
                re = 1;
                en = 1;
                if (flag) begin
                    next_state = DONE_RECORD;
                    repeat1 = repeat1 + 1;
                end
            end

            RECORD_CLIP_2: begin
                en_des = 1;
                wea = 1;
                id = 1;
                if (flag)
                    next_state = DONE_RECORD;
            end

            OUTPUT_CLIP_2: begin
                en_ser = 1;
                re = 1;
                id = 1;
                en2 = 1;
                if (flag) begin
                    next_state = DONE_RECORD;
                    repeat2 = repeat2 + 1;
                end
            end

            default: next_state = IDLE;
        endcase
    end

endmodule

