module counter_3bit (
    input wire inorder,
    input wire clock,
    input wire reset,
    output reg [2:0] count
);

    // State encoding
    parameter [2:0] STATE0 = 3'b000,
                    STATE1 = 3'b001,
                    STATE2 = 3'b010,
                    STATE3 = 3'b011,
                    STATE4 = 3'b100,
                    STATE5 = 3'b101,
                    STATE6 = 3'b110,
                    STATE7 = 3'b111;

    reg [2:0] current_state, next_state;

    // State register
    always @(posedge clock or posedge reset) begin
        if (reset)
            current_state <= STATE0;
        else
            current_state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            STATE0: next_state = STATE1;
            STATE1: next_state = inorder ? STATE2 : STATE4;
            STATE2: next_state = inorder ? STATE3 : STATE5;
            STATE3: next_state = inorder ? STATE4 : STATE6;
            STATE4: next_state = inorder ? STATE5 : STATE2;
            STATE5: next_state = inorder ? STATE6 : STATE3;
            STATE6: next_state = inorder ? STATE7 : STATE1;
            STATE7: next_state = STATE1;
            default: next_state = STATE0;
        endcase
    end

    // Output logic
    always @(*) begin
        if (current_state == STATE7)
            count = 3'b001;
        else
            count = current_state;
    end

endmodule

