    input [1:0] speed,
    output reg [9:0] car_x,
    output reg [8:0] car_y
);

    reg [18:0] clk_divider;
    reg clk_move;

    // Clock divider
    always @(posedge clk_100mhz or posedge rst) begin
        if (rst) begin
            clk_divider <= 19'd0;
            clk_move <= 1'b0;
        end else begin
            if (clk_divider == 19'd469999) begin
                clk_divider <= 19'd0;
                clk_move <= ~clk_move;
            end else begin
                clk_divider <= clk_divider + 1'b1;
            end
        end
    end

    // Car movement
    always @(posedge clk_move or posedge rst) begin
        if (rst) begin
            car_x <= 10'd364;
            car_y <= 9'd364;
        end else begin
            if (forward) begin
                car_y <= (car_y >= {1'b0, speed}) ? car_y - {1'b0, speed} : 9'd0;
            end else if (backward) begin
                car_y <= (car_y <= 9'd511 - {1'b0, speed}) ? car_y + {1'b0, speed} : 9'd511;
            end else if (left) begin
                car_x <= (car_x >= {2'b00, speed}) ? car_x - {2'b00, speed} : 10'd0;
            end else if (right) begin
                car_x <= (car_x <= 10'd1023 - {2'b00, speed}) ? car_x + {2'b00, speed} : 10'd1023;
            end
        end
    end

endmodule

