module checkEnd(
input wire [3:0] try0,
input wire [3:0] try1,
input wire [3:0] cert,
input wire [3:0] erra,
input wire clock,
input wire reset,
output reg isBlink,
output reg isend,
output wire [3:0] p,
output wire [3:0] n,
output reg [3:0] t1,
output reg [3:0] t0,
output reg b_load
);
// Entidade que possui máquina de estados que faz atribuições essenciais para sinalização de saídas.
parameter [1:0]
  S0 = 0,
  S1 = 1,
  S2 = 2,
  S3 = 3;
reg [1:0] pState = S0; reg [1:0] nState = S0;
reg [3:0] s_p = 4'b0000; reg [3:0] s_n = 4'b0000;
reg [3:0] final_try1; reg [3:0] final_try0;
reg load;
  always @(posedge clock, posedge reset) begin
    if((reset == 1'b1)) begin
      pState <= S0;
      final_try0 <= {4{1'b0}};
      final_try1 <= {4{1'b0}};
    end else begin
      if((load == 1'b1)) begin
        final_try0 <= try0;
        final_try1 <= try1;
      end
      pState <= nState;
    end
  end
  always @(pState, cert, erra, try0, try1) begin
    b_load <= 1'b1;
    load <= 1'b1;
    case(pState)
    S0 : begin
      b_load <= 1'b1;
      isblink <= 1'b0;
      t1 <= 4'b1111;
      t0 <= 4'b1111;
      isend <= 1'b0;
      nState <= S3;
    end
    S1 : begin
      isblink <= 1'b1;
      t1 <= final_try1;
      t0 <= final_try0;
      s_p <= 4'b0100;
      s_n <= 4'b0000;
      load <= 1'b0;
      isend <= 1'b0;
      b_load <= 1'b0;
      nState <= S1;
    end
    S2 : begin
      s_p <= 4'b0000;
      s_n <= 4'b0000;
      isend <= 1'b1;
      isBlink <= 1'b0;
      t1 <= 4'b1001;
      t0 <= 4'b1001;
      nState <= S2;
    end
    S3 : begin
      s_p <= cert;
      s_n <= erra;
      t1 <= 4'b1111;
      t0 <= 4'b1111;
      isend <= 1'b0;
      isblink <= 1'b0;
      if((s_p == 4'b0100)) begin
        t1 <= try1;
        t0 <= try0;
        isblink <= 1'b1;
        nState <= S1;
        b_load <= 1'b0;
        load <= 1'b1;
      end
      else if((try1 == 4'b1001 && try0 == 4'b1001)) begin
        nState <= S2;
      end
      else begin
        nState <= S3;
      end
    end
    default : begin
      nState <= S0;
    end
    endcase
  end
  assign p = s_p;
  assign n = s_n;
endmodule

module hcc_lsftcomb64(
input wire [64:1] inbus,
input wire [6:1] shift,
output wire [64:1] outbus
);
wire [64:1] levzip; wire [64:1] levone; wire [64:1] levtwo; wire [64:1] levthr;
  assign levzip = inbus;
  // shift by 0,1,2,3
  assign levone[1] = levzip[1] &  ~(shift[2]) &  ~(shift[1]);
  assign levone[2] = (levzip[2] &  ~(shift[2]) &  ~(shift[1])) | (levzip[1] &  ~(shift[2]) & shift[1]);
  assign levone[3] = (levzip[3] &  ~(shift[2]) &  ~(shift[1])) | (levzip[2] &  ~(shift[2]) & shift[1]) | (levzip[1] & shift[2] &  ~(shift[1]));
  genvar k;
  generate for (k=4; k <= 64; k = k + 1) begin: gaa
      assign levone[k] = (levzip[k] &  ~(shift[2]) &  ~(shift[1])) | (levzip[k - 1] &  ~(shift[2]) & shift[1]) | (levzip[k - 2] & shift[2] &  ~(shift[1])) | (levzip[k - 3] & shift[2] & shift[1]);
  end
  endgenerate
  // shift by 0,4,8,12
  genvar k;
  generate for (k=1; k <= 4; k = k + 1) begin: gba
      assign levtwo[k] = levone[k] &  ~(shift[4]) &  ~(shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=5; k <= 8; k = k + 1) begin: gbb
      assign levtwo[k] = (levone[k] &  ~(shift[4]) &  ~(shift[3])) | (levone[k - 4] &  ~(shift[4]) & shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=9; k <= 12; k = k + 1) begin: gbc
      assign levtwo[k] = (levone[k] &  ~(shift[4]) &  ~(shift[3])) | (levone[k - 4] &  ~(shift[4]) & shift[3]) | (levone[k - 8] & shift[4] &  ~(shift[3]));
  end
  endgenerate
  genvar k;
  generate for (k=13; k <= 64; k = k + 1) begin: gbd
      assign levtwo[k] = (levone[k] &  ~(shift[4]) &  ~(shift[3])) | (levone[k - 4] &  ~(shift[4]) & shift[3]) | (levone[k - 8] & shift[4] &  ~(shift[3])) | (levone[k - 12] & shift[4] & shift[3]);
  end
  endgenerate
  genvar k;
  generate for (k=1; k <= 16; k = k + 1) begin: gca
      assign levthr[k] = levtwo[k] &  ~(shift[6]) &  ~(shift[5]);
  end
  endgenerate
  genvar k;
  generate for (k=17; k <= 32; k = k + 1) begin: gcb
      assign levthr[k] = (levtwo[k] &  ~(shift[6]) &  ~(shift[5])) | (levtwo[k - 16] &  ~(shift[6]) & shift[5]);
  end
  endgenerate
  genvar k;
  generate for (k=33; k <= 48; k = k + 1) begin: gcc
      assign levthr[k] = (levtwo[k] &  ~(shift[6]) &  ~(shift[5])) | (levtwo[k - 16] &  ~(shift[6]) & shift[5]) | (levtwo[k - 32] & shift[6] &  ~(shift[5]));
  end
  endgenerate
  genvar k;
  generate for (k=49; k <= 64; k = k + 1) begin: gcd
      assign levthr[k] = (levtwo[k] &  ~(shift[6]) &  ~(shift[5])) | (levtwo[k - 16] &  ~(shift[6]) & shift[5]) | (levtwo[k - 32] & shift[6] &  ~(shift[5])) | (levtwo[k - 48] & shift[6] & shift[5]);
  end
  endgenerate
  assign outbus = levthr;
endmodule

