always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        r_data_in0 <= 1'b0;
        r_data_in1 <= 1'b0;
    end else begin
        r_data_in1 <= i_data_in;
        r_data_in0 <= r_data_in1;
    end
