module brdRstClk(
input wire i_rst_n,
input wire i_clk,
output wire o_rst_n,
output wire o_clk
);
//--------------------------------------------------------------------
wire s_rst_in; reg s_dly_n; reg s_rst_n; wire s_clk;  // FLASH FPGA tools will not synthesise := "00101" !!!
// With G3 expext random values, with G4 all ZEROs.
// Looks OK with Modelsim PRE synthesis, NOT in reality.
reg [4:0] s_one = 5'b00101;
reg [4:0] s_two = 5'b01001;  // not using := increases chance to find uninitialized values
  SYSRESET SYSRESET_0(
      .DEVRST_N(i_rst_n),
    .POWER_ON_RESET_N(s_rst_in));
  always @(posedge i_clk, posedge s_rst_in) begin : P2
  // sync s_rst_n to i_clk
    if(s_rst_in == 1'b0) begin
      s_dly_n <= 1'b0;
      s_rst_n <= 1'b0;
    end else begin
      s_dly_n <= 1'b1;
      s_rst_n <= s_dly_n;
    end
  end
  always @(posedge i_clk, posedge s_rst_n) begin : P1
  // divide clock by shifting pattern
    if((s_rst_n == 1'b0)) begin
      s_one <= 5'b00101;
    end else begin
      s_one <= {s_one[0],s_one[4:1]};
    end
  end
  always @(negedge i_clk, negedge s_rst_n) begin
    if((s_rst_n == 1'b0)) begin
      s_two <= 5'b01001;
    end else begin
      s_two <= {s_two[0],s_two[4:1]};
    end
  end
  assign s_clk = s_one[0] & s_two[0];
  // decide if second RESET sync block here
  assign o_rst_n = s_rst_n;
  // edit BRD_OSC_CLK_MHZ in brdConst_pkg too
  //o_clk   <= i_clk; -- 125MHz, direct
  assign o_clk = s_clk;
    //  50MHz, divided
endmodule

