module wrapper(
input wire clk,
input wire top_sensor,
input wire bottom_sensor,
input wire fpga_clk,
input wire fpga_sleep,
input wire fpga_direction,
output wire top_sensor_out,
output reg motor_clk,
output reg motor_sleep,
output wire reset_to_controller,
output reg motor_direction
);
reg rst;
reg [19:0] counter;
reg db1; reg db2; reg prev_counter; wire deb_bottom_sensor;
  assign top_sensor_out = top_sensor;
  assign top_sensor_out = top_sensor;
  always @(top_sensor, fpga_clk, fpga_sleep, fpga_direction, rst, counter, deb_bottom_sensor) begin
    if(rst == 1'b0) begin
      motor_clk <= fpga_clk;
      motor_sleep <= fpga_sleep;
      motor_direction <= fpga_direction & ( ~deb_bottom_sensor);
    end
    else begin
      motor_clk <= counter[10];
      motor_sleep <= 1'b1;
      motor_direction <= 1'b1;
    end
  end
  always @(posedge clk) begin
    counter <= counter + 1;
    if(top_sensor == 1'b1) begin
      rst <= 1'b1;
    end
    else if(deb_bottom_sensor == 1'b1) begin
      rst <= 1'b0;
    end
    prev_counter <= counter[19];
    if(prev_counter == 1'b0 && counter[19] == 1'b1) begin
      db1 <= bottom_sensor;
      db2 <= db1;
    end
  end
  assign deb_bottom_sensor = db1 & db2 & bottom_sensor;
  assign reset_to_controller = rst;
endmodule

