    input s1,
    output reg [15:0] D,
    output Z,
    output N
);

    always @(*) begin
        case ({s1, s0})
            2'b00: D = A;
            2'b01: D = A + B;
            2'b10: D = A - B;
            2'b11: D = B;
            default: D = 16'b0;
        endcase
    end

    assign Z = (A == 16'b0);
    assign N = A[15];

endmodule

