module wb_timer (
    input wire wb_clk_i,
    input wire sys_clk_i,
    input wire rst_i,
    input wire cyc_i,
    input wire stb_i,
    input wire [2:0] adr_i,
    input wire we_i,
    input wire [31:0] dat_i,
    output reg [31:0] dat_o,
    output wire ack_o,
    input wire [31:0] master_time_i,
    output reg int_o
);

reg [31:0] time_wb;
reg [31:0] int_time;
reg int_reg;

// Wishbone interface
always @(posedge wb_clk_i or posedge rst_i) begin
    if (rst_i) begin
        time_wb <= 32'b0;
        int_time <= 32'b0;
        int_reg <= 1'b0;
    end else begin
        time_wb <= master_time_i;
        if (stb_i && we_i) begin
            int_time <= dat_i;
            int_reg <= 1'b0;
        end
    end
end

assign ack_o = stb_i;
always @(*) begin
    dat_o = time_wb;
end

// Interrupt generation
always @(posedge sys_clk_i or posedge rst_i) begin
    if (rst_i) begin
        int_o <= 1'b0;
    end else begin
        if (master_time_i == int_time && int_time != 32'b0) begin
            int_reg <= 1'b1;
            int_time <= 32'b0;
        end
        int_o <= int_reg;
    end
end

endmodule

