module CNT (
    input wire FCLK,
    input wire CACT,
    input wire RefAck,
    output reg RefReq,
    output reg RefUrgent,
    output reg TimeoutA,
    output reg TimeoutB
);

    reg [7:0] RefCnt;
    reg RefDone;

    always @(posedge FCLK) begin
        // Refresh Counter Logic
        RefCnt <= RefCnt + 1'b1;

        // Refresh Done Logic
        if (RefCnt == 8'b0) begin
            RefDone <= 1'b0;
        end else if (RefAck) begin
            RefDone <= 1'b1;
        end

        // Refresh Request Logic
        RefReq <= ~RefDone;

        // Urgent Refresh Logic
        RefUrgent <= (RefCnt == 8'b11100000) & ~RefDone;

        // Timeout Logic
        if (~CACT) begin
            TimeoutA <= 1'b0;
            TimeoutB <= 1'b0;
        end else if (RefCnt == 8'b0) begin
            if (TimeoutA) begin
                TimeoutB <= 1'b1;
            end else begin
                TimeoutA <= 1'b1;
            end
        end
    end

endmodule

module UartLogic(
input wire reset,
input wire txclk,
input wire ld_tx_data,
input wire [7:0] tx_data,
input wire tx_enable,
output reg tx_out,
output wire tx_empty,
input wire rxclk,
input wire uld_rx_data,
output reg [7:0] rx_data,
input wire rx_enable,
input wire rx_in,
output wire rx_empty
);
//--------------------------------------------------
reg [7:0] tx_reg;
reg tx_is_empty;
reg tx_over_run;
reg [3:0] tx_cnt;
reg [7:0] rx_reg;
reg [3:0] rx_sample_cnt;
reg [3:0] rx_cnt;
reg rx_frame_err;
reg rx_over_run;
reg rx_d1;
reg rx_d2;
reg rx_busy;
reg rx_is_empty;
  assign rx_empty = rx_is_empty;
  assign tx_empty = tx_is_empty;
  // UART RX Logic --------------------------------------------------------------
  always @(posedge rxclk, posedge reset) begin
    if((reset == 1'b1)) begin
      rx_reg <= {8{1'b0}};
      rx_data <= {8{1'b0}};
      rx_sample_cnt <= {4{1'b0}};
      rx_cnt <= {4{1'b0}};
      rx_frame_err <= 1'b0;
      rx_over_run <= 1'b0;
      rx_is_empty <= 1'b1;
      rx_d1 <= 1'b1;
      rx_d2 <= 1'b1;
      rx_busy <= 1'b0;
    end else begin
      // Synchronize the asynch signal
      rx_d1 <= rx_in;
      rx_d2 <= rx_d1;
      // Uload the rx data
      if((uld_rx_data == 1'b1)) begin
        rx_data <= rx_reg;
        rx_is_empty <= 1'b1;
      end
      // Receive data only when rx is enabled
      if((rx_enable == 1'b1)) begin
        // Check if just received start of frame
        if((rx_busy == 1'b0 && rx_d2 == 1'b0)) begin
          rx_busy <= 1'b1;
          rx_sample_cnt <= 4'h1;
          rx_cnt <= 4'h0;
        end
        // Start of frame detected, Proceed with rest of data
        if((rx_busy == 1'b1)) begin
          rx_sample_cnt <= rx_sample_cnt + 1;
          // Logic to sample at middle of data
          if((rx_sample_cnt == 7)) begin
            if(((rx_d2 == 1'b1) && (rx_cnt == 0))) begin
              rx_busy <= 1'b0;
            end
            else begin
              rx_cnt <= rx_cnt + 1;
              // Start storing the rx data
              if((rx_cnt > 0 && rx_cnt < 9)) begin
                rx_reg[(rx_cnt) - 1] <= rx_d2;
              end
              if((rx_cnt == 9)) begin
                rx_busy <= 1'b0;
                // Check if End of frame received correctly
                if((rx_d2 == 1'b0)) begin
                  rx_frame_err <= 1'b1;
                end
                else begin
                  rx_is_empty <= 1'b0;
                  rx_frame_err <= 1'b0;
                  // Check if last rx data was not unloaded,
                  if((rx_is_empty == 1'b1)) begin
                    rx_over_run <= 1'b0;
                  end
                  else begin
                    rx_over_run <= 1'b1;
                  end
                end
              end
            end
          end
        end
      end
      if((rx_enable == 1'b0)) begin
        rx_busy <= 1'b0;
      end
    end
  end
  // UART TX Logic -----------------------------------------------------------------------
  always @(posedge txclk, posedge reset) begin
    if((reset == 1'b1)) begin
      tx_reg <= {8{1'b0}};
      tx_is_empty <= 1'b1;
      tx_over_run <= 1'b0;
      tx_out <= 1'b1;
      tx_cnt <= {4{1'b0}};
    end else begin
      if((ld_tx_data == 1'b1)) begin
        if((tx_is_empty == 1'b0)) begin
          tx_over_run <= 1'b0;
        end
        else begin
          tx_reg <= tx_data;
          tx_is_empty <= 1'b0;
        end
      end
      if((tx_enable == 1'b1 && tx_is_empty == 1'b0)) begin
        tx_cnt <= tx_cnt + 1;
        if((tx_cnt == 0)) begin
          tx_out <= 1'b0;
        end
        if((tx_cnt > 0 && tx_cnt < 9)) begin
          tx_out <= tx_reg[(tx_cnt) - 1];
        end
        if((tx_cnt == 9)) begin
          tx_out <= 1'b1;
          tx_cnt <= 4'h0;
          tx_is_empty <= 1'b1;
        end
      end
      if((tx_enable == 1'b0)) begin
        tx_cnt <= 4'h0;
      end
    end
  end
endmodule

