module angle_decoder(
    input [3:0] x_angle,
    input [3:0] a_xangle,
    input [3:0] y_angle,
    input [3:0] a_yangle,
    input [3:0] fire_angle,
    output reg [19:0] x_value,
    output reg [19:0] y_value,
    output reg [19:0] fire_value
);

    // X-angle decoding
    always @(*) begin
        case (1'b1)
            (x_angle == 4'd1) || (a_xangle == 4'd1): x_value = 20'd62500;
            (x_angle == 4'd2) || (a_xangle == 4'd2): x_value = 20'd10000;
            (x_angle == 4'd5) || (a_xangle == 4'd5): x_value = 20'd75000;
            default: x_value = 20'd70000;
        endcase
    end

    // Y-angle decoding
    always @(*) begin
        case (1'b1)
            (y_angle == 4'd1) || (a_yangle == 4'd1): y_value = 20'd62500;
            (y_angle == 4'd2) || (a_yangle == 4'd2): y_value = 20'd10000;
            (y_angle == 4'd5) || (a_yangle == 4'd5): y_value = 20'd75000;
            default: y_value = 20'd70000;
        endcase
    end

    // Fire angle decoding
    always @(*) begin
        case (fire_angle)
            4'd1: fire_value = 20'd15000;
            4'd2: fire_value = 20'd60000;
            default: fire_value = 20'd70000;
        endcase
    end

endmodule

