module priority_encoder_4to2 (
    input [3:0] W,
    output [1:0] Y,
    output zero
);

    // Priority encoding logic
    assign Y[1] = W[3] | W[2];
    assign Y[0] = W[3] | W[1];

    // Zero detection logic (odd number of high bits)
    assign zero = W[3] ^ W[2] ^ W[1] ^ W[0];

endmodule

