module vga_controller(
    input CLK_50M,
    output reg VGA_HS,
    output reg VGA_VS,
    output reg [2:0] VGA_R,
    output reg [2:0] VGA_G,
    output reg [1:0] VGA_B,
    output reg ledout
);

    // Clock division
    reg clk;
    always @(posedge CLK_50M) clk <= ~clk;

    // VGA timing parameters
    parameter H_ACTIVE_PIXEL_LIMIT = 640;
    parameter H_FRONT_PORCH = 16;
    parameter H_SYNC_PULSE = 96;
    parameter H_BACK_PORCH = 48;
    parameter H_TOTAL_PIXEL_LIMIT = H_ACTIVE_PIXEL_LIMIT + H_FRONT_PORCH + H_SYNC_PULSE + H_BACK_PORCH;

    parameter V_ACTIVE_LINE_LIMIT = 480;
    parameter V_FRONT_PORCH = 10;
    parameter V_SYNC_PULSE = 2;
    parameter V_BACK_PORCH = 29;
    parameter V_TOTAL_LINE_LIMIT = V_ACTIVE_LINE_LIMIT + V_FRONT_PORCH + V_SYNC_PULSE + V_BACK_PORCH;

    // Counters
    reg [9:0] hcount = 0;
    reg [9:0] vcount = 0;
    reg [2:0] out_count = 0;
    reg [2:0] out_color = 0;
    reg [24:0] c = 0;

    always @(posedge clk) begin
        // Horizontal counter
        if (hcount == H_TOTAL_PIXEL_LIMIT - 1) begin
            hcount <= 0;
            if (vcount == V_TOTAL_LINE_LIMIT - 1)
                vcount <= 0;
            else
                vcount <= vcount + 1;
        end else
            hcount <= hcount + 1;

        // Horizontal sync
        if (hcount >= H_ACTIVE_PIXEL_LIMIT + H_FRONT_PORCH && hcount < H_ACTIVE_PIXEL_LIMIT + H_FRONT_PORCH + H_SYNC_PULSE)
            VGA_HS <= 1'b0;
        else
            VGA_HS <= 1'b1;

        // Vertical sync
        if (vcount >= V_ACTIVE_LINE_LIMIT + V_FRONT_PORCH && vcount < V_ACTIVE_LINE_LIMIT + V_FRONT_PORCH + V_SYNC_PULSE)
            VGA_VS <= 1'b0;
        else
            VGA_VS <= 1'b1;

        // Color output
        if (hcount < H_ACTIVE_PIXEL_LIMIT && vcount < V_ACTIVE_LINE_LIMIT) begin
            if (out_count == 4) begin
                out_count <= 0;
                out_color <= out_color + 1;
            end else
                out_count <= out_count + 1;

            VGA_R <= {3{out_color[0]}};
            VGA_G <= {3{out_color[1]}};
            VGA_B <= {2{out_color[2]}};
        end else begin
            VGA_R <= 3'b000;
            VGA_G <= 3'b000;
            VGA_B <= 2'b00;
        end

        // LED blinking
        c <= c + 1;
        if (c == 25_000_000) begin
            c <= 0;
            ledout <= ~ledout;
        end
    end

endmodule

