module video_controller (
    input wire clk,
    input wire clk7p16,
    input wire white,
    input wire [7:0] data,
    input wire [7:0] lcd_xsize,
    input wire [7:0] lcd_ysize,
    input wire [7:0] lcd_xscroll,
    input wire [7:0] lcd_yscroll,
    output reg hsync,
    output reg vsync,
    output reg hblank,
    output reg vblank,
    output reg [7:0] red,
    output reg [7:0] green,
    output reg [7:0] blue,
    output reg [15:0] addr,
    output reg ce_pxl
);

    // Parameters for VGA timing
    localparam H_DISPLAY = 640;
    localparam H_FRONT_PORCH = 16;
    localparam H_SYNC_PULSE = 96;
    localparam H_BACK_PORCH = 48;
    localparam H_TOTAL = 800;

    localparam V_DISPLAY = 480;
    localparam V_FRONT_PORCH = 10;
    localparam V_SYNC_PULSE = 2;
    localparam V_BACK_PORCH = 18;
    localparam V_TOTAL = 510;

    // LCD overlay parameters
    localparam LCD_X_START = 80;
    localparam LCD_Y_START = 40;

    // Counters and registers
    reg [9:0] hcount;
    reg [9:0] vcount;
    reg [7:0] pixel_data;
    reg in_lcd_area;

    // Color palette
    wire [7:0] palette [0:7];
    assign palette[0] = white ? 8'h00 : 8'h00;
    assign palette[1] = white ? 8'h24 : 8'h24;
    assign palette[2] = white ? 8'h49 : 8'h49;
    assign palette[3] = white ? 8'h6D : 8'h6D;
    assign palette[4] = white ? 8'h92 : 8'h92;
    assign palette[5] = white ? 8'hB6 : 8'hB6;
    assign palette[6] = white ? 8'hDB : 8'hDB;
    assign palette[7] = white ? 8'hFF : 8'hFF;

    // Pixel clock enable
    always @(posedge clk) begin
        ce_pxl <= (clk7p16 == 1'b1);
    end

    // Horizontal and vertical counters
    always @(posedge clk) begin
        if (ce_pxl) begin
            if (hcount == H_TOTAL - 1) begin
                hcount <= 0;
                if (vcount == V_TOTAL - 1)
                    vcount <= 0;
                else
                    vcount <= vcount + 1;
            end else begin
                hcount <= hcount + 1;
            end
        end
    end

    // VGA sync signals
    always @(posedge clk) begin
        hsync <= (hcount >= (H_DISPLAY + H_FRONT_PORCH) &&
                  hcount < (H_DISPLAY + H_FRONT_PORCH + H_SYNC_PULSE));
        vsync <= (vcount >= (V_DISPLAY + V_FRONT_PORCH) &&
                  vcount < (V_DISPLAY + V_FRONT_PORCH + V_SYNC_PULSE));
        hblank <= (hcount >= H_DISPLAY);
        vblank <= (vcount >= V_DISPLAY);
    end

    // LCD area detection
    always @(posedge clk) begin
        if (ce_pxl) begin
            in_lcd_area <= (hcount >= LCD_X_START) && (hcount < LCD_X_START + lcd_xsize) &&
                           (vcount >= LCD_Y_START) && (vcount < LCD_Y_START + lcd_ysize);
        end
    end

    // Memory address generation
    always @(posedge clk) begin
        if (ce_pxl && in_lcd_area) begin
            addr <= ((vcount - LCD_Y_START + lcd_yscroll) & 8'hFF) * lcd_xsize +
                    ((hcount - LCD_X_START + lcd_xscroll) & 8'hFF);
        end
    end

    // Pixel data and color generation
    always @(posedge clk) begin
        if (ce_pxl) begin
            if (in_lcd_area) begin
                pixel_data <= data;
                {red, green, blue} <= {3{palette[pixel_data[7:6]]}};
            end else begin
                {red, green, blue} <= 24'h000000;
            end
        end
    end

endmodule

module VGA_top(
input wire [15:0] KEY16_INPUT,
input wire CLK_0,
output wire clk_out,
input wire reset,
output wire [2:0] R,
output wire [2:0] G,
output wire [2:0] B,
output wire Hs,
output wire Vs
);
// must 50M
// used to sync
// vga port
// display memory control
reg [0:0] dwctrl;
reg [10:0] dwaddr;
reg [7:0] dwdata;
wire dclk;
parameter [1:0]
  d1 = 0,
  d2 = 1,
  d3 = 2,
  d4 = 3;
parameter [1:0]
  s1 = 0,
  s2 = 1,
  s3 = 2,
  s4 = 3;
reg [1:0] datain = d1;
reg [1:0] datast = s1;
  assign clk_out = dclk;
  VGA_play vga(
      .CLK_0(CLK_0),
    .clkout(dclk),
    .reset(reset),
    // vga port
    .R(R),
    .G(G),
    .B(B),
    .Hs(Hs),
    .Vs(Vs),
    // fifo memory
    .wctrl(dwctrl),
    .waddr(dwaddr),
    .wdata(dwdata));
  always @(posedge dclk) begin
    dwctrl[0] <= 1'b1;
    case(datain)
    d1 : begin
      case(datast)
      s1 : begin
        dwaddr <= {7'b0000000,4'b0000};
        dwdata <= {4'b0001,input[15:12]};
        datast <= s2;
      end
      s2 : begin
        dwaddr <= {7'b0000000,4'b0001};
        dwdata <= {4'b0001,input[11:8]};
        datast <= s3;
      end
      s3 : begin
        dwaddr <= {7'b0000000,4'b0010};
        dwdata <= {7'b0000000,KEY16_INPUT[2]};
        datast <= s4;
      end
      s4 : begin
        dwaddr <= {7'b0000000,4'b0011};
        dwdata <= {7'b0000000,KEY16_INPUT[3]};
        datast <= s1;
        datain <= d2;
      end
      endcase
    end
    d2 : begin
      case(datast)
      s1 : begin
        dwaddr <= {7'b0000000,4'b0100};
        dwdata <= {7'b0000000,KEY16_INPUT[4]};
        datast <= s2;
      end
      s2 : begin
        dwaddr <= {7'b0000000,4'b0101};
        dwdata <= {7'b0000000,KEY16_INPUT[5]};
        datast <= s3;
      end
      s3 : begin
        dwaddr <= {7'b0000000,4'b0110};
        dwdata <= {7'b0000000,KEY16_INPUT[6]};
        datast <= s4;
      end
      s4 : begin
        dwaddr <= {7'b0000000,4'b0111};
        dwdata <= {7'b0000000,KEY16_INPUT[7]};
        datast <= s1;
        datain <= d3;
      end
      endcase
    end
    d3 : begin
      case(datast)
      s1 : begin
        dwaddr <= {7'b0000000,4'b1000};
        dwdata <= {7'b0000000,KEY16_INPUT[8]};
        datast <= s2;
      end
      s2 : begin
        dwaddr <= {7'b0000000,4'b1001};
        dwdata <= {7'b0000000,KEY16_INPUT[9]};
        datast <= s3;
      end
      s3 : begin
        dwaddr <= {7'b0000000,4'b1010};
        dwdata <= {7'b0000000,KEY16_INPUT[10]};
        datast <= s4;
      end
      s4 : begin
        dwaddr <= {7'b0000000,4'b1011};
        dwdata <= {7'b0000000,KEY16_INPUT[11]};
        datast <= s1;
        datain <= d4;
      end
      endcase
    end
    d4 : begin
      case(datast)
      s1 : begin
        dwaddr <= {7'b0000000,4'b1100};
        dwdata <= {7'b0000000,KEY16_INPUT[12]};
        datast <= s2;
      end
      s2 : begin
        dwaddr <= {7'b0000000,4'b1101};
        dwdata <= {7'b0000000,KEY16_INPUT[13]};
        datast <= s3;
      end
      s3 : begin
        dwaddr <= {7'b0000000,4'b1110};
        dwdata <= {7'b0000000,KEY16_INPUT[14]};
        datast <= s4;
      end
      s4 : begin
        dwaddr <= {7'b0000000,4'b1111};
        dwdata <= {7'b0000000,KEY16_INPUT[15]};
        datast <= s1;
        datain <= d1;
      end
      endcase
