module bitcreator(
    input wire clk,
    input wire [71:0] colordata,
    output reg cled
);

reg [5:0] cyc;
reg [4:0] cnt;
reg [5:0] coloraddr;
wire zerobit, onebit;

assign zerobit = (cyc >= 2) && (cyc < 16);
assign onebit = (cyc >= 2) && (cyc < 22);

always @(posedge clk) begin
    if (cyc == 31) begin
        cyc <= 0;
        if (cnt == 23) begin
            cnt <= 0;
            if (coloraddr == 19)
                coloraddr <= 0;
            else
                coloraddr <= coloraddr + 1;
        end else begin
            cnt <= cnt + 1;
        end
    end else begin
        cyc <= cyc + 1;
    end
end

always @(*) begin
    if (coloraddr < 16) begin
        cled = 0;
    end else begin
        if (colordata[cnt + 24*(coloraddr-16)])
            cled = onebit;
        else
            cled = zerobit;
    end
end

endmodule

