module sorter(
input wire Clk,
input wire [3:0] A,
input wire [3:0] B,
input wire [3:0] C,
input wire [3:0] D,
output reg [3:0] S1reg,
output reg [3:0] S2reg,
output reg [3:0] S3reg,
output reg [3:0] S4reg
);
// Internal Signal Declaration
reg [3:0] Areg;
reg [3:0] Breg;
reg [3:0] Creg;
reg [3:0] Dreg;
wire [3:0] S1;
wire [3:0] S2;
wire [3:0] S3;
wire [3:0] S4;  // Temporary signals within stages
wire [3:0] T1_1; wire [3:0] T1_2; wire [3:0] T2_1; wire [3:0] T2_2; wire [3:0] T3_1; wire [3:0] T3_2;  // Signals between stages 1 and 2
wire [3:0] O1_A; wire [3:0] O1_B; wire [3:0] O1_C; wire [3:0] O1_D;  // Signals between stages 3 and 4
wire [3:0] O2_A; wire [3:0] O2_B; wire [3:0] O2_C; wire [3:0] O2_D;
reg [3:0] R1_A; reg [3:0] R1_B; reg [3:0] R1_C; reg [3:0] R1_D;
reg [3:0] R2_A; reg [3:0] R2_B; reg [3:0] R2_C; reg [3:0] R2_D;
  // RTL
  always @(posedge Clk) begin
      // process
    Areg <= A;
    Breg <= B;
    Creg <= C;
    Dreg <= D;
    R1_A <= O1_A;
    R1_B <= O1_B;
    R1_C <= O1_C;
    R1_D <= O1_D;
    R2_A <= O2_A;
    R2_B <= O2_B;
    R2_C <= O2_C;
    R2_D <= O2_D;
    S1reg <= S1;
    S2reg <= S2;
    S3reg <= S3;
    S4reg <= S4;
  end
  // Stage 1
  assign O1_A = (Areg < Breg) ? Breg : Areg;
  assign T1_1 = (Areg < Breg) ? Areg : Breg;
  assign O1_B = (T1_1 < Creg) ? Creg : T1_1;
  assign T1_2 = (T1_1 < Creg) ? T1_1 : Creg;
  assign O1_C = (T1_2 < Dreg) ? Dreg : T1_2;
  assign O1_D = (T1_2 < Dreg) ? T1_2 : Dreg;
  // Stage 2
  assign O2_A = (R1_A < R1_B) ? R1_B : R1_A;
  assign T2_1 = (R1_A < R1_B) ? R1_A : R1_B;
  assign O2_B = (T2_1 < R1_C) ? R1_C : T2_1;
  assign T2_2 = (T2_1 < R1_C) ? T2_1 : R1_C;
  assign O2_C = (T2_2 < R1_D) ? R1_D : T2_2;
  assign O2_D = (T2_2 < R1_D) ? T2_2 : R1_D;
  // Stage 3
  assign S1 = (R2_A < R2_B) ? R2_B : R2_A;
  assign T3_1 = (R2_A < R2_B) ? R2_A : R2_B;
  assign S2 = (T3_1 < R2_C) ? R2_C : T3_1;
  assign T3_2 = (T3_1 < R2_C) ? T3_1 : R2_C;
  assign S3 = (T3_2 < R2_D) ? R2_D : T3_2;
  assign S4 = (T3_2 < R2_D) ? T3_2 : R2_D;
endmodule

