module binary2BCD(
    input [13:0] binary,
    output reg [3:0] thousands,
    output reg [3:0] hundreds,
    output reg [3:0] tens,
    output reg [3:0] ones
);

    integer i;

    always @(binary) begin
        // Clear BCD registers
        thousands = 4'd0;
        hundreds = 4'd0;
        tens = 4'd0;
        ones = 4'd0;

        // Iterate for each bit (14 times)
        for (i = 13; i >= 0; i = i - 1) begin
            // Check if any BCD digit is >= 5 and add 3 if so
            if (thousands >= 5)
                thousands = thousands + 3;
            if (hundreds >= 5)
                hundreds = hundreds + 3;
            if (tens >= 5)
                tens = tens + 3;
            if (ones >= 5)
                ones = ones + 3;

            // Shift left all BCD digits
            thousands = thousands << 1;
            thousands[0] = hundreds[3];
            hundreds = hundreds << 1;
            hundreds[0] = tens[3];
            tens = tens << 1;
            tens[0] = ones[3];
            ones = ones << 1;
            ones[0] = binary[i];
        end
    end

endmodule

module ALU (
    input [31:0] a,
    input [31:0] b,
    input [2:0] aluop,
    output reg [31:0] result,
    output reg zero
);

    always @(*) begin
        case (aluop)
            3'b010: begin // Addition
                result = a + b;
                zero = 1'b0;
            end
            3'b110: begin // Subtraction
                result = a - b;
                zero = 1'b0;
            end
            3'b000: begin // Bitwise AND
                result = a & b;
                zero = 1'b0;
            end
            3'b001: begin // Bitwise OR
                result = a | b;
                zero = 1'b0;
            end
            3'b111: begin // Set Less Than
                result = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                zero = 1'b0;
            end
            3'b100: begin // Equal Comparison
                result = 32'dx;
                zero = (a == b) ? 1'b1 : 1'b0;
            end
            3'b011: begin // Not Equal Comparison
                result = 32'dx;
                zero = (a != b) ? 1'b1 : 1'b0;
            end
            default: begin
                result = 32'dx;
                zero = 1'bx;
            end
        endcase
    end

endmodule

