module functional_unit (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [3:0] op,
    input wire branch_in,
    input wire [15:0] in_a,
    input wire [15:0] in_b,
    output reg branch_out,
    output reg [15:0] out
);

    // Operation codes
    localparam PASS_A = 4'd0, PASS_B = 4'd1, ADD = 4'd2, SUB = 4'd3,
               MULT = 4'd4, DIV = 4'd5, AND = 4'd6, OR = 4'd7,
               MOD = 4'd8, SHL = 4'd9, SHR = 4'd10, BEQ = 4'd11,
               BNE = 4'd12, SLT = 4'd13, NOT = 4'd14, MERGE = 4'd15;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            branch_out <= 1'b0;
            out <= 16'd0;
        end else if (en) begin
            case (op)
                PASS_A: begin
                    out <= in_a;
                    branch_out <= 1'b0;
                end
                PASS_B: begin
                    out <= in_b;
                    branch_out <= 1'b0;
                end
                ADD: begin
                    out <= in_a + in_b;
                    branch_out <= 1'b0;
                end
                SUB: begin
                    out <= in_a - in_b;
                    branch_out <= 1'b0;
                end
                MULT: begin
                    out <= in_a * in_b;
                    branch_out <= 1'b0;
                end
                DIV: begin
                    out <= in_a / in_b;
                    branch_out <= 1'b0;
                end
                AND: begin
                    out <= in_a & in_b;
                    branch_out <= 1'b0;
                end
                OR: begin
                    out <= in_a | in_b;
                    branch_out <= 1'b0;
                end
                MOD: begin
                    out <= in_a % in_b;
                    branch_out <= 1'b0;
                end
                SHL: begin
                    out <= in_a << 1;
                    branch_out <= 1'b0;
                end
                SHR: begin
                    out <= in_a >> 1;
                    branch_out <= 1'b0;
                end
                BEQ: begin
                    out <= 16'd0;
                    branch_out <= (in_a == in_b);
                end
                BNE: begin
                    out <= 16'd0;
                    branch_out <= (in_a != in_b);
                end
                SLT: begin
                    out <= (in_a < in_b) ? 16'd1 : 16'd0;
                    branch_out <= 1'b0;
                end
                NOT: begin
                    out <= ~in_a;
                    branch_out <= 1'b0;
                end
                MERGE: begin
                    out <= branch_in ? in_b : in_a;
                    branch_out <= 1'b0;
                end
                default: begin
                    out <= 16'd0;
                    branch_out <= 1'b0;
                end
            endcase
        end else begin
            out <= 16'd0;
            branch_out <= 1'b0;
        end
    end

endmodule

