);
//-----------------------------------------------------------------------------
parameter [0:0]
  LSB = 0,
  MSB = 1;
reg state = LSB;
  always @(posedge clk, posedge reset) begin
      // RESET
    if(reset == 1'b1) begin
      data_out <= {16{1'b0}};
      state <= LSB;
      RxRdy_out <= 1'b0;
    end else begin
      //-elsif (clk'event and clk = 'l') then
      RxRdy_out <= 1'b0;
      case(state)
            // LSByte
      LSB : begin
        if(RxRdy_in == 1'b1) begin
          data_out[7:0] <= data_in;
          RxRdy_out <= 1'b0;
          state <= MSB;
        end
        // MSByte
      end
      MSB : begin
        if(RxRdy_in == 1'b1) begin
          data_out[15:8] <= data_in;
          RxRdy_out <= 1'b1;
          state <= LSB;
        end
      end
      endcase
    end
  end
