reg [7:0] channel1_next;
reg [7:0] channel2_next;
reg [7:0] channel3_next;
reg [7:0] channel0_reg;
reg [7:0] channel1_reg;
reg [7:0] channel2_reg;
reg [7:0] channel3_reg;
wire [3:0] addr_decoded;
  complete_address_decoder #(
      .width(2))
  complete_address_decoder1(
      .addr_in(addr),
    .addr_decoded(addr_decoded));
