module flex_counter #(
    parameter NUM_CNT_BITS = 4
)(
    input wire clk,
    input wire n_rst,
    input wire s_rst,
    input wire count_enable,
    input wire [NUM_CNT_BITS-1:0] rollover_val,
    output wire rollover_flag
);

    reg [NUM_CNT_BITS-1:0] counter;
    reg [NUM_CNT_BITS-1:0] rollval;

    always @(posedge clk or negedge n_rst) begin
        if (~n_rst) begin
            counter <= {NUM_CNT_BITS{1'b0}};
            rollval <= rollover_val;
        end else if (~s_rst) begin
            counter <= {NUM_CNT_BITS{1'b0}};
            rollval <= rollover_val;
        end else if (count_enable) begin
            if (counter >= rollval) begin
                counter <= {{NUM_CNT_BITS-1{1'b0}}, 1'b1};
            end else begin
                counter <= counter + 1'b1;
            end
        end
    end

    always @(rollover_val) begin
        rollval <= rollover_val;
    end

    assign rollover_flag = (counter >= rollval);

endmodule

