module led7 #(
    parameter COUNT = 1
)(
    input [4*COUNT-1:0] data,
    output [8*COUNT-1:0] leds
);

    wire [3:0] in [COUNT-1:0];
    reg [7:0] out [COUNT-1:0];

    genvar i;
    generate
        for (i = 0; i < COUNT; i = i + 1) begin : gen_loop
            assign in[i] = data[4*i+3:4*i];
            assign leds[8*i+7:8*i] = out[i];

            always @(*) begin
                case (in[i])
                    4'h0: out[i] = 8'h03;
                    4'h1: out[i] = 8'h9f;
                    4'h2: out[i] = 8'h25;
                    4'h3: out[i] = 8'h0d;
