module seven_segment_controller(
    input clk,
    input [3:0] in0, in1, in2, in3,
    output reg [6:0] sseg,
    output dp,
    output reg [3:0] an
);

    reg [17:0] count;
    wire [1:0] digit_select;
    reg [3:0] digit_val;
    reg [3:0] digit_en;

    // Counter for digit cycling
    always @(posedge clk)
        count <= count + 1;

    assign digit_select = count[17:16];

    // Digit selection logic
    always @(*) begin
        case(digit_select)
            2'b00: begin digit_val = in0; digit_en = 4'b1110; end
            2'b01: begin digit_val = in1; digit_en = 4'b1101; end
            2'b10: begin digit_val = in2; digit_en = 4'b1011; end
            2'b11: begin digit_val = in3; digit_en = 4'b0111; end
        endcase
    end

    // Seven-segment decoder
    always @(*) begin
        case(digit_val)
            4'h0: sseg = 7'b1000000;
            4'h1: sseg = 7'b1111001;
            4'h2: sseg = 7'b0100100;
            4'h3: sseg = 7'b0110000;
            4'h4: sseg = 7'b0011001;
            4'h5: sseg = 7'b0010010;
            4'h6: sseg = 7'b0000010;
            4'h7: sseg = 7'b1111000;
            4'h8: sseg = 7'b0000000;
            4'h9: sseg = 7'b0010000;
            default: sseg = 7'b0111111; // Dash for invalid input
        endcase
    end

    // Output assignments
    assign dp = 1'b1; // Decimal point off
    always @(posedge clk)
        an <= digit_en;

endmodule

