module key_debounce (
    input wire clk,
    input wire rst_n,
    input wire key_in,
    output reg key_out
);

    // Parameters
    parameter TIME_20MS = 1_000_000;
    parameter TIME_0_5S = 25_000_000;

    // Registers
    reg [1:0] key_r;
    reg [24:0] cnt;
    reg counting;

    // Wires
    wire add_cnt;
    wire end_cnt;

    // Input synchronization
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            key_r <= 2'b11;
        else
            key_r <= {key_r[0], key_in};
    end

    // Counter control
    assign add_cnt = (key_r == 2'b00);
    assign end_cnt = (cnt == TIME_0_5S - 1);

    // Counter
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            cnt <= 25'd0;
        else if (add_cnt && !end_cnt)
            cnt <= cnt + 1'b1;
        else if (!add_cnt || end_cnt)
            cnt <= 25'd0;
    end

    // Counting flag
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            counting <= 1'b0;
        else if (add_cnt)
            counting <= 1'b1;
        else if (!add_cnt)
            counting <= 1'b0;
    end

    // Output generation
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            key_out <= 1'b0;
        else if (counting && cnt == TIME_20MS - 1)
            key_out <= 1'b1;
        else
            key_out <= 1'b0;
    end

endmodule

module arith_unit(
input wire [15:0] RA,
input wire [15:0] RB,
input wire [2:0] OP,
output wire [15:0] AR_OUT,
output wire [3:0] SREG_OUT
);
wire [16:0] a = 1'b0; wire [16:0] b = 1'b0;
reg [16:0] RESULT = 1'b0;
reg [3:0] SREG = 1'b0;
  assign a = {1'b0,RA};
  assign b = {1'b0,RB};
  always @(*) begin
    case(OP)
      3'b000,3'b101 : RESULT <= (a) + (b);
  // ADD
      3'b001 : RESULT <= (a) - (b);
  // SUB
  //a + b when "101",	-- ADDI
      default : RESULT <= {1'b0,16'h0000};
    endcase
  end
  assign SREG[3] = RESULT[16];
  // Negative with signed logic
  assign SREG[2] = RESULT[15:0] == 32'h00000000 ? 1'b1 : 1'b0;
  // Zero
  assign SREG[1] = RESULT[16] ^ RESULT[15];
  // Overflow with signed logic
  always @(*) begin
    case(OP)
      3'b000,3'b101 : SREG[0] <= RESULT[16];
  // Carry
      default : SREG[0] <= 1'b0;
    endcase
  end
  assign SREG_OUT = SREG;
  assign AR_OUT = RESULT[15:0];
endmodule

