module rxtx_to_buf(
input wire clock,
input wire reset,
output wire [10:0] ram_addr,
output wire [7:0] ram_wdata,
input wire [7:0] ram_rdata,
output wire ram_we,
output wire ram_en,
output reg [10:0] transferred,
input wire user_rx_valid,
input wire user_rx_start,
input wire [7:0] user_rx_data,
input wire user_rx_last,
input wire send_data,
input wire [10:0] last_addr,
input wire no_data,
output wire [7:0] user_tx_data,
output reg user_tx_last,
input wire user_tx_next
);
// bram interface
// Interface from RX
// Interface to TX
reg [10:0] ram_addr_i;
reg ram_en_r;
parameter [2:0]
  idle = 0,
  tx_1 = 1,
  tx_2 = 2,
  tx_3 = 3,
  rx = 4;
reg [2:0] state;
reg trx_end;
  assign ram_en = ram_en_r | user_rx_valid | user_tx_next;
  assign ram_we = user_rx_valid;
  assign ram_wdata = user_rx_data;
  assign user_tx_data = ram_rdata;
  assign ram_addr = ram_addr_i;
  always @(posedge clock) begin
    ram_en_r <= 1'b0;
    trx_end <= 1'b0;
    if(trx_end == 1'b1) begin
      transferred <= ram_addr_i;
    end
    case(state)
    idle : begin
      ram_addr_i <= {11{1'b0}};
      if(send_data == 1'b1 && no_data == 1'b0) begin
        ram_en_r <= 1'b1;
        state <= tx_1;
      end
      else if(user_rx_start == 1'b1) begin
        if(user_rx_valid == 1'b1) begin
          ram_addr_i <= ram_addr_i + 1;
        end
        state <= rx;
      end
    end
    tx_1 : begin
      ram_addr_i <= ram_addr_i + 1;
      state <= tx_2;
    end
    tx_2 : begin
      if(user_tx_next == 1'b1) begin
        ram_addr_i <= ram_addr_i + 1;
        if(ram_addr_i == last_addr) begin
          user_tx_last <= 1'b1;
          state <= tx_3;
        end
      end
    end
    tx_3 : begin
      if(user_tx_next == 1'b1) begin
        trx_end <= 1'b1;
        state <= idle;
        user_tx_last <= 1'b0;
      end
    end
    rx : begin
      if(user_rx_valid == 1'b1) begin
        ram_addr_i <= ram_addr_i + 1;
      end
      if(user_rx_last == 1'b1) begin
        trx_end <= 1'b1;
        state <= idle;
      end
    end
    default : begin
    end
    endcase
    if(reset == 1'b1) begin
      state <= idle;
      user_tx_last <= 1'b0;
    end
  end
endmodule

module hsyncx_control(
input wire RSTx,
input wire CLK_LCD,
output reg HSYNCx
);
parameter [31:0] C_HSYNC_TH;
C_HSYNC_THP;
C_NUM_CLKS_WIDTH;
//////////////////////////--
// ARCHITECTURE OF ENTITY --
//////////////////////////--
reg [C_NUM_CLKS_WIDTH - 1:0] num_hsyncx_clks_reg = 1'b0;
  //----------------------------------------------------------------
  //  Process Description:
  //    This process enables or disables the HSYNCx port depending
  //    upon the number of clocks that have passed (num_hsyncx_clks_reg)
  //    relative to C_HSYNC_THP.
  //  
  //  Inputs:
  //    RSTx
  //    CLK_LCD
  //  
  //  Outputs:
  //    HSYNCx
  //
  //  Notes:
  //    N/A
  //----------------------------------------------------------------
  always @(posedge RSTx, posedge CLK_LCD) begin
    if((RSTx == 1'b0)) begin
      HSYNCx <= 1'b1;
    end else begin
      if((num_hsyncx_clks_reg < C_HSYNC_THP)) begin
        HSYNCx <= 1'b0;
      end
      else begin
        HSYNCx <= 1'b1;
      end
    end
  end
  //----------------------------------------------------------------
  //  Process Description:
  //    This process controls the num_hsyncx_clks_reg counter
  //    and resets it when it has reached the defined C_HSYNC_TH
  //    parameter.
  //  
  //  Inputs:
  //    RSTx
  //    CLK_LCD
  //  
  //  Outputs:
  //    num_hsyncx_clks_reg
  //
  //  Notes:
  //    N/A
  //----------------------------------------------------------------
  always @(posedge RSTx, posedge CLK_LCD) begin
    if((RSTx == 1'b0)) begin
      num_hsyncx_clks_reg <= {((C_NUM_CLKS_WIDTH - 1)-(0)+1){1'b0}};
    end else begin
      if((num_hsyncx_clks_reg == (C_HSYNC_TH - 1))) begin
        // 0 to (TH - 1) = TH clocks!
        num_hsyncx_clks_reg <= {((C_NUM_CLKS_WIDTH - 1)-(0)+1){1'b0}};
        // a full HSYNC cycle has completed.  START OVER!
      end
      else begin
        num_hsyncx_clks_reg <= num_hsyncx_clks_reg + 1;
        // keep counting until we have reached a full HSYNC cycle
      end
    end
  end
endmodule

module vending_machine(
input wire coin_in,
input wire coin_in_1,
input wire coin_in_10,
input wire coin_in_100,
input wire buy_in,
input wire [7:0] price,
output reg coin_return,
output reg [7:0] coin_return_1,
output reg [7:0] coin_return_10,
output reg [7:0] coin_return_100,
input wire clk
);
parameter [1:0]
  COIN_IN_S = 0,
  COIN_RETURN_100_S = 1,
  COIN_RETURN_10_S = 2,
  COIN_RETURN_1_S = 3;
reg [1:0] current_state; reg [1:0] next_state;
  always @(posedge clk) begin
    current_state <= next_state;
  end
  always @(coin_in, buy_in, current_state) begin : P1
    reg [7:0] coin_return_total;
    reg [7:0] coin_return_100_var;
    reg [7:0] coin_return_10_var;
    reg [7:0] coin_return_1_var;
    reg [7:0] coin_in_total;
    case(current_state)
    COIN_IN_S : begin
      if(coin_in == 1'b1) begin
        coin_return <= 1'b0;
        next_state <= COIN_IN_S;
        if(coin_in_1 == 1'b1 && coin_in_10 == 1'b0 && coin_in_100 == 1'b0) begin
          coin_in_total = coin_in_total + 8'b00000001;
        end
        else if(coin_in_1 == 1'b0 && coin_in_10 == 1'b1 && coin_in_100 == 1'b0) begin
          coin_in_total = coin_in_total + 8'b00001010;
        end
        else if(coin_in_1 == 1'b0 && coin_in_10 == 1'b0 && coin_in_100 == 1'b1) begin
          coin_in_total = coin_in_total + 8'b01100100;
        end
      end
      if(buy_in == 1'b1) begin
        coin_return_total = coin_in_total - price;
        coin_return_100_var = 8'b00000000;
        coin_return_10_var = 8'b00000000;
        coin_return_1_var = 8'b00000000;
        next_state <= COIN_RETURN_100_S;
      end
    end
    COIN_RETURN_100_S : begin
      if(coin_return_total >= 8'b01100100) begin
        coin_return_total = coin_return_total - 8'b01100100;
        coin_return_100_var = coin_return_100_var + 8'b00000001;
        next_state <= COIN_RETURN_100_S;
      end
      else begin
        next_state <= COIN_RETURN_10_S;
      end
    end
    COIN_RETURN_10_S : begin
      if(coin_return_total >= 8'b00001010) begin
        coin_return_total = coin_return_total - 8'b00001010;
        coin_return_10_var = coin_return_10_var + 8'b00000001;
        next_state <= COIN_RETURN_10_S;
      end
      else begin
        next_state <= COIN_RETURN_1_S;
      end
    end
    COIN_RETURN_1_S : begin
      if(coin_return_total >= 8'b00000001) begin
        coin_return_total = coin_return_total - 8'b00000001;
        coin_return_1_var = coin_return_1_var + 8'b00000001;
        next_state <= COIN_RETURN_1_S;
      end
      else begin
        next_state <= COIN_IN_S;
        coin_return <= 1'b1;
        coin_return_1 <= coin_return_1_var;
        coin_return_10 <= coin_return_10_var;
        coin_return_100 <= coin_return_100_var;
      end
    end
    endcase
  end
endmodule

module sub_160(
output wire le,
output wire [31:0] result,
input wire [31:0] in_a,
input wire [31:0] in_b,
input wire sign
);
wire [33:0] carry_inA;
wire [33:0] carry_inB;
wire [33:0] carry_res;  // Signals to generate the comparison outputs
wire [2:0] msb_abr;
wire tmp_sign;
wire tmp_eq;
wire tmp_le;
wire tmp_ge;
  // To handle the CI input, the operation is '0' - CI
  // If CI is not present, the operation is '0' - '0'
  assign carry_inA = {1'b0,in_a,1'b0};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) - (carry_inB);
  // Set the outputs
  assign result = carry_res[32:1];
  // Other comparison outputs
  // Temporary signals
  assign msb_abr = {carry_inA[32],carry_inB[32],carry_res[32]};
  assign tmp_sign = sign;
  assign tmp_eq = in_a == in_b ? 1'b1 : 1'b0;
  assign tmp_le = msb_abr == 3'b000 || msb_abr == 3'b110 ? tmp_eq : msb_abr == 3'b001 || msb_abr == 3'b111 ? 1'b1 : tmp_sign == 1'b0 && (msb_abr == 3'b010 || msb_abr == 3'b011) ? 1'b1 : tmp_sign == 1'b1 && (msb_abr == 3'b100 || msb_abr == 3'b101) ? 1'b1 : 1'b0;
  assign tmp_ge = msb_abr == 3'b000 || msb_abr == 3'b110 ? 1'b1 : tmp_sign == 1'b0 && (msb_abr == 3'b100 || msb_abr == 3'b101) ? 1'b1 : tmp_sign == 1'b1 && (msb_abr == 3'b010 || msb_abr == 3'b011) ? 1'b1 : 1'b0;
  assign le = tmp_le;
endmodule

