  assign LEDSEG[0] = SW;
  // SEG B : F1 = B' C D' + A' C'  + B' C' D + A' B' ;
  assign LEDSEG[1] = 1'b0;
  // SEG C : F2 = B C' D + A' B'  + A' C' ;
  assign LEDSEG[2] = 1'b0;
  // SEG D : F3 = A' D' + B C D' + B' C D + B' C' D' + A' C' ;
  assign LEDSEG[3] = SW;
  // SEG E : F4 = A' C'  + B' C  + D';
  assign LEDSEG[4] = SW;
  // SEG F : F5 = A B D' + A' B'  + B C'  + C' D';
  assign LEDSEG[5] = SW;
  // SED G : A B C  + B' C' D' + A' C'  + A' B' ;
  assign LEDSEG[6] = 1'b1;
endmodule

