module TagFIFO (
    input [2:0] Board,
    input Clock,
    input Reset,
    input enableIn,
    input [1:0] dataIn,
    input enableOut,
    output reg notEmpty,
    output reg [1:0] dataOut,
    output reg overFlow
);

    reg [3:0] nStored;
    reg [3:0] writePtr;
    reg [3:0] readPtr;
    reg [1:0] Tags [0:15];

    always @(posedge Clock or posedge Reset) begin
        if (Reset) begin
            overFlow <= 0;
            writePtr <= 0;
            readPtr <= 0;
            nStored <= 0;
            notEmpty <= 0;
        end else begin
            if (enableIn) begin
                if (nStored < 15 || enableOut)
                    nStored <= nStored + (enableOut ? 0 : 1);
                else
                    overFlow <= 1;

                Tags[writePtr] <= dataIn;
                writePtr <= writePtr + 1;

                $display("Board %d: Tag %b written to FIFO at time %t", Board, dataIn, $time);
            end

            if (enableOut && nStored > 0) begin
                nStored <= nStored - (enableIn ? 0 : 1);
                dataOut <= Tags[readPtr];
                readPtr <= readPtr + 1;

                $display("Board %d: Tag %b read from FIFO at time %t", Board, Tags[readPtr], $time);
            end

            notEmpty <= (nStored > 0);
        end
    end

endmodule

module logical(
