output wire [3:0] R
);
//output signals
wire [3:0] and_R;
wire [3:0] or_R;
wire [3:0] nor_R;
wire [3:0] xor_R;
  //crunch all possible values
  assign and_R = A & B;
  assign or_R = A | B;
  assign nor_R =  ~(A | B);
  assign xor_R = A ^ B;
  //select output based on opcode
  mux4 output(
      nor_R,
    and_R,
    or_R,
    xor_R,
    op,
    R);
endmodule

module comp_4bit(
    input [3:0] a,
    input [3:0] b,
    output gr,
    output eq
);

    wire [3:0] temp;

    assign gr = (a > b);

    assign temp[0] = ~(a[0] ^ b[0]);
    assign temp[1] = ~(a[1] ^ b[1]);
    assign temp[2] = ~(a[2] ^ b[2]);
    assign temp[3] = ~(a[3] ^ b[3]);

    assign eq = &temp;

endmodule

module freq_generator(
input wire Clk,
input wire Rst,
output reg Output
);
parameter [31:0] FREQUENCY;
parameter [31:0] CLK_FREQUENCY=FPGA_CLK_FREQ;
// Operation:
// Calculate how many clocks must pass and count to that value
parameter CLK_MAX = CLK_FREQUENCY / FREQUENCY;  // 100 MHz
reg [31:0] counter;
  always @(posedge Clk, posedge Rst) begin
    Output <= 1'b0;
    counter <= counter + 1;
    if((counter + 1) == CLK_MAX) begin
      Output <= 1'b1;
      counter <= 0;
    end
    if(Rst == 1'b1) begin
      counter <= 0;
    end
  end
endmodule

