module projeto2(
input wire [3:0] a,
input wire [3:0] b,
input wire clk,
output reg [6:0] display1,
output reg [6:0] display2
);
// Entrada A.
// Entrada B.
// Clock.
reg [3:0] saida_mux;
reg [6:0] bcd;  // BCD.
  // Mux 8->4.
  always @(a, b, clk) begin
    if((clk == 1'b0)) begin
      saida_mux <= a;
    end
    else begin
      saida_mux <= b;
    end
  end
  // BCD.
  always @(a, b, clk, saida_mux, bcd) begin
    if((saida_mux == 4'b0000)) begin
      // 0
      bcd <= 7'b1111110;
    end
    else if((saida_mux == 4'b0001)) begin
      // 1
      bcd <= 7'b0110000;
    end
    else if((saida_mux == 4'b0010)) begin
      // 2
      bcd <= 7'b1101101;
    end
    else if((saida_mux == 4'b0011)) begin
      // 3
      bcd <= 7'b1111001;
    end
    else if((saida_mux == 4'b0100)) begin
      // 4
      bcd <= 7'b0110010;
    end
    else if((saida_mux == 4'b0101)) begin
      // 5
      bcd <= 7'b1011010;
    end
    else if((saida_mux == 4'b0110)) begin
      // 6
      bcd <= 7'b1011111;
    end
    else if((saida_mux == 4'b0111)) begin
      // 7
      bcd <= 7'b1110000;
    end
    else if((saida_mux == 4'b1000)) begin
      // 8
      bcd <= 7'b1111111;
    end
    else if((saida_mux == 4'b1001)) begin
      // 9
      bcd <= 7'b1111011;
    end
    else if((saida_mux == 4'b1010)) begin
      // A
      bcd <= 7'b1110111;
    end
    else if((saida_mux == 4'b1011)) begin
      // B
      bcd <= 7'b0011111;
    end
    else if((saida_mux == 4'b1100)) begin
      // C
      bcd <= 7'b1001110;
    end
    else if((saida_mux == 4'b1101)) begin
      // D
      bcd <= 7'b0111101;
    end
    else if((saida_mux == 4'b1110)) begin
      // E
      bcd <= 7'b1001111;
    end
    else begin
      bcd <= 7'b1000111;
      // Caso defaul -> 'F'
    end
  end
  // Mux 1->2.
  always @(bcd, clk) begin
    if((clk == 1'b0)) begin
      display1 <= bcd;
    end
    else begin
      display2 <= bcd;
    end
  end
endmodule

module register_file (
    input wire clk,
    input wire [4:0] rd, rs, rt,
    input wire [31:0] busw,
    input wire regwr,
    input wire regdst,
    output wire [31:0] busA, busB
);

    reg [31:0] registers [0:31];

    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1) begin
            registers[i] = 32'b0;
        end
    end

    assign busA = registers[rs];
    assign busB = registers[rt];

    always @(posedge clk) begin
        if (regwr) begin
            if (regdst)
                registers[rd] <= busw;
            else
                registers[rt] <= busw;
        end
    end

endmodule

module IFU (
    input wire clk,
    input wire ibranch,
    input wire i_typej,
    input wire sb_type,
    input wire uj_type,
    input wire [31:0] iop_a,
    input wire [31:0] imm,
    output reg [31:0] pc
);

    // Initialize PC
    initial begin
        pc = 32'h0;
    end

    always @(posedge clk) begin
        if (sb_type && ibranch) begin
            // SB-type conditional branch
            pc <= pc + {imm[30:0], 1'b0};
        end
        else if (i_typej) begin
            // I-type jump
            pc <= iop_a + imm;
        end
        else if (uj_type) begin
            // UJ-type unconditional jump
            pc <= pc + {imm[30:0], 1'b0};
        end
        else begin
            // Default case: increment PC by 4
            pc <= pc + 32'd4;
        end
    end

endmodule

