module fsm_ut_sram (
    input wire rst_i,
    input wire wb_clk_i,
    input wire wb_ack_i,
    input wire [7:0] wb_datr_i,
    output reg wb_cyc_o,
    output reg wb_we_o,
    output reg [15:0] wb_addr_o,
    output reg [7:0] wb_datw_o
);

    reg [3:0] state;

    always @(posedge wb_clk_i or posedge rst_i) begin
        if (rst_i) begin
            state <= 4'd0;
            wb_cyc_o <= 1'b0;
            wb_we_o <= 1'b0;
            wb_addr_o <= 16'd0;
        end else begin
            case (state)
                4'd0: begin // Initialization
                    state <= 4'd4;
                    wb_addr_o <= 16'd0;
                end

                4'd4: begin // Write cycle start
                    wb_cyc_o <= 1'b1;
                    wb_we_o <= 1'b1;
                    wb_datw_o <= ~wb_addr_o[7:0];
                    state <= 4'd5;
                end

                4'd5: begin // Write cycle continue
                    if (wb_ack_i) begin
                        wb_cyc_o <= 1'b0;
                        if (wb_addr_o < 16'h04FF) begin
                            wb_addr_o <= wb_addr_o + 1'b1;
                            state <= 4'd4;
                        end else begin
                            wb_addr_o <= 16'd0;
                            state <= 4'd8;
                        end
                    end
                end

                4'd8: begin // Read cycle start
                    wb_cyc_o <= 1'b1;
                    wb_we_o <= 1'b0;
                    state <= 4'd9;
                end

                4'd9: begin // Read cycle continue
                    if (wb_ack_i) begin
                        wb_cyc_o <= 1'b0;
                        if (wb_addr_o < 16'h04FF) begin
                            wb_addr_o <= wb_addr_o + 1'b1;
                            state <= 4'd8;
                        end else begin
                            wb_addr_o <= 16'd0;
                            state <= 4'd4;
                        end
                    end
                end

                default: state <= 4'd0;
            endcase
        end
    end

endmodule

