module MUX5(
input wire selector,
input wire [20:16] vector_in_1,
input wire [15:11] vector_in_2,
output reg [20:16] vector_out
);
//! selection, 0 means output 1, 1 means output 2
// input vectors
//! first input vector
//! second input vector
// output vectors
//! output vector
//-----------------------------------------------------------------------------
//! It's a MUX5 ffs
//-----------------------------------------------------------------------------
  //---------------------------------------------------------------------------
  //! On every rising edge the mux puts the selected signal on the output
  //---------------------------------------------------------------------------
  always @(vector_in_1, vector_in_2, selector) begin
    if(selector == 1'b0) begin
      vector_out <= vector_in_1;
    end
    else if(selector == 1'b1) begin
      vector_out <= vector_in_2;
    end
  end
endmodule

module fifo_wrapper(
input wire wr_clk_in,
input wire rd_clk_in,
output wire [14:0] depth_out,
input wire [7:0] inputData_in,
input wire inputValid_in,
output wire inputReady_out,
output wire [7:0] outputData_out,
output wire outputValid_out,
input wire outputReady_in
);
// Clock and depth
// Data is clocked into the FIFO on each clock edge where both valid & ready are high
// Data is clocked out of the FIFO on each clock edge where both valid & ready are high
wire inputFull;
wire outputEmpty;
  // Invert "full/empty" signals to give "ready/valid" signals
  assign inputReady_out =  ~(inputFull);
  assign outputValid_out =  ~(outputEmpty);
  // The encapsulated FIFO
  xilinx_fifo fifo(
      .wr_clk(wr_clk_in),
    .rd_clk(rd_clk_in),
    .rd_data_count(depth_out),
    // Production end
    .din(inputData_in),
    .wr_en(inputValid_in),
    .full(inputFull),
    // Consumption end
    .dout(outputData_out),
    .empty(outputEmpty),
    .rd_en(outputReady_in));
endmodule

