module axis_to_data_lanes(
input wire ClkxCI,
input wire RstxRBI,
input wire [31:0] AxiTDataxDI,
input wire AxiTValid,
output reg AxiTReady,
output wire [15:0] Data0xDO,
output wire [15:0] Data1xDO,
output wire DataStrobexDO
);
parameter [31:0] Decimation=1;
parameter [31:0] Offset=32768;
reg [31:0] DataxDP = 1'b0; reg [31:0] DataxDN = 1'b0;
reg StrobexDP = 1'b0; reg StrobexDN = 1'b0;
reg [16:0] CntxDP = 1'b0; reg [16:0] CntxDN = 1'b0;
  // Persistent signal mappings
  assign Data0xDO = DataxDP[15:0];
  assign Data1xDO = DataxDP[31:16];
  assign DataStrobexDO = StrobexDP;
  // FF logic
  always @(posedge ClkxCI) begin
    if(RstxRBI == 1'b0) begin
      // Reset Signals
      DataxDP <= {32{1'b0}};
      StrobexDP <= 1'b0;
      CntxDP <= {17{1'b0}};
      AxiTReady <= 1'b0;
    end
    else begin
      // Advance signals by 1
      DataxDP <= DataxDN;
      StrobexDP <= StrobexDN;
      CntxDP <= CntxDN;
      AxiTReady <= 1'b1;
    end
  end
  always @(AxiTValid, CntxDP, AxiTDataxDI) begin : P1
    reg [16:0] X;
    reg [16:0] Y;
    reg [15:0] A;
    reg [15:0] B;
    if(AxiTValid == 1'b1) begin
      // receive every nth sample
      if(CntxDP == (Decimation - 1)) begin
        A = AxiTDataxDI[15:0];
        B = AxiTDataxDI[31:16];
        X = (A) + Offset;
        Y = (B) + Offset;
        DataxDN <= {Y[15:0],X[15:0]};
        StrobexDN <= 1'b1;
        CntxDN <= {17{1'b0}};
      end
      else begin
        DataxDN <= DataxDP;
        CntxDN <= CntxDP + 1;
        StrobexDN <= 1'b0;
      end
    end
    else begin
      DataxDN <= DataxDP;
      CntxDN <= CntxDP;
      StrobexDN <= 1'b0;
    end
  end
endmodule

`timescale 1 ns / 1 ns
module weight_out_synth(
input wire CLK_IN,
input wire RESET_IN,
output reg [8:0] STATUS
);
//ERROR STATUS OUT OF FPGA
wire CLKA = 1'b0;
wire RSTA = 1'b0;
wire [0:0] WEA = 1'b0;
reg [0:0] WEA_R = 1'b0;
wire [5:0] ADDRA = 1'b0;
reg [5:0] ADDRA_R = 1'b0;
wire [319:0] DINA = 1'b0;
reg [319:0] DINA_R = 1'b0;
wire [319:0] DOUTA;
wire CHECKER_EN = 1'b0;
reg CHECKER_EN_R = 1'b0;
reg [22:0] STIMULUS_FLOW = 1'b0;
wire clk_in_i;
reg RESET_SYNC_R1 = 1'b1;
reg RESET_SYNC_R2 = 1'b1;
reg RESET_SYNC_R3 = 1'b1;
wire ITER_R0 = 1'b0;
wire ITER_R1 = 1'b0;
wire ITER_R2 = 1'b0;
wire [7:0] ISSUE_FLAG = 1'b0;
reg [7:0] ISSUE_FLAG_STATUS = 1'b0;
  //  clk_buf: bufg
  //    PORT map(
  //      i => CLK_IN,
  //      o => clk_in_i
  //    );
  assign clk_in_i = CLK_IN;
  assign CLKA = clk_in_i;
  assign RSTA = # 50 RESET_SYNC_R3;
  always @(posedge clk_in_i) begin
    RESET_SYNC_R1 <= RESET_IN;
    RESET_SYNC_R2 <= RESET_SYNC_R1;
    RESET_SYNC_R3 <= RESET_SYNC_R2;
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      ISSUE_FLAG_STATUS <= {8{1'b0}};
    end
    else begin
      ISSUE_FLAG_STATUS <= ISSUE_FLAG_STATUS | ISSUE_FLAG;
    end
  end
  assign STATUS[7:0] = ISSUE_FLAG_STATUS;
  CHECKER #(
      .WRITE_WIDTH(320),
    .READ_WIDTH(320))
  BMG_DATA_CHECKER_INST(
      .CLK(CLKA),
    .RST(RSTA),
    .EN(CHECKER_EN_R),
    .DATA_IN(DOUTA),
    .STATUS(ISSUE_FLAG[0]));
  always @(posedge CLKA) begin
    if((RSTA == 1'b1)) begin
      CHECKER_EN_R <= 1'b0;
    end
    else begin
      CHECKER_EN_R <= # 50 CHECKER_EN;
    end
  end
  BMG_STIM_GEN BMG_STIM_GEN_INST(
      .CLK(clk_in_i),
    .RST(RSTA),
    .ADDRA(ADDRA),
    .DINA(DINA),
    .WEA(WEA),
    .CHECK_DATA(CHECKER_EN));
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STATUS[8] <= 1'b0;
      iter_r2 <= 1'b0;
      iter_r1 <= 1'b0;
      iter_r0 <= 1'b0;
    end
    else begin
      STATUS[8] <= iter_r2;
      iter_r2 <= iter_r1;
      iter_r1 <= iter_r0;
      iter_r0 <= STIMULUS_FLOW[8];
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      STIMULUS_FLOW <= {23{1'b0}};
    end
    else if((WEA[0] == 1'b1)) begin
      STIMULUS_FLOW <= STIMULUS_FLOW + 1;
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      WEA_R <= # 50 {1{1'b0}};
      DINA_R <= # 50 {320{1'b0}};
    end
    else begin
      WEA_R <= # 50 WEA;
      DINA_R <= # 50 DINA;
    end
  end
  always @(posedge CLKA) begin
    if((RESET_SYNC_R3 == 1'b1)) begin
      ADDRA_R <= # 50 {6{1'b0}};
    end
    else begin
      ADDRA_R <= # 50 ADDRA;
    end
  end
  weight_out_exdes BMG_PORT(
      //Port A
    .WEA(WEA_R),
    .ADDRA(ADDRA_R),
    .DINA(DINA_R),
    .DOUTA(DOUTA),
    .CLKA(CLKA));
endmodule

module RegisterFile(
    input [31:0] wtd,
    input [4:0] rsa, rta, wta,
    input clk, cnt,
    output [31:0] rsd, rtd
);

    reg [31:0] registers [0:31];
    integer i;

    initial begin
        for (i = 0; i < 32; i = i + 1)
            registers[i] = 32'b0;
    end

    assign rsd = (cnt && wta != 0 && rsa == wta) ? wtd : registers[rsa];
    assign rtd = (cnt && wta != 0 && rta == wta) ? wtd : registers[rta];

    always @(posedge clk) begin
        if (cnt && wta != 0)
            registers[wta] <= wtd;
    end

endmodule

module TestRegFile;
    reg [31:0] wtd;
    reg [4:0] rsa, rta, wta;
    reg cnt, clk;
    wire [31:0] rsd, rtd;

    RegisterFile rf(
        .wtd(wtd),
        .rsa(rsa),
        .rta(rta),
