module PMem(
input wire ram_rstn,
input wire ram_clk,
input wire [11:0] ram_addr,
input wire ram_cen,
output reg [15:0] ram_dout,
input wire [15:0] ram_din,
input wire [1:0] ram_wen
);
reg [11:0] ram_addr_latch;
wire [15:0] ram_din_latch;
wire OE_0_Enable;
wire OE_1_Enable;
wire OE_0;
wire OE_1;
wire OEB_0;
wire OEB_1;
wire WE_0_Enable;
wire WE_1_Enable;
wire WE_2_Enable;
wire WE_3_Enable;
wire WE_0;
wire WE_1;
wire WE_2;
wire WE_3;
wire WEB_0;
wire WEB_1;
wire WEB_2;
wire WEB_3;
wire [15:0] dout_0;
wire [15:0] dout_1;
wire DataClkEnable;
wire DataClk;
  // keep address valid after rising_edge(Clk_i); this can't be done by a D-FF
  // because the address setup time before the active (falling) edges of OEB
  // and WEB would be too short.
  always @(ram_clk, ram_addr, ram_cen) begin
    if(ram_clk == 1'b0) begin
      ram_addr_latch <= ram_addr;
    end
  end
  assign ram_din_latch = ram_din;
  // use clock gates to generate OEB and WEB so that synthesis correctly
  // identifies these signals as clocks
  assign OE_0_Enable = ram_cen == 1'b0 && ram_wen == 2'b11 && ram_addr[11] == 1'b0 ? 1'b1 : 1'b0;
  assign OE_1_Enable = ram_cen == 1'b0 && ram_wen == 2'b11 && ram_addr[11] == 1'b1 ? 1'b1 : 1'b0;
  omsp_clock_gate OEB_0_Gate(
      .clk(ram_clk),
    .enable(OE_0_Enable),
    .scan_enable(1'b0),
    .gclk(OE_0));
  omsp_clock_gate OEB_1_Gate(
      .clk(ram_clk),
    .enable(OE_1_Enable),
    .scan_enable(1'b0),
    .gclk(OE_1));
  assign OEB_0 =  ~OE_0;
  assign OEB_1 =  ~OE_1;
  assign WE_0_Enable = ram_cen == 1'b0 && ram_wen[0] == 1'b0 && ram_addr[11] == 1'b0 ? 1'b1 : 1'b0;
  assign WE_1_Enable = ram_cen == 1'b0 && ram_wen[1] == 1'b0 && ram_addr[11] == 1'b0 ? 1'b1 : 1'b0;
  assign WE_2_Enable = ram_cen == 1'b0 && ram_wen[0] == 1'b0 && ram_addr[11] == 1'b1 ? 1'b1 : 1'b0;
  assign WE_3_Enable = ram_cen == 1'b0 && ram_wen[1] == 1'b0 && ram_addr[11] == 1'b1 ? 1'b1 : 1'b0;
  omsp_clock_gate WEB_0_Gate(
      .clk(ram_clk),
    .enable(WE_0_Enable),
    .scan_enable(1'b0),
    .gclk(WE_0));
  omsp_clock_gate WEB_1_Gate(
      .clk(ram_clk),
    .enable(WE_1_Enable),
    .scan_enable(1'b0),
    .gclk(WE_1));
  omsp_clock_gate WEB_2_Gate(
      .clk(ram_clk),
    .enable(WE_2_Enable),
    .scan_enable(1'b0),
    .gclk(WE_2));
  omsp_clock_gate WEB_3_Gate(
      .clk(ram_clk),
    .enable(WE_3_Enable),
    .scan_enable(1'b0),
    .gclk(WE_3));
  assign WEB_0 =  ~WE_0;
  assign WEB_1 =  ~WE_1;
  assign WEB_2 =  ~WE_2;
  assign WEB_3 =  ~WE_3;
  assign DataClkEnable =  ~ram_cen;
  omsp_clock_gate Data_Gate(
      .clk(ram_clk),
    .enable(DataClkEnable),
    .scan_enable(1'b0),
    .gclk(DataClk));
  always @(negedge ram_rstn, negedge DataClk) begin
    if(ram_rstn == 1'b0) begin
      ram_dout <= {16{1'b0}};
    end else begin
      ram_dout <= dout_0 | dout_1;
      // sram2kx8 O is "0" while OEB = '1'
    end
  end
  sram2kx8 ram_0(
      .A(ram_addr_latch[10:0]),
    .I(ram_din_latch[7:0]),
    .OEB(OEB_0),
    .O(dout_0[7:0]),
    .RB(1'b1),
    .WEB(WEB_0));
  sram2kx8 ram_1(
      .A(ram_addr_latch[10:0]),
    .I(ram_din_latch[15:8]),
    .OEB(OEB_0),
    .O(dout_0[15:8]),
    .RB(1'b1),
    .WEB(WEB_1));
  sram2kx8 ram_2(
      .A(ram_addr_latch[10:0]),
    .I(ram_din_latch[7:0]),
    .OEB(OEB_1),
    .O(dout_1[7:0]),
    .RB(1'b1),
    .WEB(WEB_2));
  sram2kx8 ram_3(
      .A(ram_addr_latch[10:0]),
    .I(ram_din_latch[15:8]),
    .OEB(OEB_1),
    .O(dout_1[15:8]),
    .RB(1'b1),
    .WEB(WEB_3));
endmodule

