module Part3(
    input [9:0] SW,
    output [1:0] LEDR
);

    wire [1:0] U, V, W, X;
    wire [1:0] sel;
    wire [1:0] buffer_1, buffer_2;

    // Input mapping
    assign U = SW[1:0];
    assign V = SW[3:2];
    assign W = SW[5:4];
    assign X = SW[7:6];
    assign sel = SW[9:8];

    // First-level multiplexing
    assign buffer_1 = (sel[0]) ? V : U;
    assign buffer_2 = (sel[0]) ? X : W;

    // Second-level multiplexing with bit swapping
    assign LEDR[1] = (sel[1]) ? buffer_2[0] : buffer_1[0];
    assign LEDR[0] = (sel[1]) ? buffer_2[1] : buffer_1[1];

endmodule

module sparcv8_v4(
