module ZeroTest (
    input [4:0] ALUCode,
    input [31:0] RsData,
    input [31:0] RtData,
    output reg Z
);

    localparam BEQ  = 5'b00001;
    localparam BNE  = 5'b00010;
    localparam BGEZ = 5'b00011;
    localparam BGTZ = 5'b00100;
    localparam BLEZ = 5'b00101;
    localparam BLTZ = 5'b00110;

    always @(*) begin
        case (ALUCode)
            BEQ:  Z = &(~(RsData ^ RtData));
            BNE:  Z = |(RsData ^ RtData);
            BGEZ: Z = ~RsData[31];
            BGTZ: Z = ~RsData[31] & (|RsData);
            BLEZ: Z = RsData[31] | (RsData == 32'b0);
            BLTZ: Z = RsData[31];
            default: Z = 1'b0;
        endcase
    end

endmodule

