module debouncer #(
    parameter SIZE = 16,
    parameter BTN_WIDTH = 5
)(
    input wire clk,
    input wire rst,
    input wire [BTN_WIDTH-1:0] btn_in,
    output reg [BTN_WIDTH-1:0] btn_out,
    output reg [BTN_WIDTH-1:0] btn_out_pulse
);

    reg [BTN_WIDTH-1:0] btn_in_d [3:0];
    wire [BTN_WIDTH-1:0] set;
    reg [SIZE-1:0] o;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            btn_in_d[0] <= {BTN_WIDTH{1'b0}};
            btn_in_d[1] <= {BTN_WIDTH{1'b0}};
            btn_in_d[2] <= {BTN_WIDTH{1'b0}};
            btn_in_d[3] <= {BTN_WIDTH{1'b0}};
        end else begin
            btn_in_d[0] <= btn_in;
            btn_in_d[1] <= btn_in_d[0];
            btn_in_d[2] <= btn_in_d[1];
            btn_in_d[3] <= btn_in_d[2];
        end
    end

    assign set = (btn_in_d[1] ^ btn_in_d[2]);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            o <= {SIZE{1'b0}};
        end else begin
            if (|set) begin
                o <= {SIZE{1'b0}};
            end else if (o != {SIZE{1'b1}}) begin
                o <= o + 1'b1;
            end
        end
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            btn_out <= {BTN_WIDTH{1'b0}};
            btn_out_pulse <= {BTN_WIDTH{1'b0}};
        end else begin
            if (o == {SIZE{1'b1}}) begin
                btn_out <= btn_in_d[3];
            end
            btn_out_pulse <= btn_out ^ btn_in_d[3];
        end
    end

endmodule

