module master_controller(
input wire clk_i,
input wire rst_i,
input wire en_i,
input wire spi_req_i,
output wire spi_wen_o,
output reg count_up_o
);
reg wen = 1'b1;
  // architecture str
  always @(posedge clk_i) begin
    if(rst_i == 1'b1) begin
      wen <= 1'b1;
    end
    else begin
      if(spi_req_i == 1'b1 && en_i == 1'b1) begin
        wen <= 1'b1;
        if(wen == 1'b0) begin
          count_up_o <= 1'b1;
        end
        else begin
          count_up_o <= 1'b0;
        end
      end
      else begin
        wen <= 1'b0;
        count_up_o <= 1'b0;
      end
    end
  end
  assign spi_wen_o = wen;
//-----------------------------------------------------------------------------
endmodule

module counter_4bit (
    input wire [3:0] data_in,
    input wire clk,
    input wire clear,
    input wire load,
    input wire count,
    input wire updown,
    output reg [3:0] A_count
);

    always @(posedge clk or negedge clear) begin
        if (!clear) begin
            A_count <= 4'b0000;
        end else begin
            case ({load, count, updown})
                3'b100, 3'b101: A_count <= data_in;
                3'b010: A_count <= A_count - 1'b1;
                3'b011: A_count <= A_count + 1'b1;
                default: A_count <= A_count;
            endcase
        end
    end

endmodule

module enemy_datapath(
    input start, num, clock, resetn,
    input loadX, loadY, load_colour, load_black,
    input reset_delay, en_counter, en_delay_counter,
    output [7:0] xValue,
    output [6:0] yValue,
    output [2:0] colourValue,
    output [3:0] cnt,
    output [3:0] delay_cnt
);

    wire [7:0] X;
    wire [6:0] Y;
    wire [2:0] colour;
    wire CLOCK;

    assign CLOCK = clock & (start == num);

    // X counter
    counter8bit Xcounter(
        .enable(loadX),
        .clock(CLOCK),
        .clear_b(resetn),
        .Q(X)
    );

    // Y counter
    counter7bit Ycounter(
        .enable(loadY),
        .clock(CLOCK),
        .clear_b(resetn),
        .Q(Y)
    );

    // Colour register
    reg_3bit R_Colour(
        .D({X[7:5] ^ num, X[4:2]}),
        .clock(CLOCK),
        .reset_n(resetn),
        .enable(load_colour),
        .Q(colour)
    );

    // Counter without delay
    counter4bit counter_no_delay(
        .enable(en_counter),
        .clock(CLOCK),
        .clear_b(resetn),
        .Q(cnt)
    );

    // Counter with delay
    counter4bit counter_with_delay(
        .enable(en_delay_counter),
        .clock(CLOCK),
        .clear_b(resetn),
        .Q(delay_cnt)
    );

    // Delay counter
    delay_counter delayCounter(
        .clock(clock),
        .resetn(resetn),
        .enable(1'b1),
        .num(num),
        .reset_delay(reset_delay)
    );

    // Output assignments
    assign xValue = {X[7:4], cnt[3:0]};
    assign yValue = {Y[6:4], cnt[3:0]};
    assign colourValue = load_black ? 3'b000 : colour;

endmodule

// 8-bit counter
module counter8bit(
    input enable, clock, clear_b,
    output reg [7:0] Q
);
    always @(posedge clock, negedge clear_b)
        if (!clear_b)
            Q <= 8'b0;
        else if (enable)
            Q <= Q + 1'b1;
endmodule

// 7-bit counter
module counter7bit(
    input enable, clock, clear_b,
    output reg [6:0] Q
);
    always @(posedge clock, negedge clear_b)
        if (!clear_b)
            Q <= 7'b0;
        else if (enable)
            Q <= Q + 1'b1;
endmodule

// 3-bit register
module reg_3bit(
    input [2:0] D,
    input clock, reset_n, enable,
    output reg [2:0] Q
);
    always @(posedge clock, negedge reset_n)
        if (!reset_n)
            Q <= 3'b0;
        else if (enable)
            Q <= D;
endmodule

// 4-bit counter
module counter4bit(
    input enable, clock, clear_b,
    output reg [3:0] Q
);
    always @(posedge clock, negedge clear_b)
        if (!clear_b)
            Q <= 4'b0;
        else if (enable)
            Q <= Q + 1'b1;
endmodule

// Delay counter
module delay_counter(
    input clock, resetn, enable,
    input num,
    input reset_delay
);
    reg [27:0] Q;
    always @(posedge clock, negedge resetn)
        if (!resetn)
            Q <= 28'b0;
        else if (reset_delay)
            Q <= 28'b0;
        else if (enable)
            Q <= Q + 1'b1;
endmodule

module Adder_2x16(
input wire isSubtraction,
input wire [15:0] input_A,
input wire [15:0] input_B,
output reg carry_out,
output reg [15:0] output
);
  always @(input_A, input_B, isSubtraction) begin : P1
    reg [15:0] sum, bOrNotb;
    reg carry;
    if((isSubtraction == 1'b1)) begin
      bOrNotb =  ~input_B;
    end
    else begin
      bOrNotb = input_B;
    end
    carry = isSubtraction;
    for (i=0; i <= 15; i = i + 1) begin
      sum[i] = input_A[i] ^ bOrNotb[i] ^ carry;
      carry = (input_A[i] & bOrNotb[i]) | ((input_A[i] ^ bOrNotb[i]) & carry);
    end
    carry_out <= carry;
    output <= sum;
  end
endmodule

