    if (rst) begin
        q <= 1'b0;
        temp <= a;
    end else begin
        q <= temp[0];
        temp <= temp >> 1;
    end
end

endmodule

module glitch_free (
    input wire clk0,
    input wire clk1,
    input wire select,
    input wire rst_n,
    output wire outclk
);

reg out_r1, out1, out_r0, out0;

// clk1 domain
always @(posedge clk1 or negedge rst_n) begin
    if (!rst_n)
        out_r1 <= 1'b0;
    else
        out_r1 <= select;
end

always @(negedge clk1 or negedge rst_n) begin
    if (!rst_n)
        out1 <= 1'b0;
    else
        out1 <= out_r1;
end

// clk0 domain
always @(posedge clk0 or negedge rst_n) begin
    if (!rst_n)
        out_r0 <= 1'b1;
    else
        out_r0 <= ~select;
end

always @(negedge clk0 or negedge rst_n) begin
    if (!rst_n)
        out0 <= 1'b1;
    else
        out0 <= out_r0;
end

// Output clock selection
assign outclk = (clk1 & out1) | (clk0 & out0);

endmodule

