module register_file_4x16 (
    input wire [15:0] d,
    input wire [1:0] rsel, wsel,
    input wire we, ck, res,
    output reg [15:0] q,
    output wire [15:0] r_out0, r_out1, r_out2, r_out3
);

    reg [15:0] r0, r1, r2, r3;

    always @(posedge ck or negedge res) begin
        if (!res) begin
            r0 <= 16'b0;
            r1 <= 16'b0;
            r2 <= 16'b0;
            r3 <= 16'b0;
        end
        else if (!we) begin
            case (wsel)
                2'b00: r0 <= d;
                2'b01: r1 <= d;
                2'b10: r2 <= d;
                2'b11: r3 <= d;
            endcase
        end
    end

    always @(*) begin
        case (rsel)
            2'b00: q = r0;
            2'b01: q = r1;
            2'b10: q = r2;
            2'b11: q = r3;
        endcase
    end

    assign r_out0 = r0;
    assign r_out1 = r1;
    assign r_out2 = r2;
    assign r_out3 = r3;

endmodule

module half_pixel_interpolator_fir(
input wire [7:0] x0,
input wire [7:0] x1,
input wire [7:0] x2,
input wire [7:0] x3,
input wire [7:0] x4,
input wire [7:0] x5,
output wire [7:0] y
);
//interpolation equation
//y_1 = x0 -5*x1 + 20*x2 + 20*x3 - 5*x4 + x5
//y   = clip1((y_1 + 16)>>5)
wire [31:0] x0_u;
wire [15:0] x1_u;
wire [15:0] x2_u;
wire [15:0] x3_u;
wire [15:0] x4_u;
wire [31:0] x5_u;
wire [31:0] y_a;
wire [31:0] y_b;
wire [31:0] y_c;
  assign x0_u = {24'h000000,x0};
  assign x1_u = {8'h00,x1};
  assign x2_u = {8'h00,x2};
  assign x3_u = {8'h00,x3};
  assign x4_u = {8'h00,x4};
  assign x5_u = {24'h000000,x5};
  assign y_a = x0_u - (5) * x1_u + (20) * x2_u + (20) * x3_u - (5) * x4_u + x5_u;
  assign y_b = y_a >> 5;
  assign y_c = y_b;
  assign y = y_b >= (0) && y_b <= (255) ? y_c[7:0] : y_b < (0) ? 0 : 255;
endmodule

module alu(
input wire [3:0] sel,
input wire [7:0] a,
input wire [7:0] b_from_reg,
input wire [7:0] b_from_instr,
input wire c_in,
input wire mux_sel,
output wire [7:0] sum,
output reg c_flag,
output reg z_flag
);
reg [8:0] sum_i = 1'b0; wire [8:0] a_i = 1'b0; wire [8:0] b_i = 1'b0;
reg [7:0] b_mux_i = 1'b0;
  assign a_i = {1'b0,a};
  assign b_i = {1'b0,b_mux_i};
  assign sum = sum_i[7:0];
  always @(*) begin
    case(mux_sel)
      1'b0 : b_mux_i <= b_from_reg;
      1'b1 : b_mux_i <= b_from_instr;
      default : b_mux_i <= {8{1'bX}};
    endcase
  end
  always @(a, b_mux_i, a_i, b_i, sum_i, sel, c_in) begin
    c_flag <= 1'b0;
    z_flag <= 1'b0;
    sum_i <= {9{1'b0}};
    case(sel)
        //ADD
    4'h0 : begin
      sum_i <= a_i + b_i;
      if((sum_i[7:0] == 8'h00)) begin
        z_flag <= 1'b1;
      end
      c_flag <= sum_i[8];
      //ADDC
    end
    4'h1 : begin
      sum_i <= a_i + b_i + c_in;
      if((sum_i[7:0] == 8'h00)) begin
        z_flag <= 1'b1;
      end
      c_flag <= sum_i[8];
      //CMP
    end
    4'h2 : begin
      if((a == b_mux_i)) begin
        z_flag <= 1'b1;
        c_flag <= 1'b0;
      end
      else if((a < b_mux_i)) begin
        c_flag <= 1'b1;
        z_flag <= 1'b0;
      end
      else begin
        z_flag <= 1'b0;
        c_flag <= 1'b0;
      end
      //SUB --possible error here???
    end
    4'h3 : begin
      sum_i <= a_i - b_i;
      if((sum_i[7:0] == 8'h00)) begin
        z_flag <= 1'b1;
      end
      c_flag <= sum_i[8];
      //SUBC
    end
    4'h4 : begin
      sum_i <= a_i - b_i - c_in;
      if((sum_i[7:0] == 8'h00)) begin
        z_flag <= 1'b1;
      end
      c_flag <= sum_i[8];
      //AND
    end
    4'h5 : begin
      sum_i[7:0] <= a & b_mux_i;
      if((sum_i[7:0] == 4'h0)) begin
        z_flag <= 1'b1;
      end
      //ASR
    end
    4'h6 : begin
      sum_i[7:0] <= {a[7],a[7:1]};
      c_flag <= a[0];
      if((sum_i == 8'h00)) begin
        z_flag <= 1'b1;
      end
      //EXOR
    end
    4'h7 : begin
      sum_i[7:0] <= a ^ b_mux_i;
      if((sum_i[7:0] == 8'h00)) begin
        z_flag <= 1'b1;
      end
      //LSL
    end
    4'h8 : begin
      sum_i <= {a,c_in};
      c_flag <= sum_i[8];
      if((sum_i[7:0] == 8'h00)) begin
        z_flag <= 1'b1;
      end
      //LSR
    end
    4'h9 : begin
      sum_i[7:0] <= {c_in,a[7:1]};
      c_flag <= a[0];
      if((sum_i[7:0] == 8'h00)) begin
        z_flag <= 1'b1;
      end
      //OR
    end
    4'ha : begin
      sum_i[7:0] <= a | b_mux_i;
      if((sum_i[7:0] == 8'h00)) begin
        z_flag <= 1'b1;
      end
      //ROL
    end
    4'hb : begin
      sum_i <= {a[7:0],a[7]};
      c_flag <= sum_i[8];
      if((sum_i[7:0] == 8'h00)) begin
        z_flag <= 1'b1;
      end
      //ROR
    end
    4'hc : begin
      sum_i[7:0] <= {a[0],a[7:1]};
      c_flag <= a[0];
      if((sum_i[7:0] == 8'h00)) begin
        z_flag <= 1'b1;
      end
      //TEST
    end
    4'hd : begin
      if(((a & b_mux_i) == 8'h00)) begin
        z_flag <= 1'b1;
      end
      //MOV
    end
    4'he : begin
      sum_i[7:0] <= b_mux_i;
    end
    default : begin
      sum_i <= {1'b0,8'h00};
      z_flag <= 1'b0;
      c_flag <= 1'b0;
    end
    endcase
  end
endmodule

