module Project(
    input Clk, Clk2, CLOCK_50,
    output reg [3:0] LEDS
);

reg [7:0] Condition, Conditions;
reg Right, temp;
wire slow_clock;

initial begin
    LEDS = 4'b0001;
    Condition = 8'b00000001;
    temp = 1'b0;
end

clock_divider clk_div(
    .clock_in(CLOCK_50),
    .clock_out(slow_clock)
);

always @(negedge Clk2) begin
    temp <= ~temp;
end

always @(negedge Clk) begin
    Right <= temp;
end

always @(posedge slow_clock) begin
    if (Right) begin
        case (LEDS)
            4'b0001: begin
                LEDS <= 4'b0010;
                Condition <= 8'b00000000;
                Conditions <= 8'b00000001;
            end
            4'b0010: begin
                LEDS <= 4'b0100;
                Condition <= 8'b00000001;
                Conditions <= 8'b00000010;
            end
            4'b0100: begin
                LEDS <= 4'b1000;
                Condition <= 8'b00000010;
                Conditions <= 8'b00000011;
            end
            4'b1000: begin
                LEDS <= 4'b0001;
                Condition <= 8'b00000011;
                Conditions <= 8'b00000000;
            end
            default: LEDS <= 4'b0001;
        endcase
    end else begin
        case (LEDS)
            4'b1000: begin
                LEDS <= 4'b0100;
                Conditions <= 8'b00000111;
                Condition <= 8'b00000000;
            end
            4'b0100: begin
                LEDS <= 4'b0010;
                Conditions <= 8'b00000110;
                Condition <= 8'b00000001;
            end
            4'b0010: begin
                LEDS <= 4'b0001;
                Conditions <= 8'b00000101;
                Condition <= 8'b00000010;
            end
            4'b0001: begin
                LEDS <= 4'b1000;
                Conditions <= 8'b00000100;
                Condition <= 8'b00000011;
            end
            default: LEDS <= 4'b1000;
        endcase
    end
end

endmodule

