module fsm(
input wire reg_control,
input wire press,
input wire clk,
input wire rst,
output reg [2:0] argument
);
parameter [3:0]
  inicial = 0,
  carrega_reg8 = 1,
  dummy1 = 2,
  carrega_reg16 = 3,
  dummy2 = 4,
  soma_expoentes = 5,
  soma_mantissa = 6,
  desloca_mantissa = 7,
  normaliza = 8,
  expoente = 9,
  final = 10;
reg [3:0] actual_step; reg [3:0] next_step;
reg [2:0] argument_aux;
reg [3:0] count;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      actual_step <= inicial;
    end else begin
      if((next_step == desloca_mantissa)) begin
        count <= count - 1;
      end
      else if((next_step == soma_expoentes)) begin
        count <= 4'b1000;
      end
      actual_step <= next_step;
    end
  end
  always @(actual_step, count, press, reg_control) begin
    case(actual_step)
    inicial : begin
      // Estado inicial (reset)
      argument_aux <= 3'b000;
      next_step <= carrega_reg8;
    end
    carrega_reg8 : begin
      // Carrega registrador de 8 bits (multiplicando)
      // count <= "111";
      if((press == 1'b1)) begin
        argument_aux <= 3'b001;
        next_step <= dummy1;
      end
      else begin
        argument_aux <= 3'b000;
        next_step <= carrega_reg8;
      end
    end
    dummy1 : begin
      // Evita possíveis casos de o botão ficar apertado
      // por muito tempo
      argument_aux <= 3'b000;
      if((press == 1'b0)) begin
        next_step <= carrega_reg16;
      end
      else begin
        next_step <= dummy1;
      end
    end
    carrega_reg16 : begin
      // Inicia parte baixa do registrador de 16 bits (multiplicador)
      if((press == 1'b1)) begin
        argument_aux <= 3'b010;
        next_step <= dummy2;
      end
      else begin
        argument_aux <= 3'b000;
        next_step <= carrega_reg16;
      end
    end
    dummy2 : begin
      // Evita possíveis casos de o botão ficar apertado
      // por muito tempo			
      argument_aux <= 3'b000;
      if((press == 1'b0)) begin
        next_step <= soma_expoentes;
      end
      else begin
        next_step <= dummy2;
      end
    end
    soma_expoentes : begin
      // Soma os expoentes
      if((press == 1'b1)) begin
        argument_aux <= 3'b110;
        next_step <= soma_mantissa;
      end
      else begin
        argument_aux <= 3'b000;
        next_step <= soma_expoentes;
      end
    end
    soma_mantissa : begin
      // Conta 8x para realizar a operação de multiplicação (soma e desloca)
      if((count == 4'b0000)) begin
        argument_aux <= 3'b000;
        next_step <= normaliza;
      end
      else begin
        argument_aux <= 3'b011;
        next_step <= desloca_mantissa;
      end
    end
    desloca_mantissa : begin
      // Realiza a soma e/ou deslocamento
      argument_aux <= 3'b100;
      next_step <= soma_mantissa;
    end
    normaliza : begin
      // Inicia e termina a normalização
      argument_aux <= 3'b101;
      if((reg_control == 1'b1)) begin
        next_step <= expoente;
      end
      else begin
        next_step <= normaliza;
      end
    end
    expoente : begin
      // Envia dados para o bloco expoente
      argument_aux <= 3'b111;
      next_step <= final;
    end
    final : begin
      argument_aux <= 3'b000;
      next_step <= final;
    end
    endcase
    argument <= argument_aux;
  end
endmodule

module GameCounter (
    input wire clk,
    input wire Enable,
    output reg pulse
);

    reg [26:0] counter;

    always @(posedge clk) begin
        if (!Enable) begin
            counter <= 27'd0;
        end else if (counter == 27'd24999999) begin
            counter <= 27'd0;
            pulse <= ~pulse;
        end else begin
            counter <= counter + 1'b1;
        end
    end

endmodule

module sincronizacion(
    input wire reset,
    input wire CLK_pix_rate,
    output wire h_sync,
    output wire v_sync,
    output wire video_on,
    output wire [9:0] pixel_x,
    output wire [9:0] pixel_y
);

    // Horizontal timing parameters
    localparam H_DISPLAY    = 640;
    localparam H_FRONT      = 16;
    localparam H_SYNC       = 96;
    localparam H_BACK       = 48;
    localparam H_TOTAL      = H_DISPLAY + H_FRONT + H_SYNC + H_BACK;

    // Vertical timing parameters
    localparam V_DISPLAY    = 480;
    localparam V_FRONT      = 10;
    localparam V_SYNC       = 2;
    localparam V_BACK       = 33;
    localparam V_TOTAL      = V_DISPLAY + V_FRONT + V_SYNC + V_BACK;

    reg [9:0] h_cont_reg, h_cont_next;
    reg [9:0] v_cont_reg, v_cont_next;

    wire h_fin, v_fin;

    // Register operations
    always @(posedge CLK_pix_rate or posedge reset)
    begin
        if (reset)
        begin
            h_cont_reg <= 10'b0;
            v_cont_reg <= 10'b0;
        end
        else
        begin
            h_cont_reg <= h_cont_next;
            v_cont_reg <= v_cont_next;
        end
    end

    // Next-state logic
    assign h_fin = (h_cont_reg == H_TOTAL - 1);
    assign v_fin = (v_cont_reg == V_TOTAL - 1);

    always @*
    begin
        h_cont_next = h_fin ? 10'b0 : h_cont_reg + 1;
        v_cont_next = h_fin ? (v_fin ? 10'b0 : v_cont_reg + 1) : v_cont_reg;
    end

    // Output logic
    assign h_sync = (h_cont_reg >= (H_DISPLAY + H_FRONT) &&
                     h_cont_reg < (H_DISPLAY + H_FRONT + H_SYNC));
    assign v_sync = (v_cont_reg >= (V_DISPLAY + V_FRONT) &&
                     v_cont_reg < (V_DISPLAY + V_FRONT + V_SYNC));
    assign video_on = (h_cont_reg < H_DISPLAY) && (v_cont_reg < V_DISPLAY);

    // Pixel coordinates
    assign pixel_x = h_cont_reg;
    assign pixel_y = v_cont_reg;

endmodule

module kbBuffer(
input wire CLK,
input wire CLR,
input wire LOAD,
input wire [7:0] I,
output reg [15:0] O
);
reg [7:0] DATA;
  always @(posedge CLK, posedge CLR) begin
    if((LOAD == 1'b1 && DATA == 8'h00)) begin
      DATA <= I;
    end
    else if((CLR == 1'b1)) begin
      O <= {8'b00000000,DATA};
      DATA <= {8{1'b0}};
    end
    else begin
      O <= {16{1'bZ}};
    end
  end
endmodule

module sub_189(
output wire lt,
input wire sign,
output wire [31:0] result,
input wire [31:0] in_a,
input wire [31:0] in_b
);
wire [33:0] carry_inA;
wire [33:0] carry_inB;
wire [33:0] carry_res;  // Signals to generate the comparison outputs
wire [2:0] msb_abr;
wire tmp_sign;
wire tmp_eq;
wire tmp_le;
wire tmp_ge;
  // To handle the CI input, the operation is '0' - CI
  // If CI is not present, the operation is '0' - '0'
  assign carry_inA = {1'b0,in_a,1'b0};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) - (carry_inB);
  // Set the outputs
  assign result = carry_res[32:1];
  // Other comparison outputs
  // Temporary signals
  assign msb_abr = {carry_inA[32],carry_inB[32],carry_res[32]};
  assign tmp_sign = sign;
  assign tmp_eq = in_a == in_b ? 1'b1 : 1'b0;
  assign tmp_le = msb_abr == 3'b000 || msb_abr == 3'b110 ? tmp_eq : msb_abr == 3'b001 || msb_abr == 3'b111 ? 1'b1 : tmp_sign == 1'b0 && (msb_abr == 3'b010 || msb_abr == 3'b011) ? 1'b1 : tmp_sign == 1'b1 && (msb_abr == 3'b100 || msb_abr == 3'b101) ? 1'b1 : 1'b0;
  assign tmp_ge = msb_abr == 3'b000 || msb_abr == 3'b110 ? 1'b1 : tmp_sign == 1'b0 && (msb_abr == 3'b100 || msb_abr == 3'b101) ? 1'b1 : tmp_sign == 1'b1 && (msb_abr == 3'b010 || msb_abr == 3'b011) ? 1'b1 : 1'b0;
  assign lt =  ~(tmp_ge);
endmodule

