module calc(
input wire rst,
input wire clk,
input wire rot_c,
input wire btn_east,
input wire btn_west,
input wire btn_north,
input wire [3:0] sw,
output wire [7:0] led
);
parameter [31:0] clk_frq=50000000;
// 50 MHz
// BTN_SOUTH
wire [3:0] op1;
wire [3:0] op2;
wire [2:0] op;
reg [31:0] dbnc_cnt;
wire rot_c_prev;
reg rot_c_dbnc;
  ctrl ctrlinst(
      .rst(rst),
    .clk(clk),
    .rot_c(rot_c_dbnc),
    .btn_east(btn_east),
    .btn_west(btn_west),
    .btn_north(btn_north),
    .sw(sw),
    .op1(op1),
    .op2(op2),
    .op(op));
  proc procinst(
      .op1(op1),
    .op2(op2),
    .op(op),
    .led(led));
  always @(posedge rot_c, posedge rst, posedge clk) begin
    if(rst == 1'b1) begin
      dbnc_cnt <= 5000000;
      rot_c_dbnc <= 1'b0;
    end else begin
      if(dbnc_cnt == 0) begin
        dbnc_cnt <= 5000000;
        rot_c_dbnc <= rot_c_dbnc;
      end
      else if(dbnc_cnt < 5000000) begin
        dbnc_cnt <= dbnc_cnt - 1;
        rot_c_dbnc <= rot_c_dbnc;
      end
      else if(rot_c_prev != rot_c) begin
        dbnc_cnt <= dbnc_cnt - 1;
        rot_c_dbnc <= rot_c;
      end
      else begin
        dbnc_cnt <= 5000000;
        rot_c_dbnc <= rot_c_dbnc;
      end
    end
  end
endmodule

module GreenDroidCopyCore(
input wire [31:0] i00,
input wire [31:0] i01,
input wire [31:0] i02,
input wire [31:0] i03,
output reg [31:0] r00,
output reg [31:0] r01,
output reg [31:0] r02,
output reg [31:0] r03,
input wire [31:0] FP,
output reg [31:0] FPout,
output reg [31:0] M_ADDR,
inout reg [31:0] M_DATA,
inout reg M_RD,
inout reg M_WR,
input wire M_RDY,
input wire reset,
input wire CLK
);
parameter [3:0]
  ST_INIT = 0,
  WS_INIT = 1,
  ST_RESET = 2,
  ST00 = 3,
  WS00 = 4,
  ST01 = 5,
  WS01 = 6,
  ST02 = 7,
  WS02 = 8,
  ST_END = 9;
reg [3:0] Mstate;
  // CONTROL PROCESS --------
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      Mstate <= ST_RESET;
    end else begin
      case(Mstate)
      ST_RESET : begin
        Mstate <= ST_INIT;
      end
      ST_INIT : begin
        if(M_RDY == 1'b1) begin
          Mstate <= ST00;
        end
        else begin
          Mstate <= WS_INIT;
        end
      end
      WS_INIT : begin
        if(M_RDY == 1'b1) begin
          Mstate <= ST00;
        end
      end
      ST00 : begin
        if(M_RDY == 1'b1) begin
          Mstate <= ST01;
        end
        else begin
          Mstate <= WS00;
        end
      end
      WS00 : begin
        if(M_RDY == 1'b1) begin
          Mstate <= ST01;
        end
      end
      ST01 : begin
        if(M_RDY == 1'b1) begin
          Mstate <= ST02;
        end
        else begin
          Mstate <= WS01;
        end
      end
      WS01 : begin
        if(M_RDY == 1'b1) begin
          Mstate <= ST02;
        end
      end
      ST02,WS02,ST_END : begin
      end
      default : begin
      end
      endcase
    end
  end
  // EXECUTE PROCESS --------
  always @(posedge clk, posedge reset) begin : P1
    reg [31:0] T, s0, s1, s2, s3, s4, s5, s6, s7, fpi;
    if((reset == 1'b1)) begin
      // reset any internal states -- 
      s0 = {1{1'b0}};
      s1 = {1{1'b0}};
      s2 = {1{1'b0}};
      s3 = {1{1'b0}};
      s4 = {1{1'b0}};
      s5 = {1{1'b0}};
      s6 = {1{1'b0}};
      s7 = {1{1'b0}};
      fpi = {1{1'b0}};
      M_ADDR <= {32{1'bZ}};
      M_DATA <= {32{1'bZ}};
      M_RD <= 1'bZ;
      M_WR <= 1'bZ;
    end else begin
      M_DATA <= 32'bZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZ;
      case(Mstate)
      ST_INIT : begin
        // connect 4 input params here --
        s0 = i00;
        s1 = i01;
        s2 = i02;
        s3 = i03;
        fpi = FP;
        //lit ;
        s7 = s6;
        s6 = s5;
        s5 = s4;
        s4 = s3;
        s3 = s2;
        s2 = s1;
        s1 = s0;
        s0 = 12;
        //fp- ;
        fpi = fpi + s0;
        s0 = s1;
        s1 = s2;
        s2 = s3;
        s3 = s4;
        s4 = s5;
        s5 = s6;
        s6 = s7;
        //rsu3 ;
        T = s0;
        s0 = s1;
        s1 = s2;
        s2 = T;
      end
      ST00 : begin
      end
      ST01 : begin
        //tos-- ;
        s0 = s0 - 31'b0000000000000000000000000000001;
        // bl ### ignored ### ;
        // recover 4 results here --
        r00 <= s0;
        r01 <= s1;
        r02 <= s2;
        r03 <= s3;
        FPout <= fpi;
      end
      default : begin
      end
      endcase
    end
  end
endmodule

