module mchan_arb_primitive #(
    parameter DATA_WIDTH = 32,
    parameter ID_WIDTH = 4
) (
    input wire RR_FLAG,
    input wire req0_i,
    input wire req1_i,
    input wire [DATA_WIDTH-1:0] data0_i,
    input wire [DATA_WIDTH-1:0] data1_i,
    input wire [ID_WIDTH-1:0] id0_i,
    input wire [ID_WIDTH-1:0] id1_i,
    input wire gnt_i,
    output wire gnt0_o,
    output wire gnt1_o,
    output wire req_o,
    output wire [DATA_WIDTH-1:0] data_o,
    output wire [ID_WIDTH-1:0] id_o
);

    wire sel;

    // Request output logic
    assign req_o = req0_i | req1_i;

    // Channel selection logic
    assign sel = (req0_i & req1_i) ? RR_FLAG : req1_i;

    // Grant output logic
    assign gnt0_o = gnt_i & (sel == 1'b0) & req0_i;
    assign gnt1_o = gnt_i & (sel == 1'b1) & req1_i;

    // Data and ID output multiplexing
    assign data_o = sel ? data1_i : data0_i;
    assign id_o = sel ? id1_i : id0_i;

endmodule

