input wire [31:0] FP,
output reg [31:0] FPout,
output reg [31:0] M_ADDR,
inout reg [31:0] M_DATA,
inout reg M_RD,
inout reg M_WR,
input wire M_RDY,
input wire reset,
input wire CLK
);
parameter [2:0]
  ST_INIT = 0,
  WS_INIT = 1,
  ST_RESET = 2,
  ST00 = 3,
  WS00 = 4,
  ST_END = 5;
reg [2:0] Mstate;
  // CONTROL PROCESS --------
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      Mstate <= ST_RESET;
    end else begin
      case(Mstate)
      ST_RESET : begin
        Mstate <= ST_INIT;
      end
      ST_INIT : begin
        if(M_RDY == 1'b1) begin
          Mstate <= ST00;
        end
        else begin
          Mstate <= WS_INIT;
        end
      end
      WS_INIT : begin
        if(M_RDY == 1'b1) begin
          Mstate <= ST00;
        end
      end
      ST00,WS00,ST_END : begin
      end
      default : begin
      end
      endcase
    end
  end
  // EXECUTE PROCESS --------
  always @(posedge clk, posedge reset) begin : P1
    reg [31:0] T, s0, s1, s2, s3, s4, s5, s6, s7, fpi;
    if((reset == 1'b1)) begin
      // reset any internal states -- 
      s0 = {1{1'b0}};
      s1 = {1{1'b0}};
      s2 = {1{1'b0}};
      s3 = {1{1'b0}};
      s4 = {1{1'b0}};
      s5 = {1{1'b0}};
      s6 = {1{1'b0}};
      s7 = {1{1'b0}};
      fpi = {1{1'b0}};
      M_ADDR <= {32{1'bZ}};
      M_DATA <= {32{1'bZ}};
      M_RD <= 1'bZ;
      M_WR <= 1'bZ;
    end else begin
      M_DATA <= 32'bZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZ;
      case(Mstate)
      ST_INIT : begin
        // connect 3 input params here --
        s0 = i00;
        s1 = i01;
        s2 = i02;
        fpi = FP;
        //rsd2 ;
        T = s0;
        s0 = s1;
        s1 = T;
        //lit ;
        s7 = s6;
        s6 = s5;
        s5 = s4;
        s4 = s3;
        s3 = s2;
        s2 = s1;
        s1 = s0;
        s0 = 32;
        //sub ;
        s0 = s0 - s1;
        s1 = s2;
        s2 = s3;
        s3 = s4;
        s4 = s5;
        s5 = s6;
        s6 = s7;
        //lit ;
        s7 = s6;
        s6 = s5;
        s5 = s4;
        s4 = s3;
        s3 = s2;
        s2 = s1;
        s1 = s0;
        s0 = 32;
        // bl ### ignored ### ;
        // recover 3 results here --
        r00 <= s0;
        r01 <= s1;
        r02 <= s2;
        FPout <= fpi;
      end
      default : begin
      end
      endcase
    end
  end
endmodule

