module perf_counter (
    input wire clk,
    input wire rst,
    input wire strcnt,
    input wire stpcnt,
    input wire inc_instr,
    output reg [15:0] instr_cnt,
    output reg [15:0] cycle_cnt
);

    // FSM states
    localparam IDLE = 1'b0;
    localparam CNT  = 1'b1;

    reg state, next_state;
    reg clr_cnt, enb_cnt;

    // FSM state transitions
    always @(posedge clk or posedge rst) begin
        if (rst)
            state <= IDLE;
        else
            state <= next_state;
    end

    // FSM next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: if (strcnt) next_state = CNT;
            CNT:  if (stpcnt) next_state = IDLE;
        endcase
    end

    // FSM output logic
    always @(*) begin
        clr_cnt = 1'b0;
        enb_cnt = 1'b0;
        case (state)
            IDLE: if (strcnt) clr_cnt = 1'b1;
            CNT:  enb_cnt = 1'b1;
        endcase
    end

    // Instruction counter
    always @(posedge clk or posedge rst) begin
        if (rst)
            instr_cnt <= 16'b0;
        else if (clr_cnt)
            instr_cnt <= 16'b0;
        else if (enb_cnt && inc_instr)
            instr_cnt <= instr_cnt + 1'b1;
    end

    // Cycle counter
    always @(posedge clk or posedge rst) begin
        if (rst)
            cycle_cnt <= 16'b0;
        else if (clr_cnt)
            cycle_cnt <= 16'b0;
        else if (enb_cnt)
            cycle_cnt <= cycle_cnt + 1'b1;
    end

endmodule

module ID_EX_Register (
    input wire clk,
    input wire jump, MemToReg, MemToWrite, RegWrite, RegDst, Branch, MemRead, Alusrc,
    input wire [2:0] AluOp,
    input wire [31:0] Read_D1, Read_D2, Sign_Extend, PC_adder, shift_left,
    input wire [4:0] Ins_2016, Ins_1511,

    output reg IDEX_jump, IDEX_MemToReg, IDEX_MemToWrite, IDEX_RegWrite, IDEX_RegDst, IDEX_Branch, IDEX_MemRead, IDEX_Alusrc,
    output reg [2:0] IDEX_AluOp,
    output reg [31:0] IDEX_Read_D1, IDEX_Read_D2, IDEX_Sign_Extend, IDEX_PC_adder, IDEX_shift_left,
    output reg [4:0] IDEX_Ins_2016, IDEX_Ins_1511
);

    // Initialize all outputs to zero
    initial begin
        IDEX_jump = 0;
        IDEX_MemToReg = 0;
        IDEX_MemToWrite = 0;
        IDEX_RegWrite = 0;
        IDEX_RegDst = 0;
        IDEX_Branch = 0;
        IDEX_MemRead = 0;
        IDEX_Alusrc = 0;
        IDEX_AluOp = 3'b000;
        IDEX_Read_D1 = 32'b0;
        IDEX_Read_D2 = 32'b0;
        IDEX_Sign_Extend = 32'b0;
        IDEX_PC_adder = 32'b0;
        IDEX_shift_left = 32'b0;
        IDEX_Ins_2016 = 5'b0;
        IDEX_Ins_1511 = 5'b0;
    end

    // Update outputs on positive clock edge
    always @(posedge clk) begin
        IDEX_jump <= jump;
        IDEX_MemToReg <= MemToReg;
        IDEX_MemToWrite <= MemToWrite;
        IDEX_RegWrite <= RegWrite;
        IDEX_RegDst <= RegDst;
        IDEX_Branch <= Branch;
        IDEX_MemRead <= MemRead;
        IDEX_Alusrc <= Alusrc;
        IDEX_AluOp <= AluOp;
        IDEX_Read_D1 <= Read_D1;
        IDEX_Read_D2 <= Read_D2;
        IDEX_Sign_Extend <= Sign_Extend;
        IDEX_PC_adder <= PC_adder;
        IDEX_shift_left <= shift_left;
        IDEX_Ins_2016 <= Ins_2016;
        IDEX_Ins_1511 <= Ins_1511;
    end

endmodule

