module nueva_pos_rand_async(
input wire [2:0] up_pos,
input wire [2:0] dw_pos,
input wire [2:0] rg_pos,
input wire [2:0] lf_pos,
input wire [2:0] my_x,
input wire [2:0] my_y,
output wire [2:0] new_x,
output wire [2:0] new_y,
input wire [1:0] bt_rand
);
wire [1:0] rand_num;
reg [5:0] new_pos_in;
reg pos_valida;
wire [2:0] my_y_add1;
wire [2:0] my_x_add1;
wire [2:0] my_y_sub1;
wire [2:0] my_x_sub1;
  incrCuenta3bits Inst_incrCuenta3bits_x(
      .num_in(my_x),
    .num_out(my_x_add1));
  incrCuenta3bits Inst_incrCuenta3bits_y(
      .num_in(my_y),
    .num_out(my_y_add1));
  decrCuenta3bits Inst_decrCuenta3bits_x(
      .num_in(my_x),
    .num_out(my_x_sub1));
  decrCuenta3bits Inst_decrCuenta3bits_y(
      .num_in(my_y),
    .num_out(my_y_sub1));
  // Conexión de señales
  //-------------------------------------------------------
  assign rand_num = bt_rand;
  assign new_x = new_pos_in[2:0];
  assign new_y = new_pos_in[5:3];
  // Equivalencias entre los números aleatorios y la dirección de desplazamiento:
  // 00 -> Mueve hacia arriba
  // 01 -> Mueve hacia abajo
  // 10 -> Mueve hacia la derecha
  // 11 -> Mueve hacia la izquierda
  // ¿Es válida la dirección de desplazamiento aleatoria generada?
  //------------------------------------------------------
  always @(rand_num, up_pos, dw_pos, rg_pos, lf_pos) begin
    // Si me muevo hacia arriba y no hay pared:
    if(rand_num == 2'b00 && up_pos == 3'b000) begin
      pos_valida <= 1'b1;
      // Si me muevo hacia abajo y no hay pared:
    end
    else if(rand_num == 2'b01 && dw_pos == 3'b000) begin
      pos_valida <= 1'b1;
      // Si me muevo hacia la derecha y no hay pared:
    end
    else if(rand_num == 2'b10 && rg_pos == 3'b000) begin
      pos_valida <= 1'b1;
      // Si me muevo hacia la izquierda y no hay pared:
    end
    else if(rand_num == 2'b11 && lf_pos == 3'b000) begin
      pos_valida <= 1'b1;
      // En cualquier otro caso la dirección de desplazamiento no es válida:
    end
    else begin
      pos_valida <= 1'b0;
    end
  end
  // Traducimos el número aleatorio en la posicion equivalente dentro del mapa:
  //-------------------------------------------------------
  always @(rand_num, my_x, my_y, pos_valida, my_y_add1, my_y_sub1, my_x_add1, my_x_sub1) begin
    if(pos_valida == 1'b1) begin
      if(rand_num == 2'b00) begin
        //arriba
        new_pos_in <= {my_y_add1,my_x};
      end
      else if(rand_num == 2'b01) begin
        //abajo
        new_pos_in <= {my_y_sub1,my_x};
      end
      else if(rand_num == 2'b10) begin
        //der
        new_pos_in <= {my_y,my_x_add1};
      end
      else begin
        //izq
        new_pos_in <= {my_y,my_x_sub1};
      end
    end
    else begin
      new_pos_in <= {my_y,my_x};
      // Si no es valida nos mantenemos donde estamos.
    end
  end
endmodule

