        else if (ExMem_stall) begin
            // Maintain current values when stalled
        end
        else begin
            MEM_PC <= EX_PC;
            MEM_BranchAddr <= EX_BranchAddr;
            MEM_ALUout <= EX_ALUout;
            MEM_rdataA <= EX_rdataA;
            MEM_rdataB <= EX_rdataB;
            MEM_inst <= EX_inst;
            MEM_zero <= EX_zero;
            MEM_RegWrite <= EX_RegWrite;
            MEM_MemWrite <= EX_MemWrite;
            MEM_DataToReg <= EX_DataToReg;
            MEM_PCSrc <= EX_PCSrc;
            MEM_WriteAddr <= EX_WriteAddr;
        end
    end

