module Arith_Unit(
input wire [15:0] A,
input wire [15:0] B,
input wire [2:0] OP,
output wire [3:0] CCR,
output wire [15:0] RESULT
);
wire [16:0] a1 = 1'b0; wire [16:0] b1 = 1'b0;
reg [16:0] arith = 1'b0;
  // Give extra bit to accound for carry,overflow,negative
  assign a1 = {1'b0,A};
  assign b1 = {1'b0,B};
  always @(*) begin
    case(OP)
      3'b000 : arith <= a1 + b1;
  // ADD
      3'b001 : arith <= a1 - b1;
  // SUB
      3'b101 : arith <= a1 + b1;
  // ADDI
      default : arith <= a1 + b1;
    endcase
  end
  assign CCR[3] = arith[15];
  // Negative
  assign CCR[2] = arith[15:0] == 16'h0000 ? 1'b1 : 1'b0;
  // Zero
  assign CCR[1] = arith[16] ^ arith[15];
  // Overflow
  assign CCR[0] = arith[16];
  //Carry
  assign RESULT = arith[15:0];
endmodule

