module counter_top #(
    parameter COUNTER_VALUE_WIDTH = 20
)(
    input wire clk,
    input wire rst_n,
    input wire counter_en,
    input wire [COUNTER_VALUE_WIDTH-1:0] counter_value,
    output reg counter_over
);

    reg [COUNTER_VALUE_WIDTH-1:0] dff_out;
    reg [COUNTER_VALUE_WIDTH-1:0] dff_in;
    wire [COUNTER_VALUE_WIDTH-1:0] counter_out;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            dff_out <= {COUNTER_VALUE_WIDTH{1'b0}};
        end else begin
            dff_out <= dff_in;
        end
    end

    assign counter_out = dff_out + 1'b1;

    always @(*) begin
        if (!counter_en || (dff_out == counter_value)) begin
            dff_in = {COUNTER_VALUE_WIDTH{1'b0}};
        end else begin
            dff_in = counter_out;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter_over <= 1'b0;
        end else begin
            counter_over <= (dff_out == counter_value);
        end
    end

endmodule

