module counter #(
    parameter N = 8
) (
    input wire clk,
    input wire rst,
    input wire en,
    output reg [N-1:0] q
);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            q <= {N{1'b0}};
        end else if (en) begin
            q <= q + 1'b1;
        end
    end

endmodule

module configurable_shifter (
    input [7:0] A,
    input LA,
    input LR,
    output reg [7:0] Y,
    output reg C
);

always @(*) begin
    if (LA) begin
        // Arithmetic Right Shift
        Y = {A[7], A[7:1]};
        C = A[0];
    end
    else if (LR) begin
        // Logical Right Shift
        Y = {1'b0, A[7:1]};
        C = A[0];
    end
    else begin
        // Logical Left Shift
        Y = {A[6:0], 1'b0};
        C = A[7];
    end
end

endmodule

