module configurable_lfsr #(
    parameter N = 8,
    parameter [7:0] poly = 8'h9B
)(
    input wire i_clk,
    input wire i_rst_n,
    input wire i_count_en,
    input wire i_load,
    input wire [N-1:0] i_seed,
    output reg [N-1:0] o_lfsr
);

    wire feedback;

    assign feedback = o_lfsr[N-1];

    always @(posedge i_clk or negedge i_rst_n) begin
        if (!i_rst_n) begin
            o_lfsr <= {N{1'b0}};
        end else if (i_load) begin
            o_lfsr <= i_seed;
        end else if (i_count_en) begin
            o_lfsr <= {o_lfsr[N-2:0], 1'b0} ^ (feedback ? poly[N-1:0] : {N{1'b0}});
        end
    end

endmodule

module carry_lookahead_adder(
    input [3:0] a,
    input [3:0] b,
    input c,
    output [3:0] s,
    output cout
);

    wire [3:0] p, g, k;

    // Generate and propagate signals
    assign p = a ^ b;
    assign g = a & b;

    // Intermediate carry signals
    assign k[0] = c;
    assign k[1] = g[0] | (p[0] & c);
    assign k[2] = g[1] | (p[1] & g[0]) | (p[1] & p[0] & c);
    assign k[3] = g[2] | (p[2] & g[1]) | (p[2] & p[1] & g[0]) | (p[2] & p[1] & p[0] & c);

    // Output carry
    assign cout = g[3] | (p[3] & g[2]) | (p[3] & p[2] & g[1]) | (p[3] & p[2] & p[1] & g[0]) | (p[3] & p[2] & p[1] & p[0] & c);

    // Sum
    assign s = p ^ k;

endmodule

