module decoder_2to4_structural(
    input address0, address1, enable,
    output out0, out1, out2, out3
);
    wire not_address0, not_address1, not_enable;
    wire and_out0, and_out1, and_out2, and_out3;

    not #50 (not_address0, address0);
    not #50 (not_address1, address1);
    not #50 (not_enable, enable);

    and #50 (and_out0, not_address1, not_address0);
    and #50 (and_out1, not_address1, address0);
    and #50 (and_out2, address1, not_address0);
    and #50 (and_out3, address1, address0);

    and #50 (out0, and_out0, enable);
    and #50 (out1, and_out1, enable);
    and #50 (out2, and_out2, enable);
    and #50 (out3, and_out3, enable);
endmodule

