module PSR_Modifier(
input wire [31:0] oper1,
input wire [31:0] oper2,
input wire [5:0] aluop,
input wire [31:0] aluResult,
output reg [3:0] conditionalCodes
);
  always @(aluop, oper1, oper2, aluResult) begin
    if((aluop == 6'b010001 || aluop == 6'b010101 || aluop == 6'b010010 || aluop == 6'b010110 || aluop == 6'b010011 || aluop == 6'b010111)) begin
      // ANDcc,ANDNcc,ORcc,ORNcc,XORcc,XNORcc
      conditionalCodes[3] <= aluResult[31];
      //N
      if(aluResult == 32'b00000000000000000000000000000000) begin
        //Z
        conditionalCodes[2] <= 1'b1;
      end
      else begin
        conditionalCodes[2] <= 1'b0;
      end
      conditionalCodes[1] <= 1'b0;
      //V
      conditionalCodes[0] <= 1'b0;
      //C
    end
    else if((aluop == 6'b010000 || aluop == 6'b011000)) begin
      //ADDcc, ADDXcc
      conditionalCodes[3] <= aluResult[31];
      //N
      if(aluResult == 32'b00000000000000000000000000000000) begin
        //Z
        conditionalCodes[2] <= 1'b1;
      end
      else begin
        conditionalCodes[2] <= 1'b0;
      end
      conditionalCodes[1] <= (oper1[31] & oper2[31] & ( ~aluResult[31])) | (( ~oper1[31]) & ( ~oper2[31]) & aluResult[31]);
      conditionalCodes[0] <= (oper1[31] & oper2[31]) | (( ~aluResult[31]) & (oper1[31] | oper2[31]));
    end
    else if((aluop == 6'b010100 || aluop == 6'b011100)) begin
      //SUBcc, SUBXcc
      conditionalCodes[3] <= aluResult[31];
      //N
      if(aluResult == 32'b00000000000000000000000000000000) begin
        //Z
        conditionalCodes[2] <= 1'b1;
      end
      else begin
        conditionalCodes[2] <= 1'b0;
      end
      conditionalCodes[1] <= (oper1[31] & ( ~oper2[31]) & ( ~aluResult[31])) | (( ~oper1[31]) & oper2[31] & aluResult[31]);
      conditionalCodes[0] <= (( ~oper1[31]) & oper2[31]) | (aluResult[31] & (( ~oper1[31]) | oper2[31]));
    end
  end
endmodule

