module execute_stage(
input wire clk,
input wire reset_n,
input wire stall,
input wire [31:0] a_in,
input wire [31:0] b_in,
input wire [31:0] c_in,
input wire [31:0] da_in,
input wire [31:0] db_in,
input wire [31:0] next_pc,
input wire noop_in,
output reg [31:0] b_out,
output reg [31:0] c_out,
output reg [31:0] db_out,
output reg cbranch,
output reg noop_out
);
//signals
//components
  // c may change (check that it always has a value)
  // db always changes
  always @(posedge clk) begin
    if((reset_n == 1'b0)) begin
      //initial values
      noop_out <= 1'b1;
      cbranch <= 1'b0;
    end else begin
      if((stall == 1'b0)) begin
        // SUB
        db_out <= (db_in) - (da_in);
        // BLEQ --not testing the 'equal to zero' condition because that was done in the RD stage
        if((((db_in) - (da_in)) < 0 && noop_in == 1'b0 && !(c_in == next_pc))) begin
          cbranch <= 1'b1;
        end
        else begin
          cbranch <= 1'b0;
        end
        b_out <= b_in;
        c_out <= c_in;
        noop_out <= noop_in;
      end
      else begin
        //hold previous outputs on stall (automatic)
      end
    end
  end
endmodule

