module seven_segment_display(
input wire clk,
input wire [15:0] data_in,
input wire [3:0] dp_in,
input wire [3:0] blank,
output reg [6:0] seg,
output reg dp,
output reg [3:0] an
);
parameter [31:0] COUNTER_BITS=15;
//Indicates number of bits on segment counter to count up to (determines speed)
//Data to display
//Value of 4 decimal points
//Tells which digits are blank
//Segment control signals
//Digit point control signal
//Segment anode control signals
reg [COUNTER_BITS - 1:0] counter_value = 1'b0;  //sets the initial value to 0
wire [1:0] anode_select;
reg [3:0] decode;
  always @(posedge clk) begin
    counter_value <= (counter_value) + 1;
  end
  assign anode_select = counter_value[COUNTER_BITS - 1:COUNTER_BITS - 2];
  always @(*) begin
    case(anode_select)
      2'b00 : an <= {3'b111,blank[0]};
  //Determines when the display should be blank (1 is blank)
      2'b01 : an <= {2'b11,blank[1],1'b1};
      2'b10 : an <= {1'b1,blank[2],2'b11};
      default : an <= {blank[3],3'b111};
    endcase
  end
  always @(*) begin
    case(anode_select)
  //Determines which data set to send to the seven segment decoder
      2'b00 : decode <= data_in[3:0];
      2'b01 : decode <= data_in[7:4];
      2'b10 : decode <= data_in[11:8];
      default : decode <= data_in[15:12];
    endcase
  end
  always @(*) begin
    case(anode_select)
  //Determines which decimal point to light up
      2'b00 : dp <=  ~dp_in[0];
      2'b01 : dp <=  ~dp_in[1];
      2'b10 : dp <=  ~dp_in[2];
      default : dp <=  ~dp_in[3];
    endcase
  end
  always @(*) begin
    case(decode)
  //determines which parts to light up
      4'b0000 : seg <= 7'b1000000;
  // 0
      4'b0001 : seg <= 7'b1111001;
  // 1
      4'b0010 : seg <= 7'b0100100;
  // 2
      4'b0011 : seg <= 7'b0110000;
  // 3
      4'b0100 : seg <= 7'b0011001;
  // 4
      4'b0101 : seg <= 7'b0010010;
  // 5
      4'b0110 : seg <= 7'b0000010;
  // 6
      4'b0111 : seg <= 7'b1111000;
  // 7
      4'b1000 : seg <= 7'b0000000;
  // 8
      4'b1001 : seg <= 7'b0010000;
  // 9
      4'b1010 : seg <= 7'b0001000;
  // A
      4'b1011 : seg <= 7'b0000011;
  // B
      4'b1100 : seg <= 7'b1000110;
  // C
      4'b1101 : seg <= 7'b0100001;
  // D
      4'b1110 : seg <= 7'b0000110;
  // E
      default : seg <= 7'b0001110;
    endcase
  end
    // F
endmodule

module register_file (
    input wire clk,
    input wire [3:0] ra1, ra2, wa3,
    input wire we3,
    input wire [31:0] wd3, r15,
    output wire [31:0] rd1, rd2
);

    reg [31:0] registers [0:14];
    integer i;

    // Initialize registers to zero
    initial begin
        for (i = 0; i < 15; i = i + 1) begin
            registers[i] = 32'b0;
        end
    end

    // Write operation
    always @(posedge clk) begin
        if (we3 && wa3 != 4'b1111) begin
            registers[wa3] <= wd3;
        end
    end

    // Read operation for port 1
    assign rd1 = (ra1 == 4'b1111) ? r15 : registers[ra1];

    // Read operation for port 2
    assign rd2 = (ra2 == 4'b1111) ? r15 : registers[ra2];

endmodule

module ALU(
input wire [31:0] a,
input wire [31:0] b,
input wire [2:0] alucontrol,
output reg zero,
output reg [31:0] result
);
  always @(a, b, alucontrol) begin : P1
    reg [31:0] temp;
    case(alucontrol)
    3'b000 : begin
      temp = a & b;
    end
    3'b001 : begin
      temp = a | b;
    end
    3'b010 : begin
      temp = (a) + (b);
    end
    3'b011 : begin
      temp = 32'bUUUUUUUUUUUUUUUUUUUUUUUUUUUUUUUU;
    end
    3'b100 : begin
      temp = a & ( ~b);
    end
    3'b101 : begin
      temp = a | ( ~b);
    end
    3'b110 : begin
      temp = (a) - (b);
    end
    3'b111 : begin
      if(a < b) begin
        temp = 32'h00000001;
      end
      else begin
        temp = 32'h00000000;
      end
    end
    default : begin
      temp = 32'bUUUUUUUUUUUUUUUUUUUUUUUUUUUUUUUU;
    end
    endcase
    result <= temp;
    if(temp == 32'h00000000) begin
      zero <= 1'b1;
    end
    else if(temp == 32'h00000001) begin
      zero <= 1'b0;
    end
  end
endmodule

