module regenerate_ctrl_signal (
    input wire CLK_IN,
    input wire RST_IN,
    input wire [7:0] NSTEP1,
    input wire [7:0] NSTEP2,
    input wire CNVCLK_IN,
    output reg CLK2M_OUT,
    output reg RST2M_OUT,
    output reg CNVCLK_OUT
);

    // CLK2M Generation
    reg [7:0] cnt;
    reg [7:0] int_cnt;

    always @(posedge CLK_IN or posedge RST_IN) begin
        if (RST_IN) begin
            cnt <= 8'd0;
            int_cnt <= 8'd0;
            CLK2M_OUT <= 1'b0;
        end else begin
            if (int_cnt < NSTEP1) begin
                int_cnt <= int_cnt + 1'b1;
            end else begin
                if (cnt < 8'd49) begin
                    cnt <= cnt + 1'b1;
                end else begin
                    cnt <= 8'd0;
                end
                CLK2M_OUT <= (cnt < 8'd25) ? 1'b1 : 1'b0;
            end
        end
    end

    // Reset Signal Generation
    reg [7:0] rst_cnt;
    reg [7:0] rst_int_cnt;

    always @(posedge CLK_IN or posedge RST_IN) begin
        if (RST_IN) begin
            rst_cnt <= 8'd0;
            rst_int_cnt <= 8'd0;
            RST2M_OUT <= 1'b1;
        end else begin
            if (rst_int_cnt < NSTEP1) begin
                rst_int_cnt <= rst_int_cnt + 1'b1;
            end else begin
                if (rst_cnt < 8'd250) begin
                    rst_cnt <= rst_cnt + 1'b1;
                    RST2M_OUT <= 1'b1;
                end else begin
                    RST2M_OUT <= 1'b0;
                end
            end
        end
    end

    // CNVCLK Signal Processing
    reg [2:0] cnvclk_sync;
    reg [7:0] cnvclk_cnt;

    always @(posedge CLK_IN or posedge RST_IN) begin
        if (RST_IN) begin
            cnvclk_sync <= 3'b000;
            cnvclk_cnt <= 8'd0;
            CNVCLK_OUT <= 1'b0;
        end else begin
            cnvclk_sync <= {cnvclk_sync[1:0], CNVCLK_IN};

            if (cnvclk_sync[1] && !cnvclk_sync[2]) begin
                cnvclk_cnt <= NSTEP2;
            end else if (cnvclk_cnt > 8'd0) begin
                cnvclk_cnt <= cnvclk_cnt - 1'b1;
            end

            CNVCLK_OUT <= cnvclk_sync[1] || (cnvclk_cnt > 8'd0);
        end
    end

endmodule

module IniciarCrono(
    input wire clock,
    input wire reset,
    input wire enc,
    input wire inic,
    input wire format,
    input wire lock,
    input wire fin,
    output reg ad,
    output reg wr,
    output reg cs,
    output reg rd,
    output reg [7:0] ADout
);

    reg [5:0] cont;
    reg enc_prev;

    always @(posedge clock or posedge reset) begin
        if (reset) begin
            ad <= 1'b1;
            wr <= 1'b1;
            cs <= 1'b1;
            rd <= 1'b1;
            ADout <= 8'hFF;
            cont <= 6'd0;
            enc_prev <= 1'b0;
        end else begin
            enc_prev <= enc;

            if (enc && !enc_prev) begin
                cont <= 6'd1;
            end else if (cont > 6'd0) begin
                cont <= cont + 1'b1;

                case (cont)
                    6'd1: begin
                        ad <= 1'b0;
                        wr <= 1'b1;
                        cs <= 1'b1;
                        rd <= 1'b1;
                        ADout <= 8'hFF;
                    end
                    6'd2: cs <= 1'b0;
                    6'd3: wr <= 1'b0;
                    6'd4: ADout <= 8'h00;
                    6'd5: wr <= 1'b1;
                    6'd6: cs <= 1'b1;
                    6'd7: ad <= 1'b1;

                    6'd16: ad <= 1'b0;
                    6'd17: cs <= 1'b0;
                    6'd18: wr <= 1'b0;
                    6'd19: begin
                        ADout[7:6] <= 2'b00;
                        ADout[5] <= lock;
                        ADout[4] <= format;
                        ADout[3] <= inic | fin;
                        ADout[2:0] <= 3'b000;
                    end
                    6'd20: wr <= 1'b1;
                    6'd21: cs <= 1'b1;
                    6'd22: ad <= 1'b1;

                    6'd33: cont <= 6'd0;

                    default: begin
                        ad <= 1'b1;
                        wr <= 1'b1;
                        cs <= 1'b1;
                        rd <= 1'b1;
                        ADout <= 8'hFF;
                    end
                endcase
            end else begin
                ad <= 1'b1;
                wr <= 1'b1;
                cs <= 1'b1;
                rd <= 1'b1;
                ADout <= 8'hFF;
            end
        end
    end

endmodule

