module led_FSM (
    input wire clk,
    input wire rst_n,
    input wire key_flag,
    input wire key_state,
    input wire flash_done,
    output reg [5:0] times,
    output reg mode,
    output reg en
);

    // State encoding
    localparam IDLE = 3'd0,
               KEY_PRESSED = 3'd1,
               SHORT_PRESS = 3'd2,
               MEDIUM_PRESS = 3'd3,
               LONG_PRESS = 3'd4;

    reg [2:0] state, next_state;
    reg [29:0] cnt;
    reg key_state_r, key_state_rr;
    wire key_negedge, key_posedge;

    // Edge detection
    assign key_negedge = key_state_rr & ~key_state_r;
    assign key_posedge = ~key_state_rr & key_state_r;

    // State register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Key state registers for edge detection
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            key_state_r <= 1'b1;
            key_state_rr <= 1'b1;
        end else begin
            key_state_r <= key_state;
            key_state_rr <= key_state_r;
        end
    end

    // Counter
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            cnt <= 30'd0;
        else if (state != KEY_PRESSED)
            cnt <= 30'd0;
        else
            cnt <= cnt + 1'b1;
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            IDLE:
                if (key_negedge)
                    next_state = KEY_PRESSED;
            KEY_PRESSED:
                if (key_posedge) begin
                    if (cnt < 30'd50_000_000)
                        next_state = SHORT_PRESS;
                    else if (cnt < 30'd100_000_000)
                        next_state = MEDIUM_PRESS;
                    else
                        next_state = LONG_PRESS;
                end
            SHORT_PRESS, MEDIUM_PRESS, LONG_PRESS:
                if (flash_done)
                    next_state = IDLE;
        endcase
    end

    // Output logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            times <= 6'd0;
            mode <= 1'b0;
            en <= 1'b0;
        end else begin
            case (next_state)
                IDLE: begin
                    times <= 6'd0;
                    mode <= 1'b0;
                    en <= 1'b0;
                end
                SHORT_PRESS: begin
                    times <= 6'd5;
                    mode <= 1'b0;
                    en <= 1'b1;
                end
                MEDIUM_PRESS: begin
                    times <= 6'd10;
                    mode <= 1'b0;
                    en <= 1'b1;
                end
                LONG_PRESS: begin
                    times <= 6'd20;
                    mode <= 1'b1;
                    en <= 1'b1;
                end
                default: begin
                    times <= times;
                    mode <= mode;
                    en <= en;
                end
            endcase
        end
    end

endmodule

