module AdderSub(
input wire mode,
input wire [3:0] X,
input wire [3:0] Y,
output wire [3:0] S,
output wire COUT_ADDERSUB
);
// ou seja, CIN e seletor do modo
wire C1; wire C2; wire C3; wire C4;  //Carries intermediários
wire X0_XOR; wire X1_XOR; wire X2_XOR; wire X3_XOR;
  assign X0_XOR = Y[0] ^ mode;
  assign X1_XOR = Y[1] ^ mode;
  assign X2_XOR = Y[2] ^ mode;
  assign X3_XOR = Y[3] ^ mode;
  fulladder FA0(
      X[0],
    X0_XOR,
    mode,
    S[0],
    C1);
  // S0
  fulladder FA1(
      X[1],
    X1_XOR,
    C1,
    S[1],
    C2);
  // S1
  fulladder FA2(
      X[2],
    X2_XOR,
    C2,
    S[2],
    C3);
  // S2
  fulladder FA3(
      X[3],
    X3_XOR,
    C3,
    S[3],
    C4);
  // S3
  assign COUT_ADDERSUB = C3 ^ C4;
endmodule

