module comparator(
input wire [3:0] A,
input wire [3:0] B,
input wire [2:0] op,
input wire zero,
input wire cout,
input wire overflow,
input wire [3:0] diff,
output wire R
);
//signals
wire a_GEQ_b_SIGNED_R = 1'b0;
wire a_LE_b_SIGNED_R = 1'b0;
wire a_NEQ_b_UNSIGNED_R = 1'b0;
wire a_EQ_b_UNSIGNED_R = 1'b0;
wire a_GEQ_b_UNSIGNED_R = 1'b0;
wire a_LE_b_UNSIGNED_R = 1'b0;
wire [3:0] s;
  //-----------------------------------------
  //SIGNED PORTIONS
  //-----------------------------------------
  //SIGNED is a bit more tricky. However, we can take 
  //advantage of the overflow flag and arrive at the 
  //following conclusions:
  //(thanks to: http://teahlab.com/4-Bit_Signed_Comparator/)
  // X = Y <--> zero
  // X < Y <--> diff(3) XOR overflow
  // X > Y <--> !( zero OR ( diff(3) XOR overflow) )
  //GEQ SIGNED
  assign a_GEQ_b_SIGNED_R =  ~(zero | (diff[3] ^ overflow)) | zero;
  //LE SIGNED
  assign a_LE_b_SIGNED_R = diff[3] ^ overflow;
  //-----------------------------------------
  //UNSIGNED PORTIONS
  //-----------------------------------------
  //EQ/NEQ
  //well, *that* was easy :D
  assign a_NEQ_b_UNSIGNED_R =  ~(zero);
  assign a_EQ_b_UNSIGNED_R = zero;
  //GEQ UNSIGNED
  //Well, it turns out unsigned is harder. I'm way behind and 
  //so close to being done, so I'm borrowing some code from here
  //to make sure the tests all work:
  //http://sid-vlsiarena.blogspot.com/2013/03/4-bit-magnitude-comparator-vhdl-code.html
  //I'll have to explain the karnaugh map theory behind it later in the report.
  assign s[0] =  ~(a[0] ^ b[0]);
  assign s[1] =  ~(a[1] ^ b[1]);
  assign s[2] =  ~(a[2] ^ b[2]);
  assign s[3] =  ~(a[3] ^ b[3]);
  assign a_GEQ_b_UNSIGNED_R = (a[3] & ( ~b[3])) | (s[3] & a[2] & ( ~b[2])) | (s[3] & s[2] & a[1] & ( ~b[1])) | (s[3] & s[2] & s[1] & a[0] & ( ~b[0])) | zero;
  //LE UNSIGNED
  assign a_LE_b_UNSIGNED_R = (b[3] & ( ~a[3])) | (s[3] & b[2] & ( ~a[2])) | (s[3] & s[2] & b[1] & ( ~a[1])) | (s[3] & s[2] & s[1] & b[0] & ( ~a[0]));
  //-----------------------------------------
  //select output based on opcode
  //-----------------------------------------
  mux8_bit output(
      /* open */,
    a_GEQ_b_SIGNED_R,
    a_LE_B_SIGNED_R,
    a_NEQ_b_UNSIGNED_R,
    a_EQ_b_UNSIGNED_R,
    a_GEQ_b_UNSIGNED_R,
    a_LE_b_UNSIGNED_R,
    /* open */,
    op,
    R);
endmodule

