module HB_FULL_LED (
    input wire RESETN,
    input wire CLK,
    input wire [1:0] R_IN,
    input wire [1:0] G_IN,
    input wire [1:0] B_IN,
    output reg [3:0] R,
    output reg [3:0] G,
    output reg [3:0] B
);

    integer CNT;
    reg [1:0] R_REG, G_REG, B_REG;

    always @(posedge CLK or posedge RESETN) begin
        if (RESETN) begin
            R <= 4'b0000;
            CNT <= 0;
        end else begin
            if (CNT < R_REG)
                R <= 4'b1111;
            else
                R <= 4'b0000;

            if (CNT == 3)
                CNT <= 0;
            else
                CNT <= CNT + 1;
        end
    end

    always @(posedge CLK or posedge RESETN) begin
        if (RESETN)
            G <= 4'b0000;
        else begin
            if (CNT < G_REG)
                G <= 4'b1111;
            else
                G <= 4'b0000;
        end
    end

    always @(posedge CLK or posedge RESETN) begin
        if (RESETN)
            B <= 4'b0000;
        else begin
            if (CNT < B_REG)
                B <= 4'b1111;
            else
                B <= 4'b0000;
        end
    end

    always @(posedge CLK) begin
        R_REG <= R_IN;
        G_REG <= G_IN;
        B_REG <= B_IN;
    end

endmodule

