);

    reg [25:0] cnt;

    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            cnt <= 26'd0;
            tick <= 1'b0;
        end else begin
            if (cnt == 26'd33554431) begin
                cnt <= 26'd0;
                tick <= ~tick;
