module arbiter_output_control (
    input wire clk,
    input wire reset,
    input wire polarity,
    input wire send0,
    input wire send1,
    input wire ready_out,
    output reg ready0,
    output reg ready1,
    output reg send_out,
    output reg buffer_enable_even,
    output reg buffer_enable_odd,
    output reg cap_mux
);

    // State encoding
    localparam ARBITRATION = 2'b00;
    localparam SEND0_GRANT = 2'b01;
    localparam SEND1_GRANT = 2'b10;
    localparam IDLE = 2'b11;

    reg [1:0] state, next_state;
    reg [1:0] odd_even_full;
    reg last_grant;

    // State transition and output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            odd_even_full <= 2'b00;
            last_grant <= 1'b0;
            send_out <= 1'b0;
        end else begin
            state <= next_state;

            case (state)
                ARBITRATION: begin
                    if (send0 && send1) begin
                        if (last_grant == 1'b0 || polarity == 1'b1) begin
                            next_state <= SEND0_GRANT;
                            last_grant <= 1'b0;
                        end else begin
                            next_state <= SEND1_GRANT;
                            last_grant <= 1'b1;
                        end
                    end else if (send0) begin
                        next_state <= SEND0_GRANT;
                        last_grant <= 1'b0;
                    end else if (send1) begin
                        next_state <= SEND1_GRANT;
                        last_grant <= 1'b1;
                    end else begin
                        next_state <= IDLE;
                    end
                end

                SEND0_GRANT, SEND1_GRANT: begin
                    if (ready_out) begin
                        odd_even_full[polarity] <= 1'b1;
                        next_state <= ARBITRATION;
                    end else begin
                        next_state <= state;
                    end
                end

                IDLE: begin
                    if (send0 || send1) begin
                        next_state <= ARBITRATION;
                    end else begin
                        next_state <= IDLE;
                    end
                end
            endcase

            send_out <= ready_out && odd_even_full[~polarity];
            if (send_out) begin
                odd_even_full[~polarity] <= 1'b0;
            end
        end
    end

    // Combinational logic for buffer enable and mux control
    always @(*) begin
        ready0 = (state == SEND0_GRANT) && !odd_even_full[polarity];
        ready1 = (state == SEND1_GRANT) && !odd_even_full[polarity];
        buffer_enable_even = (state == SEND0_GRANT || state == SEND1_GRANT) && (polarity == 1'b0) && ready_out;
        buffer_enable_odd = (state == SEND0_GRANT || state == SEND1_GRANT) && (polarity == 1'b1) && ready_out;
        cap_mux = (state == SEND1_GRANT);
    end

endmodule

module MUL_ctrlpath (
    input wire clk,
    input wire eqz,
    input wire start,
    output reg LdA,
    output reg LdB,
    output reg LdP,
    output reg clrP,
    output reg decB,
    output reg done
);

    // State encoding
    parameter S0 = 3'b000,
              S1 = 3'b001,
              S2 = 3'b010,
              S3 = 3'b011,
              S4 = 3'b100;

    reg [2:0] state, next_state;

    // State transition logic
    always @(posedge clk) begin
        #1 state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (state)
            S0: next_state = start ? S1 : S0;
            S1: next_state = S2;
            S2: next_state = S3;
            S3: #2 next_state = eqz ? S4 : S3;
            S4: next_state = S4;
            default: next_state = S0;
        endcase
    end

    // Output logic
    always @(*) begin
        // Default output values
        LdA = 1'b0;
        LdB = 1'b0;
        LdP = 1'b0;
        clrP = 1'b0;
        decB = 1'b0;
        done = 1'b0;

        case (state)
            S1: LdA = 1'b1;
            S2: begin
                LdB = 1'b1;
                clrP = 1'b1;
            end
            S3: begin
                LdP = 1'b1;
                decB = 1'b1;
            end
            S4: done = 1'b1;
        endcase
    end

endmodule

