module UART_TX_CTRL(
input wire SEND,
input wire [7:0] DATA,
input wire CLK,
output wire READY,
output wire UART_TX
);
parameter [1:0]
  RDY = 0,
  LOAD_BIT = 1,
  SEND_BIT = 2;
parameter BIT_TMR_MAX = 14'b10100010110000;  //10416 = (round(100MHz / 9600)) - 1
parameter BIT_INDEX_MAX = 10;  //Counter that keeps track of the number of clock cycles the current bit has been held stable over the
//UART TX line. It is used to signal when the ne
reg [13:0] bitTmr = 1'b0;  //combinatorial logic that goes high when bitTmr has counted to the proper value to ensure
//a 9600 baud rate
wire bitDone;  //Contains the index of the next bit in txData that needs to be transferred 
reg [31:0] bitIndex;  //a register that holds the current data being sent over the UART TX line
reg txBit = 1'b1;  //A register that contains the whole data packet to be sent, including start and stop bits. 
reg [9:0] txData;
reg [1:0] txState = RDY;
  //Next state logic
  always @(posedge CLK) begin
    case(txState)
    RDY : begin
      if((SEND == 1'b1)) begin
        txState <= LOAD_BIT;
      end
    end
    LOAD_BIT : begin
      txState <= SEND_BIT;
      //pragma synthesis_off
      //txState <= RDY;
      //pragma synthesis_on
    end
    SEND_BIT : begin
      if((bitDone == 1'b1)) begin
        if((bitIndex == BIT_INDEX_MAX)) begin
          txState <= RDY;
        end
        else begin
          txState <= LOAD_BIT;
        end
      end
    end
    default : begin
      //should never be reached
      txState <= RDY;
    end
    endcase
  end
  always @(posedge CLK) begin
    if((txState == RDY)) begin
      bitTmr <= {14{1'b0}};
    end
    else begin
      if((bitDone == 1'b1)) begin
        bitTmr <= {14{1'b0}};
      end
      else begin
        bitTmr <= bitTmr + 1;
      end
    end
  end
  assign bitDone = (bitTmr == BIT_TMR_MAX) ? 1'b1 : 1'b0;
  always @(posedge CLK) begin
    if((txState == RDY)) begin
      bitIndex <= 0;
    end
    else if((txState == LOAD_BIT)) begin
      bitIndex <= bitIndex + 1;
    end
  end
  always @(posedge CLK) begin
    if((SEND == 1'b1)) begin
      txData <= {1'b1,DATA,1'b0};
    end
  end
  always @(posedge CLK) begin
    if((txState == RDY)) begin
      txBit <= 1'b1;
    end
    else if((txState == LOAD_BIT)) begin
      txBit <= txData[bitIndex];
    end
  end
  assign UART_TX = txBit;
  assign READY = (txState == RDY) ? 1'b1 : 1'b0;
endmodule

module pc_update_adder(
    input wire signed [31:0] current_pc,
    input wire CLK,
    input wire RESET,
    input wire dobranch,
    input wire isjump,
    input wire dobne,
    input wire signed [7:0] offset,
    input wire busywait,
    output reg signed [31:0] updated_pc
);

    wire signed [31:0] default_pc, branch_add, sign_extended_offset, multiplied_offset;

    // Default PC update
    assign default_pc = current_pc + 32'd4;

    // Sign extension
    sign_extend se(
        .in(offset),
        .out(sign_extended_offset)
    );

    // Multiply by 4
    multiply_4 m4(
        .in(sign_extended_offset),
        .out(multiplied_offset)
    );

    // Calculate branch address
    new_adder na(
        .in1(default_pc),
        .in2(multiplied_offset),
        .out(branch_add)
    );

    // PC update logic
    always @(posedge CLK) begin
        if (RESET) begin
            #1 updated_pc <= -32'd4;
        end
        else if (!busywait) begin
            if (dobranch | isjump | dobne) begin
                #1 updated_pc <= branch_add;
            end
            else begin
                #1 updated_pc <= default_pc;
            end
        end
    end

endmodule

// Sign extension module
module sign_extend(
    input wire [7:0] in,
    output wire [31:0] out
);
    assign out = {{24{in[7]}}, in};
endmodule

// Multiply by 4 module
module multiply_4(
    input wire [31:0] in,
    output wire [31:0] out
);
    assign out = in << 2;
endmodule

// Adder module
module new_adder(
    input wire [31:0] in1,
    input wire [31:0] in2,
    output wire [31:0] out
);
    assign out = in1 + in2;
