module finiteStateMachine(
    input [1:0] trafficlight,
    input clk,
    output reg driving,
    output reg stopped,
    output reg braking
);

    // State definitions
    localparam Green = 2'b00;
    localparam Yellow = 2'b01;
    localparam Red = 2'b10;

    // State register
    reg [1:0] state;

    // State transition and output logic
    always @(posedge clk) begin
        // State transition
        state <= trafficlight;

        // Output logic
        case (state)
            Green: begin
                driving <= 1'b1;
                braking <= 1'b0;
                stopped <= 1'b0;
            end
            Yellow: begin
                driving <= 1'b0;
                braking <= 1'b1;
                stopped <= 1'b0;
            end
            Red: begin
                driving <= 1'b0;
                braking <= 1'b0;
                stopped <= 1'b1;
            end
            default: begin
                driving <= 1'b0;
                braking <= 1'b0;
                stopped <= 1'b0;
            end
        endcase
    end

endmodule

module cerrojoElectronico(
input wire intro,
input wire [7:0] switch,
input wire clk,
input wire rst,
output wire [7:0] segs,
output reg lock
);
// Entradas
// Boton para confirmar la introduccion de clave
// Switches para escribir la clave
// Reloj
// Reset
// Salidas
// Display 8-Segmentos para visualizar numero de intentos restantes
// Encederemos el primer LED para indicar que esta LOCK
// CERROJO ELECTRONICO
wire xDebounced; wire xDebRiseEdge; wire xDebFallingEdge;
reg load;
reg [7:0] salidaRegistro;
wire [7:0] rightSeg;  // MAQUINA DE ESTADOS
parameter [2:0]
  INICIAL = 0,
  S0 = 1,
  S1 = 2,
  S2 = 3,
  S3 = 4;
reg [2:0] ESTADO; reg [2:0] SIG_ESTADO;
reg [3:0] st;  //
wire [7:0] clave;
  assign segs = rightSeg;
  assign clave = switch;
  debouncer button(
      rst,
    clk,
    intro,
    xDebounced,
    xDebFallingEdge,
    xDebRiseEdge);
  always @(posedge clk, posedge rst) begin
      // Los Push Buttons, como los Switches, tienen logica negativa, es decir, es al reves.
    if(rst == 1'b0) begin
      salidaRegistro <= {8{1'b0}};
    end else begin
      if(load == 1'b1) begin
        salidaRegistro <= switch;
      end
    end
  end
  // MAQUINA ESTADOS: SINCRONO
  always @(posedge clk, posedge rst) begin
    if(rst == 1'b0) begin
      ESTADO <= INICIAL;
    end else begin
      ESTADO <= SIG_ESTADO;
    end
  end
  // MAQUINA ESTADOS: COMBINACIONAL
  always @(ESTADO, rst, xDebFallingEdge, salidaRegistro, clave) begin
    SIG_ESTADO <= ESTADO;
    load <= 1'b0;
    lock <= 1'b1;
    case(ESTADO)
    INICIAL : begin
      lock <= 1'b0;
      st <= 4'b1010;
      if(xDebFallingEdge == 1'b1) begin
        load <= 1'b1;
        SIG_ESTADO <= S3;
      end
    end
    S3 : begin
      st <= 4'b0011;
      if(xDebFallingEdge == 1'b1 && (salidaRegistro == clave)) begin
        SIG_ESTADO <= INICIAL;
      end
      else if(xDebFallingEdge == 1'b1 && (salidaRegistro != clave)) begin
        SIG_ESTADO <= S2;
      end
    end
    S2 : begin
      st <= 4'b0010;
      if(xDebFallingEdge == 1'b1 && (salidaRegistro == clave)) begin
        SIG_ESTADO <= INICIAL;
      end
      else if(xDebFallingEdge == 1'b1 && (salidaRegistro != clave)) begin
        SIG_ESTADO <= S1;
      end
    end
    S1 : begin
      st <= 4'b0001;
      if(xDebFallingEdge == 1'b1 && (salidaRegistro == clave)) begin
        SIG_ESTADO <= INICIAL;
      end
      else if(xDebFallingEdge == 1'b1 && (salidaRegistro != clave)) begin
        SIG_ESTADO <= S0;
      end
    end
    S0 : begin
      st <= 4'b0000;
    end
    endcase
  end
  binToSeg displayCuenta(
      st,
    rightSeg);
endmodule

