module Renderer(
    input [9:0] ycoord, xcoord,
    input nocolor,
    input p1x, p1y, p2x, p2y,
    output reg [3:0] red, blue, green
);

    wire top_left, top_right, bottom_left, bottom_right;

    assign top_left = (xcoord <= 320) && (ycoord <= 240);
    assign top_right = (xcoord > 320) && (ycoord <= 240);
    assign bottom_left = (xcoord <= 320) && (ycoord > 240);
    assign bottom_right = (xcoord > 320) && (ycoord > 240);

    always @(*) begin
        if (nocolor) begin
            red = 4'b0000;
            blue = 4'b0000;
            green = 4'b0000;
        end else begin
            green = 4'b0000;

            if ((p1x == 0 && p1y == 0 && top_left) ||
                (p1x == 1 && p1y == 0 && top_right) ||
                (p1x == 0 && p1y == 1 && bottom_left) ||
                (p1x == 1 && p1y == 1 && bottom_right)) begin
                red = 4'b1111;
            end else begin
                red = 4'b0000;
            end

            if ((p2x == 0 && p2y == 0 && top_left) ||
                (p2x == 1 && p2y == 0 && top_right) ||
                (p2x == 0 && p2y == 1 && bottom_left) ||
                (p2x == 1 && p2y == 1 && bottom_right)) begin
                blue = 4'b1111;
            end else begin
                blue = 4'b0000;
            end
        end
    end

endmodule

