module vga_controller #(
    parameter HT  = 800,  // Total horizontal pixels
    parameter HD  = 640,  // Horizontal display pixels
    parameter HF  = 16,   // Horizontal front porch
    parameter HS  = 96,   // Horizontal sync pulse
    parameter VT  = 525,  // Total vertical lines
    parameter VD  = 480,  // Vertical display lines
    parameter VF  = 10,   // Vertical front porch
    parameter VS  = 2     // Vertical sync pulse
)(
    input  wire        vga_pclk,
    input  wire        vga_rst,
    output wire        vga_hsync,
    output wire        vga_vsync,
    output wire        vga_valid,
    output wire [11:0] vga_h_cnt,
    output wire [10:0] vga_v_cnt
);

reg [11:0] pixel_cnt;
reg [10:0] line_cnt;
reg hsync, vsync;

always @(posedge vga_pclk or posedge vga_rst) begin
    if (vga_rst) begin
        pixel_cnt <= 12'd0;
        line_cnt <= 11'd0;
        hsync <= 1'b1;
        vsync <= 1'b1;
    end else begin
        // Pixel counter
        if (pixel_cnt == HT - 1) begin
            pixel_cnt <= 12'd0;
            if (line_cnt == VT - 1)
                line_cnt <= 11'd0;
            else
                line_cnt <= line_cnt + 11'd1;
        end else begin
            pixel_cnt <= pixel_cnt + 12'd1;
        end

        // Horizontal sync
        if (pixel_cnt == HD + HF - 1)
            hsync <= 1'b0;
        else if (pixel_cnt == HD + HF + HS - 1)
            hsync <= 1'b1;

        // Vertical sync
        if (line_cnt == VD + VF - 1)
            vsync <= 1'b0;
        else if (line_cnt == VD + VF + VS - 1)
            vsync <= 1'b1;
    end
end

// Output assignments
assign vga_hsync = hsync;
assign vga_vsync = vsync;
assign vga_valid = (pixel_cnt < HD) && (line_cnt < VD);
assign vga_h_cnt = vga_valid ? pixel_cnt : 12'd0;
assign vga_v_cnt = vga_valid ? line_cnt : 11'd0;

endmodule

