module imx51_wb16_wrapper(
inout wire [15:0] imx_da,
input wire imx_cs_n,
input wire imx_rw,
input wire imx_adv,
input wire gls_reset,
input wire gls_clk,
output wire wbm_clk,
output wire wbm_rst,
output wire [15:0] wbm_address,
input wire [15:0] wbm_readdata,
output wire [15:0] wbm_writedata,
output wire wbm_strobe,
output wire wbm_write,
input wire wbm_ack,
output wire wbm_cycle
);
// i.MX Signals
// Global Signals
// Wishbone interface signals
// Address bus
// Data bus for read access
// Data bus for write access
// Data Strobe
// Write access
// acknowledge
// bus cycle in progress
wire write;
wire read;
wire strobe;
reg [15:0] writedata;
reg [15:0] address;
  assign wbm_clk = gls_clk;
  assign wbm_rst = gls_reset;
  //  External signals synchronization process
  always @(posedge gls_clk, posedge gls_reset) begin
    if((gls_reset == 1'b1)) begin
      writedata <= {16{1'b0}};
      address <= {16{1'b0}};
    end else begin
      if((imx_adv == 1'b0)) begin
        address <= imx_da;
      end
      else begin
        writedata <= imx_da;
      end
    end
  end
  assign strobe =  ~(imx_cs_n);
  assign write = ( ~(imx_cs_n)) & ( ~(imx_rw));
  assign read = ( ~(imx_cs_n)) & imx_rw;
  assign wbm_address = address;
  assign wbm_writedata = (write == 1'b1) ? writedata : {16{1'b0}};
  assign wbm_strobe = strobe;
  assign wbm_write = write;
  assign wbm_cycle = strobe;
  assign imx_da = ((read == 1'b1) && (strobe == 1'b1)) ? wbm_readdata : {16{1'bZ}};
endmodule

