module ScheduleCtrl(
input wire ClkxC,
input wire RstxRB,
input wire StartxEI,
input wire RunningxSI,
input wire LastxSI,
output reg SwitchxEO,
output reg BusyxSO
);
// initiate context switch
// busy status flag
parameter [1:0]
  idle = 0,
  switch = 1,
  run = 2;
reg [1:0] currstate;
reg [1:0] nextstate;
  // simple
  //
  // computation of next state and current outputs
  //
  always @(LastxSI, RunningxSI, StartxEI, currstate) begin
    // process
    // default assignments
    nextstate <= currstate;
    SwitchxEO <= 1'b0;
    BusyxSO <= 1'b0;
    // non-default transitions and current outputs
    case(currstate)
    idle : begin
      if(StartxEI == 1'b1) begin
        SwitchxEO <= 1'b1;
        BusyxSO <= 1'b1;
        nextstate <= switch;
      end
    end
    switch : begin
      BusyxSO <= 1'b1;
      nextstate <= run;
    end
    run : begin
      BusyxSO <= 1'b1;
      if((RunningxSI == 1'b0) && (LastxSI == 1'b0)) begin
        SwitchxEO <= 1'b1;
        nextstate <= switch;
      end
      else if((RunningxSI == 1'b0) && (LastxSI == 1'b1)) begin
        nextstate <= idle;
      end
      // have all parasitic states flow into idle state
    end
    default : begin
      nextstate <= idle;
    end
    endcase
  end
  //
  // updating of state
  //
  always @(posedge ClkxC, posedge RstxRB) begin
      // process
    if(RstxRB == 1'b0) begin
      // asynchronous reset (active low)
      currstate <= idle;
    end else begin
      // rising clock edge
      currstate <= nextstate;
    end
  end
endmodule

