module vga_timing(
input wire clk,
input wire rst,
output wire HS,
output wire VS,
output wire [9:0] pixel_x,
output wire [9:0] pixel_y,
output wire last_column,
output wire last_row,
output wire blank
);
reg pixel_en;
reg [9:0] horizontal_pixel_counter;  //to count to 800
wire [9:0] horizontal_pixel_counter_next;
reg [9:0] vertical_pixel_counter;  //to count to 521
wire [9:0] vertical_pixel_counter_next;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      pixel_en <= 1'b0;
      horizontal_pixel_counter <= {10{1'b0}};
      vertical_pixel_counter <= {10{1'b0}};
    end else begin
      pixel_en <=  ~pixel_en;
      horizontal_pixel_counter <= horizontal_pixel_counter_next;
      vertical_pixel_counter <= vertical_pixel_counter_next;
    end
  end
  assign horizontal_pixel_counter_next = (horizontal_pixel_counter == 799 && pixel_en == 1'b1) ? {10{1'b0}} : pixel_en == 1'b1 ? horizontal_pixel_counter + 1 : horizontal_pixel_counter;
  assign vertical_pixel_counter_next = (vertical_pixel_counter == 520 && pixel_en == 1'b1 && horizontal_pixel_counter == 799) ? {10{1'b0}} : (pixel_en == 1'b1 && horizontal_pixel_counter == 799) ? vertical_pixel_counter + 1 : vertical_pixel_counter;
  assign HS = (horizontal_pixel_counter > (639 + 16) && horizontal_pixel_counter < (800 - 48)) ? 1'b0 : 1'b1;
  assign VS = (vertical_pixel_counter > (479 + 10) && vertical_pixel_counter < (521 - 29)) ? 1'b0 : 1'b1;
  assign pixel_x = horizontal_pixel_counter;
  assign pixel_y = vertical_pixel_counter;
  assign last_column = horizontal_pixel_counter == 639 ? 1'b1 : 1'b0;
  assign last_row = vertical_pixel_counter == 479 ? 1'b1 : 1'b0;
  assign blank = (horizontal_pixel_counter >= 640 || vertical_pixel_counter >= 480) ? 1'b1 : 1'b0;
endmodule

