module g_letter (
    input logic Clk,
    input logic Reset,
    input logic frame_clk,
    input logic [9:0] DrawX, DrawY,
    output logic is_g,
    output logic [9:0] pixel_x_in_g_letter, pixel_y_in_g_letter
);

    parameter [9:0] g_letter_X_Start = 10'd208;
    parameter [9:0] g_letter_Y_Start = 10'd35;
    parameter [9:0] g_letter_X_Size = 10'd74;
    parameter [9:0] g_letter_Y_Size = 10'd99;

    logic [9:0] g_letter_X_Pos, g_letter_Y_Pos;
    logic [9:0] g_letter_X_Pos_in, g_letter_Y_Pos_in;
    logic frame_clk_delayed, frame_clk_rising_edge;

    always_ff @(posedge Clk) begin
        if (Reset) begin
            g_letter_X_Pos <= g_letter_X_Start;
            g_letter_Y_Pos <= g_letter_Y_Start;
        end
        else begin
            g_letter_X_Pos <= g_letter_X_Pos_in;
            g_letter_Y_Pos <= g_letter_Y_Pos_in;
        end
    end

    always_ff @(posedge Clk) begin
        frame_clk_delayed <= frame_clk;
        frame_clk_rising_edge <= (frame_clk == 1'b1) && (frame_clk_delayed == 1'b0);
    end

    always_comb begin
        g_letter_X_Pos_in = g_letter_X_Pos;
        g_letter_Y_Pos_in = g_letter_Y_Pos;
    end

    logic signed [10:0] DistX, DistY;
    assign DistX = DrawX - g_letter_X_Pos;
    assign DistY = DrawY - g_letter_Y_Pos;

    always_comb begin
        if (DistX >= 0 && DistX < g_letter_X_Size && DistY >= 0 && DistY < g_letter_Y_Size) begin
            is_g = 1'b1;
            pixel_x_in_g_letter = DistX[9:0];
            pixel_y_in_g_letter = DistY[9:0];
        end
        else begin
            is_g = 1'b0;
            pixel_x_in_g_letter = 10'd0;
            pixel_y_in_g_letter = 10'd0;
        end
    end

endmodule

