module ALU #(
    parameter WIDTH = 32,
    parameter FUNCTION = 6
) (
    input [WIDTH-1:0] A,
    input [WIDTH-1:0] B,
    input [FUNCTION-1:0] funct,
    input enable,
    output [WIDTH-1:0] out,
    output [3:0] flags
);

    localparam ADDR_SIZE = $clog2(WIDTH);

    assign out = enable ? (
        (funct == 0) ? {WIDTH{1'b0}} :
        (funct == 1) ? A + B :
        (funct == 2) ? A - B :
        (funct == 3) ? A & B :
        (funct == 4) ? A | B :
        (funct == 5) ? A - B :
        (funct == 6) ? {31'b0, $signed(A) < $signed(B)} :
        (funct == 7) ? A << B[4:0] :
        {WIDTH{1'bz}}
    ) : {WIDTH{1'bz}};

    // Flags not implemented
