module ece324_latency_tracker(
input wire response,
input wire pulse,
input wire clk,
input wire reset,
input wire enable,
output wire [15:0] missed,
output wire [15:0] latency
);
reg responded; reg pulsed; reg enabled;
reg respondedReset; reg pulsedReset;
reg [15:0] count;
reg [15:0] misses;
reg [15:0] currentLatency;
  // sync response to the clock
  always @(posedge clk) begin
    if((response == 1'b1 && respondedReset == 1'b0)) begin
      responded <= 1'b1;
      respondedReset <= 1'b1;
    end
    else if((responded == 1'b1)) begin
      responded <= 1'b0;
    end
    else if((response == 1'b0)) begin
      respondedReset <= 1'b0;
    end
  end
  // sync pulse to the clock
  always @(posedge clk) begin
    if((pulse == 1'b1 && pulsedReset == 1'b0)) begin
      pulsed <= 1'b1;
      pulsedReset <= 1'b1;
    end
    else if((pulsed == 1'b1)) begin
      pulsed <= 1'b0;
    end
    else if((pulse == 1'b0)) begin
      pulsedReset <= 1'b0;
    end
  end
  // enable the counter on a pulse
  always @(posedge clk) begin
    if((responded == 1'b1 || reset == 1'b1)) begin
      enabled <= 1'b0;
    end
    else begin
      enabled <= pulsed | enabled;
    end
  end
  // latency counter
  always @(posedge clk) begin
    if((responded == 1'b1 || reset == 1'b1)) begin
      count <= 16'b0000000000000000;
    end
    else if((enabled == 1'b1 && enable == 1'b1)) begin
      count <= count + 1;
    end
  end
  // missed pulses counter
  always @(posedge clk) begin
    if((reset == 1'b1)) begin
      misses <= 16'b0000000000000000;
    end
    else if((enabled == 1'b1 && enable == 1'b1 && pulsed == 1'b1)) begin
      misses <= misses + 1;
    end
  end
  // maximum latency register
  always @(posedge clk) begin
    if((reset == 1'b1)) begin
      currentLatency <= 16'b0000000000000000;
    end
    else if((count > currentLatency)) begin
      currentLatency <= count;
    end
  end
  // assign our outputs
  assign missed = misses;
  assign latency = currentLatency;
endmodule

module single_port_bram #(
    parameter ADDR_WIDTH = 8,
    parameter DATA_WIDTH = 32,
    parameter DEPTH = 256
) (
    input wire i_clk,
