    input wire i_write,
    input wire [DATA_WIDTH-1:0] i_data,
    output reg [DATA_WIDTH-1:0] o_data
);

    // Memory array
    reg [DATA_WIDTH-1:0] memory_array [0:DEPTH-1];

    // Synchronous read and write operations
    always @(posedge i_clk) begin
        if (i_write) begin
            // Write operation
            memory_array[i_addr] <= i_data;
        end else begin
            // Read operation
            o_data <= memory_array[i_addr];
        end
    end

endmodule

module sobel_fsm (
    input wire clk,
    input wire rst,
    input wire SW,
    input wire gen_done,
    input wire sobel_done,
    output reg gray_en,
    output reg sobel_en,
    output reg [5:0] state
);

// State definitions
localparam RESET  = 6'b000001;
localparam IDLE   = 6'b000010;
localparam SETUP  = 6'b000100;
localparam SOBEL  = 6'b001000;
localparam DONE   = 6'b010000;
localparam ERROR  = 6'b110110;

reg [5:0] next_state;

// State transition logic
always @(posedge clk or posedge rst) begin
    if (rst)
        state <= RESET;
    else
        state <= next_state;
end

// Next state logic
always @(*) begin
    case (state)
        RESET:  next_state = SETUP;
        SETUP:  next_state = SW ? IDLE : SETUP;
        IDLE:   next_state = (!gen_done && !sobel_done) ? SOBEL : IDLE;
        SOBEL:  next_state = sobel_done ? DONE : SOBEL;
        DONE:   next_state = DONE;
        default: next_state = ERROR;
    endcase
end

// Output logic
always @(*) begin
    gray_en = (state == SETUP) && !SW;
    sobel_en = (state == SOBEL);
end

endmodule

