module noekeon(
input wire clk,
input wire rst,
input wire enc,
input wire [31:0] a_0_in,
input wire [31:0] a_1_in,
input wire [31:0] a_2_in,
input wire [31:0] a_3_in,
input wire [31:0] k_0_in,
input wire [31:0] k_1_in,
input wire [31:0] k_2_in,
input wire [31:0] k_3_in,
output wire [31:0] a_0_out,
output wire [31:0] a_1_out,
output wire [31:0] a_2_out,
output wire [31:0] a_3_out
);
// (enc, 0) / (dec, 1)
wire [7:0] rc_s;
wire [31:0] rc_ext_s;
reg [31:0] a_0_in_s;
reg [31:0] a_1_in_s;
reg [31:0] a_2_in_s;
reg [31:0] a_3_in_s;
reg [31:0] out_t_a_0_in_s;
reg [31:0] out_t_a_1_in_s;
reg [31:0] out_t_a_2_in_s;
reg [31:0] out_t_a_3_in_s;
wire [31:0] a_0_out_s;
wire [31:0] a_1_out_s;
wire [31:0] a_2_out_s;
wire [31:0] a_3_out_s;
wire [31:0] k_0_d_s;
wire [31:0] k_1_d_s;
wire [31:0] k_2_d_s;
wire [31:0] k_3_d_s;
wire [31:0] k_0_mux_s;
wire [31:0] k_1_mux_s;
wire [31:0] k_2_mux_s;
wire [31:0] k_3_mux_s;
wire [271:0] rc_in_s;
  //	rc_in_s <= X"80 1b 36 6c d8 ab 4d 9a 2f 5e bc 63 c6 97 35 6a d4";
  assign rc_in_s = 272'h80801b1b36366c6cd8d8abab4d4d9a9a2f2f5e5ebcbc6363c6c6979735356a6ad4d4;
  //	000000000000000000";
  //RC_GEN_0 : rc_gen port map (clk, rst, enc, rc_s);
  rc_shr RC_SHR_0(
      clk,
    rst,
    rc_in_s,
    rc_s);
  assign rc_ext_s = {24'h000000,rc_s};
  round_f ROUND_F_0(
      clk,
    rst,
    enc,
    rc_ext_s,
    a_0_in_s,
    a_1_in_s,
    a_2_in_s,
    a_3_in_s,
    k_0_mux_s,
    k_1_mux_s,
    k_2_mux_s,
    k_3_mux_s,
    a_0_out_s,
    a_1_out_s,
    a_2_out_s,
    a_3_out_s);
  always @(posedge clk, posedge rst, posedge enc) begin
    if(rst == 1'b1) begin
      a_0_in_s <= a_0_in;
      a_1_in_s <= a_1_in;
      a_2_in_s <= a_2_in;
      a_3_in_s <= a_3_in;
    end
    else begin
      a_0_in_s <= a_0_out_s;
      a_1_in_s <= a_1_out_s;
      a_2_in_s <= a_2_out_s;
      a_3_in_s <= a_3_out_s;
    end
  end
  // Key decryption as k' = theta(0, k)
  // This is the key required for decryption
  // in NOEKEON
  theta THETA_DECRYPT_0(
      k_0_in,
    k_1_in,
    k_2_in,
    k_3_in,
    {broken{0}},
    {broken{0}},
    {broken{0}},
    {broken{0}},
    k_0_d_s,
    k_1_d_s,
    k_2_d_s,
    k_3_d_s);
  // These multiplexers select the key that is used
  // in each mode i.e. during decryption the key generated
  // as k' = theta(0, k) (THETA_DECRYPT_0) is utilized.
  assign k_0_mux_s = enc == 1'b0 ? k_0_in : k_0_d_s;
  assign k_1_mux_s = enc == 1'b0 ? k_1_in : k_1_d_s;
  assign k_2_mux_s = enc == 1'b0 ? k_2_in : k_2_d_s;
  assign k_3_mux_s = enc == 1'b0 ? k_3_in : k_3_d_s;
  always @(posedge clk, posedge rst, posedge a_0_out_s, posedge a_1_out_s, posedge a_2_out_s, posedge a_3_out_s) begin
    out_t_a_0_in_s <= a_0_out_s;
    out_t_a_1_in_s <= a_1_out_s;
    out_t_a_2_in_s <= a_2_out_s;
    out_t_a_3_in_s <= a_3_out_s;
  end
  // This component performs the last operation
  // with theta.
  output_trans OUT_TRANS_0(
      clk,
    enc,
    rc_ext_s,
    out_t_a_0_in_s,
    out_t_a_1_in_s,
    out_t_a_2_in_s,
    out_t_a_3_in_s,
    k_0_mux_s,
    k_1_mux_s,
    k_2_mux_s,
    k_3_mux_s,
    a_0_out,
    a_1_out,
    a_2_out,
    a_3_out);
endmodule

