input wire clk_ms,
input wire clk_1hz,
input wire rst,
input wire vsync,
input wire no_frame_read,
input wire write_img,
input wire pktend,
input wire jpg_busy,
output reg [7:0] proc_time,
output reg [7:0] frame_write_time,
output reg [7:0] frame_rate,
output reg [7:0] in_frame_rate,
output reg [7:0] frame_drop_cnt
);
reg [7:0] f_cnt;
reg [7:0] w_time;
reg [7:0] p_time;
reg [7:0] frame_rate_cnt;
reg [7:0] in_frame_cnt;
reg write_img_q;
reg jpg_busy_q;
reg clk_1hz_q;
reg pktend_q;
reg vsync_q;
  // Counts the number of frames dropped
  always @(posedge vsync, posedge rst) begin
    if(rst == 1'b1) begin
      f_cnt <= {8{1'b0}};
    end else begin
      if(no_frame_read == 1'b1) begin
        f_cnt <= f_cnt + 1;
      end
      else begin
        f_cnt <= {8{1'b0}};
      end
    end
  end
  always @(negedge no_frame_read, negedge rst) begin
    if(rst == 1'b1) begin
      frame_drop_cnt <= {8{1'b0}};
    end else begin
      frame_drop_cnt <= f_cnt;
    end
  end
  //Counts the milliseconds it took to clock frame into DDR
  always @(posedge clk_ms, posedge rst) begin
    if(rst == 1'b1) begin
      w_time <= {8{1'b0}};
      frame_write_time <= {8{1'b0}};
      write_img_q <= 1'b0;
    end else begin
      write_img_q <= write_img;
      if(write_img == 1'b1) begin
        w_time <= w_time + 1;
      end
      else if(write_img_q == 1'b1) begin
        frame_write_time <= w_time;
        w_time <= {8{1'b0}};
      end
    end
  end
  //Counts the milliseconds it took to process the frame once written into ddr
  always @(posedge clk_ms, posedge rst) begin
    if(rst == 1'b1) begin
      p_time <= {8{1'b0}};
      proc_time <= {8{1'b0}};
      jpg_busy_q <= 1'b0;
    end else begin
      jpg_busy_q <= jpg_busy;
      if(jpg_busy == 1'b1) begin
        p_time <= p_time + 1;
      end
      else if(jpg_busy_q == 1'b1) begin
        proc_time <= p_time;
        p_time <= {8{1'b0}};
      end
    end
  end
  //Output frame rate
  always @(posedge clk, posedge rst) begin
    if(rst == 1'b1) begin
      frame_rate_cnt <= {8{1'b0}};
    end else begin
      clk_1hz_q <= clk_1hz;
      pktend_q <= pktend;
      if((clk_1hz_q == 1'b0 && clk_1hz == 1'b1)) begin
        frame_rate_cnt <= {8{1'b0}};
      end
      else if((pktend_q == 1'b0 && pktend == 1'b1)) begin
        frame_rate_cnt <= frame_rate_cnt + 1;
      end
    end
  end
  always @(posedge clk_1hz, posedge rst) begin
    if(rst == 1'b1) begin
      frame_rate <= {8{1'b0}};
    end else begin
      frame_rate <= frame_rate_cnt;
    end
  end
  //input frame rate
  always @(posedge clk, posedge rst) begin
    if(rst == 1'b1) begin
      in_frame_cnt <= {8{1'b0}};
      vsync_q <= 1'b0;
    end else begin
      vsync_q <= vsync;
      if((clk_1hz_q == 1'b0 && clk_1hz == 1'b1)) begin
        in_frame_cnt <= {8{1'b0}};
      end
      else if((vsync_q == 1'b0 && vsync == 1'b1)) begin
        in_frame_cnt <= in_frame_cnt + 1;
      end
    end
  end
  always @(posedge clk_1hz, posedge rst) begin
    if(rst == 1'b1) begin
      in_frame_rate <= {8{1'b0}};
    end else begin
      in_frame_rate <= in_frame_cnt;
    end
  end
endmodule

