module A4_Segled2(
    input CLK_50M,
    input RST_N,
    output reg [7:0] SEG_DATA,
    output reg [5:0] SEG_EN
);

    parameter SET_TIME_10MS = 500000;

    reg [15:0] time_cnt;
    reg [2:0] led_cnt;

    always @(posedge CLK_50M or negedge RST_N) begin
        if (!RST_N) begin
            time_cnt <= 16'd0;
            led_cnt <= 3'd0;
        end else begin
            if (time_cnt == SET_TIME_10MS - 1) begin
                time_cnt <= 16'd0;
                if (led_cnt == 3'd5)
                    led_cnt <= 3'd0;
                else
                    led_cnt <= led_cnt + 1'b1;
            end else begin
                time_cnt <= time_cnt + 1'b1;
            end
        end
    end

    always @(*) begin
        case (led_cnt)
            3'd0: SEG_DATA = 8'b00111111;
            3'd1: SEG_DATA = 8'b00000110;
            3'd2: SEG_DATA = 8'b01011011;
            3'd3: SEG_DATA = 8'b01001111;
            3'd4: SEG_DATA = 8'b01100110;
            3'd5: SEG_DATA = 8'b01101101;
            default: SEG_DATA = 8'b10111111;
        endcase
    end

    always @(*) begin
        case (led_cnt)
            3'd0: SEG_EN = 6'b111110;
            3'd1: SEG_EN = 6'b111101;
            3'd2: SEG_EN = 6'b111011;
            3'd3: SEG_EN = 6'b110111;
            3'd4: SEG_EN = 6'b101111;
            3'd5: SEG_EN = 6'b011111;
            default: SEG_EN = 6'b111111;
        endcase
    end

endmodule

module ieee754_fp_multiplier(
input wire [31:0] x,
input wire [31:0] y,
output wire [31:0] z
);
wire x_sign; wire y_sign; wire z_sign;
wire [7:0] x_exponent; wire [7:0] y_exponent; reg [7:0] z_exponent;
wire [23:0] x_mantissa; wire [23:0] y_mantissa;
reg [22:0] z_mantissa;
  assign x_sign = x[31];
  assign y_sign = y[31];
  assign z[31] = z_sign;
  // output sign is negative if only one input is negative
  assign z_sign = x_sign ^ y_sign;
  assign x_mantissa[23] = 1'b1;
  assign x_mantissa[22:0] = x[22:0];
  assign y_mantissa[23] = 1'b1;
  assign y_mantissa[22:0] = y[22:0];
  assign z[22:0] = z_mantissa;
  assign x_exponent = x[30:23];
  assign y_exponent = y[30:23];
  assign z[30:23] = z_exponent;
  always @(x_exponent, y_exponent, x_mantissa, y_mantissa) begin : P1
    reg [31:0] add, msb;
    reg [47:0] multiply, shift_multiply;
    reg [22:0] mantissa;
    if((x_exponent == 8'h00 && x_mantissa == 24'b100000000000000000000000) || (y_exponent == 8'h00 && y_mantissa == 24'b100000000000000000000000)) begin
      z_exponent <= 8'h00;
      z_mantissa <= 23'b00000000000000000000000;
    end
    else begin
      // add the exponents
      add = ((x_exponent) + (y_exponent)) - 127;
      //  multiply the mantissas
      multiply = (x_mantissa) * (y_mantissa);
      msb = 0;
      for (i=0; i <= 47; i = i + 1) begin
        if(multiply[i] == 1'b1) begin
          msb = i;
        end
      end
      shift_multiply = multiply >> (msb - 23);
      mantissa = shift_multiply[22:0];
      if(mantissa == 23'b11111111111111111111111) begin
        z_mantissa <= mantissa + 1;
        z_exponent <= add + (msb - 46) + 1;
      end
      else begin
        z_mantissa <= shift_multiply[22:0];
        z_exponent <= add + (msb - 46);
      end
    end
  end
endmodule

