            lbsigned_outEXMEM <= 1'b0;
            reg2EXMEM <= 5'b0;
            reg3EXMEM <= 5'b0;
            size_inEXMEM <= 2'b0;
        end else begin
            O_outEXMEM <= O_out;
            o_RT_DataEXMEM <= o_RT_DataIDEX;
            pcPlus4EXMEM <= pcPlus4IDEX;
            instructionROMOutEXMEM <= instructionROMOutIDEX;
            re_inEXMEM <= re_inIDEX;
