module score_synth(
input wire CLK_IN,
input wire RESET_IN,
output reg [8:0] STATUS
);
parameter [31:0] C_ROM_SYNTH=1;
//ERROR STATUS OUT OF FPGA
wire CLKA = 1'b0;
wire RSTA = 1'b0;
wire [13:0] ADDRA = 1'b0;
reg [13:0] ADDRA_R = 1'b0;
wire [11:0] DOUTA;
