module Control_Unit(
input wire [7:0] command,
inout reg [7:0] alu_command_o,
inout reg ram_command_o,
inout wire [3:0] pc_command_o,
input wire clk
);
// comamnd that comes from memory
// command that we will parse to ALU
// command that we will parse to RAM
// command tat we will parse to Program_Counter
  always @(posedge clk) begin
    // ALU commands
    if(command == 8'b00000001) begin
      alu_command_o <= 8'b00000001;
      //addition of input signals
    end
    else if(command == 8'b00000010) begin
      alu_command_o <= 8'b00000010;
      // substraction of input signals
    end
    else if(command == 8'b00000011) begin
      alu_command_o <= 8'b00000011;
      // AND operation
    end
    else if(command == 8'b00000100) begin
      alu_command_o <= 8'b00000100;
      // OR operation
    end
    else if(command == 8'b00000101) begin
      alu_command_o <= 8'b00000101;
      // XOR operation
    end
    else if(command == 8'b00000110) begin
      alu_command_o <= 8'b00000110;
      // NOT operation
    end
    else if(command == 8'b00000111) begin
      alu_command_o <= 8'b00000111;
      //shift right
    end
    else if(command == 8'b00001000) begin
      alu_command_o <= 8'b00001000;
      //shift left
      // RAM commands
    end
    else if(command == 8'b00001001) begin
      ram_command_o <= 1'b1;
      // read from ram
    end
    else if(command == 8'b00001010) begin
      ram_command_o <= 1'b1;
      // write to ram
    end
  end
endmodule

