module reset_dcm(
input wire clk,
input wire locked_i,
output reg reset_o
);
parameter [31:0] cycles=100;
//reset ='1' enable ,i.e. reset dcm
  always @(posedge clk) begin : P1
    reg [31:0] count = cycles;
    if(locked_i == 1'b1) begin
      count = count - 1;
    end
    else begin
      count = cycles;
      reset_o <= 1'b1;
    end
    if(count == 0) begin
      reset_o <= 1'b0;
    end
  end
endmodule

module alu_8bit(
    input [7:0] a,
    input [7:0] b,
    input [3:0] opcode,
    output reg [7:0] op
);

always @(*) begin
    case(opcode)
        4'b0000: op = a + b;
        4'b0001: op = a - b;
        4'b0010: op = a * b;
        4'b0011: op = a / b;
        4'b0100: op = a % b;
        4'b0101: op = a & b;
        4'b0110: op = a | b;
        4'b0111: op = (a && b) ? 8'd1 : 8'd0;
        4'b1000: op = (a || b) ? 8'd1 : 8'd0;
        4'b1001: op = a ^ b;
        4'b1010: op = ~a;
        4'b1011: op = (a == 8'd0) ? 8'd1 : 8'd0;
        4'b1100: op = a >> 1;
        4'b1101: op = a << 1;
        4'b1110: op = a + 8'd1;
        4'b1111: op = a - 8'd1;
        default: op = 8'bXXXXXXXX;
    endcase
end

endmodule

