module dsm2 (
    input wire clk,
    input wire rstx,
    input real data_in,
    output reg data_out
);

    real i1, i2;
    real feedback;

    always @(posedge clk or negedge rstx) begin
        if (!rstx) begin
            i1 <= 0.0;
            i2 <= 0.0;
            data_out <= 0;
        end else begin
            // First integrator
            i1 <= i1 + data_in - feedback;

            // Second integrator
            i2 <= i2 + i1 - feedback;

            // Quantizer
            data_out <= (i2 >= 0) ? 1 : 0;

            // Feedback conversion
            feedback <= data_out ? 1.0 : -1.0;
        end
    end

endmodule

