module conv_40to8(
input wire clk_in,
input wire reset_in,
input wire [39:0] data40_in,
input wire valid40_in,
output reg ready40_out,
output reg [7:0] data8_out,
output reg valid8_out,
input wire ready8_in
);
// System clock & reset
// 40-bit data coming in
// 8-bit data going out
parameter [2:0]
  S_WRITE0 = 0,
  S_WRITE1 = 1,
  S_WRITE2 = 2,
  S_WRITE3 = 3,
  S_WRITE4 = 4;
reg [2:0] state = S_WRITE0;
reg [2:0] state_next;
reg [31:0] wip = 1'b0;
reg [31:0] wip_next;
  // Infer registers
  always @(posedge clk_in) begin
    if((reset_in == 1'b1)) begin
      state <= S_WRITE0;
      wip <= {32{1'b0}};
    end
    else begin
      state <= state_next;
      wip <= wip_next;
    end
  end
  // Next state logic
  always @(state, wip, data40_in, valid40_in, ready8_in) begin
    state_next <= state;
    valid8_out <= 1'b0;
    wip_next <= wip;
    case(state)
        // Write byte 1
    S_WRITE1 : begin
      ready40_out <= 1'b0;
      // not ready for data from 40-bit side
      data8_out <= wip[31:24];
      if((ready8_in == 1'b1)) begin
        valid8_out <= 1'b1;
        state_next <= S_WRITE2;
      end
      // Write byte 2
    end
    S_WRITE2 : begin
      ready40_out <= 1'b0;
      // not ready for data from 40-bit side
      data8_out <= wip[23:16];
      if((ready8_in == 1'b1)) begin
        valid8_out <= 1'b1;
        state_next <= S_WRITE3;
      end
      // Write byte 3
    end
    S_WRITE3 : begin
      ready40_out <= 1'b0;
      // not ready for data from 40-bit side
      data8_out <= wip[15:8];
      if((ready8_in == 1'b1)) begin
        valid8_out <= 1'b1;
        state_next <= S_WRITE4;
      end
      // Write byte 4 (LSB)
    end
    S_WRITE4 : begin
      ready40_out <= 1'b0;
      // not ready for data from 40-bit side
      data8_out <= wip[7:0];
      if((ready8_in == 1'b1)) begin
        valid8_out <= 1'b1;
        state_next <= S_WRITE0;
      end
      // When a word arrives, write byte 0 (MSB)
    end
    default : begin
      ready40_out <= ready8_in;
      // ready for data from 40-bit side
      data8_out <= data40_in[39:32];
      valid8_out <= valid40_in;
      if((valid40_in == 1'b1 && ready8_in == 1'b1)) begin
        wip_next <= data40_in[31:0];
        state_next <= S_WRITE1;
      end
    end
    endcase
  end
endmodule

module rot_ena_gen(
