module Counter4Bits(
input wire reset,
input wire clk,
input wire enable,
output wire [3:0] valOut,
output reg termCnt
);
parameter [31:0] MAX;
reg [3:0] s_value;
  always @(posedge reset, posedge clk) begin
    if((reset == 1'b1)) begin
      s_value <= {4{1'b0}};
      termCnt <= 1'b0;
    end
    else if((enable == 1'b1)) begin
      if(((s_value) == MAX)) begin
        s_value <= {4{1'b0}};
        termCnt <= 1'b0;
      end
      else begin
        s_value <= s_value + 1;
        if(((s_value) == (MAX - 1))) begin
          termCnt <= 1'b1;
        end
        else begin
          termCnt <= 1'b0;
        end
      end
    end
  end
  assign valOut = s_value;
endmodule

module UART_TX_CTRL(
input wire SEND,
input wire [7:0] DATA,
input wire CLK,
output wire READY,
output wire UART_TX
);
parameter [1:0]
  RDY = 0,
  LOAD_BIT = 1,
  SEND_BIT = 2;
  //2Mbaud --> 49 -- 100MHz / 2Mbaud -1 =  50 -1 = 49 =    00000000110001
//constant BIT_TMR_MAX : std_logic_vector(13 downto 0) := "10100010110000"; --10416 = (round(100MHz / 9600)) - 1
parameter BIT_TMR_MAX = 14'b00000000110001;  //2Mbaud
parameter BIT_INDEX_MAX = 10;  //Counter that keeps track of the number of clock cycles the current bit has been held stable over the
//UART TX line. It is used to signal when the ne
reg [13:0] bitTmr = 1'b0;  //combinatorial logic that goes high when bitTmr has counted to the proper value to ensure
//a 9600 baud rate
wire bitDone;  //Contains the index of the next bit in txData that needs to be transferred 
reg [31:0] bitIndex;  //a register that holds the current data being sent over the UART TX line
reg txBit = 1'b1;  //A register that contains the whole data packet to be sent, including start and stop bits. 
reg [9:0] txData;
reg [1:0] txState = RDY;
  //Next state logic
  always @(posedge CLK) begin
    case(txState)
    RDY : begin
      if((SEND == 1'b1)) begin
        txState <= LOAD_BIT;
      end
    end
    LOAD_BIT : begin
      txState <= SEND_BIT;
    end
    SEND_BIT : begin
      if((bitDone == 1'b1)) begin
        if((bitIndex == BIT_INDEX_MAX)) begin
          txState <= RDY;
        end
        else begin
          txState <= LOAD_BIT;
        end
      end
    end
    default : begin
      //should never be reached
      txState <= RDY;
    end
    endcase
  end
  always @(posedge CLK) begin
    if((txState == RDY)) begin
      bitTmr <= {14{1'b0}};
    end
    else begin
      if((bitDone == 1'b1)) begin
        bitTmr <= {14{1'b0}};
      end
      else begin
        bitTmr <= bitTmr + 1;
      end
    end
  end
  assign bitDone = (bitTmr == BIT_TMR_MAX) ? 1'b1 : 1'b0;
  always @(posedge CLK) begin
    if((txState == RDY)) begin
      bitIndex <= 0;
    end
    else if((txState == LOAD_BIT)) begin
      bitIndex <= bitIndex + 1;
    end
  end
  always @(posedge CLK) begin
    if((SEND == 1'b1)) begin
      txData <= {1'b1,DATA,1'b0};
    end
  end
  always @(posedge CLK) begin
    if((txState == RDY)) begin
      txBit <= 1'b1;
    end
    else if((txState == LOAD_BIT)) begin
      txBit <= txData[bitIndex];
    end
  end
  assign UART_TX = txBit;
  assign READY = (txState == RDY) ? 1'b1 : 1'b0;
endmodule

