module UartTransmitter(
input wire clk,
input wire [7:0] data,
input wire send,
output reg rdy,
output reg TXD
);
//---------------------------------------------------------
reg running = 1'b0;
reg [0:9] s_data;
  always @(posedge clk) begin : P1
    reg [31:0] outBit =  -1;
    if(send == 1'b1 && running == 1'b0) begin
      s_data[1:8] <= data;
      s_data[9] <= 1'b0;
      // Start bit
      s_data[0] <= 1'b1;
      // Stop bit
      outBit = 9;
      rdy <= 1'b0;
      running <= 1'b1;
    end
    else if(running == 1'b1 && outBit >= 0) begin
      TXD <= s_data[outBit];
      outBit = outBit - 1;
    end
    else begin
      running <= 1'b0;
      rdy <= 1'b1;
    end
  end
endmodule

module controleDigitos(
    input wire clk,
    input wire enable,
    input wire tempoLimite,
    input wire OK,
    output reg enableLinha,
    output reg enableColuna,
    output reg clear,
    output reg [1:0] estadoMef1
);

    // State encoding
    localparam [1:0] ESPERA = 2'b00,
                     LINHA = 2'b01,
                     COLUNA = 2'b10,
                     BLOQUEADO = 2'b11;

    reg [1:0] estadoAtual, proxEstado;

    // State register
    always @(posedge clk) begin
        estadoAtual <= proxEstado;
    end

    // Next state logic
    always @(*) begin
        case (estadoAtual)
            ESPERA: proxEstado = enable ? LINHA : ESPERA;
            LINHA: begin
                if (!enable && tempoLimite)
                    proxEstado = ESPERA;
                else if (enable)
                    proxEstado = COLUNA;
                else
                    proxEstado = LINHA;
            end
            COLUNA: begin
                if (!enable && tempoLimite)
                    proxEstado = ESPERA;
                else if (enable)
                    proxEstado = BLOQUEADO;
                else
                    proxEstado = COLUNA;
            end
            BLOQUEADO: proxEstado = OK ? ESPERA : BLOQUEADO;
            default: proxEstado = ESPERA;
        endcase
    end

    // Output logic
    always @(*) begin
        case (estadoAtual)
            LINHA: begin
                enableLinha = 1'b1;
                enableColuna = 1'b0;
                clear = 1'b0;
            end
            COLUNA: begin
                enableLinha = 1'b0;
                enableColuna = 1'b1;
                clear = 1'b0;
            end
            BLOQUEADO: begin
                enableLinha = 1'b0;
                enableColuna = 1'b0;
                clear = 1'b0;
            end
            default: begin // ESPERA
                enableLinha = 1'b0;
                enableColuna = 1'b0;
                clear = 1'b1;
            end
        endcase
    end

    // Output current state
    always @(*) begin
        estadoMef1 = estadoAtual;
    end

endmodule

module nor_two(A, B, y);
