module freq_divider_debounce (
    input wire clk,
    input wire reset,
    output reg clk_out
);

    reg [27:0] counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 28'd0;
            clk_out <= 1'b0;
        end else begin
            if (counter == 28'd24_999_999) begin
                counter <= 28'd0;
                clk_out <= ~clk_out;
            end else begin
                counter <= counter + 1'b1;
            end
        end
    end

endmodule

module Control(
    input [5:0] opcode,
    input [5:0] funct,
    output reg ALUSrc,
    output reg RegDst,
    output reg MemWrite,
    output reg MemRead,
    output reg Beq,
    output reg Bne,
    output reg Jump,
    output reg MemToReg,
    output reg RegWrite,
    output reg [2:0] ALUControl
);

    always @(*) begin
        // Default values
        ALUSrc = 1'b0;
        RegDst = 1'b0;
        MemWrite = 1'b0;
        MemRead = 1'b0;
        Beq = 1'b0;
        Bne = 1'b0;
        Jump = 1'b0;
        MemToReg = 1'b0;
        RegWrite = 1'b0;
        ALUControl = 3'b000;

        case(opcode)
            6'b000000: begin // R-type instructions
                RegDst = 1'b1;
                RegWrite = 1'b1;
                case(funct)
                    6'b100000: ALUControl = 3'b010; // ADD
                    6'b100010: ALUControl = 3'b110; // SUB
                    6'b100101: ALUControl = 3'b001; // OR
                    6'b101010: ALUControl = 3'b111; // SLT
                endcase
            end
            6'b100011: begin // Load word
                ALUSrc = 1'b1;
                MemRead = 1'b1;
                MemToReg = 1'b1;
                RegWrite = 1'b1;
                ALUControl = 3'b010; // Addition for address calculation
            end
            6'b101011: begin // Store word
                ALUSrc = 1'b1;
                MemWrite = 1'b1;
                ALUControl = 3'b010; // Addition for address calculation
            end
            6'b000100: begin // Branch on equal
                Beq = 1'b1;
                ALUControl = 3'b110; // Subtraction for comparison
            end
            6'b000101: begin // Branch on not equal
                Bne = 1'b1;
                ALUControl = 3'b110; // Subtraction for comparison
            end
            6'b000010: begin // Jump
                Jump = 1'b1;
            end
            6'b001000: begin // Add immediate
                ALUSrc = 1'b1;
                RegWrite = 1'b1;
                ALUControl = 3'b010; // Addition
            end
        endcase
    end

endmodule

module final3_logic(
input wire clock,
input wire reset,
input wire RSTn_in,
input wire cart_kill,
input wire freeze_trig,
input wire freeze_act,
output reg unfreeze,
input wire io_write,
input wire [8:0] io_addr,
input wire [7:0] io_data,
output wire serve_enable,
output wire serve_vic,
output wire serve_rom,
output wire serve_io1,
output wire serve_io2,
output wire allow_write,
input wire [15:0] slot_addr,
output wire [25:0] mem_addr,
output wire [7:0] cart_mode,
output wire irq_n,
output wire nmi_n,
output reg exrom_n,
output reg game_n,
output wire CART_LEDn
);
parameter [27:0] rom_base=28'h1010000;
// enables fetching bus address PHI2=1
// enables doing so for PHI2=0
// ROML or ROMH
// IO1n
// IO2n
// debug
reg [7:0] cart_ctrl;
reg reset_in;
reg cart_en;
  assign serve_enable = cart_en;
  always @(posedge clock) begin
    reset_in <=  ~RSTn_in | reset;
    cart_en <=  ~cart_ctrl[7] | freeze_act;
    unfreeze <= 1'b0;
    // flipflops
    if(io_write == 1'b1 && io_addr == 9'b111111111) begin
      cart_ctrl <= io_data;
      unfreeze <= freeze_act;
    end
    if(cart_kill == 1'b1) begin
      cart_ctrl[7] <= 1'b1;
    end
    if(cart_en == 1'b1) begin
      exrom_n <= cart_ctrl[4];
      game_n <= cart_ctrl[5] &  ~freeze_act;
    end
    else begin
      game_n <= 1'b1;
      exrom_n <= 1'b1;
    end
    // reset
    if(reset_in == 1'b1) begin
      cart_ctrl <= 8'h00;
      //(others => '0'); -- fix = X"20" => 8K rom only to test
    end
  end
  //    game_n   <= '0' when (cart_en='1') and (cnt_q(3)='0' or cart_ctrl(5)='0') else '1';
  //    exrom_n  <= '0' when (cart_en='1') and (cart_ctrl(4)='0') else '1';
  // open drains
  assign irq_n = 1'b1;
  assign nmi_n =  ~(freeze_trig | freeze_act |  ~cart_ctrl[6]);
  assign mem_addr = {rom_base[25:16],cart_ctrl[1:0],slot_addr[13:0]};
  assign CART_LEDn =  ~cart_en;
  assign cart_mode = cart_ctrl;
