module edge_sync(
input wire RESET,
input wire CLK,
input wire EI,
output wire SO
);
parameter EDGE=1'b1;
//! '1'  :  rising edge,  '0' falling edge
//! reset
//! clock
//! input signal.
//! output pulse, 1 CLK cycle wide.
reg prev;
reg prev1;
reg prev2;
  always @(posedge CLK, posedge RESET) begin
    if(RESET == 1'b1) begin
      prev <= 1'b0;
      prev1 <= 1'b0;
      prev2 <= 1'b0;
    end else begin
      prev <= EI;
      prev1 <= prev;
      prev2 <= prev1;
    end
  end
  assign SO = ((prev2 == 1'b0 && prev1 == 1'b1 && EDGE == 1'b1) || (prev2 == 1'b1 && prev1 == 1'b0 && EDGE == 1'b0)) ? 1'b1 : 1'b0;
endmodule

