module sum_reg #(
    parameter K_SIZE = 8,
    parameter DATA_WIDTH = 32
) (
    input wire clk,
    input wire rst_n,
    input wire [DATA_WIDTH-1:0] ina,
    input wire valid_in,
    input wire last_in,
    output reg [DATA_WIDTH-1:0] out,
    output reg valid_out,
    output reg last_out
);

    reg [5:0] count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            out <= {DATA_WIDTH{1'b0}};
            count <= 6'b0;
            valid_out <= 1'b0;
            last_out <= 1'b0;
        end else begin
            last_out <= last_in;

            if (valid_in) begin
                if (count == 0) begin
                    out <= ina;
                end else if (count < K_SIZE - 1) begin
                    out <= out + ina;
                end else begin
                    out <= (out + ina) >> 3;
                end

                count <= (count == K_SIZE - 1) ? 6'b0 : count + 1'b1;
                valid_out <= (count == K_SIZE - 1);
            end else begin
                valid_out <= 1'b0;
            end
        end
    end

endmodule

