module LoadUnit (
    input wire clock,
    input wire loadEnable,
    input wire [31:0] addr,
    input wire [5:0] robNum,
    input wire hit,
    input wire [31:0] data_in,

    output reg [31:0] addr_out,
    output reg cdbEnable,
    output reg [5:0] robNum_out,
    output reg [31:0] cdbdata,
    output reg busy
);

    // Internal registers
    reg [31:0] addr_reg;
    reg [5:0] robNum_reg;
    reg waiting_for_data;

    always @(posedge clock) begin
        // Reset cdbEnable at the beginning of each clock cycle
        cdbEnable <= 1'b0;

        if (loadEnable) begin
            // Capture load request
            addr_reg <= addr;
            robNum_reg <= robNum;
            addr_out <= addr;
            busy <= 1'b1;
            waiting_for_data <= 1'b1;
        end

        if (waiting_for_data && hit) begin
            // Data is available, prepare for CDB broadcast
            cdbEnable <= 1'b1;
            robNum_out <= robNum_reg;
            cdbdata <= data_in;
            busy <= 1'b0;
            waiting_for_data <= 1'b0;
        end
    end

endmodule

