module multiplier(
input wire clk,
input wire reset,
input wire [2:0] addrA,
input wire [2:0] addrB,
input wire showAB,
input wire start,
inout reg [31:0] result,
output wire [31:0] outAB,
output wire [7:0] ready
);
wire [31:0] romAOut;
wire [31:0] romBOut;
wire [31:0] outAB_graph_s;
reg [31:0] result_graph_s;
reg en_mul;
reg rst_mul;
wire [31:0] result_graph_ss;
wire [31:0] res;
wire done_mult;
wire [31:0] graph;
parameter [1:0]
  initial = 0,
  multiply = 1,
  view_result = 2;
reg [1:0] CurrentState; reg [1:0] NextState;
  always @(CurrentState) begin
    NextState <= initial;
    result_graph_s <= {32{1'b0}};
    case(CurrentState)
    initial : begin
      en_mul <= 1'b0;
      rst_mul <= 1'b0;
      //---result<="11110000010000000010010011110001";
      if((start == 1'b0)) begin
        NextState <= multiply;
      end
      else begin
        NextState <= initial;
      end
    end
    multiply : begin
      en_mul <= 1'b1;
      rst_mul <= 1'b1;
      if((done_mult == 1'b1)) begin
        NextState <= view_result;
      end
      else begin
        NextState <= multiply;
      end
    end
    view_result : begin
      //en_mul<='1';
      //if(reset='0') then
      //NextState<=initial;
      //else
      //NextState<=view_result;
      //end if;
      NextState <= multiply;
    end
    endcase
  end
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b0) begin
      CurrentState <= initial;
    end else begin
      CurrentState <= NextState;
    end
  end
  romMemOpA uOpA(
      .addr(addrA),
    .dataOut(romAOut));
  romMemOpB uOpB(
      .addr(addrB),
    .dataOut(romBOut));
  device uMult(
      .a(romAOut),
    .b(romBOut),
    .clk(clk),
    .en(en_mul),
    .rst(rst_mul),
    .c(result_graph_ss),
    .done(done_mult));
  graph_driver outtAB_graph(
      .in_graph(outAB_graph_s),
    .out_graph(outAB));
  graph_driver result_graph(
      .in_graph(result_graph_ss),
    .out_graph(res));
  always @(*) begin
    case(currentState)
      initial : result <= 32'b11110000010000000010010011110001;
      default : result <= res;
    endcase
  end
  // When the button assoiciated to outAB is pushed romAOut is displayed
  assign outAB_graph_s = showAB == 1'b0 ? romAOut : romBOut;
  assign ready[7:0] = {8{done_mult}};
endmodule

