module binToSeg(
input wire [3:0] bin,
output reg [7:0] displaySeg
);
// 7 = A / 6 = B / ... / 0 = H
  always @(*) begin
    case(bin)
      4'b0000 : displaySeg <= 8'b11111100;
  // 0 => Leds: A,B,C,D,E,F
      4'b0001 : displaySeg <= 8'b01100000;
  // 1 => Leds: B,C
      4'b0010 : displaySeg <= 8'b11011010;
  // 2 => Leds: A,B,G,E,D
      4'b0011 : displaySeg <= 8'b11110010;
  // 3 => Leds: A,B,C,D,G
      4'b0100 : displaySeg <= 8'b01100110;
  // 4 => Leds: B,C,F,G
      4'b0101 : displaySeg <= 8'b10110110;
  // 5 => Leds: A,C,D,F,G
      4'b0110 : displaySeg <= 8'b10111110;
  // 6 => Leds: A,C,D,E,F,G
      4'b0111 : displaySeg <= 8'b11100000;
  // 7 => Leds: A,B,C
      4'b1000 : displaySeg <= 8'b11111110;
  // 8 => Leds: A,B,C,D,E,F,G
      4'b1001 : displaySeg <= 8'b11110110;
  // 9 => Leds: A,B,C,D,F,G	
      4'b1010 : displaySeg <= 8'b11101110;
  // A(10) => Leds: A,B,C,E,F,G
      4'b1011 : displaySeg <= 8'b00111110;
  // B(11) => Leds: A,B,C,D,E,F,G
      4'b1100 : displaySeg <= 8'b10011100;
  // C(12) => Leds: A,D,E,F
      4'b1101 : displaySeg <= 8'b01111010;
  // D(13) => Leds: A,B,C,D,E,F
      4'b1110 : displaySeg <= 8'b10011110;
  // E(14) => Leds: A,D,E,F,G
      4'b1111 : displaySeg <= 8'b10001110;
  // F(15) => Leds: A,E,F,G
      default : displaySeg <= 8'b00000001;
    endcase
  end
    // En cualquier otro caso encendemos el "."		   		
endmodule

