module register_file (
    input wire CLK,
    input wire [2:0] srcA, srcB, writeReg,
    input wire [15:0] writeValue,
    input wire RegWrite,
    output wire [15:0] ReadA, ReadB, LoadValue, RegFive, SPAddress
);

    reg [15:0] registers [0:15];

    // Initialize registers
    initial begin
        integer i;
        for (i = 0; i < 16; i = i + 1) begin
            if (i == 1)
                registers[i] = 16'hFFFF; // Register 1 initialized to -1
            else if (i == 6)
                registers[i] = 16'd9;    // Register 6 initialized to 9
            else
                registers[i] = 16'd0;    // All other registers initialized to 0
        end
    end

    // Write operation
    always @(posedge CLK) begin
        if (RegWrite) begin
            registers[writeReg] <= writeValue;
            $display("Writing %d to register %d", writeValue, writeReg);
        end
    end

    // Read operations
    assign ReadA = registers[srcA];
    assign ReadB = registers[srcB];

    // Special register outputs
    assign LoadValue = registers[6];
    assign RegFive = registers[5];
    assign SPAddress = registers[1];

endmodule

module Kiss2Fsm(
input wire Clk,
input wire [1:0] i,
output reg [1:0] O
);
parameter [1:0]
  S0 = 0,
  S1 = 1,
  S2 = 2,
  S3 = 3;
wire [1:0] state = s0;
  //------------------ State transitions process -----------------------
  always @(posedge Clk) begin
    case(State)
    s0 : begin
      //============================================ 
      if(i == 2'b01) begin
        State <= S1;
      end
      if(i == 2'b11) begin
        State <= S3;
      end
    end
    s1 : begin
      //============================================ 
      if(i == 2'b01) begin
        State <= S0;
      end
      if(i == 2'b11) begin
        State <= S2;
      end
    end
    s2 : begin
      //============================================ 
      if(i[1] == 1'b1) begin
        // note single bit
        State <= S3;
      end
      if(i == 2'b0-) begin
        // note dont care signal
        State <= S1;
      end
    end
    s3 : begin
      //============================================== 
      case(i)
            // alternative assignment
      2'b11 : begin
        State <= S0;
      end
      2'b10 : begin
        State <= S2;
      end
      default : begin
        State <= S3;
        // Default needed here
      end
      endcase
    end
    endcase
  end
  //------------------------ Output process -----------------------
  always @(State, i) begin
    case(state)
    s0 : begin
      //==========================================
      case(i)
      2'b01 : begin
        O <= 2'b11;
      end
      2'b11 : begin
        O <= 2'b00;
      end
      default : begin
        O <= 2'b01;
      end
      endcase
    end
    s1 : begin
      //==========================================
      case(i)
      2'b01 : begin
        O <= 2'b11;
      end
      2'b11 : begin
        O <= 2'b00;
      end
      default : begin
        O <= 2'b01;
      end
      endcase
    end
    s2 : begin
      //==========================================
      case(i)
      2'b1- : begin
        O <= 2'b01;
      end
      2'b0- : begin
        O <= 2'b10;
      end
      default : begin
        O <= 2'b11;
      end
      endcase
    end
    s3 : begin
      //==========================================
      case(i)
      2'b11 : begin
        O <= 2'b10;
      end
      2'b10 : begin
        O <= 2'b11;
      end
      default : begin
        O <= 2'b--;
      end
      endcase
    end
    endcase
  end
endmodule

