  B = 1,
  C = 2;
reg [1:0] present_state; reg [1:0] next_state;
  always @(posedge clock, posedge reset, posedge next_state) begin
    if(reset == 1'b1) begin
      present_state <= A;
    end else begin
      present_state <= next_state;
    end
  end
  always @(clock, reset, input, present_state) begin
    case(present_state)
    A : begin
      output <= 1'b0;
      if(input == 1'b1) begin
        next_state <= B;
      end
      else begin
        next_state <= A;
      end
    end
    B : begin
      output <= 1'b0;
      if(input == 1'b1) begin
        next_state <= C;
      end
      else begin
        next_state <= A;
      end
    end
    C : begin
      if(input == 1'b1) begin
        output <= 1'b1;
        next_state <= C;
      end
      else begin
        output <= 1'b0;
        next_state <= A;
      end
    end
    endcase
  end
endmodule

module blinky(
input wire SYS_CLK_N,
input wire SYS_CLK_P,
output reg [7:0] USER_LED
);
//System Clock Negative input port
//System Clock Positive input port
//Output byte representing the 8 LEDs
//Declare signals
wire SYS_CLK_BUF;
wire SYS_CLK_SLOW;
wire SYS_CLK_FB;
  //BUFG for SYS_CLOCK, the differential buffer for the System Clock
  IBUFGDS #(
      .DIFF_TERM(TRUE),
    // Differential Termination
    .IBUF_LOW_PWR(FALSE),
    // Low power (TRUE) vs. performance (FALSE)
    .IOSTANDARD(7'bLVDS_25))
  IBUFGDS_SYS_CLK(
      .I(SYS_CLK_P),
    .IB(SYS_CLK_N),
    .O(SYS_CLK_BUF));
  //PLL_BASE, the phase-lock loop
  PLL_BASE #(
      .BANDWIDTH(9'bOPTIMIZED),
    .CLKIN_PERIOD(10.0),
    .CLKOUT0_DIVIDE(1),
    .CLKOUT1_DIVIDE(1),
    .CLKOUT2_DIVIDE(1),
    .CLKOUT3_DIVIDE(1),
    .CLKOUT4_DIVIDE(1),
    .CLKOUT5_DIVIDE(1),
    .CLKOUT0_PHASE(0.000),
    .CLKOUT1_PHASE(0.000),
    .CLKOUT2_PHASE(0.000),
    .CLKOUT3_PHASE(0.000),
    .CLKOUT4_PHASE(0.000),
    .CLKOUT5_PHASE(0.000),
    .CLKOUT0_DUTY_CYCLE(0.500),
    .CLKOUT1_DUTY_CYCLE(0.500),
    .CLKOUT2_DUTY_CYCLE(0.500),
    .CLKOUT3_DUTY_CYCLE(0.500),
    .CLKOUT4_DUTY_CYCLE(0.500),
    .CLKOUT5_DUTY_CYCLE(0.500),
    .COMPENSATION(8'bINTERNAL),
    .DIVCLK_DIVIDE(1),
    //Defined clock division
    .CLKFBOUT_MULT(4),
    .CLKFBOUT_PHASE(0.0),
    .REF_JITTER(0.1))
  PLL_SYS_CLK(
      .CLKFBIN(SYS_CLK_FB),
    .CLKIN(SYS_CLK_BUF),
    .RST(1'b0),
    .CLKFBOUT(SYS_CLK_FB),
    .CLKOUT0(SYS_CLK_SLOW),
    //The output used 
    .CLKOUT1(/* open */),
    .CLKOUT2(/* open */),
    .CLKOUT3(/* open */),
    .CLKOUT4(/* open */),
    .CLKOUT5(/* open */),
    .LOCKED(/* open */));
  //Run each time clock changes state
  always @(posedge SYS_CLK_SLOW) begin : P1
  //defining the LED behaviour as a stand alone process
    reg [7:0] led_status1 = 8'b00000001;
  //various variables used during the behaviour
    reg [7:0] led_status2 = 8'b10000000;
    reg [31:0] shift_dir = 0;
    reg [31:0] count = 0;
    //each clock edge
    count = count + 1;
    //a simple counter is used to sub-divide the clock, so the change in the LEDs is visible to the naked eye.
    if(count > 400000000) begin
      //Shift LEDs
      USER_LED <= led_status1 | led_status2;
      if(shift_dir == 0) begin
        //Shift left
        led_status1 = (led_status1) << 1;
        // conversion to a STD_LOGIC_VECTOR is used to take advantage of the shifts
        led_status2 = (led_status2) >> 1;
      end
      else begin
        //Shift right
        led_status1 = (led_status1) >> 1;
        led_status2 = (led_status2) << 1;
      end
      //Reverse direction if necessary
      if(led_status1 == 8'b10000000) begin
        shift_dir = 1;
      end
      else if(led_status1 == 8'b00000001) begin
        shift_dir = 0;
      end
      count = 0;
    end
  end
endmodule

