module execute_stage(
input wire clk,
input wire reset_n,
input wire stall,
input wire noop_in,
input wire ubranch_in,
input wire cbranch_in,
input wire [31:0] ex_w_addr,
input wire [31:0] ex_w_data,
input wire ex_we,
input wire [31:0] start_address,
input wire [31:0] a_in,
input wire [31:0] b_in,
input wire [31:0] c_in,
input wire [31:0] addr_a,
input wire [31:0] addr_b,
input wire [31:0] addr_c,
input wire [31:0] next_pc,
output reg cbranch_out,
output reg [31:0] cbranch_addr,
input wire [31:0] da_in,
input wire [31:0] db_in,
output reg [31:0] w_data,
output reg [31:0] w_addr,
output reg we_out
);
//inputs
//outputs
// memory
//signals
wire [31:0] da_fwd;
wire [31:0] db_fwd;  // --for self-modifying instruction forwarding
//	signal a_fwd : std_logic_vector(31 downto 0);
//	signal b_fwd : std_logic_vector(31 downto 0);
//	signal c_fwd : std_logic_vector(31 downto 0);
wire [31:0] sub;
wire cbranch;
wire we;
  //determine forwarding
  assign da_fwd = (a_in == ex_w_addr && ex_we == 1'b1) ? ex_w_data : da_in;
  assign db_fwd = (b_in == ex_w_addr && ex_we == 1'b1) ? ex_w_data : db_in;
  // --self-modifying instruction forwarding (NOT USED. To enable this, replace instances of a with a_fwd, b with b_fwd ...)
  //	a_fwd <= ex_db when (addr_a = ex_b) else a_in;
  //	b_fwd <= ex_db when (addr_b = ex_b) else b_in;
  //	c_fwd <= ex_db when (addr_c = ex_b) else c_in;
  //'execute'
  assign sub = (db_fwd) - (da_fwd);
  //determine cbranch
  assign cbranch = (sub <= 0 && !(noop_in == 1'b1) && !(ubranch_in == 1'b1) && !(next_pc == c_in)) ? 1'b1 : 1'b0;
  //determine whether to write
  assign we = (!(noop_in == 1'b1) && !(cbranch_in == 1'b1)) ? 1'b1 : 1'b0;
  always @(posedge clk, posedge reset_n, posedge start_address) begin
    if((reset_n == 1'b0)) begin
      //initial values
      w_data <= 32'b00000000000000000000000000000000;
      w_addr <= (start_address) + (7);
      //as if the third instruction is executing
      we_out <= 1'b0;
      cbranch_out <= 1'b0;
    end else begin
      if((stall == 1'b0)) begin
        cbranch_out <= cbranch;
        cbranch_addr <= c_in;
        if((!(noop_in == 1'b1))) begin
          w_addr <= b_in;
        end
        //to prevent undefined address output after reset
        w_data <= sub;
        we_out <= we;
      end
      else begin
        //hold previous outputs on stall (automatic)
      end
    end
  end
endmodule

