module sumador #(
    parameter WIDTH = 3
) (
    input [WIDTH-1:0] a,
    input [WIDTH-1:0] b,
    output [WIDTH-1:0] sum,
    output overflow,
    output carry_out
);

    wire [WIDTH:0] extended_a, extended_b, extended_sum;

    // Sign extend inputs
    assign extended_a = {a[WIDTH-1], a};
    assign extended_b = {b[WIDTH-1], b};

    // Perform addition
    assign extended_sum = extended_a + extended_b;

    // Extract sum and carry_out
    assign sum = extended_sum[WIDTH-1:0];
    assign carry_out = extended_sum[WIDTH];

    // Detect overflow
    assign overflow = (a[WIDTH-1] == b[WIDTH-1]) && (a[WIDTH-1] != sum[WIDTH-1]);

    // Waveform dump for cocotb
    `ifdef COCOTB_SIM
    initial begin
        $dumpfile ("sumador.vcd");
        $dumpvars (0, sumador);
        #1;
    end
    `endif

endmodule

