module counter_en(
input wire Clk,
input wire Rst,
input wire Enable,
output wire [1:0] Cnt
);
// Operation:
// Count number of cycles @Enable is up.
// Increase input from 0 to 2^N_BITS - 1 then start from zero again.
reg [N_BITS - 1:0] count;
  assign Cnt = count;
  always @(posedge Clk) begin
    if(Enable == 1'b1) begin
      count <= count + 1;
    end
    if(Rst == 1'b1) begin
      count <= {((N_BITS - 1)-(0)+1){1'b0}};
    end
  end
endmodule

module falling_edge_detector(
input wire clk,
input wire rst,
input wire input,
output reg edge
);
  always @(posedge clk, posedge rst) begin : P1
    reg previous = 1'b0;
    if(rst == 1'b1) begin
      previous = 1'b0;
      edge <= 1'b0;
    end else begin
      if(previous == 1'b1 && input == 1'b0) begin
        edge <= 1'b1;
      end
      else begin
        edge <= 1'b0;
      end
      previous = input;
    end
  end
endmodule

module PCDecoder (
    input [31:0] virtualPC,
    output [9:0] physicalPC,
    output invalidPC
);

    wire [31:0] offsetPC;
    wire [31:0] shiftedPC;

    // Subtract base address and shift right by 2
    assign offsetPC = virtualPC - 32'h400000;
    assign shiftedPC = offsetPC >> 2;

    // Assign lower 10 bits to physical PC
    assign physicalPC = shiftedPC[9:0];

    // Check if virtual PC is within valid range
    assign invalidPC = (virtualPC < 32'h400000) || (virtualPC > 32'h400fff);

endmodule

module clk_mod(
input wire entrada,
input wire reset,
output wire salida
);
reg temporal;
reg [31:0] contador = 0;
  always @(posedge reset, posedge entrada) begin
    if((reset == 1'b1)) begin
      temporal <= 1'b0;
      contador <= 0;
    end else begin
      if((contador == 25000)) begin
        //ESTA VARIABLE ES LA QUE HACE QUE SE MODIFICA LA FRECUENCIA. HAY QUE DIVIDIR LA DEL RELOJ DE LA TARJETA ENTRE LA DESEADA Y DIVIDIRLA ENTRE 2 (semiperiodo).
        temporal <=  ~(temporal);
        contador <= 0;
      end
      else begin
        contador <= contador + 1;
      end
    end
  end
  assign salida = temporal;
endmodule

