module clk_bps_v (
    input wire clk,
    input wire rst_n,
    input wire in,
    input wire bps_start,
    output wire clk_bps
);

    // Parameters
    parameter CLK_PERIOD = 20;  // 20ns, 50MHz
    parameter BPS_SET = 96;
    parameter BPS_PA = CLK_PERIOD * 1000000 / BPS_SET;
    parameter BPS_PA_2 = BPS_PA / 2;

    // Internal signals
    reg [12:0] cnt;
    reg clk_bps_r;

    // Counter logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 13'd0;
        end else if (!in || !bps_start) begin
            cnt <= 13'd0;
        end else if (cnt == BPS_PA) begin
            cnt <= 13'd0;
        end else begin
            cnt <= cnt + 1'b1;
        end
    end

    // Baud rate clock generation
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            clk_bps_r <= 1'b0;
        end else if (!in || !bps_start) begin
            clk_bps_r <= 1'b0;
        end else if (cnt == BPS_PA_2) begin
            clk_bps_r <= 1'b1;
        end else begin
            clk_bps_r <= 1'b0;
        end
    end

    // Output assignment
    assign clk_bps = clk_bps_r;

endmodule

