module sync_ap_status(
input wire rst,
input wire ap_clk,
input wire ap_flag,
input wire axi_clk,
output wire flag,
input wire flag_clr
);
reg wr_cnt;
reg rd_cnt;
wire wr_en;
wire rd_en;
reg full_n;
reg empty_n;
  assign wr_en = ap_flag & full_n;
  always @(posedge ap_clk, posedge rst) begin
    if((rst == 1'b1)) begin
      wr_cnt <= 1'b0;
    end else begin
      if((wr_en == 1'b1)) begin
        wr_cnt <=  ~(wr_cnt);
      end
    end
  end
  assign rd_en = flag_clr & empty_n;
  always @(posedge axi_clk, posedge rst) begin
    if((rst == 1'b1)) begin
      rd_cnt <= 1'b0;
    end else begin
      if((rd_en == 1'b1)) begin
        rd_cnt <=  ~(rd_cnt);
      end
    end
  end
  always @(posedge ap_clk, posedge rst) begin
    if((rst == 1'b1)) begin
      full_n <= 1'b0;
    end else begin
      if((full_n == 1'b1)) begin
        full_n <=  ~(wr_en);
      end
      else begin
        full_n <=  ~(wr_cnt ^ rd_cnt);
      end
    end
  end
  always @(posedge axi_clk, posedge rst) begin
    if((rst == 1'b1)) begin
      empty_n <= 1'b0;
    end else begin
      if((empty_n == 1'b1)) begin
        empty_n <=  ~(rd_en);
      end
      else begin
        empty_n <= wr_cnt ^ rd_cnt;
      end
    end
  end
  assign flag = empty_n;
endmodule

