    always @(posedge CLK_i or negedge RSTn_i) begin
        if (!RSTn_i) begin
            LED_o <= 4'b0001;
            C0 <= 32'd0;
        end else begin
            if (C0 == 32'd99_999_999) begin
                C0 <= 32'd0;
                if (LED_o == 4'b1000)
                    LED_o <= 4'b0001;
                else
                    LED_o <= LED_o << 1;
