module mem_reader(
input wire Clk,
input wire Rst,
input wire Enable,
input wire [10:0] FrameLen,
input wire [27:0] FrameIval,
output wire [10:0] MemAddr,
input wire [7:0] MemData,
output reg BusPkt,
output wire [7:0] BusData
);
reg [27:0] time_cnt = 1'b0; wire [27:0] NEXT_time_cnt = 1'b0;
  assign NEXT_time_cnt = time_cnt + 1;
  assign MemAddr = time_cnt[10:0];
  assign BusData = MemData;
  always @(posedge Clk) begin : P1
    reg frameSent = 1'b0;
    reg saveEna = 1'b0;
    time_cnt <= NEXT_time_cnt;
    BusPkt <= 1'b0;
    if(time_cnt[10:0] < FrameLen && frameSent == 1'b0) begin
      BusPkt <= saveEna;
    end
    else begin
      frameSent = 1'b1;
    end
    if(rst == 1'b1 || NEXT_time_cnt >= FrameIval) begin
      time_cnt <= {28{1'b0}};
      frameSent = 1'b0;
      saveEna = Enable;
    end
  end
endmodule

module add_204(
output wire [24:0] output,
input wire [24:0] in_b,
input wire [24:0] in_a
);
wire [26:0] carry_inA;
wire [26:0] carry_inB;
wire [26:0] carry_res;
  // To handle the CI input, the operation is '1' + CI
  // If CI is not present, the operation is '1' + '0'
  assign carry_inA = {1'b0,in_a,1'b1};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) + (carry_inB);
  // Set the outputs
  assign output = carry_res[25:1];
endmodule

