    input wire [6:0] raddr,
    input wire [6:0] waddr,
    input wire wren,
    output reg signed [11:0] S_out
);

    reg signed [11:0] buf1 [7:0][7:0];
    reg signed [11:0] buf2 [7:0][7:0];

    wire [2:0] xr, yr, xw, yw;

    assign xr = raddr[5:3];
    assign yr = raddr[2:0];
    assign xw = waddr[2:0];
    assign yw = waddr[5:3];

    always @(posedge clk) begin
        if (wren) begin
            if (waddr[6] == 1'b0)
                buf1[yw][xw] <= S_in;
            else
                buf2[yw][xw] <= S_in;
        end

        if (raddr[6] == 1'b0)
            S_out <= buf1[yr][xr];
        else
            S_out <= buf2[yr][xr];
    end

endmodule

