module memory_register (
    input wire clk,
    input wire write,
    input wire read,
    input wire [31:0] address,
    input wire [31:0] data,
    output reg [31:0] read_data
);

    // Declare memory array
    reg [31:0] mem [0:9];

    // Initialize memory with preset values
    initial begin
        mem[0] = 32'h00000000;
        mem[1] = 32'h11111111;
        mem[2] = 32'h22222222;
        mem[3] = 32'h33333333;
        mem[4] = 32'h44444444;
        mem[5] = 32'h55555555;
        mem[6] = 32'h66666666;
        mem[7] = 32'h77777777;
        mem[8] = 32'h88888888;
        mem[9] = 32'h99999999;
    end

    // Write operation (synchronous)
    always @(posedge clk) begin
        if (write) begin
            mem[address[3:0]] <= data;
        end
    end

    // Read operation (asynchronous)
    always @(*) begin
        if (read) begin
            read_data = mem[address[3:0]];
        end
        else begin
            read_data = 32'h00000000;
        end
    end

endmodule

module clockMaster (
    input logic clk,
    output logic scriptclk,
    output logic gameclk,
    output logic bossclk
);

    logic [23:0] scounter, gcounter, bcounter;
    logic [23:0] scriptCount, gameCount, bossCount;

    assign scriptCount = 24'b100110001001011010000000;
    assign gameCount = 24'b100001101011110000100000;
    assign bossCount = 24'b101111101011110000100000;

    always_ff @(posedge clk) begin
        if (scounter == scriptCount) begin
            scriptclk <= 1'b1;
            scounter <= 24'd0;
        end else begin
            scriptclk <= 1'b0;
            scounter <= scounter + 1'b1;
        end
    end

    always_ff @(posedge clk) begin
        if (gcounter == gameCount) begin
            gameclk <= 1'b1;
            gcounter <= 24'd0;
        end else begin
            gameclk <= 1'b0;
            gcounter <= gcounter + 1'b1;
        end
    end

    always_ff @(posedge clk) begin
        if (bcounter == bossCount) begin
            bossclk <= 1'b1;
            bcounter <= 24'd0;
        end else begin
            bossclk <= 1'b0;
            bcounter <= bcounter + 1'b1;
        end
    end

endmodule

