module lru_4way (
    input wire [1:0] index_i,
    input wire access,
    input wire update,
    input wire clk,
    input wire rst,
    output reg [1:0] index_o
);

    reg [1:0] lru_list [3:0];

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            lru_list[0] <= 2'b00;
            lru_list[1] <= 2'b00;
            lru_list[2] <= 2'b00;
            lru_list[3] <= 2'b00;
        end
        else if (access && !update) begin
            lru_list[0] <= (index_i == 2'b00) ? 2'b00 : (lru_list[0] == 2'b11) ? 2'b11 : lru_list[0] + 1;
            lru_list[1] <= (index_i == 2'b01) ? 2'b00 : (lru_list[1] == 2'b11) ? 2'b11 : lru_list[1] + 1;
            lru_list[2] <= (index_i == 2'b10) ? 2'b00 : (lru_list[2] == 2'b11) ? 2'b11 : lru_list[2] + 1;
            lru_list[3] <= (index_i == 2'b11) ? 2'b00 : (lru_list[3] == 2'b11) ? 2'b11 : lru_list[3] + 1;
        end
        else if (!access && update) begin
            lru_list[index_i] <= 2'b00;
        end
    end

    always @(*) begin
        if (lru_list[0] > lru_list[1]) begin
            if (lru_list[2] > lru_list[3]) begin
                index_o = (lru_list[0] > lru_list[2]) ? 2'b00 : 2'b10;
            end else begin
                index_o = (lru_list[0] > lru_list[3]) ? 2'b00 : 2'b11;
            end
        end else begin
            if (lru_list[2] > lru_list[3]) begin
                index_o = (lru_list[1] > lru_list[2]) ? 2'b01 : 2'b10;
            end else begin
                index_o = (lru_list[1] > lru_list[3]) ? 2'b01 : 2'b11;
            end
        end
    end

endmodule

module ErrorGenerator(
input wire Clock,
output reg [2:0] Qout
);
wire [2:0] SymbolRandom;
reg ErrorStop;
wire [2:0] Result;
wire [2:0] Dsa0;
wire [2:0] Dsa1;
wire [2:0] Dsa2;
wire [2:0] Dsa3;
wire [2:0] Dsa4;
wire [2:0] Dsa5;
wire [2:0] Dsa6;
wire [2:0] Qsa0;
wire [2:0] Qsa1;
wire [2:0] Qsa2;
wire [2:0] Qsa3;
wire [2:0] Qsa4;
wire [2:0] Qsa5;
wire [2:0] Qsa6;
reg [2:0] counter_rnd = 3'b000;
  flipflop ffsymbola0(
      Dsa0,
    Clock,
    1'b0,
    Qsa0);
  flipflop ffsymbola1(
      Dsa1,
    Clock,
    1'b0,
    Qsa1);
  flipflop ffsymbola2(
      Dsa2,
    Clock,
    1'b0,
    Qsa2);
  flipflop ffsymbola3(
      Dsa3,
    Clock,
    1'b0,
    Qsa3);
  flipflop ffsymbola4(
      Dsa4,
    Clock,
    1'b0,
    Qsa4);
  flipflop ffsymbola5(
      Dsa5,
    Clock,
    1'b0,
    Qsa5);
  flipflop ffsymbola6(
      Dsa6,
    Clock,
    1'b0,
    Qsa6);
  assign Result[0] = Qsa2[1] ^ Qsa4[1] ^ Qsa3[1] ^ Qsa2[2] ^ Qsa0[0] ^ Qsa2[0] ^ Qsa1[2] ^ Qsa5[0];
  assign Result[1] = Qsa4[0] ^ Qsa1[0] ^ Qsa5[0] ^ Qsa2[0] ^ Qsa2[2] ^ Qsa1[2] ^ Qsa0[2];
  assign Result[2] = Qsa2[2] ^ Qsa0[2] ^ Qsa2[2] ^ Qsa4[1] ^ Qsa1[1] ^ Qsa5[1];
  assign SymbolRandom[0] = Qsa3[0] ^ Qsa5[2] ^ Qsa1[1] ^ Qsa6[1] ^ Qsa3[2] ^ Qsa1[2] ^ Qsa5[2];
  assign SymbolRandom[1] = Qsa5[1] ^ Qsa1[1] ^ Qsa2[1] ^ Qsa4[0] ^ Qsa0[2] ^ Qsa6[0];
  assign SymbolRandom[2] = Qsa1[2] ^ Qsa0[2] ^ Qsa0[0] ^ Qsa3[2] ^ Qsa3[1];
  assign Dsa0 = Qsa1;
  assign Dsa1 = Qsa2;
  assign Dsa2 = Qsa3;
  assign Dsa3 = Qsa4;
  assign Dsa4 = Qsa5;
  assign Dsa5 = Qsa6;
  assign Dsa6 = Result;
  always @(posedge Clock, posedge Result) begin
    counter_rnd <= counter_rnd + 1;
    if(((Result[0] ^ Result[2] ^ Result[1]) == 1'b1 && ErrorStop != 1'b1)) begin
      Qout[0] <= SymbolRandom[0];
      Qout[1] <= SymbolRandom[1];
      Qout[2] <= SymbolRandom[2];
      ErrorStop <= 1'b1;
    end
    else begin
      Qout <= 3'b000;
    end
    if((counter_rnd == 3'b111)) begin
      counter_rnd <= 3'b001;
      ErrorStop <= 1'b0;
    end
  end
endmodule

module sub_370(
output wire [31:0] result,
input wire [31:0] in_a,
input wire [31:0] in_b
);
wire [33:0] carry_inA;
wire [33:0] carry_inB;
wire [33:0] carry_res;
  // To handle the CI input, the operation is '0' - CI
  // If CI is not present, the operation is '0' - '0'
  assign carry_inA = {1'b0,in_a,1'b0};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) - (carry_inB);
  // Set the outputs
  assign result = carry_res[32:1];
endmodule

module posy (
    input wire clk,
    input wire rst,
    input wire change,
    output reg [9:0] o_signal
);

    // State encoding
    localparam [1:0] s0 = 2'b00,
                     s1 = 2'b01,
                     s2 = 2'b10,
                     s3 = 2'b11;

    // State register
    reg [1:0] rState, nState;

    // State transition logic
    always @(*) begin
        case (rState)
            s0: nState = s1;
            s1: nState = change ? s2 : s1;
            s2: nState = change ? s3 : s2;
            s3: nState = change ? s1 : s3;
            default: nState = s0;
        endcase
    end

    // State register update
    always @(posedge clk or posedge rst) begin
        if (rst)
            rState <= s0;
        else
            rState <= nState;
    end

    // Output logic
    reg [9:0] salida;
    always @(*) begin
        case (rState)
            s0: salida = 10'b0000000000;
            s1: salida = 10'b0011001000;
            s2: salida = 10'b0011100110;
            s3: salida = 10'b0100000000;
            default: salida = 10'b0000000000;
        endcase
    end

    // Output assignment
    always @(posedge clk or posedge rst) begin
        if (rst)
            o_signal <= 10'b0000000000;
        else
            o_signal <= salida;
    end

endmodule

