module glitcher (
    input wire clk_96m,
    input wire glitch,
    inout wire cpu_reset
);

    parameter Glitch_Start = 34720;
    parameter Glitch_Cycles = 1;

    reg [15:0] tick_cnt;
    reg cpu_glitch;

    always @(posedge clk_96m or negedge clk_96m) begin
        if (glitch) begin
            if (tick_cnt == Glitch_Start) begin
                cpu_glitch <= 1'b0;
            end else if (tick_cnt == Glitch_Start + Glitch_Cycles) begin
                cpu_glitch <= 1'b1;
            end
            tick_cnt <= tick_cnt + 1'b1;
        end else begin
            cpu_glitch <= 1'bz;
            tick_cnt <= 16'd0;
        end
    end

    assign cpu_reset = cpu_glitch;

endmodule

module grain128(
input wire CLK_I,
input wire CLKEN_I,
input wire ARESET_I,
input wire KEY_I,
input wire IV_I,
input wire INIT_I,
output wire KEYSTREAM_O,
output wire KEYSTREAM_VALID_O
);
parameter DEBUG=false;
parameter FAST=false;
// attempt manual register balancing
parameter [1:0]
  IDLE = 0,
  INIT_KEYIV = 1,
  INIT_RUN = 2;
reg [1:0] state;
reg [8:0] cnt;
reg inject_input; reg set_injected_iv; reg allow_output;
reg add_output;
wire output_bit; reg output_bit_d; reg allow_output_d;
  assign KEYSTREAM_O = output_bit_d;
  assign KEYSTREAM_VALID_O = allow_output_d;
  generate if (FAST == false) begin: slow_design
      grain128_datapath_slow #(
          .DEBUG(DEBUG))
    functions0(
          .CLK_I(CLK_I),
      .CLKEN_I(CLKEN_I),
      .ARESET_I(ARESET_I),
      .KEY_I(KEY_I),
      .IV_I(IV_I),
      .INJECT_INPUT_I(inject_input),
      .PAD_IV_I(set_injected_iv),
      .ADD_OUTPUT_I(add_output),
      .H_O(output_bit));
  end
  endgenerate
  generate if (FAST == true) begin: fast_design
      grain128_datapath_fast #(
          .DEBUG(DEBUG))
    functions1(
          .CLK_I(CLK_I),
      .CLKEN_I(CLKEN_I),
      .ARESET_I(ARESET_I),
      .KEY_I(KEY_I),
      .IV_I(IV_I),
      .INJECT_INPUT_I(inject_input),
      .PAD_IV_I(set_injected_iv),
      .ADD_OUTPUT_I(add_output),
      .H_O(output_bit));
  end
  endgenerate
  // output registers:
  // (in case the "user" forgets this is at 
  //  his end and kills my fmax)
  // 
  always @(posedge CLK_I, posedge ARESET_I) begin
    if(ARESET_I == 1'b1) begin
      output_bit_d <= 1'b0;
      allow_output_d <= 1'b0;
    end else begin
      if(CLKEN_I == 1'b1) begin
        output_bit_d <= output_bit;
        allow_output_d <= allow_output;
      end
    end
  end
  // the counter:
  always @(posedge CLK_I) begin
    if(CLKEN_I == 1'b1) begin
      if(state == IDLE) begin
        cnt <= 11'b0_0000_0001;
      end
      else begin
        cnt <= cnt + 1;
      end
    end
  end
  // the controller fsm:
  always @(posedge CLK_I, posedge ARESET_I) begin
    if(ARESET_I == 1'b1) begin
      state <= IDLE;
      inject_input <= 1'b0;
      set_injected_iv <= 1'b0;
      add_output <= 1'b0;
      allow_output <= 1'b0;
    end else begin
      if(CLKEN_I == 1'b1) begin
        case(state)
        IDLE : begin
          if(INIT_I == 1'b1) begin
            state <= INIT_KEYIV;
            inject_input <= 1'b1;
            set_injected_iv <= 1'b0;
            allow_output <= 1'b0;
          end
        end
        INIT_KEYIV : begin
          if(cnt[6:5] == 2'b11) begin
            set_injected_iv <= 1'b1;
          end
          if(cnt[7] == 1'b1) begin
            state <= INIT_RUN;
            inject_input <= 1'b0;
            add_output <= 1'b1;
          end
        end
        INIT_RUN : begin
          if(cnt[8:7] == 2'b11) begin
            state <= IDLE;
            add_output <= 1'b0;
            allow_output <= 1'b1;
          end
        end
        default : begin
          state <= IDLE;
        end
        endcase
      end
    end
  end
endmodule

