module atmega_wb8_wrapper(
input wire [6:0] Address_H,
inout wire [7:0] DA,
input wire ALE,
input wire RD,
input wire WR,
output wire DIR_buffer,
output wire wbm_clk,
output wire wbm_rst,
output wire [14:0] wbm_address,
input wire [7:0] wbm_readdata,
output wire [7:0] wbm_writedata,
output wire wbm_strobe,
output wire wbm_write,
input wire wbm_ack,
output wire wbm_cycle,
input wire clk,
input wire reset
);
// Atmega128 port
// Wishbone port
// clock 50MHz and reset
reg write;
reg strobe;
reg cycle;
reg [7:0] writedata;
reg [14:0] address;
  // connect clock and reset
  assign wbm_clk = clk;
  assign wbm_reset = reset;
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      strobe <= 1'b0;
      write <= 1'b0;
      cycle <= 1'b0;
      address <= {15{1'b0}};
      writedata <= {8{1'b0}};
    end else begin
      // Address bus latching
      if(ALE == 1'b1) begin
        address[14:8] <= Address_H;
        address[7:0] <= DA;
      end
      else begin
        address <= address;
      end
      writedata <= DA;
      // signals controls
      strobe <=  ~(RD & WR);
      cycle <=  ~(RD & WR);
      write <=  ~WR;
    end
  end
  assign wbm_write = write;
  assign wbm_strobe = strobe;
  assign wbm_cycle = cycle;
  assign wbm_address = address;
  assign wbm_writedata = (write == 1'b1) ? writedata : {8{1'b0}};
  // buffer direction
  assign DIR_buffer = write == 1'b0 && strobe == 1'b1 ? 1'b1 : 1'b0;
  assign DA = write == 1'b0 && strobe == 1'b1 ? wbm_readdata : {8{1'bZ}};
endmodule

module ROM(
input wire cs,
input wire rd,
input wire [4:0] dir,
output reg [7:0] data
);
  always @(cs, rd, dir) begin
    if(cs == 1'b1 && rd == 1'b0) begin
      case(dir)
      5'b00000 : begin
        data <= 8'b00011000;
        // JMP MAIN
      end
      5'b00001 : begin
        data <= 8'b00000011;
        // 
      end
      5'b00010 : begin
        data <= 8'b00000000;
        // VI
      end
      5'b00011 : begin
        data <= 8'b00011000;
        // MAIN:MOV ACC,CTE
      end
      5'b00100 : begin
        data <= 8'b00000000;
        // 
      end
      5'b00101 : begin
        data <= 8'b00010000;
        // MOV A,ACC			;A=Cont
      end
      5'b00110 : begin
        data <= 8'b00011000;
        // CICLO:MOV ACC,CTE	;INIRAM
      end
      5'b00111 : begin
        data <= 8'b11111000;
        // 
      end
      5'b01000 : begin
        data <= 8'b01001000;
        // ADD ACC,A  		;INIRAM+Cont
      end
      5'b01001 : begin
        data <= 8'b00101000;
        // MOV DPTR,ACC	 
      end
      5'b01010 : begin
        data <= 8'b00001000;
        // MOV ACC,A 
      end
      5'b01011 : begin
        data <= 8'b00110000;
        // MOV [DPTR],ACC 	; [INIRAM+Cont]=Cont
      end
      5'b01100 : begin
        data <= 8'b00011000;
        // MOV ACC,CTE1
      end
      5'b01101 : begin
        data <= 8'b00000001;
        //
      end
      5'b01110 : begin
        data <= 8'b01001000;
        // ADD ACC,A			;Cont+1
      end
      5'b01111 : begin
        data <= 8'b01101000;
