module Memory (
    input wire clk,
    input wire MemRead,
    input wire MemWrite,
    input wire [63:0] Address,
    input wire [63:0] WriteData,
    output reg [63:0] ReadData
);

    reg [63:0] Instr_DataMemory [0:1023];

    initial begin
        // Initialize instruction memory
        Instr_DataMemory[0] = 64'h0000000000000000;
        Instr_DataMemory[1] = 64'h0000000000000000;
        Instr_DataMemory[2] = 64'h0000000000000000;
        // ... (more instruction initializations)
        Instr_DataMemory[52] = 64'h0000000000000000;

        // Initialize data memory
        Instr_DataMemory[800] = 64'h0000000000000001;
        Instr_DataMemory[801] = 64'h0000000000000002;
        Instr_DataMemory[802] = 64'h0000000000000003;
        // ... (more data initializations)
    end

    always @(*) begin
        if (MemRead)
            ReadData = Instr_DataMemory[Address >> 3];
        else
            ReadData = Instr_DataMemory[Address >> 2];
    end

    always @(posedge clk) begin
        if (MemWrite)
            Instr_DataMemory[Address >> 3] <= WriteData;
    end

endmodule

module mult_16_8(
input wire [15:0] a,
input wire [15:0] b,
output wire [15:0] p
);
wire [31:0] internal;
wire [15:0] internal_reduced;
wire [15:0] abs_a;
wire [15:0] abs_b;
wire l_neg = 1'b0;  // sign of product
  // Compute absolute values of operands
  assign abs_a = ( ( $signed(a) < 0 ) ? -$signed(a) : a );
  assign abs_b = ( ( $signed(b) < 0 ) ? -$signed(b) : b );
  // Compute sign of product
  assign l_neg = a[15] ^ b[15];
  // Compute unsigned extendend product
  simple_mult simple_mult(
      .a(abs_a),
    .b(abs_b),
    .p(internal));
  //  internal <= std_logic_vector(unsigned(abs_a) * unsigned(abs_b));
  // Trunk product
  truncator trunc(
      .i(internal),
    .o(internal_reduced));
  //internal_reduced(15 downto 0) <= internal(23 downto 8);
  // restablish sign if needed
  assign p = l_neg == 1'b0 ? internal_reduced :  -(internal_reduced);
    //        internal_a(15 downto 0) <= a;
  //        internal_a(17) <= a(15);
  //        internal_a(16) <= a(15);
  //        internal_b(15 downto 0) <= b;
  //        internal_b(17) <= b(15);
  //        internal_b(16) <= b(15);
  //	internal <= std_logic_vector(unsigned(internal_a) * unsigned(internal_b));
  //	p(15 downto 0) <= internal(23 downto 8);
endmodule

