    output reg DP_RAM_regW
);

reg [7:0] color;
reg cont;

always @(posedge PCLK) begin
    if (HREF && !VSYNC) begin
        color <= D;
        if (cont == 0) begin
            DP_RAM_data_in[7:5] <= color[7:5];
            DP_RAM_data_in[4:2] <= color[2:0];
            DP_RAM_regW <= 0;
