module nowyRXTX(
input wire [15:0] data_in,
output wire [15:0] data_out,
input wire [4:0] phy_addr,
input wire [4:0] reg_addr,
input wire write_read,
input wire strt,
output wire busy,
input wire reset,
input wire clk,
output reg MDC,
inout reg MDIO
);
reg [15:0] latched_data = 1'b0;
reg [4:0] latched_phy_addr = 1'b0;
reg [4:0] latched_reg_addr = 1'b0;
reg latched_write_read = 1'b1;
reg busy_in = 1'b0;
reg [7:0] counter = 1'b0;
reg [7:0] bit_counter = 1'b0;
reg clk_div = 1'b0;
reg [45 + 1:0] read_send_data;
reg [15:0] read_receive_data;
reg [63:0] write_send_data;
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      counter <= {8{1'b0}};
      clk_div <= 1'b0;
    end
    else if(bit_counter == 65) begin
      counter <= {8{1'b0}};
      clk_div <= 1'b0;
    end
    else if(busy_in == 1'b1) begin
      if((counter == 9)) begin
        clk_div <=  ~clk_div;
        counter <= {8{1'b0}};
      end
      else begin
        counter <= counter + 1;
      end
    end
  end
  always @(posedge clk) begin
    if(reset == 1'b1) begin
      busy_in <= 1'b0;
    end
    else if(strt == 1'b1) begin
      busy_in <= 1'b1;
    end
    else if(bit_counter == 65) begin
      busy_in <= 1'b0;
    end
  end
  always @(posedge clk) begin
    if(strt == 1'b1) begin
      latched_data <= data_in;
      latched_phy_addr <= phy_addr;
      latched_reg_addr <= reg_addr;
      latched_write_read <= write_read;
    end
  end
  always @(negedge clk_div, negedge strt) begin
    if(strt == 1'b1) begin
      bit_counter <= {8{1'b0}};
    end else begin
      bit_counter <= bit_counter + 1;
    end
  end
  always @(negedge clk_div) begin
    if(reset == 1'b1) begin
      write_send_data <= {64{1'b0}};
    end
    else if(bit_counter == 0) begin
      write_send_data[63:0] <= {32'b11111111111111111111111111111111,2'b01,2'b01,latched_phy_addr[4:0],latched_reg_addr[4:0],2'bZZ,latched_data[15:0]};
    end
    else if(bit_counter > 0 && bit_counter < 65) begin
      write_send_data[63:0] <= {write_send_data[62:0],1'b0};
    end
  end
  always @(negedge clk_div) begin
    if(reset == 1'b1) begin
      read_send_data <= {((45 + 1)-(0)+1){1'b0}};
    end
    else if(bit_counter == 0) begin
      read_send_data[45:0] <= {32'b11111111111111111111111111111111,2'b01,2'b10,phy_addr[4:0],reg_addr[4:0]};
    end
    else if(bit_counter > 0 && bit_counter < 47) begin
      read_send_data[45:0] <= {read_send_data[44:0],1'b0};
    end
  end
  always @(posedge clk_div) begin
    if(reset == 1'b1) begin
      read_receive_data <= {16{1'b0}};
    end
    else if(latched_write_read == 1'b0 && bit_counter > 48 && bit_counter < 65) begin
      read_receive_data[15:1] <= read_receive_data[14:0];
      read_receive_data[0] <= MDIO;
    end
  end
  assign busy = busy_in;
  assign data_out = read_receive_data;
  always @(posedge clk) begin
    if((bit_counter > 0 && bit_counter < 65) && (bit_counter != 47 && bit_counter != 48) && latched_write_read == 1'b1) begin
      MDIO <= write_send_data[63];
    end
    else if((bit_counter > 0 && bit_counter < 47) && latched_write_read == 1'b0) begin
      MDIO <= read_send_data[45];
    end
    else begin
      MDIO <= 1'bZ;
    end
  end
  always @(posedge clk) begin
    if(bit_counter > 0 && bit_counter < 65) begin
      MDC <= clk_div;
    end
    else begin
      MDC <= 1'bZ;
    end
  end
endmodule

module CanisterCounter(
input wire clk,
input wire reset,
input wire enable,
input wire sync,
input wire LasersChanged,
output reg CanisterCountChanged,
input wire DoorSiteLaser_I,
input wire RejectBinLaser_I,
input wire AcceptBinLaser_I,
output wire [7:0] CanisterCount_O,
output wire done
);
//for clock and reset signal
//input events
//output events
//input variables
//type was BOOL
//type was BOOL
//type was BOOL
//output variables
//type was BYTE
//for done signal
// Build an enumerated type for the state machine
parameter [0:0]
  STATE_Start = 0;
  // Register to hold the current state
reg state = STATE_Start;  // signals to store variable sampled on enable 
reg DoorSiteLaser = 1'b0;  //register for input
reg RejectBinLaser = 1'b0;  //register for input
reg AcceptBinLaser = 1'b0;  //register for input
// signals to rename outputs 
reg [7:0] CanisterCount = 1'b0;  // signals for enabling algorithms	
reg ChangeCount_alg_en = 1'b0;
reg ChangeCount_alg_done = 1'b1;  // signal for algorithm completion
reg AlgorithmsStart = 1'b0;
wire AlgorithmsDone;
  // Registers for data variables (only updated on relevant events)
  always @(posedge clk) begin
    if(sync == 1'b1) begin
      if(LasersChanged == 1'b1) begin
        DoorSiteLaser <= DoorSiteLaser_I;
        RejectBinLaser <= RejectBinLaser_I;
        AcceptBinLaser <= AcceptBinLaser_I;
      end
    end
  end
  //output var renaming, no output registers as inputs are stored where they are processed
  assign CanisterCount_O = CanisterCount;
  // Logic to advance to the next state
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      state <= STATE_Start;
      AlgorithmsStart <= 1'b1;
    end else begin
      if(AlgorithmsStart == 1'b1) begin
        //algorithms should be triggered only once via this pulse signal
        AlgorithmsStart <= 1'b0;
      end
      else if(enable == 1'b1) begin
        //default values
        state <= state;
        AlgorithmsStart <= 1'b0;
        //next state logic
        if(AlgorithmsStart == 1'b0 && AlgorithmsDone == 1'b1) begin
          case(state)
          STATE_Start : begin
            if(LasersChanged == 1'b1) begin
              state <= STATE_Start;
              AlgorithmsStart <= 1'b1;
            end
          end
          endcase
        end
      end
    end
  end
  // Event outputs and internal algorithm triggers depend solely on the current state
  always @(state) begin
    //default values
    //events
    CanisterCountChanged <= 1'b0;
    //algorithms
    ChangeCount_alg_en <= 1'b0;
    case(state)
    STATE_Start : begin
      ChangeCount_alg_en <= 1'b1;
      CanisterCountChanged <= 1'b1;
    end
    endcase
  end
  // Algorithms process
  always @(posedge clk) begin
    if(AlgorithmsStart == 1'b1) begin
      if(ChangeCount_alg_en == 1'b1) begin
        // Algorithm ChangeCount
        ChangeCount_alg_done <= 1'b0;
      end
    end
    if(ChangeCount_alg_done == 1'b0) begin
      // Algorithm ChangeCount
      //begin algorithm raw text
      if(DoorSiteLaser == 1'b1) begin
        CanisterCount <= CanisterCount + 1;
      end
      if(RejectBinLaser == 1'b1 || AcceptBinLaser == 1'b1) begin
        CanisterCount <= CanisterCount - 1;
      end
      ChangeCount_alg_done <= 1'b1;
      //end algorithm raw text
    end
  end
  //Done signal
  assign AlgorithmsDone = ( ~AlgorithmsStart) & ChangeCount_alg_done;
  assign Done = AlgorithmsDone;
endmodule

