module HDU (
    input wire IC_stall, DC_stall,
    input wire [4:0] ID_Rs, ID_Rt, EX_WR_out,
    input wire EX_MemtoReg,
    input wire [1:0] EX_JumpOP,
    output reg PCWrite, IF_IDWrite, ID_EXWrite, EX_MWrite, M_WBWrite,
    output reg IF_Flush, ID_Flush, Branch_Flush,
    output reg Load_wait
);

    always @(*) begin
        // Default state
        PCWrite = 1'b1;
        IF_IDWrite = 1'b1;
        ID_EXWrite = 1'b1;
        EX_MWrite = 1'b1;
        M_WBWrite = 1'b1;
        IF_Flush = 1'b0;
        ID_Flush = 1'b0;
        Branch_Flush = 1'b0;
        Load_wait = 1'b0;

        // Jump handling
        if (EX_JumpOP != 2'b00) begin
            IF_Flush = 1'b1;
            ID_Flush = 1'b1;
        end

        // Load-use hazard detection
        if (EX_MemtoReg && (EX_WR_out == ID_Rs || EX_WR_out == ID_Rt)) begin
            PCWrite = 1'b0;
            IF_IDWrite = 1'b0;
            ID_Flush = 1'b1;
            Load_wait = 1'b1;
        end

        // Cache stall handling
        if (IC_stall || DC_stall) begin
            PCWrite = 1'b0;
            IF_IDWrite = 1'b0;
            ID_EXWrite = 1'b0;
            EX_MWrite = 1'b0;
            M_WBWrite = 1'b0;
            IF_Flush = 1'b0;
            ID_Flush = 1'b0;
            Branch_Flush = 1'b0;
        end
    end

endmodule

module trace_fifo_wrapper(
input wire clk_in,
output wire [12:0] depth_out,
input wire [55:0] inputData_in,
input wire inputValid_in,
output wire inputReady_out,
output wire [55:0] outputData_out,
output wire outputValid_out,
input wire outputReady_in
);
// Clock
// Data is clocked into the FIFO on each clock edge where both valid & ready are high
// Data is clocked out of the FIFO on each clock edge where both valid & ready are high
wire inputFull;
wire outputEmpty;
  // Invert "full/empty" signals to give "ready/valid" signals
  assign inputReady_out =  ~(inputFull);
  assign outputValid_out =  ~(outputEmpty);
  // The encapsulated FIFO
  xilinx_trace_fifo fifo(
      .clk(clk_in),
    .data_count(depth_out),
    // Production end
    .din(inputData_in),
    .wr_en(inputValid_in),
    .full(inputFull),
    // Consumption end
    .dout(outputData_out),
    .empty(outputEmpty),
    .rd_en(outputReady_in));
endmodule

