module keyboard_cont (
    input logic clock,
    input logic reset,
    input logic [7:0] pressedkey,
    output logic direction,
    output logic pause,
    output logic restart
);

    // State encoding
    localparam [3:0] 
        INIT = 4'b1101,
        FORWARD_START = 4'b1000,
        FORWARD_PAUSE = 4'b1100,
        FORWARD_RESTART = 4'b1001,
        BACKWARD_START = 4'b0000,
        BACKWARD_PAUSE = 4'b0100,
        BACKWARD_RESTART = 4'b0001;

    reg [3:0] current_state, next_state;

    // State transition logic
    always @(posedge clock or posedge reset) begin
        if (reset)
            current_state <= (current_state[3]) ? FORWARD_RESTART : BACKWARD_RESTART;
        else
            current_state <= next_state;
    end

    // Next state logic
    always @(*) begin
        next_state = current_state;
        case (current_state)
            INIT: next_state = FORWARD_START;
            FORWARD_START, FORWARD_PAUSE, FORWARD_RESTART:
                case (pressedkey)
                    8'h42: next_state = BACKWARD_START; // 'B'
                    8'h44: next_state = FORWARD_PAUSE;  // 'D'
                    8'h45: next_state = FORWARD_START;  // 'E'
                    8'h52: next_state = FORWARD_RESTART; // 'R'
                    default: next_state = current_state;
                endcase
            BACKWARD_START, BACKWARD_PAUSE, BACKWARD_RESTART:
                case (pressedkey)
                    8'h46: next_state = FORWARD_START;  // 'F'
                    8'h44: next_state = BACKWARD_PAUSE; // 'D'
                    8'h45: next_state = BACKWARD_START; // 'E'
                    8'h52: next_state = BACKWARD_RESTART; // 'R'
                    default: next_state = current_state;
                endcase
            default: next_state = current_state;
        endcase
    end

    // Output logic
    always @(*) begin
        direction = current_state[3];
        pause = current_state[2];
        restart = current_state[0];
    end

endmodule

module vga_controller (
    input wire clock,
    input wire [1:0] switch,
    output reg [2:0] disp_RGB,
    output reg hsync,
    output reg vsync
);

// Parameters for VGA timing
parameter hpixel_end = 10'd799;
parameter hdat_begin = 10'd144;
parameter hdat_end = 10'd783;
parameter hsync_begin = 10'd0;
parameter hsync_end = 10'd95;
parameter vline_end = 10'd524;
parameter vdat_begin = 10'd35;
parameter vdat_end = 10'd514;
parameter vsync_begin = 10'd0;
parameter vsync_end = 10'd1;

// Internal signals
reg vga_clk;
reg [9:0] hcount, vcount;
reg [2:0] h_dat, v_dat;
reg [2:0] data;

// Clock generation
always @(posedge clock)
    vga_clk <= ~vga_clk;

// Horizontal counter
always @(posedge vga_clk)
    if (hcount == hpixel_end)
        hcount <= 10'd0;
    else
        hcount <= hcount + 10'd1;

// Vertical counter
always @(posedge vga_clk)
    if (hcount == hpixel_end)
        if (vcount == vline_end)
            vcount <= 10'd0;
        else
            vcount <= vcount + 10'd1;

// Sync signal generation
always @(posedge vga_clk) begin
    hsync <= (hcount >= hsync_begin && hcount <= hsync_end) ? 1'b0 : 1'b1;
    vsync <= (vcount >= vsync_begin && vcount <= vsync_end) ? 1'b0 : 1'b1;
end

// Color pattern generation
always @(posedge vga_clk) begin
    h_dat <= hcount[9:7];
    v_dat <= vcount[9:7];
end

// Display mode selection
always @(*) begin
    case (switch)
        2'b00: data = h_dat;
        2'b01: data = v_dat;
        2'b10: data = h_dat ^ v_dat;
        2'b11: data = ~(h_dat ^ v_dat);
    endcase
end

// Output generation
always @(posedge vga_clk) begin
    if (hcount >= hdat_begin && hcount <= hdat_end &&
        vcount >= vdat_begin && vcount <= vdat_end)
        disp_RGB <= data;
    else
        disp_RGB <= 3'b000;
end

endmodule

