    // Write operation
    always @(posedge clk) begin
        if (rst) begin
            regs[0] <= {DATA_WIDTH{1'b0}};
        end else if (wen && (waddr != {ADDR_WIDTH{1'b0}})) begin
            regs[~waddr[ADDR_WIDTH-1:0]] <= wdata;
        end
    end

    // Read operation
    assign rdata1 = (raddr1 == {ADDR_WIDTH{1'b0}}) ? {DATA_WIDTH{1'b0}} : regs[~raddr1[ADDR_WIDTH-1:0]];
    assign rdata2 = (raddr2 == {ADDR_WIDTH{1'b0}}) ? {DATA_WIDTH{1'b0}} : regs[~raddr2[ADDR_WIDTH-1:0]];

endmodule

