module load_store_arbi (
    input wire clk,
    input wire rst,
    input wire ld_req,
    input wire str_req,
    input wire idle,
    input wire done,
    output reg ld_grnt,
    output reg str_grnt,
    output reg enable,
    output reg addr_sel,
    output reg rd_wrt_ca
);

    // State encoding
    localparam IDLE = 2'b00;
    localparam STORE = 2'b01;
    localparam LOAD = 2'b10;

    reg [1:0] state, next_state;

    // State register
    always @(posedge clk or posedge rst) begin
        if (rst)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (state)
            IDLE: begin
                if (str_req)
                    next_state = STORE;
                else if (ld_req)
                    next_state = LOAD;
                else
                    next_state = IDLE;
            end
            STORE: begin
                if (done)
                    next_state = str_req ? STORE : (ld_req ? LOAD : IDLE);
                else
                    next_state = STORE;
            end
            LOAD: begin
                if (done)
                    next_state = str_req ? STORE : (ld_req ? LOAD : IDLE);
                else
                    next_state = LOAD;
            end
            default: next_state = IDLE;
        endcase
    end

    // Output logic
    always @(*) begin
        ld_grnt = 1'b0;
        str_grnt = 1'b0;
        enable = 1'b0;
        addr_sel = 1'b0;
        rd_wrt_ca = 1'b0;

        case (state)
            IDLE: begin
                // No outputs asserted in IDLE state
            end
            STORE: begin
                enable = 1'b1;
                addr_sel = 1'b1;
                str_grnt = 1'b1;
            end
            LOAD: begin
                enable = 1'b1;
                rd_wrt_ca = 1'b1;
                ld_grnt = 1'b1;
            end
        endcase
    end

endmodule

module framer(
input wire clk,
input wire sin,
input wire resetb,
output reg SOUT,
output wire clk_div_8,
output wire decode_F628_out
);
parameter [31:0] N=16;
reg [15:0] shiftreg_16;
parameter F628 = 16'hF628;
reg decode_F628;
reg [7:0] parallel_reg;
wire parallel_clk;
wire [3:0] count_4bit;
reg [31:0] count_4bit_int;
reg [31:0] bit_counter;
  always @(posedge clk, posedge resetb) begin
    if((resetb == 1'b0)) begin
      SOUT <= 1'b0;
      shiftreg_16 <= {16{1'b0}};
    end else begin
      shiftreg_16 <= {shiftreg_16[14:0],SIN};
      SOUT <= shiftreg_16[N - 1];
    end
  end
  always @(shiftreg_16) begin
    if((shiftreg_16 == F628)) begin
      decode_F628 <= 1'b1;
    end
    else begin
      decode_F628 <= 1'b0;
    end
  end
  assign decode_F628_out = decode_F628;
  always @(posedge clk, posedge resetb) begin
    if((resetb == 1'b0)) begin
      bit_counter <= 0;
    end else begin
      if((decode_F628 == 1'b1)) begin
        bit_counter <= 0;
      end
      else if((bit_counter == 7)) begin
        bit_counter <= 0;
      end
      else begin
        bit_counter <= (bit_counter + 1) % 8;
      end
    end
  end
  assign count_4bit = count_4bit_int;
  assign clk_div_8 = count_4bit[2];
  always @(posedge clk, posedge resetb) begin
    if((resetb == 1'b0)) begin
      count_4bit_int <= 0;
    end else begin
      if((decode_F628 == 1'b1)) begin
        count_4bit_int <= 0;
      end
      else if((count_4bit_int == 15)) begin
        count_4bit_int <= 0;
      end
      else begin
        count_4bit_int <= count_4bit_int + 1;
      end
    end
  end
  always @(posedge clk, posedge resetb) begin
    if((resetb == 1'b0)) begin
      parallel_reg <= {8{1'b0}};
    end else begin
      if((decode_F628 == 1'b1)) begin
        parallel_reg <= shiftreg_16[15:8];
      end
      else if((bit_counter == 7)) begin
        parallel_reg <= shiftreg_16[15:8];
      end
    end
  end
endmodule

module branch_controller (
    input [6:0] opcode,
    input [2:0] funct3,
    input [31:0] alu_out,
    output branch_ctrl
);

    // RISC-V branch instruction opcode
    parameter BRANCH_OPCODE = 7'b1100011;

    // Branch condition parameters
    parameter BEQ  = 3'b000;
    parameter BNE  = 3'b001;
    parameter BLT  = 3'b100;
    parameter BGE  = 3'b101;
    parameter BLTU = 3'b110;
    parameter BGEU = 3'b111;

    function automatic logic branch_control;
        input [6:0] opcode;
        input [2:0] funct3;
        input [31:0] alu_out;
        begin
            if (opcode == BRANCH_OPCODE) begin
                case (funct3)
                    BEQ:  branch_control = (alu_out == 32'b0);
                    BNE:  branch_control = (alu_out != 32'b0);
                    BLT:  branch_control = alu_out[0];
                    BGE:  branch_control = ~alu_out[0];
                    BLTU: branch_control = alu_out[0];
                    BGEU: branch_control = ~alu_out[0];
                    default: branch_control = 1'b0;
                endcase
            end else begin
                branch_control = 1'b0;
            end
        end
    endfunction

    assign branch_ctrl = branch_control(opcode, funct3, alu_out);

endmodule

module I82C55(
input wire [1:0] I_ADDR,
input wire [7:0] I_DATA,
output reg [7:0] O_DATA,
input wire CS_H,
input wire WR_L,
output reg [7:0] O_PA,
input wire [7:0] I_PB,
input wire [3:0] I_PC,
output reg [3:0] O_PC,
input wire RESET,
input wire ENA,
input wire CLK
);
// A1-A0
// D7-D0
// (CPU) clk enable
// registers
reg [7:0] r_porta;
reg [7:0] r_portb;
reg [3:0] l_portc;
reg [3:0] h_portc;
reg [7:0] ctrl_reg;
  always @(posedge RESET, posedge CLK) begin
    if((RESET == 1'b0)) begin
      r_porta <= 8'h00;
      r_portb <= 8'h00;
      l_portc <= 4'h0;
      h_portc <= 4'h0;
      ctrl_reg <= 8'h00;
    end else begin
      if(ENA == 1'b1) begin
        O_PA <= r_porta;
        r_portb <= I_PB;
        h_portc <= I_PC;
        O_PC <= l_portc;
        if((CS_H == 1'b1)) begin
          if((WR_L == 1'b0)) begin
            case(I_ADDR)
            2'b00 : begin
              r_porta <= I_DATA;
              //when "01" => r_portb   <= I_DATA;
            end
            2'b10 : begin
              l_portc <= I_DATA[3:0];
            end
            2'b11 : begin
              if((I_DATA[7] == 1'b0)) begin
                // set/clr
                l_portc[2] <= I_DATA[0];
              end
              else begin
                ctrl_reg <= I_DATA;
              end
            end
            default : begin
            end
            endcase
          end
          else begin
            // read ports
            case(I_ADDR)
            2'b00 : begin
              O_DATA <= r_porta;
            end
            2'b01 : begin
              O_DATA <= r_portb;
            end
            2'b10 : begin
              O_DATA <= {h_portc,l_portc};
            end
            2'b11 : begin
              O_DATA <= ctrl_reg;
            end
            default : begin
            end
            endcase
          end
        end
      end
    end
  end
endmodule

module enum_sort (
    input wire clk,
    input wire [79:0] a1, a2, a3, a4, a5, a6, a7, a8, a9, a10,
    output reg [79:0] out1, out2, out3, out4, out5, out6, out7, out8, out9, out10
);

    reg [79:0] dat1, dat2, dat3, dat4, dat5, dat6, dat7, dat8, dat9, dat10;
    reg [79:0] arr [0:9];
    reg [79:0] temp;
    integer i, j;

    always @(posedge clk) begin
        dat1 <= a1; dat2 <= a2; dat3 <= a3; dat4 <= a4; dat5 <= a5;
        dat6 <= a6; dat7 <= a7; dat8 <= a8; dat9 <= a9; dat10 <= a10;
    end

    always @* begin
        arr[0] = dat1; arr[1] = dat2; arr[2] = dat3; arr[3] = dat4; arr[4] = dat5;
        arr[5] = dat6; arr[6] = dat7; arr[7] = dat8; arr[8] = dat9; arr[9] = dat10;

        for (i = 0; i < 10; i = i + 1) begin
            for (j = 0; j < 9; j = j + 1) begin
                if (arr[j] < arr[j+1]) begin
                    temp = arr[j];
                    arr[j] = arr[j+1];
                    arr[j+1] = temp;
                end
            end
        end
    end

    always @(posedge clk) begin
        out1 <= arr[0]; out2 <= arr[1]; out3 <= arr[2]; out4 <= arr[3]; out5 <= arr[4];
        out6 <= arr[5]; out7 <= arr[6]; out8 <= arr[7]; out9 <= arr[8]; out10 <= arr[9];
    end

endmodule

