// Module 2: mem2reg_test2
module mem2reg_test2(
    input clk, reset, mode,
    input [2:0] addr,
    output reg [3:0] out_data
);
    reg [3:0] mem [0:7];
    integer i;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            for (i = 0; i < 8; i = i + 1)
                mem[i] <= i;
        end else if (mode) begin
            for (i = 0; i < 8; i = i + 1)
                mem[i] <= mem[i] + 1;
        end else begin
            mem[addr] <= 4'b0;
        end
    end

    always @(posedge clk)
        out_data <= mem[addr];
endmodule

