  ip_extract_header #(
      .our_ip(our_ip),
    .our_broadcast(our_broadcast))
  i_ip_extract_header(
      .clk(clk),
    .data_valid_in(ether_extracted_data_valid),
    .data_in(ether_extracted_data),
    .data_valid_out(ip_extracted_data_valid),
