module barcode (
    input wire clk,
    input wire rst_n,
    input wire BC,
    input wire clr_ID_vld,
    output reg ID_vld,
    output reg [7:0] ID
);

    // State encoding
    localparam IDLE = 2'b00;
    localparam COUNT = 2'b01;
    localparam DURATION = 2'b10;
    localparam SHIFT = 2'b11;

    reg [1:0] state, next_state;
    reg [21:0] cnt, duration;
    reg [3:0] bit_cnt;
    reg [1:0] BC_sync;
    wire BC_falling_edge;

    // Double-flop synchronizer
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            BC_sync <= 2'b11;
        else
            BC_sync <= {BC_sync[0], BC};
    end

    assign BC_falling_edge = BC_sync[1] & ~BC_sync[0];

    // State register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (state)
            IDLE: next_state = (!ID_vld && BC_falling_edge) ? COUNT : IDLE;
            COUNT: next_state = BC_falling_edge ? DURATION : COUNT;
            DURATION: next_state = BC_falling_edge ? SHIFT : DURATION;
            SHIFT: next_state = (cnt == duration) ? (bit_cnt == 4'd7 ? IDLE : COUNT) : SHIFT;
            default: next_state = IDLE;
        endcase
    end

    // Counter logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            cnt <= 22'd0;
        else if (state == IDLE || state == DURATION || (state == SHIFT && cnt == duration))
            cnt <= 22'd0;
        else
            cnt <= cnt + 1'b1;
    end

    // Duration register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            duration <= 22'd0;
        else if (state == DURATION && BC_falling_edge)
            duration <= cnt;
    end

    // Bit counter
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            bit_cnt <= 4'd0;
        else if (state == IDLE)
            bit_cnt <= 4'd0;
        else if (state == SHIFT && cnt == duration)
            bit_cnt <= bit_cnt + 1'b1;
    end

    // ID shift register
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            ID <= 8'd0;
        else if (state == SHIFT && cnt == duration)
            ID <= {ID[6:0], (cnt > (duration >> 1))};
    end

    // ID_vld logic
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            ID_vld <= 1'b0;
        else if (clr_ID_vld)
            ID_vld <= 1'b0;
        else if (state == SHIFT && cnt == duration && bit_cnt == 4'd7 && ID[7:6] == 2'b00)
            ID_vld <= 1'b1;
    end

endmodule

module iec61499_network_top(
input wire clk,
input wire reset,
input wire rx_conveyor_moving,
input wire rx_conveyor_jammed,
output wire tx_conveyor_run,
input wire rx_global_run,
input wire rx_global_run_infinite,
input wire rx_global_fault,
output wire tx_box_dropper_run,
output wire debug_enable,
output wire debug_sync,
output wire debug_done
);
//for clock and reset signal
//special emitted internal variables for child I/O
//type was BOOL 
//type was BOOL 
//type was BOOL 
//type was BOOL 
//type was BOOL 
//type was BOOL 
//type was BOOL 
//signals in case external components want to measure time
// Build an enumerated type for the state machine
parameter [1:0]
  STATE_sync = 0,
  STATE_wait_sync_done = 1,
  STATE_run = 2,
  STATE_wait_run_done = 3;
  // Register to hold the current state
reg [1:0] state = STATE_sync;
reg enable = 1'b0;
reg sync = 1'b0;
wire done = 1'b0;
  //port map for top level block
  DE2_115 top_block(
      .clk(clk),
    .reset(reset),
    .enable(enable),
    .sync(sync),
    //special emitted internal variables for child I/O
    .rx_conveyor_moving(rx_conveyor_moving),
    //going in 
    .rx_conveyor_jammed(rx_conveyor_jammed),
    //going in 
    .tx_conveyor_run(tx_conveyor_run),
    //going out 
    .rx_global_run(rx_global_run),
    //going in 
    .rx_global_run_infinite(rx_global_run_infinite),
    //going in 
    .rx_global_fault(rx_global_fault),
    //going in 
    .tx_box_dropper_run(tx_box_dropper_run),
    //going out 
    .done(done));
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b1) begin
      state <= STATE_sync;
    end else begin
      //default values
      state <= state;
      enable <= 1'b0;
      sync <= 1'b0;
      case(state)
      STATE_sync : begin
        sync <= 1'b1;
        state <= STATE_wait_sync_done;
      end
      STATE_wait_sync_done : begin
        //TODO sync_done signal
        state <= STATE_run;
      end
      STATE_run : begin
        enable <= 1'b1;
        state <= STATE_wait_run_done;
      end
      STATE_wait_run_done : begin
        if(done == 1'b1) begin
          state <= STATE_sync;
        end
      end
      endcase
    end
  end
  assign debug_done = done;
  assign debug_enable = enable;
  assign debug_sync = sync;
endmodule

