module decoder(
input wire [7:0] instr,
output reg d_alutoreg,
output reg [1:0] d_alua,
output reg [1:0] d_alub,
output reg d_write,
output reg d_read,
output reg d_jumpf,
output reg d_jumpb
);
  always @(instr) begin
    // d_alutoreg
    // 0 : write alu result to mem(pointer)
    // 1 : write alu result to pointer
    // d_alua
    // 00 : mem(pointer)
    // 01 : pointer
    // 10 : read from input
    // 11 : illegal
    // d_alub
    // 00 : 0
    // 01 : 1
    // 10 : Illegal
    // 11 : -1
    // d_write
    // 1 : write alu result to output
    d_alutoreg <= 1'b0;
    d_alub <= 2'b00;
    d_alua <= 2'b00;
    d_write <= 1'b0;
    d_read <= 1'b0;
    d_jumpf <= 1'b0;
    d_jumpb <= 1'b0;
    case(instr)
        // <
    8'h3C : begin
      d_alutoreg <= 1'b1;
      d_alua <= 2'b01;
      d_alub <= 2'b11;
      // >
    end
    8'h3E : begin
      d_alutoreg <= 1'b1;
      d_alua <= 2'b01;
      d_alub <= 2'b01;
      // +
    end
    8'h2B : begin
      d_alub <= 2'b01;
      // -
    end
    8'h2D : begin
      d_alub <= 2'b11;
      // .
    end
    8'h2E : begin
      d_write <= 1'b1;
      // ,
    end
    8'h2C : begin
      d_read <= 1'b1;
      d_alua <= 2'b10;
      // [
    end
    8'h5B : begin
      d_jumpf <= 1'b1;
      // ]
    end
    8'h5D : begin
      d_jumpb <= 1'b1;
    end
    default : begin
      // nop
    end
    endcase
  end
endmodule

