module rom_64x8 (
    input wire clock,
    input wire reset,
    input wire [7:0] addr,
    output reg [63:0] y
);

    (* ram_style = "block" *) reg [63:0] ram;

    always @(posedge clock) begin
        case (addr)
            8'd0: ram <= 64'h0000_0000_0000_0001;
            8'd1: ram <= 64'h0000_0000_0000_0010;
            8'd2: ram <= 64'h0000_0000_0000_0100;
            8'd3: ram <= 64'h0000_0000_0000_1000;
            8'd4: ram <= 64'h0000_0000_0001_0000;
            8'd5: ram <= 64'h0000_0000_0010_0000;
            8'd6: ram <= 64'h0000_0000_0100_0000;
            8'd7: ram <= 64'h0000_0000_1000_0000;
            default: ram <= 64'h0000_0000_0000_0000;
        endcase
    end

    always @(posedge clock) begin
        y <= ram;
    end

endmodule

module simple_alu (
    input [7:0] DATA1,
    input [7:0] DATA2,
    input [2:0] SELECT,
    output reg [7:0] RESULT
);

always @(*) begin
    case (SELECT)
        3'b000: RESULT = DATA2;
        3'b001: RESULT = DATA1 + DATA2;
        3'b010: RESULT = DATA1 & DATA2;
        3'b011: RESULT = DATA1 | DATA2;
        default: RESULT = 8'b0;
    endcase
end

endmodule

module sub_220(
output wire [31:0] result,
input wire [31:0] in_a,
input wire [31:0] in_b
);
wire [33:0] carry_inA;
wire [33:0] carry_inB;
wire [33:0] carry_res;
  // To handle the CI input, the operation is '0' - CI
  // If CI is not present, the operation is '0' - '0'
  assign carry_inA = {1'b0,in_a,1'b0};
  assign carry_inB = {1'b0,in_b,1'b0};
  // Compute the result
  assign carry_res = (carry_inA) - (carry_inB);
  // Set the outputs
  assign result = carry_res[32:1];
endmodule

module uart_interrupt(
input wire CLK,
input wire RST,
input wire [3:0] IER,
input wire [4:0] LSR,
input wire THI,
input wire RDA,
input wire CTI,
input wire AFE,
input wire [3:0] MSR,
output wire [3:0] IIR,
output wire INT
);
// Clock
// Reset
// IER 3:0
// LSR 4:0
// Transmitter holding register empty interrupt
// Receiver data available
// Character timeout indication
// Automatic flow control enable
// MSR 3:0
// IIR 3:0
// Interrupt
// Signals
wire iRLSInterrupt;  // Receiver line status interrupt
wire iRDAInterrupt;  // Received data available interrupt
wire iCTIInterrupt;  // Character timeout indication interrupt
wire iTHRInterrupt;  // Transmitter holding register empty interrupt
wire iMSRInterrupt;  // Modem status interrupt
reg [3:0] iIIR;  // IIR register
  // Priority 1: Receiver line status interrupt on: Overrun error, parity error, framing error or break interrupt
  assign iRLSInterrupt = IER[2] & (LSR[1] | LSR[2] | LSR[3] | LSR[4]);
  // Priority 2: Received data available or trigger level reached in FIFO mode
  assign iRDAInterrupt = IER[0] & RDA;
  // Priority 2: Character timeout indication
  assign iCTIInterrupt = IER[0] & CTI;
  // Priority 3: Transmitter holding register empty
  assign iTHRInterrupt = IER[1] & THI;
  // Priority 4: Modem status interrupt: dCTS (when AFC is disabled), dDSR, TERI, dDCD
  assign iMSRInterrupt = IER[3] & ((MSR[0] &  ~AFE) | MSR[1] | MSR[2] | MSR[3]);
  // IIR
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      iIIR <= 4'b0001;
      // TODO: Invert later
    end else begin
      // IIR register
      if((iRLSInterrupt == 1'b1)) begin
        iIIR <= 4'b0110;
      end
      else if((iCTIInterrupt == 1'b1)) begin
        iIIR <= 4'b1100;
      end
      else if((iRDAInterrupt == 1'b1)) begin
        iIIR <= 4'b0100;
      end
      else if((iTHRInterrupt == 1'b1)) begin
        iIIR <= 4'b0010;
      end
      else if((iMSRInterrupt == 1'b1)) begin
        iIIR <= 4'b0000;
      end
      else begin
        iIIR <= 4'b0001;
      end
    end
  end
  // Outputs
  assign IIR = iIIR;
  assign INT =  ~iIIR[0];
endmodule

module bit_delay(
input wire clk,
input wire rst,
input wire input,
output wire output
);
parameter [31:0] size=1;
// size of delay
// clock
//rst
// input
// output
//  signal delayed_output : std_logic_vector(size downto 0) := (others => '0');  -- delayed output
wire delayed_output[0:size] = 1'b0;  // delayed output
  // behavourial
  assign delayed_output[0] = input;
  generate if (size > 0) begin: size_non_zero
      genvar i;
    generate for (i=0; i <= size - 1; i = i + 1) begin: delay_loop
          single_delay inst(
              .clk(clk),
        .rst(rst),
        .input(delayed_output[i]),
        .output(delayed_output[i + 1]));
    end
    endgenerate
    assign output = delayed_output[size];
  end
  endgenerate
  generate if (size == 0) begin: size_zero
      assign output = input;
  end
  endgenerate
endmodule

module true_dual_port_ram_byte_enable
#(
    parameter BYTE_WIDTH = 8,
    parameter ADDRESS_WIDTH = 8,
    parameter BYTES = 4,
    parameter DATA_WIDTH_R = BYTE_WIDTH * BYTES
)
(
    input wire clk,
    input wire [ADDRESS_WIDTH-1:0] addr1,
    input wire [ADDRESS_WIDTH-1:0] addr2,
    input wire [BYTES-1:0] be1,
    input wire [BYTES-1:0] be2,
    input wire [DATA_WIDTH_R-1:0] data_in1,
    input wire [DATA_WIDTH_R-1:0] data_in2,
    input wire we1,
    input wire we2,
    output reg [DATA_WIDTH_R-1:0] data_out1,
    output reg [DATA_WIDTH_R-1:0] data_out2
);

    localparam RAM_DEPTH = 2**ADDRESS_WIDTH;

    reg [BYTE_WIDTH-1:0] ram[RAM_DEPTH-1:0][BYTES-1:0];

    reg [DATA_WIDTH_R-1:0] data_reg1;
    reg [DATA_WIDTH_R-1:0] data_reg2;

    integer i;

    always @(posedge clk) begin
        // Port 1
        if (we1) begin
            for (i = 0; i < BYTES; i = i + 1) begin
                if (be1[i]) begin
                    ram[addr1][i] <= data_in1[BYTE_WIDTH*i +: BYTE_WIDTH];
                end
            end
        end
        data_reg1 <= {ram[addr1][BYTES-1], ram[addr1][BYTES-2], ram[addr1][BYTES-3], ram[addr1][0]};

        // Port 2
        if (we2) begin
            for (i = 0; i < BYTES; i = i + 1) begin
                if (be2[i]) begin
                    ram[addr2][i] <= data_in2[BYTE_WIDTH*i +: BYTE_WIDTH];
                end
            end
        end
        data_reg2 <= {ram[addr2][BYTES-1], ram[addr2][BYTES-2], ram[addr2][BYTES-3], ram[addr2][0]};
    end

    always @(posedge clk) begin
        data_out1 <= data_reg1;
        data_out2 <= data_reg2;
    end

endmodule

module LedBar(
input wire clk_i,
input wire en_i,
input wire rnl_i,
output wire [15:0] leds_o
);
parameter [31:0] C_SYS_CLK_FREQ_MHZ=100;
parameter [31:0] C_SECONDS_TO_RECORD=3;
// number of seconds to record
// system clock
// active-high enable
// Right/Left shift select
// output LED bus
//----------------------------------------------------------------------
// Constant Declarations
//----------------------------------------------------------------------
parameter CLK_DIV_RATIO = ((C_SECONDS_TO_RECORD * C_SYS_CLK_FREQ_MHZ * 1000000) / 16) - 1;  //----------------------------------------------------------------------
// Signal Declarations
//----------------------------------------------------------------------
// Clock divider counter
reg [31:0] cnt_clk = 0;
reg clk_div;  //Shift register to hold the Led data
reg [15:0] tmp_sig = 1'b0;  //----------------------------------------------------------------------
// Module Implementation
//----------------------------------------------------------------------
  // shift register
  always @(posedge clk_i) begin
    if(en_i == 1'b1) begin
      if(clk_div == 1'b1) begin
        // shift left
        if(rnl_i == 1'b0) begin
          tmp_sig <= {tmp_sig[14:0],1'b1};
          // shift right
        end
        else begin
          tmp_sig <= {1'b1,tmp_sig[15:1]};
        end
      end
    end
    else begin
      tmp_sig <= {16{1'b0}};
    end
  end
  assign leds_o = tmp_sig;
  // Generate shift clock
  always @(posedge clk_i) begin
    if(en_i == 1'b0 || cnt_clk == CLK_DIV_RATIO) begin
      cnt_clk <= 0;
      clk_div <= 1'b1;
    end
    else begin
      cnt_clk <= cnt_clk + 1;
      clk_div <= 1'b0;
    end
  end
endmodule

module phyActGen(
input wire iRst,
input wire iClk,
input wire iTxEnable,
input wire iRxValid,
output wire oActivity
);
//! Generated activity frequency of oActivity [Hz]
parameter [31:0] gActivityFreq=6;
parameter [31:0] gClkFreq=50e6;
//! Reset
//! Clock
//! MAC Tx enable signal
//! MAC Rx data valid signal
//! Generated activity signal
//! Obtain maximum counter value to achieve activity frequency
parameter cCntMaxValue = gClkFreq / gActivityFreq;  //! Obtain counter width
parameter cCntWidth = logDualis[cCntMaxValue];  //! Constant for counter value zero
parameter cCntIsZero = cInactivated;  //! The counter
reg [cCntWidth - 1:0] counter;  //! Terminal counter
wire counterTc;  //! Trigger activity in next cycle due to packet activity
reg triggerActivity;  //! Enable activity
reg enableActivity;
  assign oActivity = enableActivity == cActivated ? counter[(cCntWidth - 1)] : cInactivated;
  always @(posedge iRst, posedge iClk) begin
    if(iRst == cActivated) begin
      triggerActivity <= cInactivated;
      enableActivity <= cInactivated;
    end else begin
      //monoflop, of course no default value!
      if(triggerActivity == cActivated && counterTc == cActivated) begin
        //counter overflow and activity within last cycle
        enableActivity <= cActivated;
      end
      else if(counterTc == cActivated) begin
        //counter overflow but no activity
        enableActivity <= cInactivated;
      end
      //monoflop, of course no default value!
      if(counterTc == cActivated) begin
        //count cycle over, reset trigger
        triggerActivity <= cInactivated;
      end
      else if(iTxEnable == cActivated || iRxValid == cActivated) begin
        //activity within cycle
        triggerActivity <= cActivated;
      end
    end
  end
  always @(posedge iClk, posedge iRst) begin
    if(iRst == cActivated) begin
      counter <= {((cCntWidth - 1)-(0)+1){cInactivated}};
    end else begin
      counter <= (counter) - 1;
    end
  end
  assign counterTc = counter == cCntIsZero ? cActivated : cInactivated;
endmodule

module EdgeDetector(
input wire reset,
input wire clk,
input wire in_data,
output wire pulse
);
parameter RISING=1'b1;
parameter FALLING=1'b0;
parameter [31:0] PULSE_WIDTH=10;
reg t_i; wire t_o;
reg lastData;
  always @(posedge reset, posedge clk, posedge t_o, posedge in_data) begin
    if(reset == 1'b1) begin
      t_i <= t_o;
      lastData <= in_data;
    end else begin
      if(lastData != in_data) begin
        if(RISING == 1'b1 && lastData == 1'b0 && in_data == 1'b1) begin
          t_i <=  ~t_o;
        end
        if(FALLING == 1'b1 && lastData == 1'b1 && in_data == 1'b0) begin
          t_i <=  ~t_o;
        end
      end
      lastData <= in_data;
    end
  end
  SinglePulseGenerator #(
      .WIDTH(PULSE_WIDTH))
  spg(
      .reset(reset),
    .clk(clk),
    .t_in(t_i),
    .t_out(t_o),
    .pulse(pulse));
endmodule

module sram_ctrl (
    input wire clk,
    input wire rst_n,
    input wire selec,
    input wire write,
    input wire read,
    input wire [15:0] data_wr_in,
    output reg [15:0] data_wr_out,
    input wire [18:0] addr_wr,
    inout wire [15:0] sram_data,
    output wire [18:0] sram_addr,
    output reg sram_oe_r,
    output reg sram_ce_r,
    output reg sram_we_r,
    output reg sram_ub_r,
    output reg sram_lb_r
);

reg [15:0] data_wr;
reg en;

assign sram_addr = addr_wr;
assign sram_data = en ? data_wr : 16'bz;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sram_oe_r <= 1'b1;
        sram_ce_r <= 1'b1;
        sram_we_r <= 1'b1;
        sram_ub_r <= 1'b1;
        sram_lb_r <= 1'b1;
        en <= 1'b0;
        data_wr <= 16'b0;
        data_wr_out <= 16'b0;
    end else begin
        if (selec) begin
            if (write && !read) begin
                sram_ce_r <= 1'b0;
                sram_we_r <= 1'b0;
                sram_ub_r <= 1'b0;
                sram_lb_r <= 1'b0;
                sram_oe_r <= 1'b1;
                en <= 1'b1;
            end else if (read && !write) begin
                sram_ce_r <= 1'b0;
                sram_oe_r <= 1'b0;
                sram_ub_r <= 1'b0;
                sram_lb_r <= 1'b0;
                sram_we_r <= 1'b1;
                en <= 1'b0;
            end else begin
                sram_oe_r <= 1'b1;
                sram_ce_r <= 1'b1;
                sram_we_r <= 1'b1;
                sram_ub_r <= 1'b1;
                sram_lb_r <= 1'b1;
                en <= 1'b0;
            end
        end else begin
            sram_oe_r <= 1'b1;
            sram_ce_r <= 1'b1;
            sram_we_r <= 1'b1;
            sram_ub_r <= 1'b1;
            sram_lb_r <= 1'b1;
            en <= 1'b0;
        end
    end
end

always @(negedge clk) begin
    if (selec && write && !read) begin
        data_wr <= data_wr_in;
    end else if (selec && read && !write) begin
        data_wr_out <= sram_data;
    end
end

endmodule

module waveform_gen(
input wire clk,
input wire reset,
input wire [31:0] phase_inc,
output wire [11:0] sin_out,
output wire [11:0] cos_out,
output wire [11:0] squ_out,
output wire [11:0] saw_out
);
// system signals
// NCO frequency control
// Output waveforms
reg [31:0] phase_acc;
wire [11:0] lut_addr;
reg [11:0] lut_addr_reg;
wire [11:0] sin_out_reg;
  //------------------------------------------------------------------------
  // Phase accumulator increments by 'phase_inc' every clock cycle        --
  // Output frequency determined by formula: Phase_inc = (Fout/Fclk)*2^32 --
  // E.g. Fout = 36MHz, Fclk = 100MHz,  Phase_inc = 36*2^32/100           --
  // Frequency resolution is 100MHz/2^32 = 0.00233Hz                      --
  //------------------------------------------------------------------------
  always @(posedge clk, posedge reset) begin
    if(reset == 1'b0) begin
      phase_acc <= {32{1'b0}};
    end else begin
      phase_acc <= (phase_acc) + (phase_inc);
      //	 sin_out <= signed(sin_out_reg) + 2047;		--Modified to make it unsigned - jpg 10/6/2011
    end
  end
  //-------------------------------------------------------------------
  // use top 12-bits of phase accumulator to address the SIN/COS LUT --
  //-------------------------------------------------------------------
  assign lut_addr = phase_acc[31:20];
  //--------------------------------------------------------------------
  // SIN/COS LUT is 4096 by 12-bit ROM                                --
  // 12-bit output allows sin/cos amplitudes between 2047 and -2047   --
  // (-2048 not used to keep the output signal perfectly symmetrical) --
  // Phase resolution is 2Pi/4096 = 0.088 degrees                     --
  //--------------------------------------------------------------------
  sincos_lut lut(
      .clk(clk),
    .addr(lut_addr),
    .sin_out(sin_out),
    .cos_out(cos_out));
  //-------------------------------
  // Hide the latency of the LUT --
  //-------------------------------
  always @(posedge clk) begin
    lut_addr_reg <= lut_addr;
  end
  //-------------------------------------------
  // Square output is msb of the accumulator --
  //-------------------------------------------
  assign squ_out = lut_addr_reg[11] == 1'b1 ? 12'b011111111111 : 12'b100000000000;
  //-----------------------------------------------------
  // Sawtooth output is top 12-bits of the accumulator --
  //-----------------------------------------------------
  assign saw_out = lut_addr_reg;
endmodule
